INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('d7843ba9-a7eb-597c-a545-42a6d0aa7cfa', '90925ae1-848c-562e-a257-9dd6d175f9a6', 'c932bdb5-080f-573b-a163-3eca4818e562', 20, 20, 'ኤሞርና ልጁ ሴኬምም ሄዱና ወደ ከተማቸው በር ደረሱ፤ ለከተማቸውም ሰዎች ሁሉ እንዲህ ብለው ነገሩ፦'),
  ('6401b86c-e283-5c16-a0ef-445153e9323b', '90925ae1-848c-562e-a257-9dd6d175f9a6', 'c932bdb5-080f-573b-a163-3eca4818e562', 21, 21, '“እነዚህ ሰዎች በእኛ ዘንድ የሰላም ሰዎች ናቸው፤ በምድራችን ይቀመጡ፤ ይነግዱባትም፤ እነሆም፥ ምድሪቱ ሰፊ ናት፤ ሴቶች ልጆቻቸውን ለሚስትነት እንውሰድ፤ ለእነርሱም ሴቶች ልጆቻችንን እንስጥ።'),
  ('0975cee8-1f62-5c55-a59c-9b7dec6c2aca', '90925ae1-848c-562e-a257-9dd6d175f9a6', 'c932bdb5-080f-573b-a163-3eca4818e562', 22, 22, 'እነርሱ እንደ እኛ ይሆኑ ዘንድ በዚህ ብቻ እንምሰላቸው። አንድ ወገንም እንሁን፤ እነርሱ እንደሚገርዙ ወንዶቻችንን ሁሉ እንገርዛለን።'),
  ('4058f70d-5c8f-5621-a270-51a2d47c3dc6', '90925ae1-848c-562e-a257-9dd6d175f9a6', 'c932bdb5-080f-573b-a163-3eca4818e562', 23, 23, 'መንጋቸውም፥ የጋማ ከብቶቻቸውም፥ ገንዘባቸውም ሁሉ ለእኛ አይደሉምን? ነገር ግን በዚህ ብቻ ከመሰልናቸው ከእኛ ጋር ይቀመጣሉ።”'),
  ('595bd1cd-89dd-50b0-a28b-cdddf1be64a5', '90925ae1-848c-562e-a257-9dd6d175f9a6', 'c932bdb5-080f-573b-a163-3eca4818e562', 24, 24, 'በከተማዪቱም በር የሚገቡ ሁሉ ኤሞርንና ልጁን ሴኬምን እሺ አሉ፤ ወንዶችም ሁሉ የሰውነታቸውን ሸለፈት ተገረዙ።'),
  ('54589c88-7bd5-5df0-a0e6-649dfab47995', '90925ae1-848c-562e-a257-9dd6d175f9a6', '551397bb-7e9c-511c-a6c4-1917a9356880', 1, 25, 'እንዲህም ሆነ፤ በሦስተኛው ቀን እጅግ ቈስለው ሳሉ ሁለቱ የያዕቆብ ልጆች የዲና ወንድሞች ስምዖንና ሌዊ እየራሳቸው ሰይፋቸውን ይዘው ተደፋፍረው ወደ ከተማ ገቡ፤ ወንዱንም ሁሉ ገደሉ፤'),
  ('e05f8e20-fa82-522d-a118-b2dbec136a15', '90925ae1-848c-562e-a257-9dd6d175f9a6', '551397bb-7e9c-511c-a6c4-1917a9356880', 2, 26, 'ኤሞርንና ልጁን ሴኬምንም በሰይፍ ገደሉ፤ እኅታቸው ዲናንም ከሴኬም ቤት ይዘው ወጡ።'),
  ('71c5927a-3bfd-54e9-a1ee-5745adb7798f', '90925ae1-848c-562e-a257-9dd6d175f9a6', '551397bb-7e9c-511c-a6c4-1917a9356880', 3, 27, 'የያዕቆብ ልጆችም ወደ ሞቱት ገብተው እኅታቸው ዲናን ያስነወሩባትን ከተማዪቱን ዘረፉ፤'),
  ('1d49a0a3-1f33-55b6-a710-a95c57e3fe20', '90925ae1-848c-562e-a257-9dd6d175f9a6', '551397bb-7e9c-511c-a6c4-1917a9356880', 4, 28, 'ላሞቻቸውንም፥ በጎቻቸውንም፥ አህዮቻቸውንም በሜዳም፥ በከተማም ያለውን ወሰዱ ።'),
  ('13d9eebf-30ec-56f3-a305-33745ba6de92', '90925ae1-848c-562e-a257-9dd6d175f9a6', '551397bb-7e9c-511c-a6c4-1917a9356880', 5, 29, 'ሎሌዎቻቸውንና ሚስቶቻቸውን፥ የቤታቸውንም ቈሳቍስ ሁሉ ማረኩ፤ በቤትና በከተማ ያለውንም ሁሉ ዘረፉ።'),
  ('03510e50-d9b4-5ff8-af4c-fedcf20868f3', '90925ae1-848c-562e-a257-9dd6d175f9a6', '551397bb-7e9c-511c-a6c4-1917a9356880', 6, 30, 'ያዕቆብም ስምዖንንና ሌዊን እንዲህ አላቸው፥ “ክፉ አደረጋችሁብኝ፤ በዚች ሀገር በሚኖሩ በከነዓናውያንና በፌርዜዎናውያን ሰዎች ዘንድ አስጠላችሁኝ። እኔ በቍጥር ጥቂት ነኝ፤ እነርሱ በእኔ ላይ ይሰበሰቡና ይወጉኛል፤ እኔና ቤቴም እንጠፋለን።”'),
  ('6b8a3bf9-d44a-5d61-a746-a9fa04a54e10', '90925ae1-848c-562e-a257-9dd6d175f9a6', '551397bb-7e9c-511c-a6c4-1917a9356880', 7, 31, 'እነርሱም፥ “እኅታችንን እንደ አመንዝራ አድርገው ለምን አዋረዷት?” አሉት።'),
  ('de30472b-43a1-5d8c-a4dc-432ffade9b4f', '876cccf0-7a0a-544a-a3d2-008684634a88', 'c070b892-b9bf-57ed-ac52-8faa733ef18a', 1, 1, 'እግዚአብሔርም ያዕቆብን አለው፥ “ተነሥተህ ወደ ቤቴል ውጣ፤ በዚያም ኑር፤ ከወንድምህ ከዔሳው ፊት በሸሸህ ጊዜ ለተገለጥሁልህ ለእኔ መሥውያን ሥራ።”'),
  ('16c1cb7a-470a-55fb-a093-e4eb1c15a18d', '876cccf0-7a0a-544a-a3d2-008684634a88', 'c070b892-b9bf-57ed-ac52-8faa733ef18a', 2, 2, 'ያዕቆብም ለቤተ ሰቡና ከእርሱ ጋር ላሉት ሁሉ እንዲህ አለ፥ “ከእናንተ ጋር ያሉ እንግዶች አማልክትን ከመካከላችሁ አስወግዱ፤ ንጹሓንም ሁኑ፤ ልብሳችሁንም እጠቡ፤'),
  ('37a9ac04-d5e2-59fc-a18d-bd45ca027623', '876cccf0-7a0a-544a-a3d2-008684634a88', 'c070b892-b9bf-57ed-ac52-8faa733ef18a', 3, 3, 'ተነሡና ወደ ቤቴል እንውጣ፤ በዚያም በመከራዬ ቀን ለሰማኝ፥ በሄድሁበትም መንገድ ከእኔ ጋር ለነበረው፥ ከመከራም አድኖ ላሻገረኝ ለእግዚአብሔር መሠውያን እንሥራ።”'),
  ('97044d2c-d025-51b9-a9c0-c42bf78dcf2a', '876cccf0-7a0a-544a-a3d2-008684634a88', 'c070b892-b9bf-57ed-ac52-8faa733ef18a', 4, 4, 'በእጃቸው ያሉትንም እንግዶች አማልክት ሁሉ፥ በጆሮአቸውም ያሉትን ጉትቾች ለያዕቆብ ሰጡት፤ ያዕቆብም በሴቄም አጠገብ ካለችው ዛፍ በታች ቀበራቸው። እስከ ዛሬም ድረስ አጠፋቸው።'),
  ('9387c257-af1c-555a-a084-043d4cb6aea3', '876cccf0-7a0a-544a-a3d2-008684634a88', 'c070b892-b9bf-57ed-ac52-8faa733ef18a', 5, 5, 'እስራኤልም ከሴቄም ሄደ፤ እግዚአብሔርንም መፍራት በዙሪያቸው ባሉት ከተሞች ሁሉ ወደቀ፤ የእስራኤልንም ልጆች ለማሳደድ አልተከተሉአቸውም።'),
  ('adc6e84a-ddcb-5253-a91e-8eee47c049ef', '876cccf0-7a0a-544a-a3d2-008684634a88', 'c070b892-b9bf-57ed-ac52-8faa733ef18a', 6, 6, 'ያዕቆብም እርሱ፥ ከእርሱ ጋርም የነበሩት ሰዎች ሁሉ በከነዓን ምድር ወዳለችው ወደ ሎዛ መጡ፤ እርስዋም ቤቴል ናት።'),
  ('3de9be54-5d98-5cd5-ab83-fdc61e5c7969', '876cccf0-7a0a-544a-a3d2-008684634a88', 'c070b892-b9bf-57ed-ac52-8faa733ef18a', 7, 7, 'በዚያም መሠውያዉን ሠራ፤ የዚያንም ቦታ ስም ቤቴል ብሎ ጠራው፤ እርሱ ከወንድሙ ከዔሳው ፊት በሸሸበት ጊዜ እግዚአብሔር በዚያ ተገልጦለት ነበርና።'),
  ('fd0aa158-1c7b-5127-a2af-ea2e7002d239', '876cccf0-7a0a-544a-a3d2-008684634a88', 'c070b892-b9bf-57ed-ac52-8faa733ef18a', 8, 8, 'የርብቃ ሞግዚት ዲቦራም ሞተች፤ ከቤቴል በታች ባላን በሚባል ዛፍ ሥርም ተቀበረች፤ ያዕቆብም ስሙን “የልቅሶ ዛፍ” ብሎ ጠራው።'),
  ('5b13bfc4-5406-5450-a530-e5064bdc745c', '876cccf0-7a0a-544a-a3d2-008684634a88', 'c070b892-b9bf-57ed-ac52-8faa733ef18a', 9, 9, 'እግዚአብሔርም ለያዕቆብ ከሁለት ወንዞች መካከል ከሶርያ ከተመለሰ በኋላ እንደገና በሎዛ ተገለጠለት፤ እግዚአብሔርም ባረከው።'),
  ('26bf7ab5-98b0-5ca4-a507-90c3a9a8b04c', '876cccf0-7a0a-544a-a3d2-008684634a88', 'c070b892-b9bf-57ed-ac52-8faa733ef18a', 10, 10, 'እግዚአብሔርም አለው፥ “ስምህ ያዕቆብ አይባል፤ ስምህ እስራኤል ይባል እንጂ” ስሙንም እስራኤል ብሎ ጠራው።'),
  ('3aa3c32d-06c2-5886-a060-c55ecb6cddf5', '876cccf0-7a0a-544a-a3d2-008684634a88', 'c070b892-b9bf-57ed-ac52-8faa733ef18a', 11, 11, 'እግዚአብሔርም አለው፥ “አምላክህ እኔ ነኝ፤ ብዛ፤ ተባዛም፤ ሕዝብና የአሕዛብ ማኅበር ከአንተ ይሆናል፤ ነገሥታትም ከጕልበትህ ይወጣሉ።'),
  ('0c91ea0c-62da-5560-a955-1931af71ad91', '876cccf0-7a0a-544a-a3d2-008684634a88', 'c070b892-b9bf-57ed-ac52-8faa733ef18a', 12, 12, 'ለአብርሃምና ለይስሐቅም የሰጠኋትን ምድር ለአንተ፥ ከአንተም በኋላ ለዘርህ እሰጣለሁ።”'),
  ('dba5a833-cbe9-5250-a6b6-193aa2e4dd9f', '876cccf0-7a0a-544a-a3d2-008684634a88', 'c070b892-b9bf-57ed-ac52-8faa733ef18a', 13, 13, 'እግዚአብሔርም ከእርሱ ጋር ከተነጋገረበት ስፍራ ወደ ላይ ወጣ።'),
  ('9eadc423-4b28-5e47-add2-346876ba9443', '876cccf0-7a0a-544a-a3d2-008684634a88', 'c070b892-b9bf-57ed-ac52-8faa733ef18a', 14, 14, 'ያዕቆብም እግዚአብሔር ከእርሱ ጋር በተነጋገረበት ቦታ የድንጋይ ሐውልት ተከለ፤ የመጠጥ መሥዋዕትንም በእርሱ ላይ አፈሰሰ፤ ዘይትንም አፈሰሰበት።'),
  ('cda29747-70d8-5fb6-a121-0d205b9758d7', '876cccf0-7a0a-544a-a3d2-008684634a88', 'c070b892-b9bf-57ed-ac52-8faa733ef18a', 15, 15, 'ያዕቆብም እግዚአብሔር ከእርሱ ጋር የተነጋገረበትን ያን ቦታ “ቤቴል” ብሎ ጠራው።'),
  ('871f64b9-75d9-5563-abbd-68962822ac56', '876cccf0-7a0a-544a-a3d2-008684634a88', 'da78492c-83ea-5452-a654-9e33979fc929', 1, 16, 'ያዕቆብም ከቤቴል ተጓዘ፤ በጋዲር ግንብ አጠገብ ድንኳን ተከለ፤ ወደ ኤፍራታም ለመድረስ በቀረበ ጊዜ ራሔልን ምጥ ያዛት፤ በምጡም ተጨነቀች።'),
  ('6d2274af-ff4e-5cce-a42d-6b24e4396611', '876cccf0-7a0a-544a-a3d2-008684634a88', 'da78492c-83ea-5452-a654-9e33979fc929', 2, 17, 'በምጥ ሳለችም አዋላጂቱ፥ “አትፍሪ ይህኛው ደግሞ ወንድ ልጅ ይሆንልሻልና” አለቻት።'),
  ('5c9e17e1-6f4c-5076-aca0-436341c6055f', '876cccf0-7a0a-544a-a3d2-008684634a88', 'da78492c-83ea-5452-a654-9e33979fc929', 3, 18, 'ከዚያም በኋላ ነፍስዋ ልትወጣ ደረሰች፤ ሞትዋ በእርሱ ሆኖአልና ስሙን የጭንቀቴ ልጅ ብላ ጠራችው ፤ አባቱ ግን ብንያም አለው።'),
  ('139ee38f-61e7-5d50-acd3-1c7ad97bf2a9', '876cccf0-7a0a-544a-a3d2-008684634a88', 'da78492c-83ea-5452-a654-9e33979fc929', 4, 19, 'ራሔልም ሞተች፤ ወደ ኤፍራታም በምትወስድ መንገድ ተቀበረች፤ እርስዋም ቤተ ልሔም ናት።'),
  ('1c48ceee-dbf1-5fda-ac03-96ae5cc262e3', '876cccf0-7a0a-544a-a3d2-008684634a88', 'da78492c-83ea-5452-a654-9e33979fc929', 5, 20, 'ያዕቆብም በመቃብርዋ ላይ ሐውልት አቆመ፤ እርስዋም እስከ ዛሬ የራሔል የመቃብርዋ ሐውልት ትባላለች።'),
  ('55dcb087-d031-5bb7-aeb4-becd1ab5ca03', '876cccf0-7a0a-544a-a3d2-008684634a88', 'da78492c-83ea-5452-a654-9e33979fc929', 6, 21, 'ከዚህም በኋላ እስራኤል በዚያች ምድር ሳለ ሮቤል ሄደ፤ ከአባቱ ከያዕቆብ ዕቅብት ከባላ ጋርም ተኛ፤ እስራኤልም ሰማ። በፊቱም ክፉ ነገር ሆነ።'),
  ('0862b25e-04d9-52d1-a7ef-a83cae6ad6e0', '876cccf0-7a0a-544a-a3d2-008684634a88', '0c96a465-3075-5ffe-a755-0b938120ccd1', 1, 22, 'የያዕቆብም ልጆች ዐሥራ ሁለት ናቸው፤'),
  ('00a8082a-0c5d-539e-a7fb-b609bace964a', '876cccf0-7a0a-544a-a3d2-008684634a88', '0c96a465-3075-5ffe-a755-0b938120ccd1', 2, 23, 'የልያ ልጆች፤ የያዕቆብ በኵር ልጅ ሮቤል፥ ስምዖን፥ ሌዊ፥ ይሁዳ፥ ይሳኮር፥ ዛብሎን፤'),
  ('0334572a-4acc-5396-a852-25f7e82dda65', '876cccf0-7a0a-544a-a3d2-008684634a88', '0c96a465-3075-5ffe-a755-0b938120ccd1', 3, 24, 'የራሔል ልጆች፤ ዮሴፍ፥ ብንያም፤'),
  ('4b113b5f-1059-5565-a86b-abbf9b91132b', '876cccf0-7a0a-544a-a3d2-008684634a88', '0c96a465-3075-5ffe-a755-0b938120ccd1', 4, 25, 'የራሔል አገልጋይ የባላ ልጆችም፤ ዳን፥ ንፍታሌም፤'),
  ('548ab347-78b9-5e38-ae33-1c938b7d47dd', '876cccf0-7a0a-544a-a3d2-008684634a88', '0c96a465-3075-5ffe-a755-0b938120ccd1', 5, 26, 'የልያ አገልጋይ የዘለፋ ልጆችም፤ ጋድ፥ አሴር፤ እነዚህ በሁለቱ ወንዞች መካከል በሶርያ የተወለዱለት የያዕቆብ ልጆች ናቸው።'),
  ('3d8e9e6a-bc8b-5ef7-a93e-97b0a45e3377', '876cccf0-7a0a-544a-a3d2-008684634a88', 'c6417e32-a45c-5808-a096-62b398fc7176', 1, 27, 'ያዕቆብም ወደ አባቱ ወደ ይስሐቅ፥ አብርሃምና ይስሐቅ እንግዶች ሆነው ወደ ተቀመጡባት በአርባቅ ከተማ ወደምትገኘው ወደ መምሬ እርስዋም ኬብሮን ወደምትባለው መጣ።'),
  ('b13c4711-37b0-5030-a6e6-483c4941dfeb', '876cccf0-7a0a-544a-a3d2-008684634a88', 'c6417e32-a45c-5808-a096-62b398fc7176', 2, 28, 'የይስሐቅም ዕድሜ መቶ ሰማንያ ዓመት ሆነ።'),
  ('920ddffc-ebb3-50ba-af97-6d16de890bf7', '876cccf0-7a0a-544a-a3d2-008684634a88', 'c6417e32-a45c-5808-a096-62b398fc7176', 3, 29, 'ይስሐቅም ሸምግሎ ዕድሜንም ጠግቦ ሞተ፤ ወደ ወገኖቹም ተጨመረ፤ ልጆቹም ዔሳውና ያዕቆብ ቀበሩት።'),
  ('e227ca59-5510-56fb-a7b7-87ad93975637', '5eec3048-70de-5fd1-a55b-65213d3bdf81', '65280453-c4ed-5422-a44a-4cecfe3209e9', 1, 1, 'ኤዶም የተባለው የዔሳው ትውልድ እንዲህ ነው።'),
  ('34f0c847-b1f2-516c-a85b-66a4c78df78d', '5eec3048-70de-5fd1-a55b-65213d3bdf81', '65280453-c4ed-5422-a44a-4cecfe3209e9', 2, 2, 'ዔሳው ከከነዓን ልጆች ሚስቶችን አገባ፤ የኬጤያዊውን የዔሎን ልጅ ሐዳሶን፥ የኤውያዊው የሴቤሶ ልጅ ሐና የወለዳትን ኤሌባማን፥'),
  ('113571dc-ad4b-56e5-ae57-cf36cb5e431b', '5eec3048-70de-5fd1-a55b-65213d3bdf81', '65280453-c4ed-5422-a44a-4cecfe3209e9', 3, 3, 'የይስማኤልን ልጅ የናቡአት እኅት ቤሴሞትን።'),
  ('03a94905-ffce-5325-adef-321367b4eb61', '5eec3048-70de-5fd1-a55b-65213d3bdf81', '65280453-c4ed-5422-a44a-4cecfe3209e9', 4, 4, 'ሐዳሶ ለእርሱ ኤልፋዝን ወለደች፤ ቤሴሞትም ራጉኤልን ወለደች፤'),
  ('ef4ff609-ac06-592f-a519-e7aa0848fcdb', '5eec3048-70de-5fd1-a55b-65213d3bdf81', '65280453-c4ed-5422-a44a-4cecfe3209e9', 5, 5, 'ኤሌባማም ዮሔልን፥ ይጉሜልን፥ ቆሬንም ወለደች። በከነዓን ምድር የተወለዱለት የዔሳው ልጆች እነዚህ ናቸው።'),
  ('8bebf76c-6545-5f1e-af16-f9754d2a938f', '5eec3048-70de-5fd1-a55b-65213d3bdf81', '65280453-c4ed-5422-a44a-4cecfe3209e9', 6, 6, 'ዔሳውም ሚስቶቹን፥ ወንዶች ልጆቹንና ሴቶች ልጆቹን፥ ቤተ ሰቡንም ሁሉ፥ እንስሶቹንም ሁሉ፥ በከነዓንም ሀገር ያገኘውን ገንዘቡን ሁሉ ይዞ ከወንድሙ ከያዕቆብ ፊት ከከነዓን ሀገር ሄደ።'),
  ('0f45ae4e-2256-50d7-a628-48da56d952b3', '5eec3048-70de-5fd1-a55b-65213d3bdf81', '65280453-c4ed-5422-a44a-4cecfe3209e9', 7, 7, 'ከብታቸው ስለበዛ በአንድነት ይቀመጡ ዘንድ አልቻሉም፤ በእንግድነት የተቀመጡባትም ምድር ከከብታቸው ብዛት የተነሣ ልትበቃቸው አልቻለችም።'),
  ('483a8ab1-0432-5ae7-a1de-e05e724395ec', '5eec3048-70de-5fd1-a55b-65213d3bdf81', '65280453-c4ed-5422-a44a-4cecfe3209e9', 8, 8, 'ዔሳውም በሴይር ተራራ ተቀመጠ፤ ዔሳውም ኤዶም ነው።'),
  ('9bc390dd-c11b-55dc-a7f4-79c69efb57c2', '5eec3048-70de-5fd1-a55b-65213d3bdf81', '65280453-c4ed-5422-a44a-4cecfe3209e9', 9, 9, 'በሴይር ተራራ የሚኖሩ የኤዶማውያን አባት የዔሳው ትውልድም እንዲህ ነው።'),
  ('c1d87d6f-1114-5225-a8d1-92d7f76bf581', '5eec3048-70de-5fd1-a55b-65213d3bdf81', '65280453-c4ed-5422-a44a-4cecfe3209e9', 10, 10, 'የዔሳው ልጆች ስም ይህ ነው፤ የዔሳው ሚስት የሐዳሶ ልጅ ኤልፋዝ፤ የዔሳው ሚስት የቤሴሞት ልጅ ራጉኤል።'),
  ('fe95d41e-1d7a-54ab-a149-fd6913f27dd5', '5eec3048-70de-5fd1-a55b-65213d3bdf81', '65280453-c4ed-5422-a44a-4cecfe3209e9', 11, 11, 'የዔሳው ልጅ የኤልፋዝ ልጆችም እነዚህ ናቸው፤ ቴማን፥ ኤሞር፥ ሳፍር፥ ጎቶን፥ ቄኔዝ።'),
  ('81a59c83-30c3-5dab-a5b7-2b13de96e662', '5eec3048-70de-5fd1-a55b-65213d3bdf81', '65280453-c4ed-5422-a44a-4cecfe3209e9', 12, 12, 'ቴምናሕም ለዔሳው ልጅ ለኤልፋዝ ዕቅብት ነበረች፤ አማሌቅንም ለኤልፋዝ ወለደችለት፤ የዔሳውም ሚስት የሐዳሶ ልጆች እነዚህ ናቸው።'),
  ('9dbd2d8d-9cc5-56ad-a7ac-0d529e9d89f9', '5eec3048-70de-5fd1-a55b-65213d3bdf81', '65280453-c4ed-5422-a44a-4cecfe3209e9', 13, 13, 'የዔሳው ልጅ የራጉኤል ልጆችም እነዚህ ናቸው፤ ናሖት፥ ዛራ፥ ሲም፥ ሞዛህ፤ እነዚህም የዔሳው ሚስት የቤሴሞት ልጆች ናቸው።'),
  ('82ed5a66-f03a-56c0-a460-b63f8abaa093', '5eec3048-70de-5fd1-a55b-65213d3bdf81', '65280453-c4ed-5422-a44a-4cecfe3209e9', 14, 14, 'የሴቤጎን ልጅ የሐና ልጅ የዔሳው ሚስት የኤሌባማ ልጆች እነዚህ ናቸው፤ ለዔሳውም ዮሔልን፥ ዩጉሜልን፥ ቆሬን ወለደች።'),
  ('5cb8b6f4-9a15-5e97-a2a9-11fc45d9fd84', '5eec3048-70de-5fd1-a55b-65213d3bdf81', '65280453-c4ed-5422-a44a-4cecfe3209e9', 15, 15, 'የዔሳው ልጆች መሳፍንት እነዚህ ናቸው፤ የዔሳው የበኵር ልጅ የኤልፋዝ ልጆች፤ ቴማን መስፍን፥ ኦሜር መስፍን፥ ሳፍር መስፍን፥ ቄኔዝ መስፍን፥'),
  ('17cc87b4-eb16-59f6-a419-b94b269061da', '5eec3048-70de-5fd1-a55b-65213d3bdf81', '65280453-c4ed-5422-a44a-4cecfe3209e9', 16, 16, 'ቆሬ መስፍን፥ ጎቶን መስፍን፥ አማሌቅ መስፍን፤ በኤዶም ምድር የኤልፋዝ መሳፍንት እነዚህ ናቸው፤ እነዚህ የሓዳሶ ልጆች ናቸው ።'),
  ('6c290fd9-aaa0-5a7a-ab0d-7535c2d79fda', '5eec3048-70de-5fd1-a55b-65213d3bdf81', '65280453-c4ed-5422-a44a-4cecfe3209e9', 17, 17, 'የዔሳው ልጅ የራጉኤል ልጆች መሳፍንት እነዚህ ናቸው፤ ናሖት መስፍን፥ ዛራ መስፍን፥ ሲን መስፍን፥ ሞዛህ መስፍን፤ በኤዶም ምድር የራጉኤል ልጆች መሳፍንት እነዚህ ናቸው፤ እነዚህም የዔሳው ሚስት የቤሴሞት ልጆች ናቸው።'),
  ('acdca042-6417-581a-a7bb-016038bcd47c', '5eec3048-70de-5fd1-a55b-65213d3bdf81', '65280453-c4ed-5422-a44a-4cecfe3209e9', 18, 18, 'የዔሳው ሚስት የኤሌባማ ልጆች መሳፍንት እነዚህ ናቸው፤ ዮሔል መስፍን፥ ይጉሜል መስፍን፥ ቆሬ መስፍን፤ የዔሳው ሚስት የሐና ልጅ የኤሌባማ ልጆች መሳፍንት እነዚህ ናቸው።'),
  ('70c9891c-30fb-56ba-abb0-27fe74163d62', '5eec3048-70de-5fd1-a55b-65213d3bdf81', '65280453-c4ed-5422-a44a-4cecfe3209e9', 19, 19, 'የዔሳው ልጆችና መስፍኖቻቸው እነዚህ ናቸው፤ እነርሱም የኤዶም ልጆች ናቸው።'),
  ('761f2175-74d5-57c6-a231-39f1c65d4d97', '5eec3048-70de-5fd1-a55b-65213d3bdf81', 'ae44b9e0-e449-5046-a52e-2d893e51093d', 1, 20, 'በዚያች ሀገር የተቀመጡ የሖሪያዊው የሴይር ልጆች እነዚህ ናቸው፤ ሉጣን፥ ሦባን፥ ሳባቅ፥ አናም፥'),
  ('c7c3875f-d280-53e7-a932-b40b1e4c81c1', '5eec3048-70de-5fd1-a55b-65213d3bdf81', 'ae44b9e0-e449-5046-a52e-2d893e51093d', 2, 21, 'ዲሶን፥ ኤሶር፥ ዲሳን፤ እነዚህ በኤዶም ምድር የሖሪያዊው የሴይር ልጆች መሳፍንት ናቸው።'),
  ('9fa8e37e-d8dc-5b96-a2ca-41cb07fc65cb', '5eec3048-70de-5fd1-a55b-65213d3bdf81', 'ae44b9e0-e449-5046-a52e-2d893e51093d', 3, 22, 'የሉጣን ልጆችም እነዚህ ናቸው፤ ሖሪ፥ ሃማን ናቸው፤ የሉጣንም እኅት ትምናዕ ናት።'),
  ('15ecc52b-9e6b-57b6-aa95-0bc23140b4c9', '5eec3048-70de-5fd1-a55b-65213d3bdf81', 'ae44b9e0-e449-5046-a52e-2d893e51093d', 4, 23, 'የሦባን ልጆችም እነዚህ ናቸው፤ ዓልዋን፥ ማኔሐት፥ ኤቤል፥ ሳፋር፥ አውናም።'),
  ('9aa77d7a-15e4-57fd-a15a-edc6947d1c0b', '5eec3048-70de-5fd1-a55b-65213d3bdf81', 'ae44b9e0-e449-5046-a52e-2d893e51093d', 5, 24, 'የሳባቅ ልጆችም እነዚህ ናቸው፤ ኢኣ፥ ዓናን፤ ይህም ዓናን በምድረ በዳ የአባቱን የሳባቅን አህዮች ሲጠብቅ ፍል ውኃዎችን ያገኘ ነው።'),
  ('cf0fba44-9b86-5931-a54f-354abee0607c', '5eec3048-70de-5fd1-a55b-65213d3bdf81', 'ae44b9e0-e449-5046-a52e-2d893e51093d', 6, 25, 'የዓናን ልጆችም እነዚህ ናቸው፤ ዲሶን፤ የዓናን ሴት ልጅ ኤሌባማ።'),
  ('5c50b758-47be-572e-a13f-722b6658b1ed', '5eec3048-70de-5fd1-a55b-65213d3bdf81', 'ae44b9e0-e449-5046-a52e-2d893e51093d', 7, 26, 'የዲሶንም ልጆች እነዚህ ናቸው፤ ሕምዳን፥ አስባን፥ ቤዖር፥ ይትራን፥ ክራን።'),
  ('e2d77734-02d8-5c43-a4e7-c786e13bd207', '5eec3048-70de-5fd1-a55b-65213d3bdf81', 'ae44b9e0-e449-5046-a52e-2d893e51093d', 8, 27, 'የኤሶር ልጆችም እነዚህ ናቸው፤ ከልሐን፥ ዛኦን፥ ዓቃን።'),
  ('c03a7ec3-e9c1-51c0-ad7a-68c10f73d59e', '5eec3048-70de-5fd1-a55b-65213d3bdf81', 'ae44b9e0-e449-5046-a52e-2d893e51093d', 9, 28, 'የሪሶን ልጆችም እነዚህ ናቸው፤ ዑሳ፥ አራን።'),
  ('9f572c51-e2d9-5320-a97e-62d8bff91512', '5eec3048-70de-5fd1-a55b-65213d3bdf81', 'ae44b9e0-e449-5046-a52e-2d893e51093d', 10, 29, 'የሖሪ መሳፍንት እነዚህ ናቸው፤ ሉጣን መስፍን፥ ሦባን መስፍን፥ ሳባቅ መስፍን፥ ዓናን መስፍን፥'),
  ('601d7a05-d7fb-539c-a7f8-bce51abdec95', '5eec3048-70de-5fd1-a55b-65213d3bdf81', 'ae44b9e0-e449-5046-a52e-2d893e51093d', 11, 30, 'ዲሶን መስፍን፥ ኤሶር መስፍን፥ ሪሶን መስፍን፤ በሴይር ምድር በየሹመታቸው መሳፍንት የሆኑ የሖሪ መሳፍንት እነዚህ ናቸው።'),
  ('dfa1a667-4a51-5d25-ad7b-deff50f1ae5b', '5eec3048-70de-5fd1-a55b-65213d3bdf81', 'bc20037b-9a69-5866-a1ff-b3d6dd02cdee', 1, 31, 'በእስራኤል ልጆች ላይ ንጉሥ ከመንገሡ በፊት በኤዶም ሀገር የነገሡ ነገሥታት እነዚህ ናቸው።'),
  ('904270da-1175-5b17-a7b7-785f0c71dbf9', '5eec3048-70de-5fd1-a55b-65213d3bdf81', 'bc20037b-9a69-5866-a1ff-b3d6dd02cdee', 2, 32, 'በኤዶምም የቤዖር ልጅ ባላቅ ነገሠ፤ የከተማዋም ስም ዴናባ ናት።'),
  ('5e889e3a-da6c-583a-a176-1372c1ba5114', '5eec3048-70de-5fd1-a55b-65213d3bdf81', 'bc20037b-9a69-5866-a1ff-b3d6dd02cdee', 3, 33, 'ባላቅም ሞተ፤ በእርሱ ፈንታም የባሶራው የዛራ ልጅ ኢዮባብ ነገሠ።'),
  ('3b408205-0f8f-58a1-a516-4e5df31dd17f', '5eec3048-70de-5fd1-a55b-65213d3bdf81', 'bc20037b-9a69-5866-a1ff-b3d6dd02cdee', 4, 34, 'ኢዮባብም ሞተ፤ በእርሱም ፈንታ የቴማኒው ሀገር ሑሳም ነገሠ።'),
  ('c0ab6dbb-326c-5730-a7bb-0be26c7137a2', '5eec3048-70de-5fd1-a55b-65213d3bdf81', 'bc20037b-9a69-5866-a1ff-b3d6dd02cdee', 5, 35, 'ሑሳምም ሞተ፤ በእርሱም ፈንታ የምድያምን ሰዎች በሞዓብ ሜዳ የገደለ የቤዳድ ልጅ አዳድ ነገሠ፤ የከተማዋም ስም ዓዊት ተባለ።'),
  ('b48ee090-ca53-5556-acd9-1b7a5c5d858f', '5eec3048-70de-5fd1-a55b-65213d3bdf81', 'bc20037b-9a69-5866-a1ff-b3d6dd02cdee', 6, 36, 'ዓዳድም ሞተ፤ በእርሱም ፈንታ የምስሬቃው ሠምላ ነገሠ።'),
  ('4e5ddade-0185-5f25-ad5e-13391aab95c2', '5eec3048-70de-5fd1-a55b-65213d3bdf81', 'bc20037b-9a69-5866-a1ff-b3d6dd02cdee', 7, 37, 'ሠምላም ሞተ፤ በእርሱም ፈንታ በወንዝ አጠገብ ካለችው ከርኆቦት ሳኦል ነገሠ።'),
  ('919fc50f-f52f-5cae-aeb3-2c60aeec269d', '5eec3048-70de-5fd1-a55b-65213d3bdf81', 'bc20037b-9a69-5866-a1ff-b3d6dd02cdee', 8, 38, 'ሳኦልም ሞተ፤ በእርሱም ፈንታ የዓክቦር ልጅ በአልሐናን ነገሠ።'),
  ('96e6961b-e7e3-531f-a08e-1cfd045e982a', '5eec3048-70de-5fd1-a55b-65213d3bdf81', 'bc20037b-9a69-5866-a1ff-b3d6dd02cdee', 9, 39, 'የአክቦር ልጅ በአልሐናንም ሞተ፤ በእርሱም ፈንታ አዳር ነገሠ፤ የከተማውም ስም ፎጎር ነው፤ ሚስቱም የሜዛአብ ልጅ መጥሬድ የወለደቻት ምኤጠብኤል ትባላለች።'),
  ('60e59732-11e3-55d8-ab18-1d9b723d36c2', '5eec3048-70de-5fd1-a55b-65213d3bdf81', 'bc20037b-9a69-5866-a1ff-b3d6dd02cdee', 10, 40, 'የዔሳውም የመሳፍንቱ ስም በየነገዳቸው፥ በየስፍራቸው፥ በያገራቸውና በየሕዝባቸው ይህ ነው፤ ትምናዕ መስፍን፥ ዓልዋ መስፍን፥ ኤቴት መስፍን፥'),
  ('4b65c470-bf99-511f-a7e9-f7e5ef293229', '5eec3048-70de-5fd1-a55b-65213d3bdf81', 'bc20037b-9a69-5866-a1ff-b3d6dd02cdee', 11, 41, 'ኤሌባማ መስፍን፥ ኤላ መስፍን፥ ፊኖን መስፍን፥'),
  ('87049270-8b9c-5189-ad0b-ca50c25cc468', '5eec3048-70de-5fd1-a55b-65213d3bdf81', 'bc20037b-9a69-5866-a1ff-b3d6dd02cdee', 12, 42, 'ቄኔዝ መስፍን፥ ቴማን መስፍን፥ ሜብሳር መስፍን፥'),
  ('430e6870-cd68-5458-ab9d-803c8de98f73', '5eec3048-70de-5fd1-a55b-65213d3bdf81', 'bc20037b-9a69-5866-a1ff-b3d6dd02cdee', 13, 43, 'መግዴኤል መስፍን፥ ኤራም መስፍን፤ እነዚህ በግዛታቸው ምድር በየመኖሪያቸው የኤዶም መሳፍንት ናቸው። የኤዶማውያንም አባት ይህ ዔሳው ነው።'),
  ('966ba12a-2ecd-5c16-ad4f-2bfaace6939f', '9bce2b3b-dc73-57b6-ae6e-a6a7bc1d2257', '2c242f0c-26e0-5c37-a923-b64b8e3f1fe1', 1, 1, 'ያዕቆብም አባቱ በስደት በኖረበት ሀገር በከነዓን ምድር ተቀመጠ።'),
  ('38d37c6c-38bf-56e4-a689-ba2ca4aaef89', '9bce2b3b-dc73-57b6-ae6e-a6a7bc1d2257', '2c242f0c-26e0-5c37-a923-b64b8e3f1fe1', 2, 2, 'የያዕቆብም ትውልድ እንዲህ ነው። ዮሴፍ ዐሥራ ሰባት ዓመት በሆነው ጊዜ ከወንድሞቹ ጋር የአባቱን በጎች ይጠብቅ ነበር፤ እርሱም ከአባቱ ሚስቶች ከባላና ከዘለፋ ልጆች ጋር ሳለ ብላቴና ነበረ፤ ዮሴፍም የክፋታቸውን ወሬ ወደ አባታቸው ወደ እስራኤል ያመጣ ነበር።'),
  ('5218465f-f1ea-5ba5-a921-a81657bead57', '9bce2b3b-dc73-57b6-ae6e-a6a7bc1d2257', '2c242f0c-26e0-5c37-a923-b64b8e3f1fe1', 3, 3, 'ያዕቆብም ዮሴፍን ከልጆቹ ሁሉ ይልቅ ይወድደው ነበር፤ እርሱ በሽምግልናው የወለደው ነበርና። በብዙ ኅብር ያጌጠችም ቀሚስ አደረገለት።'),
  ('272c7909-3081-5989-a853-c4a83e6e21b3', '9bce2b3b-dc73-57b6-ae6e-a6a7bc1d2257', '2c242f0c-26e0-5c37-a923-b64b8e3f1fe1', 4, 4, 'ወንድሞቹም አባታቸው ከልጆቹ ሁሉ ይልቅ እንደሚወድደው በአዩ ጊዜ ጠሉት፤ በሰላም ይናገሩትም ዘንድ አልቻሉም።'),
  ('f60339fe-8ad4-50e3-a711-1904db687ed5', '9bce2b3b-dc73-57b6-ae6e-a6a7bc1d2257', '2c242f0c-26e0-5c37-a923-b64b8e3f1fe1', 5, 5, 'ዮሴፍም ሕልምን አለመ፤ ለወንድሞቹም ነገራቸው።'),
  ('64a9d1e0-62f7-5c6d-a429-b6fbc0690343', '9bce2b3b-dc73-57b6-ae6e-a6a7bc1d2257', '2c242f0c-26e0-5c37-a923-b64b8e3f1fe1', 6, 6, 'እርሱም አላቸው፥ “እኔ ያለምሁትን ሕልም ስሙ፤'),
  ('eb61f290-8ff9-5e14-ad38-f58b4a9ec483', '9bce2b3b-dc73-57b6-ae6e-a6a7bc1d2257', '2c242f0c-26e0-5c37-a923-b64b8e3f1fe1', 7, 7, 'እነሆ፥ እኛ በእርሻ መካከል ነዶ ስናስር ነበርና፥ እነሆ፥ የእኔ ነዶ ቀጥ ብላ ቆመች፤ የእናንተም ነዶዎች በዙርያ ከብበው እነሆ፥ ለእኔ ነዶ ሰገዱ።”'),
  ('31a6a833-1102-5ee6-a1e1-d73dc16b9ec0', '9bce2b3b-dc73-57b6-ae6e-a6a7bc1d2257', '2c242f0c-26e0-5c37-a923-b64b8e3f1fe1', 8, 8, 'ወንድሞቹም፥ “በእኛ ላይ ልትነግሥብን ይሆን? ወይስ ገዢ ትሆነን ይሆን?” አሉት። እንደገናም ስለ ሕልሙና ስለ ነገሩ የበለጠ ጠሉት።'),
  ('3abb994d-8f84-5d00-ab0f-9f2fd72a81c2', '9bce2b3b-dc73-57b6-ae6e-a6a7bc1d2257', '2c242f0c-26e0-5c37-a923-b64b8e3f1fe1', 9, 9, 'ደግሞም ሌላ ሕልምን አየ፤ ለአባቱና ለወንድሞቹም ነገራቸው፤ እንዲህም አለ፥ “እነሆ፥ ደግሞ ሌላ ሕልም አለምሁ፤ ሕልሙም እንዲህ ነው፦ ፀሐይና ጨረቃ ዐሥራ አንድ ከዋክብትም ይሰግዱልኝ ነበር።”'),
  ('72fe7e60-d19f-5fe0-a33a-979b61704710', '9bce2b3b-dc73-57b6-ae6e-a6a7bc1d2257', '2c242f0c-26e0-5c37-a923-b64b8e3f1fe1', 10, 10, 'አባቱም ገሠጸው፤ እንዲህም አለው፥ “ይህ ያለምኸው ሕልም ምንድን ነው? በውኑ እኔና እናትህ፥ ወንድሞችህም መጥተን በምድር ላይ እንሰግድልህ ይሆን?”'),
  ('203b5b32-8db9-5956-a103-13780d6ae08d', '9bce2b3b-dc73-57b6-ae6e-a6a7bc1d2257', '2c242f0c-26e0-5c37-a923-b64b8e3f1fe1', 11, 11, 'ወንድሞቹም ቀኑበት፤ አባቱ ግን ይህን ነገር በልቡ ይጠብቀው ነበር።'),
  ('fca2c005-c36a-57c6-ad79-61704a8b5f35', '9bce2b3b-dc73-57b6-ae6e-a6a7bc1d2257', '2fa8b99b-c3d3-5bbc-a605-135615babc7d', 1, 12, 'ወንድሞቹም በሴኬም የአባታቸውን በጎች ይጠብቁ ዘንድ ሄዱ።'),
  ('c0878f7b-62eb-5adf-af2d-6c595a46f914', '9bce2b3b-dc73-57b6-ae6e-a6a7bc1d2257', '2fa8b99b-c3d3-5bbc-a605-135615babc7d', 2, 13, 'እስራኤልም ዮሴፍን፥ “ወንድሞችህ በሴኬም በጎችን የሚጠብቁ አይደሉምን? ወደ እነርሱ እልክህ ዘንድ ና” አለው። እርሱም፥ “እሺ” አለው።'),
  ('14370bf3-6268-5d31-ab6e-85138591b6cb', '9bce2b3b-dc73-57b6-ae6e-a6a7bc1d2257', '2fa8b99b-c3d3-5bbc-a605-135615babc7d', 3, 14, 'እርሱም፥ “ሄደህ ወንድሞችህና በጎቹ ደኅና እንደ ሆኑ እይ፤ ወሬአቸውንም አምጣልኝ” አለው። ወደ ኬብሮንም ቆላ ላከው፤ ወደ ሴኬምም መጣ።'),
  ('dc1858a6-9d73-541f-af73-c2e421759ffb', '9bce2b3b-dc73-57b6-ae6e-a6a7bc1d2257', '2fa8b99b-c3d3-5bbc-a605-135615babc7d', 4, 15, 'እነሆም፥ በምድረ በዳ ሲቅበዘበዝ ሳለ አንድ ሰው አገኘው፤ ሰውየውም፥ “ምን ትፈልጋለህ?” ብሎ ጠየቀው።'),
  ('6b7d2c5b-a8af-50d0-a369-e4ce5a1b13d0', '9bce2b3b-dc73-57b6-ae6e-a6a7bc1d2257', '2fa8b99b-c3d3-5bbc-a605-135615babc7d', 5, 16, 'እርሱም፥ “ወንድሞችን እፈልጋለሁ፤ በጎቹን የሚጠብቁበት ወዴት እንደ ሆነ እባክህ ንገረኝ?” አለ።'),
  ('c46075bd-e29c-5d4e-ac8e-0783b4630821', '9bce2b3b-dc73-57b6-ae6e-a6a7bc1d2257', '2fa8b99b-c3d3-5bbc-a605-135615babc7d', 6, 17, 'ሰውየውም፥ “ከዚህ ተነሥተዋል፤ ወደ ዶታይን እንሂድ ሲሉም ሰምቼአቸዋለሁ” አለው። ዮሴፍም ወንድሞቹን ተከታትሎ ሄደ፤ በዶታይንም አገኛቸው።'),
  ('11c585c1-de4d-5faa-a05a-297788cf253f', '9bce2b3b-dc73-57b6-ae6e-a6a7bc1d2257', '2fa8b99b-c3d3-5bbc-a605-135615babc7d', 7, 18, 'እነርሱም ወደ እነርሱ ሳይቀርብ ከሩቅ አስቀድመው አዩት፥ ይገድሉትም ዘንድ በእርሱ ላይ ተማከሩ።'),
  ('6342f076-0e7b-5a47-ad34-d22943c27952', '9bce2b3b-dc73-57b6-ae6e-a6a7bc1d2257', '2fa8b99b-c3d3-5bbc-a605-135615babc7d', 8, 19, 'አንዱም ለአንዱ እንዲህ አለው፥ “ያ ባለ ሕልም ይኸው መጣ።'),
  ('bc2077fb-7b71-543e-ab1d-c81f5326de51', '9bce2b3b-dc73-57b6-ae6e-a6a7bc1d2257', '2fa8b99b-c3d3-5bbc-a605-135615babc7d', 9, 20, 'ኑ፥ እንግደለውና በአንድ ጕድጓድ ውስጥ እንጣለው፤ ክፉ አውሬም በላው እንላለን፤ ሕልሞቹም ምን እንደሚሆኑ እናያለን።”'),
  ('220e1e9a-53b2-53d3-a50f-43b612f00994', '9bce2b3b-dc73-57b6-ae6e-a6a7bc1d2257', '2fa8b99b-c3d3-5bbc-a605-135615babc7d', 10, 21, 'ሮቤልም ይህን ሰማ፤ ከእጃቸውም አዳነው፤ እንዲህም አለ፥ “ሕይወቱን አናጥፋ።”'),
  ('6902060b-b97f-5421-ac41-484fb3e6c9bf', '9bce2b3b-dc73-57b6-ae6e-a6a7bc1d2257', '2fa8b99b-c3d3-5bbc-a605-135615babc7d', 11, 22, 'ሮቤልም፥ “ደም አታፍስሱ፤ በዚች ምድረ በዳ ባለችው ጕድጓድ ጣሉት፤ ነገር ግን እጃችሁን አትጣሉበት” አላቸው። ሮቤልም እንዲህ ማለቱ ከእጃቸው ሊያድነውና ወደ አባቱ ሊመልሰው ነው።'),
  ('22b96f8c-0f27-58d8-ae30-71664e583f71', '9bce2b3b-dc73-57b6-ae6e-a6a7bc1d2257', '2fa8b99b-c3d3-5bbc-a605-135615babc7d', 12, 23, 'እንዲህም ሆነ፤ ዮሴፍ ወደ ወንድሞቹ በቀረበ ጊዜ የለበሳትን በብዙ ኅብር ያጌጠቺውን ቀሚሱን ገፈፉት፤'),
  ('0a89a03f-6f15-5424-aea3-b5f851d6d34c', '9bce2b3b-dc73-57b6-ae6e-a6a7bc1d2257', '2fa8b99b-c3d3-5bbc-a605-135615babc7d', 13, 24, 'ወስደውም ወደ ጕድጓድ ጣሉት፤ ጕድጓዱም ውኃ የሌለበት ባዶ ነበረ።'),
  ('80e86bd7-306c-5975-a84e-84d32f458e57', '9bce2b3b-dc73-57b6-ae6e-a6a7bc1d2257', '2fa8b99b-c3d3-5bbc-a605-135615babc7d', 14, 25, 'እንጀራም ሊበሉ ተቀመጡ፤ ዐይኖቻቸውንም በአነሡ ጊዜ እነሆ፥ ይስማኤላውያን ነጋድያን ከገለዓድ ሲመጡ አዩ፤ ግመሎቻቸውም ሽቱና በለሳን፥ ከርቤም ተጭነው ነበር። ወደ ግብፅ ሀገርም ሊያራግፉ ይሄዱ ነበር።'),
  ('674da1e4-b52f-56f0-a6d9-6a2938753a2a', '9bce2b3b-dc73-57b6-ae6e-a6a7bc1d2257', '2fa8b99b-c3d3-5bbc-a605-135615babc7d', 15, 26, 'ይሁዳም ወንድሞቹን እንዲህ አላቸው፥ “ወንድማችንን ገድለን ደሙን ብንሸሽግ ጥቅማችን ምንድን ነው?'),
  ('640cdbac-1e71-5cb1-acf6-152dc388b71a', '9bce2b3b-dc73-57b6-ae6e-a6a7bc1d2257', '2fa8b99b-c3d3-5bbc-a605-135615babc7d', 16, 27, 'ኑ፥ ለእነዚህ ይስማኤላውያን እንሽጠው፤ እጃችንን ግን በእርሱ ላይ አንጣል፤ ወንድማችን ሥጋችን ነውና።” ወንድሞቹም የነገራቸውን ሰሙት።'),
  ('bfd992cf-da44-536f-acb4-c67a9d8451e6', '9bce2b3b-dc73-57b6-ae6e-a6a7bc1d2257', '2fa8b99b-c3d3-5bbc-a605-135615babc7d', 17, 28, 'እነዚያ ይስማኤላውያን ነጋዴዎችም ሲያልፉ ወንድሞቹ ዮሴፍን ከጕድጓድ ጐትተው አወጡት፤ ለይስማኤላውያንም ዮሴፍን በሃያ ብር ሸጡት፤ እነርሱም ዮሴፍን ወደ ግብፅ ወሰዱት።'),
  ('60241779-f8d7-5f83-a36a-1fbe5e7812fc', '9bce2b3b-dc73-57b6-ae6e-a6a7bc1d2257', '2fa8b99b-c3d3-5bbc-a605-135615babc7d', 18, 29, 'ሮቤልም ወደ ጕድጓዱ ተመለሰ፤ እነሆም፥ ዮሴፍን ከጕድጓድ በአጣው ጊዜ ልብሱን ቀደደ።'),
  ('cc4dea48-a706-5de2-acef-bfec912036d0', '9bce2b3b-dc73-57b6-ae6e-a6a7bc1d2257', '2fa8b99b-c3d3-5bbc-a605-135615babc7d', 19, 30, 'ሮቤልም ወደ ወንድሞቹ ተመልሶ፥ “ብላቴናው በጕድጓድ የለም፤ እንግዲህ እኔ ወዴት እሄዳለሁ?” አለ።'),
  ('1a7ac70c-d81c-5980-a31e-3ac6a0698d47', '9bce2b3b-dc73-57b6-ae6e-a6a7bc1d2257', '2fa8b99b-c3d3-5bbc-a605-135615babc7d', 20, 31, 'የዮሴፍንም ቀሚስ ወሰዱ፤ የፍየልም ጠቦት አርደው ቀሚሱን በደም ነከሩት።'),
  ('32aed9af-8ba3-5a78-aaa0-90fa3cd47b2a', '9bce2b3b-dc73-57b6-ae6e-a6a7bc1d2257', '2fa8b99b-c3d3-5bbc-a605-135615babc7d', 21, 32, 'ብዙ ኅብር ያለበትን ቀሚሱንም ላኩ፤ ወደ አባታቸውም አገቡት፤ እንዲህም አሉት፥ “ይህን ልብስ አገኘን፤ ይህ የልጅህ ልብስ እንደ ሆነ ወይም እንዳልሆነ እስኪ እየው?”'),
  ('dc688d12-15fc-52e2-a1cf-af854c26e824', '9bce2b3b-dc73-57b6-ae6e-a6a7bc1d2257', '2fa8b99b-c3d3-5bbc-a605-135615babc7d', 22, 33, 'እርሱም ዐውቆ፥ “የልጄ ቀሚስ ነው፤ ክፉ አውሬ በልቶታል፤ ዮሴፍን ቦጫጭቆታል” አለ።'),
  ('9bad37d5-da3e-5b79-ab1e-508bfcc59049', '9bce2b3b-dc73-57b6-ae6e-a6a7bc1d2257', '2fa8b99b-c3d3-5bbc-a605-135615babc7d', 23, 34, 'ያዕቆብም ልብሱን ቀደደ፤ በወገቡም ማቅ ታጥቆ ለልጁ ብዙ ቀን አለቀሰ።'),
  ('95beda43-9075-5ea3-a6b4-89114651e3e2', '9bce2b3b-dc73-57b6-ae6e-a6a7bc1d2257', '2fa8b99b-c3d3-5bbc-a605-135615babc7d', 24, 35, 'ወንዶች ልጆቹና ሴቶች ልጆቹ ሁሉ ተሰብስበው መጡ። ኀዘኑንም ያስተዉት ዘንድ አባታቸውን ማለዱት። ኀዘኑንም መተውን እንቢ አለ፥ እንዲህም አላቸው፥ “ወደ ልጄ ወደ መቃብር እያዘንሁ እወርዳለሁ።” አባቱም ስለ እርሱ አለቀሰ።'),
  ('8f8b0921-2db5-5ced-a155-9adc3231f4ad', '9bce2b3b-dc73-57b6-ae6e-a6a7bc1d2257', '2fa8b99b-c3d3-5bbc-a605-135615babc7d', 25, 36, 'እነዚያ ይስማኤላውያን ሰዎች ግን ዮሴፍን በግብፅ ለፈርዖን ጃንደረባ ለዘበኞቹ አለቃ ለጲጥፋራ ሸጡት።'),
  ('222ee3aa-8636-57ef-a69d-13c1cf52d74f', '5f1cf3e1-01c8-5ab6-ad81-f8d3476f16d4', '038dcabf-588a-5411-a4a0-3105f94a1bd0', 1, 1, 'በዚያም ወራት እንዲህ ሆነ፤ ይሁዳ ከወንድሞቹ ተለይቶ ወረደ፤ ስሙ ኤራስ በሚባል በዓዶሎማዊውም ሰው ዘንድ አደረ።'),
  ('5c91958d-f077-5c8c-a427-ea9b3b6e3672', '5f1cf3e1-01c8-5ab6-ad81-f8d3476f16d4', '038dcabf-588a-5411-a4a0-3105f94a1bd0', 2, 2, 'ከዚያም ይሁዳ ያንድ ከነዓናዊ ሰው ሴት ልጅን አየ፤ ስምዋም ሴዋ ይባላል። ወሰዳትም፤ ወደ እርስዋም ገባ።'),
  ('9a5292c7-8636-51be-a9c7-96867537697b', '5f1cf3e1-01c8-5ab6-ad81-f8d3476f16d4', '038dcabf-588a-5411-a4a0-3105f94a1bd0', 3, 3, 'ፀነሰችም፤ ወንድ ልጅንም ወለደች፤ ስሙንም ዔር ብላ ጠራችው።'),
  ('1cda2c50-c201-5a0a-ac9e-51faa68a877f', '5f1cf3e1-01c8-5ab6-ad81-f8d3476f16d4', '038dcabf-588a-5411-a4a0-3105f94a1bd0', 4, 4, 'ደግሞም ፀነሰች፤ ወንድ ልጅንም ወለደች፤ ስሙንም አውናን ብላ ጠራችው።'),
  ('070ed26d-239c-5935-a8ed-a0e48015f923', '5f1cf3e1-01c8-5ab6-ad81-f8d3476f16d4', '038dcabf-588a-5411-a4a0-3105f94a1bd0', 5, 5, 'እንደገና ደግሞ ወንድ ልጅን ወለደች፤ ስሙንም ሴሎም ብላ ጠራችው፤ እነርሱንም በወለደች ጊዜ ኬሴቢ በሚባል ሀገር ነበረች።'),
  ('37f96686-5a9b-5d2e-aa12-c6a556e0aa20', '5f1cf3e1-01c8-5ab6-ad81-f8d3476f16d4', '038dcabf-588a-5411-a4a0-3105f94a1bd0', 6, 6, 'ይሁዳም ለበኵር ልጁ ለዔር ትዕማር የምትባል ሚስት አጋባው።'),
  ('4b7f1c37-202b-57b1-a8a8-1b709a1f8686', '5f1cf3e1-01c8-5ab6-ad81-f8d3476f16d4', '038dcabf-588a-5411-a4a0-3105f94a1bd0', 7, 7, 'የይሁዳም የበኵር ልጅ ዔር በእግዚአብሔር ፊት ክፉ ነበረ፤ እግዚአብሔርም ቀሠፈው።'),
  ('c3b72ed3-61ad-57e1-a649-158ca690c933', '5f1cf3e1-01c8-5ab6-ad81-f8d3476f16d4', '038dcabf-588a-5411-a4a0-3105f94a1bd0', 8, 8, 'ይሁዳም አውናንን፥ “ወደ ወንድምህ ሚስት ግባ፤ አግባትም፤ ለወንድምህም ዘርን አቁምለት” አለው።'),
  ('3cdbbde6-1421-52f7-acf5-439f6f1e8641', '5f1cf3e1-01c8-5ab6-ad81-f8d3476f16d4', '038dcabf-588a-5411-a4a0-3105f94a1bd0', 9, 9, 'አውናንም ዘሩ ለእርሱ እንዳይሆን ዐወቀ፤ ወደ ወንድሙ ሚስትም በገባ ጊዜ ለወንድሙ ዘር እንዳይተካ ዘሩን በምድር ያፈስሰው ነበር።'),
  ('a4d2a7e6-8aac-580c-aac8-068372edbb0d', '5f1cf3e1-01c8-5ab6-ad81-f8d3476f16d4', '038dcabf-588a-5411-a4a0-3105f94a1bd0', 10, 10, 'ይህም ሥራው በእግዚአብሔር ዘንድ ክፉ ሆነበት፤ እንዲህ አድርጎአልና እርሱንም ደግሞ ቀሠፈው።'),
  ('2d5eaff2-3205-5992-a7ca-95a0365ec261', '5f1cf3e1-01c8-5ab6-ad81-f8d3476f16d4', '038dcabf-588a-5411-a4a0-3105f94a1bd0', 11, 11, 'ይሁዳም ምራቱን ትዕማርን፥ “ልጄ ሴሎም እስኪያድግ ድረስ በአባትሽ ቤት መበለት ሆነሽ ተቀመጪ” አላት፤ እርሱ ደግሞ እንደ ወንድሞቹ እንዳይሞትብኝ ብሎአልና። ትዕማርም ሄዳ በአባቷ ቤት ተቀመጠች።'),
  ('697f8c6d-8c7d-57f2-a61c-acccbdb9321f', '5f1cf3e1-01c8-5ab6-ad81-f8d3476f16d4', '038dcabf-588a-5411-a4a0-3105f94a1bd0', 12, 12, 'ዘመንዋም በተፈጸመ ጊዜ የይሁዳ ሚስት ሴዋ ሞተች፤ ይሁዳም ተጽናና፤ የበጎቹን ጠጕር ወደሚሸልቱት ሰዎችም ወደ ተምና ወጣ፤ እርሱም ዓዶሎማዊው በግ ጠባቂው ኤራስም።'),
  ('10db9e37-58e6-52c2-a8be-64c1e49a733f', '5f1cf3e1-01c8-5ab6-ad81-f8d3476f16d4', '038dcabf-588a-5411-a4a0-3105f94a1bd0', 13, 13, 'ለምራቱ ትዕማርም፥ “እነሆ፥ አማትሽ ይሁዳ የበጎቹን ጠጕር ይሸልት ዘንድ ወደ ተምና ይወጣል” ብለው ነገሩአት።'),
  ('734f5795-14f1-56c1-a0ce-b00a04319fbb', '5f1cf3e1-01c8-5ab6-ad81-f8d3476f16d4', '038dcabf-588a-5411-a4a0-3105f94a1bd0', 14, 14, 'እርስዋም የመበለትነቷን ልብስ አወለቀች፤ መጐናጸፊያዋንም ለበሰች፤ ተሸፈነችም፤ ወደ ተምናም በሚወስደው መንገድ ዳር በኤናይም ደጅ ተቀመጠች፤ ሴሎም እንደ አደገ፥ ሚስትም ትሆነው ዘንድ እርስዋን ሊሰጠው እንዳልፈለገ አይታለችና።'),
  ('c1b3d685-bb5d-5740-ae5c-75e35fe10915', '5f1cf3e1-01c8-5ab6-ad81-f8d3476f16d4', '038dcabf-588a-5411-a4a0-3105f94a1bd0', 15, 15, 'ይሁዳም በአያት ጊዜ ዘማ መሰለችው፤ ፊቷን ተሸፍና ነበርና አላወቃትም።'),
  ('467c51ad-344e-5f5f-a03b-579e2c5c1a5b', '5f1cf3e1-01c8-5ab6-ad81-f8d3476f16d4', '038dcabf-588a-5411-a4a0-3105f94a1bd0', 16, 16, 'ወደ እርስዋም አዘነበለ፥ “እባክሽ ወደ አንቺ ልግባ አላት፤” እርስዋ ምራቱ እንደ ሆነች አላወቀም ነበርና። እርስዋም፥ “ወደ እኔ ብትገባ ምን ትሰጠኛለህ?” አለችው።'),
  ('7116b8ea-a4d9-5fed-a4ef-e7af7ad9aed8', '5f1cf3e1-01c8-5ab6-ad81-f8d3476f16d4', '038dcabf-588a-5411-a4a0-3105f94a1bd0', 17, 17, '“የፍየል ጠቦት ከመንጋዬ እልክልሻለሁ” አላት። እርስዋም፥ “እስክትልክልኝ ድረስ መያዣ ስጠኝ” አለችው።'),
  ('249b6f7d-1006-5fcc-a03b-966840c6377f', '5f1cf3e1-01c8-5ab6-ad81-f8d3476f16d4', '038dcabf-588a-5411-a4a0-3105f94a1bd0', 18, 18, 'እርሱም፥ “ምን መያዣ ልስጥሽ?” አላት። እርስዋም፥ “ቀለበትህን፥ ኩፌትህን፥ በእጅህ ያለውን በትር” አለች። እርሱም ሰጣትና ከእርስዋ ደረሰ፤ እርስዋም ፀነሰችለት።'),
  ('631f450b-d941-5e30-ab8a-01ae2ff25465', '5f1cf3e1-01c8-5ab6-ad81-f8d3476f16d4', '038dcabf-588a-5411-a4a0-3105f94a1bd0', 19, 19, 'እርስዋም ተነሥታ ሄደች፤ መጐናጸፊያዋንም አውልቃ የመበለትነቷን ልብስ ለበሰች።'),
  ('e5eb6274-79ca-5f76-af3d-0ed266c1d0f3', '5f1cf3e1-01c8-5ab6-ad81-f8d3476f16d4', '038dcabf-588a-5411-a4a0-3105f94a1bd0', 20, 20, 'ይሁዳም መያዣውን ከሴቲቱ እጅ ይቀበል ዘንድ በበግ ጠባቂው በዓዶሎማዊው እጅ የፍየሉን ጠቦት ላከላት፤ እርስዋንም አላገኛትም።'),
  ('f6123746-d950-5925-a150-eae48f1ea275', '5f1cf3e1-01c8-5ab6-ad81-f8d3476f16d4', '038dcabf-588a-5411-a4a0-3105f94a1bd0', 21, 21, 'እርሱም የሀገሩን ሰዎች፥ “በኤናይም በመንገድ ዳር ተቀምጣ የነበረች ዘማ ወዴት ናት?” ብሎ ጠየቃቸው። እነርሱም፥ “በዚህ ዘማ አልነበረችም” አሉት።'),
  ('0ebc6dde-aaab-597d-a827-ab4f14d47d17', '5f1cf3e1-01c8-5ab6-ad81-f8d3476f16d4', '038dcabf-588a-5411-a4a0-3105f94a1bd0', 22, 22, 'ወደ ይሁዳም ተመልሶ እንዲህ አለው፥ “አላገኘኋትም፤ የሀገሩ ሰዎች ደግሞ፦ ከዚህ ዘማ የለችም” አሉኝ።'),
  ('0dffcce6-fd7b-5ae7-a476-bb3c9daba9c1', '5f1cf3e1-01c8-5ab6-ad81-f8d3476f16d4', '038dcabf-588a-5411-a4a0-3105f94a1bd0', 23, 23, 'ይሁዳም፥ “እኛ መዘበቻ እንዳንሆን ትውሰደው፤ እነሆ፥ የፍየሉን ጠቦት ላክሁላት፤ አንተም አላገኘሃትም” አለ።'),
  ('93d4cee5-5d3d-58f9-a915-5b8145981ef5', '5f1cf3e1-01c8-5ab6-ad81-f8d3476f16d4', '038dcabf-588a-5411-a4a0-3105f94a1bd0', 24, 24, 'እንዲህም ሆነ፤ ከሦስት ወር በኋላ ለይሁዳ፥ “ምራትህ ትዕማር ሴሰነች፤ እነሆ፥ በዝሙት ፀነሰች” ብለው ነገሩት። ይሁዳም፥ “አውጡአትና በእሳት ትቃጠል” አለ።'),
  ('008a3269-468a-5544-af99-f2d4e217821c', '5f1cf3e1-01c8-5ab6-ad81-f8d3476f16d4', '038dcabf-588a-5411-a4a0-3105f94a1bd0', 25, 25, 'እርስዋም ሲወስዱአት ወደ አማቷ እንዲህ ብላ ላከች፤ “ተመልከት፦ ይህ ቀለበት፥ ይህ ኩፌት፥ ይህ በትር የማን ነው? ይህስ ፅንስ የማን ነው?”'),
  ('ac796a11-1bd4-5a92-a8d6-fda49460f948', '5f1cf3e1-01c8-5ab6-ad81-f8d3476f16d4', '038dcabf-588a-5411-a4a0-3105f94a1bd0', 26, 26, 'ይሁዳም አይቶ “ከእኔ ይልቅ ትዕማር እውነተኛ ሆነች፤ ልጄን ሴሎምን አልሰጠኋትምና” አለ። ትገደል ማለትንም ተወ፤ ደግሞም አላወቃትም።'),
  ('ba2791e9-ba9f-5c7b-a8cf-db05e5b06833', '5f1cf3e1-01c8-5ab6-ad81-f8d3476f16d4', '038dcabf-588a-5411-a4a0-3105f94a1bd0', 27, 27, 'መውለጃዋም በደረሰ ጊዜ እነሆ፥ መንታ ልጆች በሆድዋ ነበሩ።'),
  ('0a194259-7c5d-53b4-a7c5-6c244cd17af7', '5f1cf3e1-01c8-5ab6-ad81-f8d3476f16d4', '038dcabf-588a-5411-a4a0-3105f94a1bd0', 28, 28, 'ስትወልድም አንዱ እጁን አወጣ፤ አዋላጂቱም ቀይ ፈትል ወስዳ በእጁ አሰረች፥ “ይህ መጀመሪያ ይወጣል” አለች።'),
  ('d76ef462-231b-574b-a23b-8fed40c27bff', '5f1cf3e1-01c8-5ab6-ad81-f8d3476f16d4', '038dcabf-588a-5411-a4a0-3105f94a1bd0', 29, 29, 'እንዲህም ሆነ፤ እጁን በመለሰ ጊዜ እነሆ፥ ወንድሙ ወጣ፤ እርስዋም፥ “ለምን ጥሰህ ወጣህ? ስትል ስሙን ፋሬስ” ብላ ጠራችው።'),
  ('739dd707-e5fa-5bc1-a74f-b493bf95aacf', '5f1cf3e1-01c8-5ab6-ad81-f8d3476f16d4', '038dcabf-588a-5411-a4a0-3105f94a1bd0', 30, 30, 'ከእርሱም በኋላ ቀይ ፈትል በእጁ ያለበት ወንድሙ ወጣ፤ ስሙም ዛራ ተባለ።'),
  ('1a3fe50b-b6c1-5fde-a2cb-639685efabdd', '671a7c2c-7ae7-53ef-adec-ec637f557578', 'b64f0b12-18c3-5246-abe2-2755d7137ddc', 1, 1, 'ዮሴፍ ግን ወደ ግብፅ ወረደ፤ የፈርዖን ጃንደረባ የመጋቢዎቹም አለቃ የሚሆን የግብፅ ሰው ጲጥፋራ ወደ ግብፅ ከአወረዱት ከይስማኤላውያን እጅ ገዛው።'),
  ('13c0f0d8-108e-585c-a794-a25621507b1c', '671a7c2c-7ae7-53ef-adec-ec637f557578', 'b64f0b12-18c3-5246-abe2-2755d7137ddc', 2, 2, 'እግዚአብሔርም ከዮሴፍ ጋር ነበር፤ ሥራውም የተከናወነለት ሰው ሆነ፤ በግብፃዊው ጌታውም ቤት ተሾመ።'),
  ('e624ebab-0ee6-59d0-a72b-31dd16c4f2a8', '671a7c2c-7ae7-53ef-adec-ec637f557578', 'b64f0b12-18c3-5246-abe2-2755d7137ddc', 3, 3, 'ጌታውም እግዚአብሔር ከዮሴፍ ጋር እንዳለ፥ እርሱ የሚሠራውንም ሁሉ እግዚአብሔር በእጁ እንዲያከናውንለት አየ።'),
  ('229de87c-49e4-5771-ae4c-0304671ab343', '671a7c2c-7ae7-53ef-adec-ec637f557578', 'b64f0b12-18c3-5246-abe2-2755d7137ddc', 4, 4, 'ዮሴፍም በጌታው ፊት ሞገስን አገኘ፤ እርሱንም ደስ ያሰኘው ነበር፤ በቤቱም ላይ ሾመው፤ ያለውንም ሁሉ በእጁ ሰጠው።'),
  ('e0d24436-90ba-5fad-a089-e94446302242', '671a7c2c-7ae7-53ef-adec-ec637f557578', 'b64f0b12-18c3-5246-abe2-2755d7137ddc', 5, 5, 'እንዲህም ሆነ፤ በቤቱ ባለውም ሁሉ ላይ ከሾመው በኋላ እግዚአብሔር የግብፃዊውን ቤት በዮሴፍ ምክንያት ባረከው። የእግዚአብሔርም በረከት በቤቱም፥ በእርሻውም ባለው ሁሉ ላይ ሆነ።'),
  ('0841072a-ff30-5a3d-a525-8933b23ede88', '671a7c2c-7ae7-53ef-adec-ec637f557578', 'b64f0b12-18c3-5246-abe2-2755d7137ddc', 6, 6, 'ያለውንም ሁሉ ለዮሴፍ በእጁ አስረከበው፤ ከሚበላውም እንጀራ በቀር ምንም የሚያውቀው አልነበረም። ዮሴፍም መልኩ ያማረ፥ ፊቱም እጅግ የተዋበ ነበር።'),
  ('e9d31107-9ca8-5dab-ab3d-23fdcc45ade4', '671a7c2c-7ae7-53ef-adec-ec637f557578', 'b64f0b12-18c3-5246-abe2-2755d7137ddc', 7, 7, 'ከዚህም በኋላ እንዲህ ሆነ፤ የጌታው ሚስት በዮሴፍ ላይ ዐይንዋን ጣለችበት፤ “ከእኔም ጋር ተኛ” አለችው።'),
  ('2fff0ec0-e9e9-5df3-ab45-405a925c03e3', '671a7c2c-7ae7-53ef-adec-ec637f557578', 'b64f0b12-18c3-5246-abe2-2755d7137ddc', 8, 8, 'እርሱም እንቢ አለ፤ ለጌታውም ሚስት እንዲህ አላት፥ “እነሆ፥ ጌታዬ በቤቱ ያለውን ሁሉ ለእኔ በእጄ አስረክቦኛል፤ በቤቱ ያለውንም ምንም የሚያውቀው የለም፤'),
  ('5d206829-f572-5d12-a430-9cd4d1cc8cae', '671a7c2c-7ae7-53ef-adec-ec637f557578', 'b64f0b12-18c3-5246-abe2-2755d7137ddc', 9, 9, 'በዚህ ቤት ከእኔ የሚበልጥ ሰው የለም፤ ሚስቱ ስለሆንሽ ከአንቺ በቀር ያልሰጠኝ ነገር የለም፤ እንዴት ይህን ትልቅ ክፉ ነገር አደርጋለሁ? በእግዚአብሔር ፊት እንዴት ኀጢአትን እሠራለሁ?”'),
  ('0aa68760-f35c-50ca-a455-3682030580f5', '671a7c2c-7ae7-53ef-adec-ec637f557578', 'b64f0b12-18c3-5246-abe2-2755d7137ddc', 10, 10, 'ይህንም ነገር በየዕለቱ ለዮሴፍ ትነግረው ነበር፤ እርሱም ከእርስዋ ጋር ይተኛ ዘንድ፥ ከእርስዋም ጋር ይሆን ዘንድ አልሰማትም።'),
  ('d63bce75-c0f8-57ca-a932-c3e1a4dbde67', '671a7c2c-7ae7-53ef-adec-ec637f557578', 'b64f0b12-18c3-5246-abe2-2755d7137ddc', 11, 11, 'በአንዲትም ቀን እንዲህ ሆነ፤ በዚያ ቀን ሥራውን እንዲሠራ ዮሴፍ ወደ ቤቱ ገባ፤ በቤትም ውስጥ ከቤተ ሰዎች ማንም አልነበረም።'),
  ('9c20be86-6222-5431-a7ae-461554dd3ca6', '671a7c2c-7ae7-53ef-adec-ec637f557578', 'b64f0b12-18c3-5246-abe2-2755d7137ddc', 12, 12, 'ልብሱን ይዛ፥ “ና ከእኔ ጋር ተኛ” አለችው፤ እርሱም ልብሱን በእጅዋ ትቶላት ሸሸ፤ ወደ ውጭም ወጣ።'),
  ('e8fa0748-e198-587f-aa14-3bac821b9042', '671a7c2c-7ae7-53ef-adec-ec637f557578', 'b64f0b12-18c3-5246-abe2-2755d7137ddc', 13, 13, 'እንዲህም ሆነ፤ ልብሱን ትቶ ወደ ውጭ እንደ ሸሸ በአየች ጊዜ፥'),
  ('eaef7464-8498-5b26-ab27-fa91e4a85d1b', '671a7c2c-7ae7-53ef-adec-ec637f557578', 'b64f0b12-18c3-5246-abe2-2755d7137ddc', 14, 14, 'የቤቷን ሰዎች ወደ እርስዋ ጠርታ እንዲህ ብላ ነገረቻቸው፥ “እዩ፤ ይህ ዕብራዊ ባርያ በእኛ እንዲሣለቅ አመጣብን፤ እርሱ ወደ እኔ ገብቶ ከእኔ ጋር ተኚ አለኝ፤ እኔም ድምፄን ከፍ አድርጌ ጮኽሁ፤'),
  ('59b4271d-fc4c-5eee-a415-34844b3c5cca', '671a7c2c-7ae7-53ef-adec-ec637f557578', 'b64f0b12-18c3-5246-abe2-2755d7137ddc', 15, 15, 'ድምፄንም ከፍ አድርጌ እንደ ጮኽሁ ቢሰማ፥ ልብሱን በእኔ ዘንድ ጥሎ ሸሸ፤ ወደ ውጭም ወጣ።”'),
  ('ed6802b0-2cc8-5225-ab7c-f680abe8cee6', '671a7c2c-7ae7-53ef-adec-ec637f557578', 'b64f0b12-18c3-5246-abe2-2755d7137ddc', 16, 16, 'ጌታው ወደ ቤቱ እስኪገባ ድረስም ልብሱን ከእርስዋ ዘንድ አኖረች።'),
  ('35201670-c530-5758-aa99-24c44b49a26e', '671a7c2c-7ae7-53ef-adec-ec637f557578', 'b64f0b12-18c3-5246-abe2-2755d7137ddc', 17, 17, 'ይህንም ነገር እንዲህ ብላ ነገረችው፥ “ያመጣኸው ዕብራዊው ባሪያ ሊሣለቅብኝ ወደ እኔ ገባ፤ ከአንቺም ጋር ልተኛ አለኝ።'),
  ('d4b17a93-7508-5c95-ac41-1da2fe651521', '671a7c2c-7ae7-53ef-adec-ec637f557578', 'b64f0b12-18c3-5246-abe2-2755d7137ddc', 18, 18, 'እኔም ድምፄን ከፍ አድርጌ ስጮኽ ልብሱን በእጄ ተወና ወደ ውጭ ሸሸ።”'),
  ('beac1f41-f17b-5a1d-a079-708154b20ee3', '671a7c2c-7ae7-53ef-adec-ec637f557578', 'b64f0b12-18c3-5246-abe2-2755d7137ddc', 19, 19, 'ጌታውም፥ “ባሪያህ እንዲህ አደረገኝ” ብላ የነገረችውን የሚስቱን ቃል በሰማ ጊዜ እጅግ ተቈጣ።'),
  ('7ec96c43-ed1f-5420-ac9c-af0bde594be6', '671a7c2c-7ae7-53ef-adec-ec637f557578', 'b64f0b12-18c3-5246-abe2-2755d7137ddc', 20, 20, 'ዮሴፍንም ወሰደው፤ የንጉሡ እስረኞች ወደሚታሰሩበት ስፍራ ወደ ግዞት ቤትም አገባው፤ ከዚያም በግዞት ነበረ።'),
  ('669d9b06-e523-5e30-a49e-6be807c1eb9e', '671a7c2c-7ae7-53ef-adec-ec637f557578', 'b64f0b12-18c3-5246-abe2-2755d7137ddc', 21, 21, 'እግዚአብሔርም ከዮሴፍ ጋር ነበረ፤ ምሕረትንም አበዛለት፤ በግዞት ቤቱም አለቃ ፊት ሞገስን ሰጠው።'),
  ('19c1bee3-87d4-58c3-ac1e-a56a8d5b5287', '671a7c2c-7ae7-53ef-adec-ec637f557578', 'b64f0b12-18c3-5246-abe2-2755d7137ddc', 22, 22, 'የግዞት ቤቱም አለቃ በግዞት ያሉትን እስረኞች ሁሉ በዮሴፍ እጅ አሳልፎ ሰጣቸው፤ በዚያም የሚደረገው ነገር ሁሉ እርሱ የሚያደርገው ነበረ።'),
  ('9c4b78a3-cb33-5c01-ada7-837d5bc8f880', '671a7c2c-7ae7-53ef-adec-ec637f557578', 'b64f0b12-18c3-5246-abe2-2755d7137ddc', 23, 23, 'የግዞት ቤቱ ጠባቂዎች አለቃም በግዞት ቤት የሚደረገውን ሁሉ ምንም አያውቅም ነበር፤ ሁሉን ለዮሴፍ ትቶለት ነበር፤ እግዚአብሔርም ከእርሱ ጋር ነበረና፤ የሚያደርገውንም ሁሉ እግዚአብሔር በእጁ ያቀናለት ነበር።'),
  ('0e436689-3a51-527b-ace6-1ea2e6840584', '4af2812e-ef07-511d-a34e-0b9b3a9b2e60', 'bd652047-78bf-56b3-a52f-2a34c8f5969f', 1, 1, 'ከዚህ ነገር በኋላም እንዲህ ሆነ፤ የግብፅ ንጉሥ የጠጅ አሳላፊዎች አለቃና የእንጀራ አበዛዎች አለቃ ጌታቸውን የግብፅ ንጉሥን በደሉ።'),
  ('56bb67de-9a64-5331-a05b-03588213aaca', '4af2812e-ef07-511d-a34e-0b9b3a9b2e60', 'bd652047-78bf-56b3-a52f-2a34c8f5969f', 2, 2, 'ፈርዖንም በሁለቱ ሹሞች በጠጅ አሳላፊዎቹ አለቃና በእንጀራ አበዛዎቹ አለቃ ላይ ተቈጣ፤'),
  ('c0c11083-d74c-5a0a-a0d0-c48cfd69106b', '4af2812e-ef07-511d-a34e-0b9b3a9b2e60', 'bd652047-78bf-56b3-a52f-2a34c8f5969f', 3, 3, 'በእስር ቤት ውስጥም ዮሴፍ ታስሮ በነበረበት የግዞት ስፍራ አጋዛቸው።'),
  ('f8982c56-b5b8-5105-ac30-2ff88c56380e', '4af2812e-ef07-511d-a34e-0b9b3a9b2e60', 'bd652047-78bf-56b3-a52f-2a34c8f5969f', 4, 4, 'የእስር ቤቱ ዘበኞች አለቃም ለዮሴፍ አሳልፎ ሰጣቸው፤ እርሱም ያገለግላቸው ነበር፤ በግዞት ቤትም አንድ ዓመት ተቀመጡ።'),
  ('7796f37b-201a-5c7a-a992-689d801e1edc', '4af2812e-ef07-511d-a34e-0b9b3a9b2e60', 'bd652047-78bf-56b3-a52f-2a34c8f5969f', 5, 5, 'ሁለቱም በአንዲት ሌሊት ሕልምን አለሙ። በግዞት ቤት የነበሩት የግብፅ ንጉሥ ጠጅ አሳላፊዎች አለቃና የእንጀራ አበዛዎች አለቃ ሁለቱም እየራሳቸው ሕልምን አለሙ።'),
  ('5a9f4bad-62c0-5f0c-afe4-b77ece07a321', '4af2812e-ef07-511d-a34e-0b9b3a9b2e60', 'bd652047-78bf-56b3-a52f-2a34c8f5969f', 6, 6, 'ዮሴፍም ማልዶ ወደ እነርሱ ገባ፤ እነሆም፥ አዝነው አያቸው።'),
  ('cabbb93f-adae-5f98-a4e6-a8e2cc2e1b66', '4af2812e-ef07-511d-a34e-0b9b3a9b2e60', 'bd652047-78bf-56b3-a52f-2a34c8f5969f', 7, 7, 'በጌታው ቤት ከእርሱ ጋር በግዞት የነበሩትንም የፈርዖን ሹሞች እንዲህ ብሎ ጠየቃቸው፥ “እናንት ዛሬ ስለምን አዝናችኋል?”'),
  ('8730cb48-69ee-51b7-a97e-eed826c9d02d', '4af2812e-ef07-511d-a34e-0b9b3a9b2e60', 'bd652047-78bf-56b3-a52f-2a34c8f5969f', 8, 8, 'እነርሱም፥ “ሕልምን አልመን የሚተረጕምልን አጣን” አሉት። ዮሴፍም አላቸው፥ “ሕልምን የሚተረጕም እግዚአብሔር የሰጠው አይደለምን? እስቲ ንገሩኝ፤ ሕልማችሁ ምንድን ነው?”'),
  ('db5a6a6b-c16a-555b-a5ee-253e4e2a66ba', '4af2812e-ef07-511d-a34e-0b9b3a9b2e60', 'bd652047-78bf-56b3-a52f-2a34c8f5969f', 9, 9, 'የጠጅ አሳላፊዎች አለቃም ለዮሴፍ ሕልሙን እንዲህ ብሎ ነገረው፥ “በሕልሜ የወይን ሐረግ በፊቴ ሆና አየሁ፥'),
  ('70dfd63e-7583-534e-a960-199cebec54e1', '4af2812e-ef07-511d-a34e-0b9b3a9b2e60', 'bd652047-78bf-56b3-a52f-2a34c8f5969f', 10, 10, 'በሐረጉም ሦስት ቅርንጫፎች ወጡ፤ እርስዋም ቅጠልና አበባ አወጣች፤ ዘለላም አንጠለጠለች፤ የዘለላዋም ፍሬ በሰለ፤'),
  ('1869067f-1b03-5298-a54c-ebce79b9bd84', '4af2812e-ef07-511d-a34e-0b9b3a9b2e60', 'bd652047-78bf-56b3-a52f-2a34c8f5969f', 11, 11, 'የፈርዖንም ጽዋ በእጄ ነበር፤ ፍሬውንም ወስጄ በፈርዖን ጽዋ ጨመቅሁት፤ ጽዋዉንም ለፈርዖን በእጁ ሰጠሁት።”'),
  ('7ce10245-d8ef-57a2-a008-299e86fc8a1b', '4af2812e-ef07-511d-a34e-0b9b3a9b2e60', 'bd652047-78bf-56b3-a52f-2a34c8f5969f', 12, 12, 'ዮሴፍም አለው፥ “የሕልምህ ትርጓሜው ይህ ነው፤ ሦስት ቅርንጫፎች ሦስት ቀኖች ናቸው።'),
  ('7e38ef4f-f6b5-5618-aa59-12a72daabc51', '4af2812e-ef07-511d-a34e-0b9b3a9b2e60', 'bd652047-78bf-56b3-a52f-2a34c8f5969f', 13, 13, 'እስከ ሦስት ቀንም ድረስ ፈርዖን ሹመትህን ያስባል፤ ወደ ጠጅ አሳላፊዎች አለቃነትህም ይመልስሃል፤ ጠጅ አሳላፊ በነበርህበት ጊዜ ስታደርገው እንደ ነበረው እንደ ቀድሞው ሹመትህም የፈርዖንን ጽዋ በእጁ ትሰጣለህ።'),
  ('48ed8865-0747-5708-a736-9849af08d06a', '4af2812e-ef07-511d-a34e-0b9b3a9b2e60', 'bd652047-78bf-56b3-a52f-2a34c8f5969f', 14, 14, 'ነገር ግን በጎ ነገር በተደረገልህ ጊዜ እኔን ዐስበኝ፤ ምሕረትንም አድርግልኝ፤ ስለ እኔም ለፈርዖን አሳስበህ ከዚህ እስር ቤት አውጣኝ፤'),
  ('a8a4606d-9fe8-5d4e-aa05-9a1e82902eaa', '4af2812e-ef07-511d-a34e-0b9b3a9b2e60', 'bd652047-78bf-56b3-a52f-2a34c8f5969f', 15, 15, 'ሌቦች በስውር ከዕብራውያን ሀገር ሰርቀውኛልና፤ በዚህም ደግሞ ምንም ያደረግሁት ሳይኖር በግዞት ቤት አኑረውኛልና።”'),
  ('f85bc242-402d-57fe-a83f-6d10588f4e6a', '4af2812e-ef07-511d-a34e-0b9b3a9b2e60', 'bd652047-78bf-56b3-a52f-2a34c8f5969f', 16, 16, 'የእንጀራ አበዛዎቹ አለቃም ሕልሙን በመልካም እንደ ተረጐመለት በአየ ጊዜ ዮሴፍን እንዲህ አለው፥ “እኔም ደግሞ ሕልም አይች ነበር፤ እነሆም፥ ሦስት መሶብ ነጭ እንጀራ በራሴ ላይ ነበረ፤'),
  ('19cf3efb-b465-5a82-a7a8-9666b8971e1c', '4af2812e-ef07-511d-a34e-0b9b3a9b2e60', 'bd652047-78bf-56b3-a52f-2a34c8f5969f', 17, 17, 'በላይኛውም መሶብ ፈርዖን የሚበላው ጋጋሪው በያይነቱ የሠራው መብል ነበረበት፤ ወፎችም በራሴ ላይ ከመሶቡ ይበሉ ነበር።”'),
  ('bcaac1f8-d5bf-5368-ac7a-59455e08c219', '4af2812e-ef07-511d-a34e-0b9b3a9b2e60', 'bd652047-78bf-56b3-a52f-2a34c8f5969f', 18, 18, 'ዮሴፍም መልሶ እንዲህ አለው፥ “የሕልምህ ትርጓሜው ይህ ነው፤ ሦስቱ መሶብ ሦስት ቀን ነው፤'),
  ('49bf75cb-a83a-5ee3-ad2b-97aea5679c7f', '4af2812e-ef07-511d-a34e-0b9b3a9b2e60', 'bd652047-78bf-56b3-a52f-2a34c8f5969f', 19, 19, 'እስከ ሦስት ቀን ድረስ ፈርዖን ራስህን ይቈርጥሃል፤ በዕንጨትም ላይ ይሰቅልሃል፤ የሰማይ ወፎችም ሥጋህን ይበሉታል።”'),
  ('d6cf0db1-e869-589f-a004-12699ca83a94', '4af2812e-ef07-511d-a34e-0b9b3a9b2e60', 'bd652047-78bf-56b3-a52f-2a34c8f5969f', 20, 20, 'እንዲህም ሆነ፤ በሦስተኛው ቀን ፈርዖን የተወለደበት ዕለት ነበር፤ ለሠራዊቱም ሁሉ ግብር አደረገ፤ የጠጅ አሳላፊዎቹን አለቃና የእንጀራ አበዛዎቹን አለቃ በአሽከሮቹ መካከል ዐሰበ።'),
  ('34cd339a-cdd3-5c26-a14b-a4cb46fe45e2', '4af2812e-ef07-511d-a34e-0b9b3a9b2e60', 'bd652047-78bf-56b3-a52f-2a34c8f5969f', 21, 21, 'የጠጅ አሳላፊዎቹንም አለቃ ወደ ሹመቱ መለሰው፤ ጽዋውንም በፈርዖን እጅ ሰጠ፤'),
  ('a42c398b-f353-578d-a853-9803c3ba5cec', '4af2812e-ef07-511d-a34e-0b9b3a9b2e60', 'bd652047-78bf-56b3-a52f-2a34c8f5969f', 22, 22, 'የእንጀራ አበዛዎቹንም አለቃ በዕንጨት ላይ ሰቀለው፤ ዮሴፍ እንደ ተረጐመላቸው።'),
  ('713c0c58-2886-594e-a992-93bfb280adc0', '4af2812e-ef07-511d-a34e-0b9b3a9b2e60', 'bd652047-78bf-56b3-a52f-2a34c8f5969f', 23, 23, 'የጠጅ አሳላፊዎች አለቃ ግን ዮሴፍን አላሰበውም፤ ረሳው እንጂ።'),
  ('d3e3a898-f045-5e31-a3b2-d4166529fe71', '5e3d341b-413e-545a-a939-6d4437e2a613', 'e00f9e4b-6dc0-56f7-a41a-68e67e10898a', 1, 1, 'ከሁለት ዓመት በኋላም ፈርዖን ሕልምን አየ፤ እነሆም፥ በወንዙ ዳር ቆሞ ነበር።'),
  ('503b8482-784e-57ba-aa82-eb3b17b3b2f6', '5e3d341b-413e-545a-a939-6d4437e2a613', 'e00f9e4b-6dc0-56f7-a41a-68e67e10898a', 2, 2, 'እነሆም፥ መልካቸው ያማረ፥ ሥጋቸውም የወፈረ ሰባት ላሞች ከወንዙ ወጡ፤ በወንዙም ዳር በመስኩ ይሰማሩ ነበር።'),
  ('67b278af-1eb4-5672-a5d2-3c320d97c28e', '5e3d341b-413e-545a-a939-6d4437e2a613', 'e00f9e4b-6dc0-56f7-a41a-68e67e10898a', 3, 3, 'ከእነርሱም በኋላ እነሆ፥ መልካቸው የከፋ፥ ሥጋቸውም የከሳ ሌሎች ሰባት ላሞች ከወንዙ ወጡ፤ በእነዚያም ላሞች አጠገብ በወንዙ ዳር ተሰማርተው ነበር።'),
  ('228b04a0-2529-5d4d-a71f-8229c81faf1e', '5e3d341b-413e-545a-a939-6d4437e2a613', 'e00f9e4b-6dc0-56f7-a41a-68e67e10898a', 4, 4, 'መልካቸው የከፋ፥ ሥጋቸውም የከሳ እነዚያ ሰባት ላሞች መልካቸው ያማረውን፥ ሥጋቸውም የወፈረውን ሰባቱን ላሞች ዋጡአቸው። ፈርዖንም ነቃ፤'),
  ('066b1804-7578-5e9b-a0a3-1263e8ea8d18', '5e3d341b-413e-545a-a939-6d4437e2a613', 'e00f9e4b-6dc0-56f7-a41a-68e67e10898a', 5, 5, 'ደግሞም ተኛ፤ ሁለተኛ ሕልምንም አየ፤ እነሆም፥ በአንድ አገዳ ላይ የነበሩ፥ ያማሩና ምርጥ የሆኑ ሰባት እሸቶች ወጡ፤'),
  ('5735c20f-7a97-52e9-a442-6e40a04b4276', '5e3d341b-413e-545a-a939-6d4437e2a613', 'e00f9e4b-6dc0-56f7-a41a-68e67e10898a', 6, 6, 'እነሆም፥ ከእነርሱ በኋላ የሰለቱና በነፋስ የተመቱ ሰባት እሸቶች ወጡ፤'),
  ('7c5a1219-72a6-52ac-a024-ba506705bc73', '5e3d341b-413e-545a-a939-6d4437e2a613', 'e00f9e4b-6dc0-56f7-a41a-68e67e10898a', 7, 7, 'እነዚያም የሰለቱና ነፋስ የመታቸው እሸቶች ሰባቱን ያማሩና የጐመሩ እሸቶች ዋጡአቸው። ፈርዖንም ነቃ፤ እነሆም ሕልም ነበር።'),
  ('75c7e3d0-7c92-58dd-ab25-a2f77bb47253', '5e3d341b-413e-545a-a939-6d4437e2a613', 'e00f9e4b-6dc0-56f7-a41a-68e67e10898a', 8, 8, 'በነጋም ጊዜ መንፈሱ ታወከችበት፤ የግብፅ ሕልም ተርጓሚዎችንና ጠቢባንን ሁሉ ልኮ አስጠራቸው፤ ፈርዖንም ሕልሙን ነገራቸው፤ ነገር ግን ከእነርሱ ለፈርዖን ሕልሙን የሚተረጕምለት አልተገኘም።'),
  ('9e665f33-2fb0-5796-a5c9-93dd0a5cc835', '5e3d341b-413e-545a-a939-6d4437e2a613', 'e00f9e4b-6dc0-56f7-a41a-68e67e10898a', 9, 9, 'የዚያን ጊዜ የጠጅ አሳላፊዎቹ አለቃ እንዲህ ብሎ ለፈርዖን ተናገረ፥ “እኔ ኀጢአቴን ዛሬ አስባለሁ፤'),
  ('f91e7b7a-79eb-5e9f-a644-7444a0749dc8', '5e3d341b-413e-545a-a939-6d4437e2a613', 'e00f9e4b-6dc0-56f7-a41a-68e67e10898a', 10, 10, 'ፈርዖን በአገልጋዮቹ ላይ ተቈጣ፤ እኔንም የእንጀራ አበዛዎቹንም አለቃ በግዞት ቤት አኖረን፤'),
  ('fbb9cfaf-dd8f-5f15-ad13-dc2d57977d75', '5e3d341b-413e-545a-a939-6d4437e2a613', 'e00f9e4b-6dc0-56f7-a41a-68e67e10898a', 11, 11, 'እኛም በአንዲት ሌሊት ሕልምን አለምን፤ እኔና እርሱ እያንዳንዳችን እንደ ሕልማችን ትርጓሜ አለምን።'),
  ('de14b3da-c2df-598c-abeb-b829b93f9635', '5e3d341b-413e-545a-a939-6d4437e2a613', 'e00f9e4b-6dc0-56f7-a41a-68e67e10898a', 12, 12, 'በዚያም የእንጀራ አበዛዎች አለቃ አገልጋይ የሆነ አንድ ዕብራዊ ጐልማሳ ከእኛ ጋር ነበር፤ ለእርሱም ነገርነው፤ ሕልማችንንም ተረጐመልን።'),
  ('6d8cfe9e-bc68-56dd-ac34-2c6f673a6999', '5e3d341b-413e-545a-a939-6d4437e2a613', 'e00f9e4b-6dc0-56f7-a41a-68e67e10898a', 13, 13, 'እንዲህም ሆነ፤ እንደ ተረጐመልን እንደዚያው ሆነ፤ እኔ ወደ ሹመቴ ተመለስሁ፤ እርሱም ተሰቀለ።”'),
  ('c9e9d6bb-a2f4-5590-a12e-0e16a80ec826', '5e3d341b-413e-545a-a939-6d4437e2a613', 'e00f9e4b-6dc0-56f7-a41a-68e67e10898a', 14, 14, 'ፈርዖንም ልኮ ዮሴፍን አስጠራው፤ ከግዞት ቤትም አወጡት፤ ራሱንም ላጩት፤ ልብሱንም ለወጡ፤ ወደ ፈርዖንም ገባ።'),
  ('7b1b82b8-e50f-503a-a302-ef21f12704b7', '5e3d341b-413e-545a-a939-6d4437e2a613', 'e00f9e4b-6dc0-56f7-a41a-68e67e10898a', 15, 15, 'ፈርዖንም ዮሴፍን አለው፥ “ሕልምን አየሁ፤ የሚተረጕምልኝም አጣሁ፤ ሕልምን እንደ ሰማህ፥ እንደ ተረጐምህም ስለ አንተ ሰማሁ።”'),
  ('a8167802-2651-5ba7-a926-a1975a8dee4f', '5e3d341b-413e-545a-a939-6d4437e2a613', 'e00f9e4b-6dc0-56f7-a41a-68e67e10898a', 16, 16, 'ዮሴፍም፥ “እግዚአብሔር ከገለጸለት ሰው በቀር መተርጐም የሚችል የለም” ብሎ ለፈርዖን መለሰለት።'),
  ('c66f6596-9af5-5dc7-a8cf-c7c45be142ed', '5e3d341b-413e-545a-a939-6d4437e2a613', 'e00f9e4b-6dc0-56f7-a41a-68e67e10898a', 17, 17, 'ፈርዖንም ለዮሴፍ እንዲህ አለው፥ “እነሆ፥ በሕልሜ በወንዝ ዳር ቆሜ ነበር፤'),
  ('4408188b-c1ae-5b67-a1f7-6f4df1c10b37', '5e3d341b-413e-545a-a939-6d4437e2a613', 'e00f9e4b-6dc0-56f7-a41a-68e67e10898a', 18, 18, 'እነሆም፥ ሥጋቸው የወፈረ፥ መልካቸውም ያማረ ሰባት ላሞች ወጡ፤ በወንዙ ዳር በመስኩም ይሰማሩ ነበር፤'),
  ('fdca2099-18d3-51d5-a445-dedf3fd18436', '5e3d341b-413e-545a-a939-6d4437e2a613', 'e00f9e4b-6dc0-56f7-a41a-68e67e10898a', 19, 19, 'ከእነርሱም በኋላ እነሆ፥ የደከሙ፥ መልካቸውም እጅግ የከፋ፥ ሥጋቸውም የከሳ ሌሎች ሰባት ላሞች ከወንዙ ወጡ፤ በግብፅም ምድር ሁሉ እንደ እነርሱ መልከ ክፉ ከቶ አላየሁም፤'),
  ('39068f53-61a6-5c2a-a23f-bcbbe8ba9d0f', '5e3d341b-413e-545a-a939-6d4437e2a613', 'e00f9e4b-6dc0-56f7-a41a-68e67e10898a', 20, 20, 'እነዚያ የከሱትና መልከ ክፉዎቹ ላሞች እነዚያን የመጀመሪያዎቹን ያማሩና የወፈሩ ሰባት ላሞች ዋጡአቸው፤ በሆዳቸውም ተዋጡ፤'),
  ('7c50eb34-1b65-58b9-aaa6-f9a4c69395e0', '5e3d341b-413e-545a-a939-6d4437e2a613', 'e00f9e4b-6dc0-56f7-a41a-68e67e10898a', 21, 21, 'በሆዳቸውም ውስጥ የገባ እንደሌለ ሆኑ፤ መልካቸውም በመጀመሪያ እንደ ነበረው የከፋ ነበረ፤ ነቃሁም። ዳግመኛም ተኛሁ፤'),
  ('5c799711-9cdc-5192-a28e-49d1b7647c60', '5e3d341b-413e-545a-a939-6d4437e2a613', 'e00f9e4b-6dc0-56f7-a41a-68e67e10898a', 22, 22, 'በሕልሜም እነሆ፥ የጐመሩና መልካም የሆኑ ሰባት እሸቶች ከአንድ አገዳ ሲወጡ አየሁ፤'),
  ('f583dc29-51e8-5e38-a43c-91addada1097', '5e3d341b-413e-545a-a939-6d4437e2a613', 'e00f9e4b-6dc0-56f7-a41a-68e67e10898a', 23, 23, 'ከእነርሱም በኋላ እነሆ የሰለቱና በነፋስ የተመቱ ሌሎች ሰባት እሸቶች ወጡ፤'),
  ('9ccdd168-4a20-5cac-afa3-461e3557bdaa', '5e3d341b-413e-545a-a939-6d4437e2a613', 'e00f9e4b-6dc0-56f7-a41a-68e67e10898a', 24, 24, 'እነዚያ የሰለቱትና በነፋስ የተመቱት እሸቶች እነዚያን ያማሩትንና የጐመሩትን ሰባቱን እሸቶች ዋጡአቸው። ለሕልም ተርጓሚዎችም ሕልሜን ነገርሁ፤ የተረጐመልኝም የለም።”'),
  ('a70c80b5-e1de-5d78-a6af-9de44335b760', '5e3d341b-413e-545a-a939-6d4437e2a613', 'e00f9e4b-6dc0-56f7-a41a-68e67e10898a', 25, 25, 'ዮሴፍም ፈርዖንን አለው፥ “የፈርዖን ሕልሙ አንድ ነው፤ እግዚአብሔር ሊያደርገው ያለውን ለፈርዖን አሳይቶታል።'),
  ('78e5eb43-117a-5f94-a224-7717a9badde7', '5e3d341b-413e-545a-a939-6d4437e2a613', 'e00f9e4b-6dc0-56f7-a41a-68e67e10898a', 26, 26, 'እነዚያ ሰባቱ መልካካሞች ላሞች ሰባት ዓመታት ናቸው፤ እነዚያም ሰባቱ መልካካሞች እሸቶች ሰባት ዓመታት ናቸው፤ የፈርዖን ሕልሙ አንድ ነው።'),
  ('723477e1-873c-58d4-aff2-531e1b4cf567', '5e3d341b-413e-545a-a939-6d4437e2a613', 'e00f9e4b-6dc0-56f7-a41a-68e67e10898a', 27, 27, 'ከእነርሱም በኋላ የወጡት እነዚያ የከሱና መልከ ክፉዎቹ ሰባት ላሞች ሰባት ዓመታት ናቸው፤ እነዚያም የሰለቱትና ነፋስ የመታቸው ሰባቱ እሸቶች እነርሱ ራብ የሚሆንባቸው ሰባት ዓመታት ናቸው።'),
  ('78aa2652-5671-51f5-a7f4-b26acc399a32', '5e3d341b-413e-545a-a939-6d4437e2a613', 'e00f9e4b-6dc0-56f7-a41a-68e67e10898a', 28, 28, 'ለፈርዖን የነገርሁት ነገር ይህ ነው፤ እግዚአብሔር ሊያደርገው ያለውን ለፈርዖን አሳየው።'),
  ('6c5fa1ef-ade6-5500-ada6-97f9002cce80', '5e3d341b-413e-545a-a939-6d4437e2a613', 'e00f9e4b-6dc0-56f7-a41a-68e67e10898a', 29, 29, 'እነሆ፥ በግብፅ ምድር ሁሉ እጅግ ጥጋብ የሚሆንባቸው ሰባት ዓመታት ይመጣሉ፤'),
  ('5f1a3cf2-f76c-582b-a841-6acbf9e87e1e', '5e3d341b-413e-545a-a939-6d4437e2a613', 'e00f9e4b-6dc0-56f7-a41a-68e67e10898a', 30, 30, 'ደግሞም ከዚህ በኋላ ሰባት የራብ ዓመት ይመጣል፤ በግብፅ ሀገር ሁሉ የነበረውንም ጥጋብ ሁሉ ይረሱታል፤ ራብም ምድርን ሁሉ ያጠፋል፤'),
  ('b6fae89f-90ff-51af-adff-804d01445f14', '5e3d341b-413e-545a-a939-6d4437e2a613', 'e00f9e4b-6dc0-56f7-a41a-68e67e10898a', 31, 31, 'በኋላም ከሚሆነው ከዚያ ራብ የተነሣ በምድር የሆነው ጥጋብ አይታወቅም፤ እጅግ ጽኑ ይሆናልና።'),
  ('79833941-1bcf-5cf1-a8fa-3f6e5e092214', '5e3d341b-413e-545a-a939-6d4437e2a613', 'e00f9e4b-6dc0-56f7-a41a-68e67e10898a', 32, 32, 'ሕልሙም ለፈርዖን ደጋግሞ መታየቱ ነገሩ ከእግዚአብሔር ዘንድ የተቈረጠ ስለሆነ ነው፤ እግዚአብሔርም ፈጥኖ ያደርገዋል።'),
  ('b1cf6cf2-cfa1-5c02-a8d1-b9c684f8d957', '5e3d341b-413e-545a-a939-6d4437e2a613', 'e00f9e4b-6dc0-56f7-a41a-68e67e10898a', 33, 33, 'አሁንም ብልህና ዐዋቂ ሰውን ለአንተ ፈልግ፤ በግብፅ ምድር ላይም ሹመው።'),
  ('d635ef7b-2e78-5205-a3af-0a0ad7028719', '5e3d341b-413e-545a-a939-6d4437e2a613', 'e00f9e4b-6dc0-56f7-a41a-68e67e10898a', 34, 34, 'ፈርዖን በግብፅ ምድር ላይ ሹሞችን ይሹም፤ በሰባቱም የጥጋብ ዓመታት ከሚገኘው ፍሬ በግብፅ ምድር ሁሉ ከአምስት እጅ አንደኛውን ይውሰድ።'),
  ('d9fbf4a9-5ece-533e-af79-e8ef69dae969', '5e3d341b-413e-545a-a939-6d4437e2a613', 'e00f9e4b-6dc0-56f7-a41a-68e67e10898a', 35, 35, 'የሚመጡትን የመልካሞቹን ሰባት ዓመታት እህላቸውን ያከማቹ፤ ስንዴውንም ከፈርዖን እጅ በታች ያኑሩ፤ እህሎችም በከተሞች ይጠበቁ።'),
  ('c431ab06-90bd-55f5-a742-24d47a968048', '5e3d341b-413e-545a-a939-6d4437e2a613', 'e00f9e4b-6dc0-56f7-a41a-68e67e10898a', 36, 36, 'በግብፅ ምድር ስለሚሆነው ስለ ሰባቱ ዓመታት ራብ እህሉ ለሀገሩ ሁሉ ተጠብቆ ይኑር፥ ምድሪቱም በራብ አትጠፋም።”'),
  ('86a5e7f3-3364-5a02-a27e-ba1523163f2b', '5e3d341b-413e-545a-a939-6d4437e2a613', '6e4ccb4a-51af-5d9b-a156-198020fda20c', 1, 37, 'ነገሩም ፈርዖንንና ሰዎቹን ሁሉ ደስ አሰኛቸው፤'),
  ('6942746a-84af-5d57-a138-da4bb34dc38b', '5e3d341b-413e-545a-a939-6d4437e2a613', '6e4ccb4a-51af-5d9b-a156-198020fda20c', 2, 38, 'ፈርዖንም ሎሌዎቹን እንዲህ አላቸው፥ “በውኑ የእግዚአብሔር መንፈስ ያለበትን እንደዚህ ያለ ሰውን እናገኛለን?”'),
  ('7a3ceea2-14b8-598f-a925-7fa8643c9ddb', '5e3d341b-413e-545a-a939-6d4437e2a613', '6e4ccb4a-51af-5d9b-a156-198020fda20c', 3, 39, 'ፈርዖንም ዮሴፍን አለው፥ “እግዚአብሔር ይህን ሁሉ ገልጦልሃልና ከአንተ ይልቅ ብልህና ዐዋቂ ሰው የለም።'),
  ('55846f28-9a31-5110-a89e-ad1eaa4e9e6d', '5e3d341b-413e-545a-a939-6d4437e2a613', '6e4ccb4a-51af-5d9b-a156-198020fda20c', 4, 40, 'አንተ በቤቴ ላይ ተሾም፤ ሕዝቤም ሁሉ ለቃልህ ይታዘዝ፤ እኔም ከዙፋኔ በቀር ከአንተ የምበልጥበት የለም።”'),
  ('6ac2bda7-bc53-568b-a49d-12bdfb2c5665', '5e3d341b-413e-545a-a939-6d4437e2a613', '6e4ccb4a-51af-5d9b-a156-198020fda20c', 5, 41, 'ፈርዖንም ዮሴፍን፥ “በግብፅ ምድር ሁሉ ላይ ሾምሁህ” አለው።'),
  ('5b552a15-456a-5704-a3a3-75230272dbee', '5e3d341b-413e-545a-a939-6d4437e2a613', '6e4ccb4a-51af-5d9b-a156-198020fda20c', 6, 42, 'ፈርዖን ቀለበቱን ከእጁ አወለቀ፤ በዮሴፍም እጅ አደረገው፤ የነጭ ሐር ልብስንም አለበሰው፤ በአንገቱም የወርቅ ዝርግፍን አደረገለት፤'),
  ('ddc20382-94ca-5ae9-aaa8-e7e8f0c678c8', '5e3d341b-413e-545a-a939-6d4437e2a613', '6e4ccb4a-51af-5d9b-a156-198020fda20c', 7, 43, 'የእርሱም በምትሆን በሁለተኛይቱ ሰረገላ አስቀመጠው፤ ስገዱ እያለም በፊት በፊቱ አዋጅ ነጋሪ እንዲሄድ አደረገ፤ በግብፅ ምድር ሁሉ ላይም ሾመው።'),
  ('2b8ccad8-3d93-5f0f-ae4d-e9cb4abd5e8d', '5e3d341b-413e-545a-a939-6d4437e2a613', '6e4ccb4a-51af-5d9b-a156-198020fda20c', 8, 44, 'ፈርዖንም ዮሴፍን አለው፥ “እኔ ራሴ ፈርዖን ነኝ፤ በግብፅ ሀገር ሁሉ ያለ አንተ ማንም እጁን አያንሣ።”'),
  ('f469fe0b-00ac-54a2-a17b-86cb57cbd7e8', '5e3d341b-413e-545a-a939-6d4437e2a613', '6e4ccb4a-51af-5d9b-a156-198020fda20c', 9, 45, 'ፈርዖንም የዮሴፍን ስም “እስፍንቶፎኔህ” ብሎ ጠራው፤ የሄልዮቱ ከተማ ካህን የጴጤፌራ ልጅ የምትሆን አስኔትንም ሚስት ትሆነው ዘንድ ሰጠው።'),
  ('75c1ece2-c17a-509e-a9d8-0015da3dc323', '5e3d341b-413e-545a-a939-6d4437e2a613', '6e4ccb4a-51af-5d9b-a156-198020fda20c', 10, 46, 'ዮሴፍም በግብፅ ንጉሥ በፈርዖን ፊት በቆመ ጊዜ ዕድሜው ሠላሳ ዓመት ነበረ። ዮሴፍም ከፈርዖን ፊት ወጣ፤ የግብፅ ምድርንም ሁሉ ዞረ።'),
  ('aa2437a8-f372-5ad4-affd-c734060ef8fe', '5e3d341b-413e-545a-a939-6d4437e2a613', '6e4ccb4a-51af-5d9b-a156-198020fda20c', 11, 47, 'በሰባቱም የጥጋብ ዓመታት ግብፅ ያስገኘችው እህል ሁሉ ክምር ሆነ።'),
  ('87b7b813-2e83-510a-a22a-1c8bede4cf17', '5e3d341b-413e-545a-a939-6d4437e2a613', '6e4ccb4a-51af-5d9b-a156-198020fda20c', 12, 48, 'በግብፅ ምድር ሁሉ ያለውን የሰባቱን የጥጋብ ዓመታት እህል ሁሉ ሰበሰበ፤ እህልንም በከተሞቹ አደለበ፤ በየከተማይቱም ዙሪያ ያለውን የእርሻውን እህል ሁሉ በዚያው ከተተ።'),
  ('63a95163-26d9-5f08-ab0a-9d327804c3e0', '5e3d341b-413e-545a-a939-6d4437e2a613', '6e4ccb4a-51af-5d9b-a156-198020fda20c', 13, 49, 'ዮሴፍም እንደ ባሕር አሸዋ እጅግ ብዙ የሆነ ስንዴን አከማቸ፤ መስፈር እስኪሳናቸው ድረስ፤ ሊሰፈር አልተቻለምና።'),
  ('1e0c3647-396d-5ce7-a805-41327c390fd9', '5e3d341b-413e-545a-a939-6d4437e2a613', '6e4ccb4a-51af-5d9b-a156-198020fda20c', 14, 50, 'ለዮሴፍም የሄልዮቱ ከተማ ካህን የጴጤፌራ ልጅ አስኔት የወለደችለት ሁለት ልጆች የራብ ዘመን ገና ሳይመጣ ተወለዱለት።'),
  ('83cf5e47-a21b-515c-a561-c7287d565325', '5e3d341b-413e-545a-a939-6d4437e2a613', '6e4ccb4a-51af-5d9b-a156-198020fda20c', 15, 51, 'ዮሴፍም የበኵር ልጁን ስም ምናሴ ብሎ ጠራው፤ እንዲህ ሲል፥ “እግዚአብሔር መከራዬን ሁሉ የአባቴንም ቤት እንድረሳ አደረገኝ፤”'),
  ('c2187c5b-5d08-5929-a5be-ae6443d991e2', '5e3d341b-413e-545a-a939-6d4437e2a613', '6e4ccb4a-51af-5d9b-a156-198020fda20c', 16, 52, 'የሁለተኛውንም ስም ኤፍሬም ብሎ ጠራው፤ እንዲህ ሲል፥ “እግዚአብሔር በመከራዬ ሀገር አብዝቶኛልና።”'),
  ('81483c4a-addc-5f41-a206-f700fb1189a4', '5e3d341b-413e-545a-a939-6d4437e2a613', '6e4ccb4a-51af-5d9b-a156-198020fda20c', 17, 53, 'በግብፅ ምድር የነበረውም ሰባቱ የጥጋብ ዓመት አለፈ፤'),
  ('36b3623d-20b2-50be-a175-3b3797239eef', '5e3d341b-413e-545a-a939-6d4437e2a613', '6e4ccb4a-51af-5d9b-a156-198020fda20c', 18, 54, 'ዮሴፍም እንደ ተናገረ ሰባቱ የራብ ዓመት መምጣት ጀመረ። በየሀገሩም ሁሉ ራብ ሆነ፤ በግብፅ ምድር ሁሉ ግን እህል ነበረ።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('dda9180c-3da1-508b-a96d-3969a92fcf05', '5e3d341b-413e-545a-a939-6d4437e2a613', '6e4ccb4a-51af-5d9b-a156-198020fda20c', 19, 55, 'የግብፅ ምድርም ሁሉ ተራበ፤ ሕዝቡም ስለ እህል ወደ ፈርዖን ጮኸ፤ ፈርዖንም የግብፅ ሰዎችን ሁሉ፥ “ወደ ዮሴፍ ሂዱ፤ እርሱ ያላችሁንም ሁሉ አድርጉ” አላቸው።'),
  ('ba107c22-ba23-5aba-a3ba-c26f9b32b8fe', '5e3d341b-413e-545a-a939-6d4437e2a613', '6e4ccb4a-51af-5d9b-a156-198020fda20c', 20, 56, 'በምድርም ሁሉ ላይ ራብ ሆነ፤ ዮሴፍም እህል ያለበትን ጎተራ ሁሉ ከፍቶ ለግብፅ ሰዎች ሁሉ ይሸጥ ነበር።'),
  ('e137f31e-2ce8-5384-a285-08008346772e', '5e3d341b-413e-545a-a939-6d4437e2a613', '6e4ccb4a-51af-5d9b-a156-198020fda20c', 21, 57, 'ሀገሮችም ሁሉ ከዮሴፍ እህል ይገዙ ዘንድ ወደ ግብፅ ወጡ፤ በምድር ሁሉ ራብ እጅግ ጸንቶ ነበርና።'),
  ('c71d6c18-08a7-5483-a543-118d99b5e1ef', 'ae51fe87-e163-5aee-aaa1-24ce208d9e6c', 'f71d01c1-7680-50e8-ac46-4da3f3b57813', 1, 1, 'ያዕቆብም በግብፅ የሚሸመት እህል እንዳለ ሰማ፤ ልጆቹንም፥ “ለምን ትተክዛላችሁ?” አላቸው።'),
  ('f361f87f-a8a5-5a3a-a871-50f1f6e81e76', 'ae51fe87-e163-5aee-aaa1-24ce208d9e6c', 'f71d01c1-7680-50e8-ac46-4da3f3b57813', 2, 2, 'እንዲህም አለ፥ “እነሆ፥ እህል በግብፅ እንዳለ ሰምቼአለሁ፤ ወደዚያ ውረዱ፤ እንድንድንና በራብ እንዳንሞትም ከዚያ ሸምቱልን።”'),
  ('6ac3bf85-4f25-5e10-a976-c1d9a98530b5', 'ae51fe87-e163-5aee-aaa1-24ce208d9e6c', 'f71d01c1-7680-50e8-ac46-4da3f3b57813', 3, 3, 'የዮሴፍም ዐሥሩ ወንድሞቹ እህልን ከግብፅ ይሸምቱ ዘንድ ወረዱ፤'),
  ('61fdd762-0d71-59b7-ae3e-92662b65379a', 'ae51fe87-e163-5aee-aaa1-24ce208d9e6c', 'f71d01c1-7680-50e8-ac46-4da3f3b57813', 4, 4, 'የዮሴፍን ወንድም ብንያምን ግን ያዕቆብ ከወንድሞቹ ጋር አልሰደደውም፥ “ምናልባት ክፉ እንዳያገኘው” ብሎአልና።'),
  ('d60ea1f7-5922-574d-a431-f40a2750d854', 'ae51fe87-e163-5aee-aaa1-24ce208d9e6c', 'f71d01c1-7680-50e8-ac46-4da3f3b57813', 5, 5, 'የእስራኤልም ልጆች ለእህል ሸመታ ከመጡት ጋር ገቡ፤ በከነዓን ሀገር ራብ ነበርና።'),
  ('b84041e8-32af-5d6b-a643-98b410aee413', 'ae51fe87-e163-5aee-aaa1-24ce208d9e6c', 'f71d01c1-7680-50e8-ac46-4da3f3b57813', 6, 6, 'ዮሴፍም በግብፅ ምድር ላይ ገዥ ነበረ፤ እርሱም ለምድር ሕዝብ ሁሉ እህል ይሸጥ ነበር፤ የዮሴፍም ወንድሞች በመጡ ጊዜ በምድር ላይ በግንባራቸው ሰገዱለት።'),
  ('349c741a-b403-50cf-aa17-49231316e219', 'ae51fe87-e163-5aee-aaa1-24ce208d9e6c', 'f71d01c1-7680-50e8-ac46-4da3f3b57813', 7, 7, 'ዮሴፍም ወንድሞቹን በአያቸው ጊዜ ዐወቃቸው፤ እንደማያውቃቸውም ሆነ፤ ክፉ ቃልንም ተናገራቸው፥ “እናንተ ከወዴት መጣችሁ?” አላቸው። እነርሱም፥ “ከከነዓን ምድር እህል ልንሸምት የመጣን ነን” አሉት።'),
  ('3817ce5d-0e56-53c4-a866-de9c899bafa2', 'ae51fe87-e163-5aee-aaa1-24ce208d9e6c', 'f71d01c1-7680-50e8-ac46-4da3f3b57813', 8, 8, 'ዮሴፍም ወንድሞቹን ዐወቃቸው፤ እነርሱ ግን አላወቁትም፤ ዮሴፍም አይቶት የነበረውን ሕልም ዐሰበ።'),
  ('2f11d0ed-2c58-5de5-a4f2-9fa584ed6e67', 'ae51fe87-e163-5aee-aaa1-24ce208d9e6c', 'f71d01c1-7680-50e8-ac46-4da3f3b57813', 9, 9, 'እንዲህም አላቸው፥ “እናንተ ሰላዮች ናችሁ ፤ የሀገሩን ሁኔታ ልታዩ መጥታችኋል።”'),
  ('afd3d051-763a-55fd-a9e3-b9c3091b0f43', 'ae51fe87-e163-5aee-aaa1-24ce208d9e6c', 'f71d01c1-7680-50e8-ac46-4da3f3b57813', 10, 10, 'እነርሱም አሉት፥ “ጌታ ሆይ፥ አይደለም፤ ባሪያዎችህስ ስንዴ ሊገዙ መጥተዋል፤'),
  ('45a7197a-f0da-544d-af92-cb36042bc2bf', 'ae51fe87-e163-5aee-aaa1-24ce208d9e6c', 'f71d01c1-7680-50e8-ac46-4da3f3b57813', 11, 11, 'እኛ ሁላችን የአንድ ሰው ልጆች ነን፤ እኛ የሰላም ሰዎች ነን፤ ባሪያዎችህስ ሰላዮች አይደሉም።”'),
  ('b7deba91-f4c5-57f6-af04-e31ec9575248', 'ae51fe87-e163-5aee-aaa1-24ce208d9e6c', 'f71d01c1-7680-50e8-ac46-4da3f3b57813', 12, 12, 'እርሱም አላቸው፥ “አይደለም፤ ነገር ግን እናንተ ሰላዮች ናችሁ፤ የሀገሩንም ሁኔታ ልታዩ መጥታችኋል።”'),
  ('07b55147-00b2-5b41-a2ad-625dd651fe90', 'ae51fe87-e163-5aee-aaa1-24ce208d9e6c', 'f71d01c1-7680-50e8-ac46-4da3f3b57813', 13, 13, 'እነርሱም አሉ፥ “ባሪያዎችህ በከነዓን ምድር የምንኖር ዐሥራ ሁለት ወንድማማቾች ነን፤ ታናሹም እነሆ ዛሬ ከአባታችን ጋር ነው፤ ሌላውም ሞቶአል።”'),
  ('62f0fd17-b51a-5efe-a5b3-ffd3f67d8ecb', 'ae51fe87-e163-5aee-aaa1-24ce208d9e6c', 'f71d01c1-7680-50e8-ac46-4da3f3b57813', 14, 14, 'ዮሴፍም አላቸው፥ “እናንተ ሰላዮች ናችሁ ብዬ የተናገርሁአችሁም ይህ ነው፤ በዚህ ትታወቃላችሁ፤'),
  ('567507e6-d75c-57dd-a4a2-a208973a2af5', 'ae51fe87-e163-5aee-aaa1-24ce208d9e6c', 'f71d01c1-7680-50e8-ac46-4da3f3b57813', 15, 15, 'ታናሽ ወንድማችሁን ከአላመጣችሁ በቀር ‘የፈርዖንን ሕይወት!’ ከዚህ አትወጡም።'),
  ('f63dd796-5ede-5d84-ae3a-4e2eaa8879a3', 'ae51fe87-e163-5aee-aaa1-24ce208d9e6c', 'f71d01c1-7680-50e8-ac46-4da3f3b57813', 16, 16, 'ወንድማችሁን ያመጣ ዘንድ ከእናንተ አንዱን ላኩ፤ እናንተ ግን እውነትን የምትናገሩ ከሆነ ወይም ከአልሆነ ነገራችሁ እስኪታወቅ ድረስ ከዚህ ተቀመጡ፤ ይህ ከአልሆነ ‘የፈርዖንን ሕይወት!’ ሰላዮች ናችሁ።”'),
  ('b9517d6d-65ae-527f-aa22-76138cd05aff', 'ae51fe87-e163-5aee-aaa1-24ce208d9e6c', 'f71d01c1-7680-50e8-ac46-4da3f3b57813', 17, 17, 'ሦስት ቀን ያህልም በግዞት ቤት ጨመራቸው።'),
  ('d1b49860-a22b-5954-aee9-92656efedef9', 'ae51fe87-e163-5aee-aaa1-24ce208d9e6c', 'f71d01c1-7680-50e8-ac46-4da3f3b57813', 18, 18, 'በሦስተኛው ቀን ዮሴፍ እንዲህ አላቸው፥ “ትድኑ ዘንድ ይህን አድርጉ፤ እኔ እግዚአብሔርን እፈራለሁና።'),
  ('7cf4c680-1c09-5dc1-a77f-f351be7debf9', 'ae51fe87-e163-5aee-aaa1-24ce208d9e6c', 'f71d01c1-7680-50e8-ac46-4da3f3b57813', 19, 19, 'እናንተ ሰላማውያን ከሆናችሁ ከእናንተ አንዱ ወንድማችሁ በግዞት ቤት ይታሰር፤ እናንተ ግን ሂዱ፤ የሸመታችሁትን እህልም ውሰዱ፤'),
  ('71b6b848-af9b-54b9-a995-663902f5ce6b', 'ae51fe87-e163-5aee-aaa1-24ce208d9e6c', 'f71d01c1-7680-50e8-ac46-4da3f3b57813', 20, 20, 'ታናሹንም ወንድማችሁን ወደ እኔ አምጡ፤ ነገራችሁ የታመነ ይሆናልና፤ ይህ ከአልሆነ ግን ትሞታላችሁ።” እንዲህም አደረጉ።'),
  ('d553c17e-e830-56de-af3c-33e0f43b1ef5', 'ae51fe87-e163-5aee-aaa1-24ce208d9e6c', 'f71d01c1-7680-50e8-ac46-4da3f3b57813', 21, 21, 'እነርሱም እርስ በርሳቸው እንዲህ ተባባሉ፥ “በእውነት ወንድማችንን በድለናል፤ እኛን በመማጠን ነፍሱ ስትጨነቅ አይተን አልሰማነውምና፤ ስለዚህ ይህ መከራ መጣብን።”'),
  ('ba720639-51b6-5aad-aa71-f8ecd2f22e66', 'ae51fe87-e163-5aee-aaa1-24ce208d9e6c', 'f71d01c1-7680-50e8-ac46-4da3f3b57813', 22, 22, 'ሮቤልም መልሶ እንዲህ አላቸው፥ “ብላቴናውን አትበድሉ ብዬአችሁ አልነበረምን? እኔንም አልሰማችሁኝም፤ ስለዚህ እነሆ፥ አሁን ደሙ ይፈላለጋችኋል።”'),
  ('62ca3b65-588d-5d1a-a602-6f12be1c98f3', 'ae51fe87-e163-5aee-aaa1-24ce208d9e6c', 'f71d01c1-7680-50e8-ac46-4da3f3b57813', 23, 23, 'እነርሱም ዮሴፍ ነገራቸውን እንደሚሰማባቸው አላወቁም፤ በመካከላቸው አስተርጓሚ ነበርና።'),
  ('f850c521-96e7-5050-add6-eee6433d3165', 'ae51fe87-e163-5aee-aaa1-24ce208d9e6c', 'f71d01c1-7680-50e8-ac46-4da3f3b57813', 24, 24, 'ዮሴፍም ከእነርሱ ዘወር ብሎ አለቀሰ፤ ደግሞም ወደ እነርሱ ተመልሶ ተናገራቸው፤ ስምዖንንም ከእነርሱ ለይቶ ወስዶ በፊታቸው አሰረው።'),
  ('3efde1a0-523a-5950-a515-b975fd621863', 'ae51fe87-e163-5aee-aaa1-24ce208d9e6c', 'f71d01c1-7680-50e8-ac46-4da3f3b57813', 25, 25, 'ዮሴፍም ዓይበታቸውን እህል ይሞሉት ዘንድ አዘዘ፤ የየራሳቸውንም ብር በየዓይበታቸው ይመልሱት ዘንድ፥ ደግሞም የመንገድ ስንቅ ይሰጡአቸው ዘንድ አዘዘ። እንዲህም አደረጉ።'),
  ('42ca20b8-6c53-5ded-a84d-00a339d5bd8d', 'ae51fe87-e163-5aee-aaa1-24ce208d9e6c', '440d5768-8682-5aaf-a1b1-fd98c44c46fd', 1, 26, 'እነርሱም እህሉን በአህዮቻቸው ላይ ጫኑ፤ ከዚያም ተነሥተው ሄዱ።'),
  ('da84df85-0f00-54f7-ac11-0d38cdc099ab', 'ae51fe87-e163-5aee-aaa1-24ce208d9e6c', '440d5768-8682-5aaf-a1b1-fd98c44c46fd', 2, 27, 'ከእነርሱም አንዱ በአደሩበት ስፍራ ለአህዮቹ ገፈራን ይሰጥ ዘንድ ዓይበቱን ፈታ፤ ብሩንም በዓይበቱ አፍ ተቋጥሮ አገኘ።'),
  ('255a9803-7a23-5437-accb-a8e7388427d2', 'ae51fe87-e163-5aee-aaa1-24ce208d9e6c', '440d5768-8682-5aaf-a1b1-fd98c44c46fd', 3, 28, 'ለወንድሞቹም፥ “ብሬ ተመለሰችልኝ፤ እርስዋም በዓይበቴ አፍ እነኋት” አላቸው። ልባቸውም ደነገጠ፤ እየታወኩም እርስ በርሳቸው ተባባሉ፥ “እግዚአብሔር ያደረገብን ይህ ምንድን ነው?”'),
  ('ff682d61-4738-59fa-a30e-49c053e53818', 'ae51fe87-e163-5aee-aaa1-24ce208d9e6c', '440d5768-8682-5aaf-a1b1-fd98c44c46fd', 4, 29, 'ወደ አባታቸውም ወደ ያዕቆብ ወደ ከነዓን ምድር መጡ፤ የደረሰባቸውንም ነገር ሁሉ እንዲህ ብለው አወሩ፦'),
  ('f7c6fd07-dc63-5543-a7d6-7c797ab3b398', 'ae51fe87-e163-5aee-aaa1-24ce208d9e6c', '440d5768-8682-5aaf-a1b1-fd98c44c46fd', 5, 30, '“የሀገሩ ጌታ የሆነው ሰው በክፉ ንግግር ተናገረን፤ የምድሪቱም ሰላዮች እንደሆን አድርጎ ወደ እስር ቤት አስገባን።”'),
  ('037d5bb5-7c2e-5df5-adda-5ae1156a4d98', 'ae51fe87-e163-5aee-aaa1-24ce208d9e6c', '440d5768-8682-5aaf-a1b1-fd98c44c46fd', 6, 31, 'እኛም እንዲህ አልነው፥ “ሰላማውያን ሰዎች ነን እንጂ ሰላዮች አይደለንም፤'),
  ('33778b7f-383c-5a18-addf-394271eaf4e8', 'ae51fe87-e163-5aee-aaa1-24ce208d9e6c', '440d5768-8682-5aaf-a1b1-fd98c44c46fd', 7, 32, 'እኛ የአባታችን ልጆች ዐሥራ ሁለት ወንድማማቾች ነን፤ አንዱ ሞቶአል፤ ታናሹም በከነዓን ምድር ዛሬ ከአባታችን ጋር አለ።'),
  ('b7b3112d-bb93-53a8-aaf2-8f80a7355f31', 'ae51fe87-e163-5aee-aaa1-24ce208d9e6c', '440d5768-8682-5aaf-a1b1-fd98c44c46fd', 8, 33, 'የሀገሩም ጌታ ያ ሰው እንዲህ አለን፦ ‘ሰላማውያን ሰዎች ከሆናችሁ በዚህ ዐውቃለሁ፤ አንደኛውን ወንድማችሁን ከእኔ ጋር ተዉት፤ ለቤታችሁም የሸመታችሁትን እህል ይዛችሁ ሂዱ፤'),
  ('580bcefe-e703-51f6-abc1-c6580c95a5f6', 'ae51fe87-e163-5aee-aaa1-24ce208d9e6c', '440d5768-8682-5aaf-a1b1-fd98c44c46fd', 9, 34, 'ታናሹንም ወንድማችሁን አምጡልኝ፤ ሰላማውያን እንጂ ሰላዮች አለመሆናችሁንም በዚህ ዐውቀዋለሁ፤ ወንድማችሁንም እሰጣችኋለሁ፤ እናንተም በሀገራችን ትነግዳላችሁ።’ ”'),
  ('130258b7-a422-53d1-ad77-bdd68a34a425', 'ae51fe87-e163-5aee-aaa1-24ce208d9e6c', '440d5768-8682-5aaf-a1b1-fd98c44c46fd', 10, 35, 'እንዲህም ሆነ፤ ዓይበታቸውን በፈቱ ጊዜ እነሆ፥ ከእነርሱ እያንዳንዳቸው ብራቸውን በዓይበታቸው ተቋጥሮ አገኙት፤ እነርሱም አባታቸውም የተቋጠረ ብራቸውን አይተው ፈሩ።'),
  ('8c23b46f-335d-55dc-af67-47b8a68dae58', 'ae51fe87-e163-5aee-aaa1-24ce208d9e6c', '440d5768-8682-5aaf-a1b1-fd98c44c46fd', 11, 36, 'አባታቸው ያዕቆብም እንዲህ አላቸው፥ “ልጅ አልባ አስቀራችሁኝ፤ ዮሴፍ የለም፤ ስምዖንም የለም፤ ብንያምንም ትወስዱብኛላችሁ፤ ይህ ሁሉ በእኔ ላይ ደረሰ።”'),
  ('ad1bfceb-1fad-5f4b-a677-b43235d3c585', 'ae51fe87-e163-5aee-aaa1-24ce208d9e6c', '440d5768-8682-5aaf-a1b1-fd98c44c46fd', 12, 37, 'ሮቤልም አባቱን አለው፥ “ወደ አንተ መልሼ ያላመጣሁት እንደሆነ ሁለቱን ልጆችን ግደል፤ ልጅህን በእጄ ስጠኝ፤ እኔም ወደ አንተ እመልሰዋለሁ።”'),
  ('ab1c10df-31d3-5f2f-a150-95b7917f7a69', 'ae51fe87-e163-5aee-aaa1-24ce208d9e6c', '440d5768-8682-5aaf-a1b1-fd98c44c46fd', 13, 38, 'እርሱም አለ፥ “ልጄ ከእናንተ ጋር አይወርድም፤ ወንድሙ ሞቶ እርሱ ብቻ ቀርቶአልና፤ በምትሄዱበት መንገድ ምናልባት ክፉ ነገር ቢያገኘው ሽምግልናዬን በኀዘን ወደ መቃብር ታወርዱታላችሁ።”'),
  ('f1118e15-8d7f-5f3d-a6de-1d796813052e', '0aa40910-76fd-553b-af87-6634c608bcbe', '16ac84e4-476a-5d44-a6c1-cb8c3bf05c2f', 1, 1, 'ከዚህም በኋላ ራብ በሀገር ላይ ጸና።'),
  ('1ed476e5-bf3f-5bc7-a4e7-c7be605b1fa9', '0aa40910-76fd-553b-af87-6634c608bcbe', '16ac84e4-476a-5d44-a6c1-cb8c3bf05c2f', 2, 2, 'ከግብፅም ያመጡትን እህል በልተው ከፈጸሙ በኋላ አባታቸው፥ “እንደገና ሂዱ፤ ጥቂት እህል ሸምታችሁ አምጡልን” አላቸው።'),
  ('2a1763d0-7ae6-56b7-a663-968d48d2fe4e', '0aa40910-76fd-553b-af87-6634c608bcbe', '16ac84e4-476a-5d44-a6c1-cb8c3bf05c2f', 3, 3, 'ይሁዳም እንዲህ አለው፥ “የሀገሩ ጌታ ያ ሰው፦ ‘ወንድማችሁ ከእናንተ ጋር ከአልመጣ ፊቴን አታዩም’ ብሎ በምስክር ፊት አዳኝቶብናል።'),
  ('697b7b77-a8e4-5046-a29e-5cc86cfbf662', '0aa40910-76fd-553b-af87-6634c608bcbe', '16ac84e4-476a-5d44-a6c1-cb8c3bf05c2f', 4, 4, 'ወንድማችንን ከእኛ ጋር ብትልከው እንወርዳለን፤ እህልም እንሸምትልሃልን፤'),
  ('3643018a-05d3-5c48-aa1a-b9be2d4b9b20', '0aa40910-76fd-553b-af87-6634c608bcbe', '16ac84e4-476a-5d44-a6c1-cb8c3bf05c2f', 5, 5, 'ወንድማችንን ከእኛ ጋር ባትልከው ግን አንሄድም፤ ያ ሰው ‘ታናሽ ወንድማችሁን ከእናንተ ጋር ካላመጣችሁ ፊቴን አታዩም’ ብሎናልና።”'),
  ('06d01838-6907-5a4e-ab8e-3f4b920db7db', '0aa40910-76fd-553b-af87-6634c608bcbe', '16ac84e4-476a-5d44-a6c1-cb8c3bf05c2f', 6, 6, 'እስራኤልም አላቸው፥ “በእኔ ላይ ያደረጋችኋት ይህች ክፋት ምንድን ናት? በዚያውስ ላይ ሌላ ወንድም አለን ብላችሁ ለምን ነገራችሁት?”'),
  ('461ba155-cc9d-52ec-a010-bb2d5200a37a', '0aa40910-76fd-553b-af87-6634c608bcbe', '16ac84e4-476a-5d44-a6c1-cb8c3bf05c2f', 7, 7, 'እነርሱም አሉ፥ “ያ ሰው ስለ እኛና ስለ ትውልዳችን ፈጽሞ ጠየቀን፤ እንዲህም አለን፦ ‘ሽማግሌው አባታችሁ ገና በሕይወት ነው? ወንድምስ አላችሁን?’ እኛም እንደዚሁ እንደ ጠየቀን መለስንለት፤ በውኑ፦ ‘ወንድማችሁን አምጡ’ እንዲለን እናውቅ ነበርን?”'),
  ('f4b6fd6b-dce4-58c3-a4e6-35fa0d217ef1', '0aa40910-76fd-553b-af87-6634c608bcbe', '16ac84e4-476a-5d44-a6c1-cb8c3bf05c2f', 8, 8, 'ይሁዳም አባቱን እስራኤልን አለው፥ “እኛና አንተ ልጆቻችንም ደግሞ እንድንድን፥ እንዳንሞትም ብላቴናውን ከእኔ ጋር ላከው፤ እኛም ተነሥተን እንሄዳለን።'),
  ('3a6ea51f-8270-5ed0-aa84-1bcd0d0384e6', '0aa40910-76fd-553b-af87-6634c608bcbe', '16ac84e4-476a-5d44-a6c1-cb8c3bf05c2f', 9, 9, 'እኔ እዋሳለሁ፤ ከእጄ ትሻዋለህ፤ ወደ አንተ ባላመጣው፥ በፊትህም ባላቆመው፥ በዘመናት ሁሉ አንተን የበደልሁህ ልሁን።'),
  ('8dee8ccb-ce93-5418-af1c-ea29405a349a', '0aa40910-76fd-553b-af87-6634c608bcbe', '16ac84e4-476a-5d44-a6c1-cb8c3bf05c2f', 10, 10, 'ባንዘገይስ ኖሮ አሁን ሁለተኛ ጊዜ በተመለስን ነበር።”'),
  ('4bc8b5bf-180e-58da-a8cc-aed2f58946f8', '0aa40910-76fd-553b-af87-6634c608bcbe', '16ac84e4-476a-5d44-a6c1-cb8c3bf05c2f', 11, 11, 'አባታቸው እስራኤልም እንዲህ አላቸው፥ “ነገሩ እንዲህ ከሆነስ ይህን አድርጉ ፤ ከምድሩ ፍሬ በዓይበታችሁ ይዛችሁ ሂዱ፤ ለዚያም ሰው እጅ መንሻ፥ ጥቂት በለሳን፥ ጥቂት ማር፥ ሽቱ፥ ዕጣን፥ ተምር፥ ለውዝ ውሰዱ።'),
  ('a1af37af-6a65-58b8-aa17-1bafb38c0ac1', '0aa40910-76fd-553b-af87-6634c608bcbe', '16ac84e4-476a-5d44-a6c1-cb8c3bf05c2f', 12, 12, 'ብሩን በአጠፌታ አድርጋችሁ በእጃችሁ ውሰዱ፤ በዓይበታችሁም አፍ የተመለሰውን ብር መልሳችሁ ውሰዱ፤ ምናልባት ባለማወቅ ይሆናል።'),
  ('1f83c247-3d49-5590-a1cf-2b79a4f0021a', '0aa40910-76fd-553b-af87-6634c608bcbe', '16ac84e4-476a-5d44-a6c1-cb8c3bf05c2f', 13, 13, 'ወንድማችሁንም ከእናንተ ጋር ውሰዱ፤ ተነሥታችሁም ወደዚያ ሰው ውረዱ።'),
  ('d17245e4-f265-5bd2-a3d2-a674528a43e0', '0aa40910-76fd-553b-af87-6634c608bcbe', '16ac84e4-476a-5d44-a6c1-cb8c3bf05c2f', 14, 14, 'አምላኬም በዚያ ሰው ፊት ሞገስን ይስጣችሁ፤ ያን ወንድማችሁንና ብንያምንም ይመልስላችሁ፤ እኔም ልጆችን እንዳጣሁ አጣሁ።”'),
  ('ccd7b4f8-2e78-5cf8-ad27-c301d5693e93', '0aa40910-76fd-553b-af87-6634c608bcbe', '16ac84e4-476a-5d44-a6c1-cb8c3bf05c2f', 15, 15, 'ሰዎቹም በእጃቸው ያችን እጅ መንሻና ብራቸውን በእጥፍ፥ ብንያምንም ከእነርሱ ጋር ወሰዱ፤ ተነሥተውም ወደ ግብፅ ወረዱ፤ በዮሴፍም ፊት ቆሙ፤ ሰገዱለትም።'),
  ('5f25a6bf-416f-5f96-a9d2-92f5e4058a2d', '0aa40910-76fd-553b-af87-6634c608bcbe', '16ac84e4-476a-5d44-a6c1-cb8c3bf05c2f', 16, 16, 'ዮሴፍም ብንያምን ከእነርሱ ጋር በአየው ጊዜ የቤቱን አዛዥ እንዲህ ብሎ አዘዘው፥ “እነዚያን ሰዎች ወደ ቤት አስገባቸው፤ እርድም እረድ፤ አዘጋጅም፤ እነዚያ ሰዎች በእኩለ ቀን ከእኔ ጋር ይበላሉና።”'),
  ('9a3bb056-66b5-51b4-a08b-fa095cf97a56', '0aa40910-76fd-553b-af87-6634c608bcbe', '16ac84e4-476a-5d44-a6c1-cb8c3bf05c2f', 17, 17, 'ያም ሰው ዮሴፍ እንዳለው አደረገ፤ ሰዎቹንም ወደ ዮሴፍ ቤት አስገባ።'),
  ('c6d9305c-2a6c-5371-a753-8529ce452f3c', '0aa40910-76fd-553b-af87-6634c608bcbe', '16ac84e4-476a-5d44-a6c1-cb8c3bf05c2f', 18, 18, 'እነዚያም ሰዎች ወደ ዮሴፍ ቤት እንደ ገቡ በአዩ ጊዜ እንዲህ አሉ፥ “በዓይበታችን ቀድሞ ስለ ተመለሰው ብር ሊተነኰሉብን፥ ሊወድቁብንም፥ እኛንም በባርነት ሊገዙን፥ አህዮቻችንንም ሊወስዱ ወደዚህ አስገቡን።”'),
  ('873b77ac-b648-51bb-a58c-079aa1b6a028', '0aa40910-76fd-553b-af87-6634c608bcbe', '16ac84e4-476a-5d44-a6c1-cb8c3bf05c2f', 19, 19, 'ወደ ዮሴፍ ቤት አዛዥም ቀረቡ፤ በቤቱም ደጅ ተናገሩት፤'),
  ('42e125b2-62de-510c-a2a5-bc110c1541f3', '0aa40910-76fd-553b-af87-6634c608bcbe', '16ac84e4-476a-5d44-a6c1-cb8c3bf05c2f', 20, 20, 'እንዲህም አሉ፥ “ጌታ ሆይ፥ እንማልድሃለን፤ ቀድሞ እህልን ልንሸምት ወርደን ነበር፤'),
  ('afb99541-e530-5935-accd-4e3bf33a09d0', '0aa40910-76fd-553b-af87-6634c608bcbe', '16ac84e4-476a-5d44-a6c1-cb8c3bf05c2f', 21, 21, 'እንዲህም ሆነ፥ ወደምናድርበትም ስፍራ በደረስን ጊዜ ዓይበታችንን ከፈትን፤ እነሆም፥ የየአንዳንዱ ሰው ብር በየዓይበቱ አፍ ነበር፤ አሁንም ብራችንን በእጃችን እንደ ሚዛኑ መለስነው።'),
  ('da5d76ab-1811-5a6d-a2fe-c9945cad55a0', '0aa40910-76fd-553b-af87-6634c608bcbe', '16ac84e4-476a-5d44-a6c1-cb8c3bf05c2f', 22, 22, 'እህል እንሸምትበት ዘንድ ሌላም ብር በእጃችን አመጣን፤ ብራችንንም በዓይበታችን ማን እንደ ጨመረው አናውቅም።”'),
  ('2f182793-fa08-51df-a151-2245b3047c75', '0aa40910-76fd-553b-af87-6634c608bcbe', '16ac84e4-476a-5d44-a6c1-cb8c3bf05c2f', 23, 23, 'እርሱም አላቸው፥ “ሰላም ለእናንተ ይሁን፥ አትፍሩ፤ አምላካችሁ የአባቶቻችሁ አምላክ በዓይበታችሁ የተሰወረ ገንዘብ ሰጣችሁ፤ ብራችሁንስ መዝኜ ተቀብያለሁ።”'),
  ('45c35978-7f51-52f0-ad78-431b4cba45ae', '0aa40910-76fd-553b-af87-6634c608bcbe', '16ac84e4-476a-5d44-a6c1-cb8c3bf05c2f', 24, 24, 'ስምዖንንም ወደ እነርሱ አወጣላቸው። እግራቸውንም ሊታጠቡ ውኃ አመጣላቸው፤ ለአህዮቻቸውም ገፈራ ሰጣቸው።'),
  ('adf74a98-2776-51c6-ad88-81d41295676f', '0aa40910-76fd-553b-af87-6634c608bcbe', '16ac84e4-476a-5d44-a6c1-cb8c3bf05c2f', 25, 25, 'ዮሴፍም በእኩለ ቀን እስኪገባ ድረስ እነርሱ እጅ መንሻቸውን አዘጋጁ፤ ከዚያ ምሳ እንደሚበሉ ሰምተዋልና።'),
  ('bc49e1b3-9ea6-5966-ac0b-f48a1ece0160', '0aa40910-76fd-553b-af87-6634c608bcbe', '16ac84e4-476a-5d44-a6c1-cb8c3bf05c2f', 26, 26, 'ዮሴፍም ወደ ቤቱ በገባ ጊዜ በእጃቸው ያለውን እጅ መንሻ በቤት ውስጥ አቀረቡለት፤ ወደ ምድርም በግንባራቸው ወድቀው ሰገዱለት።'),
  ('5c446f8b-c409-590f-ad76-5bebc4156afe', '0aa40910-76fd-553b-af87-6634c608bcbe', '16ac84e4-476a-5d44-a6c1-cb8c3bf05c2f', 27, 27, 'እርሱም ደኅንነታቸውን ጠየቃቸው፤ እንዲህም አለ፥ “የነገራችሁኝ ሽማግሌ አባታችሁ ደኅና ነውን? ገና በሕይወት አለን?”'),
  ('1869869b-1608-5467-ac6c-3081161222d3', '0aa40910-76fd-553b-af87-6634c608bcbe', '16ac84e4-476a-5d44-a6c1-cb8c3bf05c2f', 28, 28, 'እነርሱም አሉት፥ “ባሪያህ ሽማግሌው አባታችን ደኅና ነው፤ ገና በሕይወት አለ።” ዮሴፍም አለ፥ “ሰውየው እግዚአብሔር የባረከው ነው።” ራሳቸውንም ዝቅ አድርገው ሰገዱለት።'),
  ('cbee62b1-c361-52d4-af90-d18fe80cf57c', '0aa40910-76fd-553b-af87-6634c608bcbe', '16ac84e4-476a-5d44-a6c1-cb8c3bf05c2f', 29, 29, 'ዮሴፍም ዐይኑን አንሥቶ የእናቱን ልጅ ወንድሙ ብንያምን አየው፤ እርሱም አለ፥ “ወደ አንተ እናመጣዋለን ብላችሁ የነገራችሁኝ ታናሽ ወንድማችሁ ይህ ነውን?” እነርሱም፥ “አዎን” አሉት። እንዲህም አለው፥ “ልጄ ሆይ፥ እግዚአብሔር ይቅር ይበልህ።”'),
  ('1a50cb26-7c94-547a-a14c-88cb6facae3a', '0aa40910-76fd-553b-af87-6634c608bcbe', '16ac84e4-476a-5d44-a6c1-cb8c3bf05c2f', 30, 30, 'ዮሴፍም ታወከ፤ አንጀቱ ወንድሙን ናፍቆታልና፤ ሊያለቅስም ወደደ፤ ወደ እልፍኙም ገብቶ በዚያ አለቀሰ።'),
  ('5eacd4fe-515f-5f31-afa7-87214c953091', '0aa40910-76fd-553b-af87-6634c608bcbe', '16ac84e4-476a-5d44-a6c1-cb8c3bf05c2f', 31, 31, 'ፊቱንም ታጥቦ ተጽናንቶም ወጣ። “እንጀራ አቅርቡልን” አለ።'),
  ('049ffeb6-c705-5e87-a9a2-635ccfe43791', '0aa40910-76fd-553b-af87-6634c608bcbe', '16ac84e4-476a-5d44-a6c1-cb8c3bf05c2f', 32, 32, 'ለእርሱም ለብቻው አቀረቡ፤ ለእነርሱም ለብቻቸው፤ ከእርሱ ጋር ለሚበሉት ለግብፅ ሰዎችም ለብቻቸው፤ የግብፅ ሰዎች ከዕብራውያን ጋር መብላት አይችሉምና፥ ይህ ለግብፅ ሰዎች እንደ መርከስ ነውና።'),
  ('67b67211-882f-5993-a282-874d9eb65042', '0aa40910-76fd-553b-af87-6634c608bcbe', '16ac84e4-476a-5d44-a6c1-cb8c3bf05c2f', 33, 33, 'በፊቱም በኵሩ እንደ ታላቅነቱ፥ ታናሹም እንደ ታናሽነቱ ተቀመጡ፤ እነርሱም እርስ በርሳቸው በመደነቅ ተያዩ።'),
  ('a9148b2e-817d-531c-af05-2e3511d7a1b1', '0aa40910-76fd-553b-af87-6634c608bcbe', '16ac84e4-476a-5d44-a6c1-cb8c3bf05c2f', 34, 34, 'በፊቱም ከአለው መብል ፈንታቸውን አቀረበላቸው፤ የብንያምም ፈንታ ከሁሉ አምስት እጅ የሚበልጥ ነበረ። እነርሱም በሉ፤ ጠጡም፤ ከእርሱም ጋር ደስ አላቸው።'),
  ('5144551e-b4a3-5257-ab72-cabe3d60aa51', 'cf190beb-ef08-5a81-aaaa-b52da0f38ee0', 'f7946e9b-0f6d-5780-a466-08e5f7605ca5', 1, 1, 'ዮሴፍም የቤቱን አዛዥ እንዲህ ብሎ አዘዘው፥ “የእነዚህ ሰዎች ዓይበቶቻቸው መያዝ የሚችሉትን ያህል እህል ሙላላቸው፤ የሁሉንም ብር በየዓይበታቸው አፍ ጨምረው፤'),
  ('6c2a58c5-4931-51b4-a63f-0ca060d0c3f6', 'cf190beb-ef08-5a81-aaaa-b52da0f38ee0', 'f7946e9b-0f6d-5780-a466-08e5f7605ca5', 2, 2, 'በታናሹም ዓይበት አፍ የብሩን ጽዋዬንና የእህሉን ዋጋ ጨምረው።” እርሱም ዮሴፍ እንዳለው አደረገ።'),
  ('72c5dd50-2aa7-5d92-ab3a-ad1c589382d9', 'cf190beb-ef08-5a81-aaaa-b52da0f38ee0', 'f7946e9b-0f6d-5780-a466-08e5f7605ca5', 3, 3, 'ነግህ በሆነ ጊዜም ሰዎቹ አህዮቻቸውን ይዘው ይሄዱ ዘንድ አሰናበታቸው።'),
  ('cc51e9b8-5f7c-5520-a06e-dcdca65584fe', 'cf190beb-ef08-5a81-aaaa-b52da0f38ee0', 'f7946e9b-0f6d-5780-a466-08e5f7605ca5', 4, 4, 'ከከተማዪቱም ወጥተው ገና ሳይርቁ ዮሴፍ ለቤቱ አዛዥ እንዲህ አለ፥ “ተነሥተህ ሰዎቹን ተከትለህ ያዛቸው፤ እንዲህም በላቸው፦ በመልካሙ ፈንታ ስለምን ክፉን መለሳችሁ?'),
  ('8446aa46-fef0-53d8-a705-a9dcb3c15e87', 'cf190beb-ef08-5a81-aaaa-b52da0f38ee0', 'f7946e9b-0f6d-5780-a466-08e5f7605ca5', 5, 5, 'ጌታዬ የሚጠጣበትን፥ ምስጢርንም የሚያውቅበትን የብር ጽዋ ለምን ሰረቃችሁ? ባደረጋችሁት ነገር በደላችሁ።”'),
  ('1f5dfbb4-5268-580c-aad0-d205617d1181', 'cf190beb-ef08-5a81-aaaa-b52da0f38ee0', 'f7946e9b-0f6d-5780-a466-08e5f7605ca5', 6, 6, 'እርሱም ሂዶ አገኛቸው፤ “ለምን እንዲህ አደረጋችሁ? ስለ አደረግሁላችሁ መልካም ነገር ለምን ክፉ ትከፍሉኛላችሁ? የጌታዬንስ የብር ጽዋ ለምን ሰረቃችሁኝ?” አላቸው።'),
  ('aa406558-62de-5ce8-aed6-2118428b795d', 'cf190beb-ef08-5a81-aaaa-b52da0f38ee0', 'f7946e9b-0f6d-5780-a466-08e5f7605ca5', 7, 7, 'እነርሱም አሉት፥ “ጌታችን እንደዚህ ለምን ክፉ ትናገራለህ? ይህን ነገር ያደርጉት ዘንድ ለባሪያዎችህ አግባባቸው አይደለም።'),
  ('14e64b16-4957-590a-a224-5f419ae4f035', 'cf190beb-ef08-5a81-aaaa-b52da0f38ee0', 'f7946e9b-0f6d-5780-a466-08e5f7605ca5', 8, 8, 'በየዓይበታችን አፍ ያገኘነውን ብር እንኳን ይዘን ከከነዓን ሀገር ወደ አንተ ተመልሰናል፤ ከጌታህስ ቤት ወርቅ ወይስ ብር እንዴት እንሰርቃለን?'),
  ('426ecdd5-427a-5b35-a4fb-9b1f89ae8556', 'cf190beb-ef08-5a81-aaaa-b52da0f38ee0', 'f7946e9b-0f6d-5780-a466-08e5f7605ca5', 9, 9, 'አሁንም ከባሪያዎችህ ጽዋው የተገኘበት እርሱ ይሙት፤ እኛም ደግሞ ለጌታችን አገልጋዮች እንሁን።”'),
  ('56356891-3a45-575d-aad1-02a7486c9361', 'cf190beb-ef08-5a81-aaaa-b52da0f38ee0', 'f7946e9b-0f6d-5780-a466-08e5f7605ca5', 10, 10, 'እርሱም አለ፥ “አሁንም እንዲሁ እንደ ነገራችሁ ይሁን፤ ጽዋው የተገኘበት እርሱ ለእኔ አገልጋይ ይሁነኝ፤ እናንተም ንጹሓን ትሆናላችሁ።”'),
  ('54432828-430e-599f-a4c0-0920f72a7435', 'cf190beb-ef08-5a81-aaaa-b52da0f38ee0', 'f7946e9b-0f6d-5780-a466-08e5f7605ca5', 11, 11, 'እየራሳቸውም ፈጥነው ዓይበታቸውን ወደ ምድር አወረዱ፤ እየራሳቸውም ዓይበታቸውን ፈቱ።'),
  ('6ea40b31-5632-5e8d-a5bd-b82577252874', 'cf190beb-ef08-5a81-aaaa-b52da0f38ee0', 'f7946e9b-0f6d-5780-a466-08e5f7605ca5', 12, 12, 'እርሱም ከታላቁ ጀምሮ እስከ ታናሹ ድረስ በረበራቸው፤ ጽዋውንም በብንያም ዓይበት ውስጥ አገኘው።'),
  ('17c27fd5-e6c3-5226-ad70-14bf901f2a0a', 'cf190beb-ef08-5a81-aaaa-b52da0f38ee0', 'f7946e9b-0f6d-5780-a466-08e5f7605ca5', 13, 13, 'ልብሳቸውንም ቀደዱ፤ ዓይበታቸውንም በየአህዮቻቸው ጭነው ወደ ከተማዪቱ ተመለሱ።'),
  ('a1c3f1e6-a2f7-5d18-aa39-b7b0a4a891e9', 'cf190beb-ef08-5a81-aaaa-b52da0f38ee0', 'f7946e9b-0f6d-5780-a466-08e5f7605ca5', 14, 14, 'ይሁዳም ከወንድሞቹ ጋር ወደ ዮሴፍ ገባ፤ እርሱም ገና ከዚያው ነበረ፤ በፊቱም በምድር ላይ ወደቁ።'),
  ('e34477cb-5f7e-5a68-af27-9c3a20132596', 'cf190beb-ef08-5a81-aaaa-b52da0f38ee0', 'f7946e9b-0f6d-5780-a466-08e5f7605ca5', 15, 15, 'ዮሴፍም፥ “ይህ ያደረጋችሁት ነገር ምንድን ነው? እንደ እኔ ያለ ሰው ምሥጢርን እንዲያውቅ አታውቁምን?” አላቸው።'),
  ('70355746-0ac5-51a7-a896-df5789bd26a7', 'cf190beb-ef08-5a81-aaaa-b52da0f38ee0', 'f7946e9b-0f6d-5780-a466-08e5f7605ca5', 16, 16, 'ይሁዳም አለ፦ “ለጌታችን ምን እንመልሳለን? ምንስ እንናገራለን? ወይስ በምን እንነጻለን? እግዚአብሔር የአገልጋዮችህን ኀጢአት ገለጠ። እነሆ፥ እኛም ጽዋው ከእርሱ ዘንድ የተገኘበትም ደግሞ ለጌታችን አገልጋዮቹ ነን።”'),
  ('534cd127-0a1b-5d62-ad6a-7056f3570b8b', 'cf190beb-ef08-5a81-aaaa-b52da0f38ee0', 'f7946e9b-0f6d-5780-a466-08e5f7605ca5', 17, 17, 'ዮሴፍም አላቸው፥ “ይህን አደርግ ዘንድ አይገባኝም፤ ጽዋው የተገኘበት ሰው እርሱ አገልጋይ ይሁነኝ እንጂ፤ እናንተ ግን ወደ አባታችሁ በደኅና ሂዱ።”'),
  ('b2f5293c-6eac-51f8-a758-bec84d9b6bfc', 'cf190beb-ef08-5a81-aaaa-b52da0f38ee0', 'b2bd8e4d-50c1-51c3-a1e3-a83c5c18ec2f', 1, 18, 'ይሁዳም ወደ እርሱ ቀረበ፤ እንዲህም አለ፥ “ጌታዬ ሆይ፥ እኔ አገልጋይህ በፊትህ አንዲት ቃልን እንድናገር እለምናለሁ፤ እኔን አገልጋይህን አትቈጣኝ፤ አንተ ከፈርዖን ቀጥለህ ነህና።'),
  ('a4c5da6c-2e4c-51c2-a572-9853fa6fa223', 'cf190beb-ef08-5a81-aaaa-b52da0f38ee0', 'b2bd8e4d-50c1-51c3-a1e3-a83c5c18ec2f', 2, 19, 'ጌታዬ አገልጋዮችህን፦ አባት አላችሁን? ወይስ ወንድም? ብለህ ጠየቅሃቸው።'),
  ('771e6ab2-729e-5436-a57d-b90c606996d0', 'cf190beb-ef08-5a81-aaaa-b52da0f38ee0', 'b2bd8e4d-50c1-51c3-a1e3-a83c5c18ec2f', 3, 20, 'እኛም ለጌታዬ እንዲህ አልን፦ ሽማግሌ አባት አለን፤ በሽምግልናው የወለደውም ታናሽ ብላቴና አለ፤ ወንድሙ ግን ሞተ፤ ለእናቱም እርሱ ብቻውን ቀረ፤ አባቱም ይወድደዋል።'),
  ('e9c363fa-32a7-53bb-a64e-3792b2e979ef', 'cf190beb-ef08-5a81-aaaa-b52da0f38ee0', 'b2bd8e4d-50c1-51c3-a1e3-a83c5c18ec2f', 4, 21, 'አንተም ለአገልጋዮችህ፦ ወደ እኔ አምጡት፤ እኔም እጠብቀዋለሁ አልህ።'),
  ('6d28e235-10bd-5316-a85a-8cc8316a0ec6', 'cf190beb-ef08-5a81-aaaa-b52da0f38ee0', 'b2bd8e4d-50c1-51c3-a1e3-a83c5c18ec2f', 5, 22, 'ጌታዬንም፦ ብላቴናው አባቱን መተው አይሆንለትም፤ የተወው እንደ ሆነ አባቱ ይሞታልና አልንህ።'),
  ('36117f88-337c-5afe-a9b5-eead9c115043', 'cf190beb-ef08-5a81-aaaa-b52da0f38ee0', 'b2bd8e4d-50c1-51c3-a1e3-a83c5c18ec2f', 6, 23, 'አንተ ጌታችንም አገልጋዮችህን፦ ታናሽ ወንድማችሁን ከእናንተ ጋር ከአላመጣችሁት ዳግመኛ ፊቴን አታዩም አልኸን።'),
  ('4a86159f-9d61-5260-a2e1-0e5dfabc5419', 'cf190beb-ef08-5a81-aaaa-b52da0f38ee0', 'b2bd8e4d-50c1-51c3-a1e3-a83c5c18ec2f', 7, 24, 'ወደ ባሪያህ ወደ አባታችን በተመለስን ጊዜም የጌታችንን ቃል ነገርነው።'),
  ('fc56bbbb-4917-5ae8-a0b4-8c0153dd2aea', 'cf190beb-ef08-5a81-aaaa-b52da0f38ee0', 'b2bd8e4d-50c1-51c3-a1e3-a83c5c18ec2f', 8, 25, 'አባታችንም፦ ዳግመኛ ሄዳችሁ ጥቂት እህል ሸምቱልን አለን።'),
  ('e62c0ebf-6338-5eed-a6e4-0cf5e70ca6af', 'cf190beb-ef08-5a81-aaaa-b52da0f38ee0', 'b2bd8e4d-50c1-51c3-a1e3-a83c5c18ec2f', 9, 26, 'እኛም አልነው፦ ታናሹ ወንድማችን ከእኛ ጋር ካልሄደ መሄድ አንችልም፤ ታናሹ ወንድማችን ከእኛ ጋር ከሌለ የዚያን ሰው ፊት ማየት አይቻለንምና።'),
  ('3ac564e2-0e3c-5d1f-af9d-a113c5528677', 'cf190beb-ef08-5a81-aaaa-b52da0f38ee0', 'b2bd8e4d-50c1-51c3-a1e3-a83c5c18ec2f', 10, 27, 'አገልጋይህ አባታችንም እንዲህ አለን፦ ሚስቴ ሁለት ወንዶች ልጆችን እንደ ወለደችልኝ እናንተ ታውቃላችሁ፤'),
  ('d5f9b627-2327-5719-a546-4fdeedaac1ad', 'cf190beb-ef08-5a81-aaaa-b52da0f38ee0', 'b2bd8e4d-50c1-51c3-a1e3-a83c5c18ec2f', 11, 28, 'አንዱም ከእኔ ወጣ፤ አውሬ በላው አላችሁኝ፤ እስከ ዛሬም ገና አላየሁትም፤'),
  ('2deb7cc2-8cfe-5c0e-a834-2228588773d3', 'cf190beb-ef08-5a81-aaaa-b52da0f38ee0', 'b2bd8e4d-50c1-51c3-a1e3-a83c5c18ec2f', 12, 29, 'ይህንም ከእኔ ለይታችሁ ደግሞ ብትወስዱት በመንገድም ክፉ ቢያገኘው፥ እርጅናዬን በኀዘን ወደ መቃብር ታወርዱታላችሁ።'),
  ('a8a35c84-4d97-5c26-ad06-8d2e866b74f3', 'cf190beb-ef08-5a81-aaaa-b52da0f38ee0', 'b2bd8e4d-50c1-51c3-a1e3-a83c5c18ec2f', 13, 30, 'አሁንም እኛ ወደ አባታችን ወደ አገልጋይህ ብንሄድ፥ ብላቴናውም ከእኛ ጋር ከሌለ፥ ነፍሱ በብላቴናው ነፍስ ታስራለችና'),
  ('0cdd84f4-696b-55e0-a248-2a1528a0ccc9', 'cf190beb-ef08-5a81-aaaa-b52da0f38ee0', 'b2bd8e4d-50c1-51c3-a1e3-a83c5c18ec2f', 14, 31, 'ብላቴናው ከእኛ ጋር እንደሌለ በአየ ጊዜ ይሞታል፤ አገልጋዮችህም የአገልጋይህን የአባታችንን እርጅና በኀዘን ወደ መቃብር እናወርዳለን።'),
  ('483bcaf4-2784-5eee-a7d9-84722bdec8ca', 'cf190beb-ef08-5a81-aaaa-b52da0f38ee0', 'b2bd8e4d-50c1-51c3-a1e3-a83c5c18ec2f', 15, 32, 'እኔ አገልጋይህ በአባቴ ዘንድ ስለ ብላቴናው እንዲህ ብዬ ተውሼአለሁና፦ እርሱንስ ወደ አንተ መልሼ በፊትህ ባላቆመው በአባቴ ዘንድ በዘመናት ሁሉ ኀጢአተኛ እሆናለሁ።'),
  ('d99eea4d-3793-58bf-a340-c69999bdecf3', 'cf190beb-ef08-5a81-aaaa-b52da0f38ee0', 'b2bd8e4d-50c1-51c3-a1e3-a83c5c18ec2f', 16, 33, 'አሁንም እኔ በብላቴናው ፈንታ የጌታዬ አገልጋይ ሆኜ ልቀመጥ፤ ብላቴናው ግን ከወንድሞቹ ጋር ይሂድ።'),
  ('f1b5d396-69be-53ee-a274-d2098fd55435', 'cf190beb-ef08-5a81-aaaa-b52da0f38ee0', 'b2bd8e4d-50c1-51c3-a1e3-a83c5c18ec2f', 17, 34, 'አለዚያም ብላቴናው ከእኛ ጋር ከሌለ እኔ ወደ አባታችን እንዴት እሄዳለሁ? አባታችንን የሚያገኘውን መከራ እንዳላይ።”'),
  ('033a826e-418c-5f98-af7b-3fc11700716c', '1aa5d404-92c1-5b44-a06f-d1f65edde0a2', '79c604d5-35ae-5f7f-af26-1b183d6e672e', 1, 1, 'ዮሴፍም በፊቱ ሰዎች ሁሉ ቆመው ሳሉ ሊታገሥ አልተቻለውም፥ “ሰዎቹንም ሁሉ ከፊቴ አስወጡልኝ” ብሎ ተናገረ፤ ዮሴፍ ለወንድሞቹ ራሱን በገለጠ ጊዜ በእርሱ ዘንድ የቆመ ማንም አልነበረም።'),
  ('993ac786-3cca-5543-a460-a293cc1a7474', '1aa5d404-92c1-5b44-a06f-d1f65edde0a2', '79c604d5-35ae-5f7f-af26-1b183d6e672e', 2, 2, 'ቃሉንም ከፍ አድርጎ አለቀሰ፤ የግብፅ ሰዎችም ሰሙ፤ በፈርዖን ቤትም ተሰማ።'),
  ('5e17679c-b34d-5e8c-a58a-797827d53872', '1aa5d404-92c1-5b44-a06f-d1f65edde0a2', '79c604d5-35ae-5f7f-af26-1b183d6e672e', 3, 3, 'ዮሴፍም ለወንድሞቹ፥ “እኔ ወንድማችሁ ዮሴፍ ነኝ፤ አባቴ እስከ አሁን በሕይወቱ ነውን?” አላቸው። ወንድሞቹም ይመልሱለት ዘንድ አልቻሉም፤ ደንግጠው ነበርና።'),
  ('1e9b5c58-51eb-5431-a9ef-0d5c8ece3eb2', '1aa5d404-92c1-5b44-a06f-d1f65edde0a2', '79c604d5-35ae-5f7f-af26-1b183d6e672e', 4, 4, 'ዮሴፍም ወንድሞቹን፥ “ወደ እኔ ቅረቡ” አላቸው። ወደ እርሱም ቀረቡ። እንዲህም አላቸው፥ “ወደ ግብፅ የሸጣችሁኝ እኔ ወንድማችሁ ዮሴፍ ነኝ።'),
  ('6a5f3481-172e-5171-acd0-9e2691ec180f', '1aa5d404-92c1-5b44-a06f-d1f65edde0a2', '79c604d5-35ae-5f7f-af26-1b183d6e672e', 5, 5, 'አሁንም ወደዚህ ስለሸጣችሁኝ አትፍሩ፤ አትቈርቈሩም፤ እግዚአብሔር ለሕይወት ከእናንተ በፊት ልኮኛልና።'),
  ('d22197b6-e7ba-55d8-aa84-15b56845288a', '1aa5d404-92c1-5b44-a06f-d1f65edde0a2', '79c604d5-35ae-5f7f-af26-1b183d6e672e', 6, 6, 'እነሆ፥ ይህ ሁለቱ ዓመት በምድር ላይ ራብ የሆነበት ነውና፤ የማይታረስበትና የማይታጨድበት አምስት ዓመት ገና አለ።'),
  ('bb9ed1cb-1251-5017-a00d-0f5f52daffdb', '1aa5d404-92c1-5b44-a06f-d1f65edde0a2', '79c604d5-35ae-5f7f-af26-1b183d6e672e', 7, 7, 'እግዚአብሔርም በምድር ላይ እንድትድኑና እንድትተርፉ እመግባችሁ ዘንድ ከእናንተ በፊት ላከኝ።'),
  ('c4af4fdc-aaf0-5cdd-a497-d65c482715e0', '1aa5d404-92c1-5b44-a06f-d1f65edde0a2', '79c604d5-35ae-5f7f-af26-1b183d6e672e', 8, 8, 'አሁንም እናንተ ወደዚህ የላካችሁኝ አይደላችሁም፤ እግዚአብሔር ላከኝ እንጂ፤ ለፈርዖንም እንደ አባት አደረገኝ፤ በቤቱም ሁሉ ላይ ጌታ፥ በግብፅ ምድርም ሁሉ ላይ አለቃ አደረገኝ።'),
  ('ff7e108b-7a75-5c0e-a00e-b31725b80d48', '1aa5d404-92c1-5b44-a06f-d1f65edde0a2', '79c604d5-35ae-5f7f-af26-1b183d6e672e', 9, 9, 'አሁንም ፈጥናችሁ ወደ አባቴ ሂዱ፤ እንዲህም በሉት፦ ልጅህ ዮሴፍ የሚለው ነገር ይህ ነው፦ እግዚአብሔር በግብፅ ምድር ሁሉ ላይ ጌታ አደረገኝ፤ ወደ እኔ ና፤ በዚያም አትዘግይ፤'),
  ('e5ac1203-b5ad-565e-a87a-9ea18eb9377c', '1aa5d404-92c1-5b44-a06f-d1f65edde0a2', '79c604d5-35ae-5f7f-af26-1b183d6e672e', 10, 10, 'በዐረብ በኩል በጌሤም ምድርም ትቀመጣለህ፤ ወደ እኔም ትቀርባለህ። አንተና ልጆችህ የልጆችህም ልጆች፥ በጎችህና ላሞችህ፥ የአንተ የሆነው ሁሉ፥'),
  ('1c1bad1b-d886-5af3-a3d6-7b6e8a0114d9', '1aa5d404-92c1-5b44-a06f-d1f65edde0a2', '79c604d5-35ae-5f7f-af26-1b183d6e672e', 11, 11, 'በዚያም አንተና የቤትህ ሰዎች የአንተ የሆነው ሁሉ እንዳትቸገሩ እመግብሃለሁ፤ የራቡ ዘመን ገና አምስት ዓመት ቀርቶአልና፤'),
  ('75008f06-b9cc-5025-a359-5d0efab7c3d4', '1aa5d404-92c1-5b44-a06f-d1f65edde0a2', '79c604d5-35ae-5f7f-af26-1b183d6e672e', 12, 12, 'እነሆም፥ ለእናንተ እኔ ራሴ በአፌ እንደ ተናገርሁአችሁ እናንተ በዐይኖቻችሁ አይታችኋል፤ ወንድሜ ብንያም በዐዓይኖቹ አይቶአል።'),
  ('b81577c1-0cce-5af9-a8d7-6568767de16a', '1aa5d404-92c1-5b44-a06f-d1f65edde0a2', '79c604d5-35ae-5f7f-af26-1b183d6e672e', 13, 13, 'ለአባቴ በግብፅ ምድር ያለኝን ክብሬን ሁሉ፥ በዐይኖቻችሁ ያያችሁትንም ሁሉ ንገሩት፤ አባቴንም ወደዚህ ፈጥናችሁ አምጡት።”'),
  ('d5d32bef-c66b-5abb-aa02-6a2a3a9d33ba', '1aa5d404-92c1-5b44-a06f-d1f65edde0a2', '79c604d5-35ae-5f7f-af26-1b183d6e672e', 14, 14, 'የወንድሙን የብንያምንም አንገት አቅፎ አለቀሰ፤ ብንያምም በአንገቱ ላይ አለቀሰ።'),
  ('2a71f451-6cbd-57fc-a516-cf002fcc953f', '1aa5d404-92c1-5b44-a06f-d1f65edde0a2', '79c604d5-35ae-5f7f-af26-1b183d6e672e', 15, 15, 'ወንድሞቹን ሁሉ ሳማቸው፤ በእነርሱም ላይ አለቀሰ፤ ከዚያም በኋላ ወንድሞቹ ከእርሱ ጋር ተጨዋወቱ።'),
  ('b65bf560-4205-5fc6-ad98-1f95c661d752', '1aa5d404-92c1-5b44-a06f-d1f65edde0a2', '79c604d5-35ae-5f7f-af26-1b183d6e672e', 16, 16, 'በፈርዖንም ቤት፥ “የዮሴፍ ወንድሞች መጡ” ተብሎ ወሬ ተሰማ፤ ፈርዖንና ቤተ ሰቡም ሁሉ ደስ አላቸው።'),
  ('5a0e86ea-da31-5c4a-a91f-ccdb9cf81897', '1aa5d404-92c1-5b44-a06f-d1f65edde0a2', '79c604d5-35ae-5f7f-af26-1b183d6e672e', 17, 17, 'ፈርዖንም ዮሴፍን አለው፥ “ለወንድሞችህ እንዲህ ብለህ ንገራቸው፦ ይህን አድርጉ፤ ዕቃችሁን ጭናችሁ ወደ ከነዓን ምድር ሂዱ፤'),
  ('b5b651ae-7101-58b2-a1e4-4daf754990e2', '1aa5d404-92c1-5b44-a06f-d1f65edde0a2', '79c604d5-35ae-5f7f-af26-1b183d6e672e', 18, 18, 'አባታችሁንና ንብረታችሁን ሁሉ ይዛችሁ ወደ እኔ ኑ፤ እኔም የግብፅን ምድር በረከት ሁሉ እሰጣችሁአለሁ፤ የምድሪቱንም ድልብ ትበላላችሁ።'),
  ('90d9925c-85d9-5dd5-a199-ee6da35432a3', '1aa5d404-92c1-5b44-a06f-d1f65edde0a2', '79c604d5-35ae-5f7f-af26-1b183d6e672e', 19, 19, 'አንተም ወንድሞችህን፦ እንዲህ አድርጉ በላቸው፤ ከግብፅ ምድር ለሕፃኖቻችሁ፥ ለሴቶቻችሁም ሰረገሎችን ውሰዱ፤ አባታችሁንም ይዛችሁ ኑ፤'),
  ('cff98996-1171-5751-af9a-7a5b18695b43', '1aa5d404-92c1-5b44-a06f-d1f65edde0a2', '79c604d5-35ae-5f7f-af26-1b183d6e672e', 20, 20, 'ለዕቃችሁም ዐይናችሁ ለአየውም ሁሉ አታስቡ፤ የግብፅ በረከት ሁሉ ለእናንተ ነውና።”'),
  ('363514d0-7e8f-5870-a8fe-2e7e5f273c1d', '1aa5d404-92c1-5b44-a06f-d1f65edde0a2', '79c604d5-35ae-5f7f-af26-1b183d6e672e', 21, 21, 'የእስራኤል ልጆችም እንደ አዘዛቸው አደረጉ፤ ዮሴፍም የግብፅ ንጉሥ ፈርዖን እንደ ነገረው ሰረገሎችንና ለመንገድ ስንቅን ሰጣቸው፤'),
  ('f077ab60-798f-5b51-a944-2c1b96e9febd', '1aa5d404-92c1-5b44-a06f-d1f65edde0a2', '79c604d5-35ae-5f7f-af26-1b183d6e672e', 22, 22, 'ለሁሉም ሁለት ሁለት መለወጫ ልብስ ሰጣቸው፤ ለብንያም ግን ሦስት መቶ ብርና አምስት መለወጫ ልብስ ሰጠው።'),
  ('66658c92-cc22-5457-a35b-dad2cba19fc3', '1aa5d404-92c1-5b44-a06f-d1f65edde0a2', '79c604d5-35ae-5f7f-af26-1b183d6e672e', 23, 23, 'ለአባቱም እንደዚሁ ላከ፤ ከግብፅ በረከት ሁሉ የተጫኑ ዐሥር አህዮችን፥ ደግሞም በመንገድ ለአባቱ ስንቅ የተጫኑ ዐሥር በቅሎዎችን።'),
  ('5449d057-6171-528e-a94e-943d214a01f4', '1aa5d404-92c1-5b44-a06f-d1f65edde0a2', '79c604d5-35ae-5f7f-af26-1b183d6e672e', 24, 24, 'ዮሴፍም ወንድሞቹን አሰናበታቸው፤ እንዲህም አላቸው፥ “በመንገድ እርስ በርሳችሁ አትጣሉ።”'),
  ('10057f64-9993-5d34-ad67-43362e4b11cc', '1aa5d404-92c1-5b44-a06f-d1f65edde0a2', '79c604d5-35ae-5f7f-af26-1b183d6e672e', 25, 25, 'እነርሱም ከግብፅ ሀገር ወጥተው ሄዱ፤ ወደ ከነዓንም ምድር ወደ አባታቸው ወደ ያዕቆብ ደረሱ።'),
  ('a7d261f9-c28a-5ecf-a793-5aa6e155a98f', '1aa5d404-92c1-5b44-a06f-d1f65edde0a2', '79c604d5-35ae-5f7f-af26-1b183d6e672e', 26, 26, 'እንዲህም ብለው ነገሩት፥ “ልጅህ ዮሴፍ በሕይወቱ ነው፤ እርሱም በግብፅ ምድር ሁሉ ላይ ገዥ ሆኖአል።” ያዕቆብም ልቡ ደነገጠ፤ አላመናቸውምም፤'),
  ('0337b2dc-a835-5b20-ad87-99397aa3d54b', '1aa5d404-92c1-5b44-a06f-d1f65edde0a2', '79c604d5-35ae-5f7f-af26-1b183d6e672e', 27, 27, 'እነርሱም ዮሴፍ ያላቸውን፥ የተናገራቸውንም ነገር ሁሉ ነገሩት፤ ይወስዱት ዘንድ ዮሴፍ የላካቸውን ሰረገሎች በአየ ጊዜ የአባታቸው የያዕቆብ ልቡ፥ መንፈሱም ታደሰ።'),
  ('876eee47-455b-587e-add8-30ee7602b7db', '1aa5d404-92c1-5b44-a06f-d1f65edde0a2', '79c604d5-35ae-5f7f-af26-1b183d6e672e', 28, 28, 'እስራኤልም፥ “ልጄ ዮሴፍ ገና በሕይወት ከሆነ ይህ ለእኔ ታላቅ ነገር ነው፤ ሳልሞት እንዳየው እሄዳለሁ” አለ።'),
  ('ec955b45-0f21-5b2e-a8a7-2af994254b81', '95e0023a-1119-53db-a60d-0ce7309d72b6', 'c2012b30-98af-5326-a3cb-e2f6cb46face', 1, 1, 'እስራኤልም ለእርሱ ያለውን ሁሉ ይዞ ተነሣ፤ ወደ ዐዘቅተ መሐላም መጣ፤ መሥዋዕትንም ለአባቱ ለይስሐቅ አምላክ ሠዋ።'),
  ('759decef-1192-5339-a4d4-9c0fa1389e15', '95e0023a-1119-53db-a60d-0ce7309d72b6', 'c2012b30-98af-5326-a3cb-e2f6cb46face', 2, 2, 'እግዚአብሔርም በሌሊት ራእይ፥ “ያዕቆብ ያዕቆብ” ብሎ ለእስራኤል ተናገረው። እርሱም “ምንድን ነው?” አለ።'),
  ('dd03521d-ebe7-53ac-a18b-0f2a761b4acf', '95e0023a-1119-53db-a60d-0ce7309d72b6', 'c2012b30-98af-5326-a3cb-e2f6cb46face', 3, 3, 'አለውም፥ “የአባቶችህ አምላክ እግዚአብሔር እኔ ነኝ፤ ወደ ግብፅ መውረድን አትፍራ፤ በዚያ ትልቅ ሕዝብ አደርግሃለሁና።'),
  ('fb4f06f9-e2e7-5d9c-a279-fb40333a10ba', '95e0023a-1119-53db-a60d-0ce7309d72b6', 'c2012b30-98af-5326-a3cb-e2f6cb46face', 4, 4, 'እኔ ወደ ግብፅ አብሬህ እወርዳለሁ፤ ከዚያም ደግሞ እኔ አወጣሃለሁ፤ ልጅህ ዮሴፍም እጁን በዐይንህ ላይ ያኖራል።”'),
  ('ad3c3a03-49a8-56ca-a554-8704c57213ab', '95e0023a-1119-53db-a60d-0ce7309d72b6', 'c2012b30-98af-5326-a3cb-e2f6cb46face', 5, 5, 'ያዕቆብም ከዐዘቅተ መሐላ ተነሣ፤ የእስራኤልም ልጆች አባታቸውን፥ ገንዘባቸውን፥ ሚስቶቻቸውንም እነርሱን ያመጡባቸው ዘንድ ዮሴፍ በላካቸው ሰረገሎች ጭነው ወሰዱ።'),
  ('ca4b1328-a6df-55b2-a799-fcfce8536fcd', '95e0023a-1119-53db-a60d-0ce7309d72b6', 'c2012b30-98af-5326-a3cb-e2f6cb46face', 6, 6, 'ጓዛቸውን፥ በከነዓን ሀገርም ያገኙትን ጥሪታቸውን ሁሉ ይዘው ያዕቆብና ዘሩ ሁሉ ከእርሱ ጋር ወደ ግብፅ መጡ፤'),
  ('aa450d3b-9d57-5405-a98e-a3fc22cae11b', '95e0023a-1119-53db-a60d-0ce7309d72b6', 'c2012b30-98af-5326-a3cb-e2f6cb46face', 7, 7, 'ወንዶች ልጆቹንና የወንዶች ልጆቹን ወንዶች ልጆች፥ ሴቶች ልጆቹንና የሴቶች ልጆቹን ሴቶች ልጆች፥ ዘሩንም ሁሉ ከእርሱ ጋር ወደ ግብፅ አስገባቸው።'),
  ('0130cef0-c49e-5429-a68d-54e0f9e01698', '95e0023a-1119-53db-a60d-0ce7309d72b6', 'c2012b30-98af-5326-a3cb-e2f6cb46face', 8, 8, 'ከአባታቸው ከያዕቆብ ጋር ወደ ግብፅ የገቡት የእስራኤል ልጆች ስም ይህ ነው፤ ያዕቆብና ልጆቹ፤ የያዕቆብ በኵር ሮቤል።'),
  ('62f1dfb6-b1ff-5145-a0ea-a24048b458af', '95e0023a-1119-53db-a60d-0ce7309d72b6', 'c2012b30-98af-5326-a3cb-e2f6cb46face', 9, 9, 'የሮቤልም ልጆች፤ ሄኖኅ፥ ፍሉስ፥ አስሮን፥ ከርሜ።'),
  ('463b8ec1-5ac5-5d67-a700-8366bb6147ad', '95e0023a-1119-53db-a60d-0ce7309d72b6', 'c2012b30-98af-5326-a3cb-e2f6cb46face', 10, 10, 'የስምዖን ልጆች፤ ይሙኤል፥ ያሚን፥ አኡድ፥ ያኪን፥ ሱሐር፥ የከነዓናዊት ልጅ ሳዑል።'),
  ('aa414b9a-3254-588d-a378-148e95538727', '95e0023a-1119-53db-a60d-0ce7309d72b6', 'c2012b30-98af-5326-a3cb-e2f6cb46face', 11, 11, 'የሌዊም ልጆች፤ ጌድሶን፥ ቀዓት፥ ሜራሪ።'),
  ('b8ec6e19-31e7-5ef3-af92-8e001890c71c', '95e0023a-1119-53db-a60d-0ce7309d72b6', 'c2012b30-98af-5326-a3cb-e2f6cb46face', 12, 12, 'የይሁዳም ልጆች፤ ዔር፥ አውናን፥ ሴሎም፥ ፋሬስ፥ ዛራ፤ ዔርና አውናን በከነዓን ምድር ሞቱ። የፋሬስም ልጆች እኒህ ናቸው፤ ኤስሮም፥ ይሞሔል፤'),
  ('d345faa7-5baf-519c-a731-c0ed620c53cd', '95e0023a-1119-53db-a60d-0ce7309d72b6', 'c2012b30-98af-5326-a3cb-e2f6cb46face', 13, 13, 'የይሳኮርም ልጆች፤ ቶላዕ፥ ፎሓ፥ ያሱብ፥ ስምራ።'),
  ('41c3c084-64c2-5ca1-a038-f96e8dacd9fe', '95e0023a-1119-53db-a60d-0ce7309d72b6', 'c2012b30-98af-5326-a3cb-e2f6cb46face', 14, 14, 'የዛብሎንም ልጆች፤ ሳሬድ፥ አሎን፥ አሌል።'),
  ('1aa3eeb1-a84b-5266-a8bc-4d0bfeb7989d', '95e0023a-1119-53db-a60d-0ce7309d72b6', 'c2012b30-98af-5326-a3cb-e2f6cb46face', 15, 15, 'ልያ በመስጴጦምያ በሶርያ ለያዕቆብ የወለደቻቸው ልጆችና ሴቲቱ ልጅዋ ዲና እነዚህ ናቸው፤ ወንዶችም ሴቶችም ልጆችዋ ሁሉ ሠላሳ አራት ነፍስ ናቸው።'),
  ('82e50226-1296-5b97-a40a-3b53677a18f0', '95e0023a-1119-53db-a60d-0ce7309d72b6', 'c2012b30-98af-5326-a3cb-e2f6cb46face', 16, 16, 'የጋድም ልጆች፤ ስፎን፥ ሐጊ፥ ሱኒ፥ አዜን፥ አድ፥ አሮሐድ፥ አርሔል።'),
  ('3f048e6f-9044-5262-a308-cfc2a1633f28', '95e0023a-1119-53db-a60d-0ce7309d72b6', 'c2012b30-98af-5326-a3cb-e2f6cb46face', 17, 17, 'የአሴርም ልጆች፤ ኢያምን፥ ኢያሱ፥ኢዩል፥ በሪዓ፥ እኅታቸው ሳራ፤ የበሪዓ ልጆችም፤ ኮቦር፥ መልኪኤል።'),
  ('09a3adf6-663a-54f6-a795-447e22200cb9', '95e0023a-1119-53db-a60d-0ce7309d72b6', 'c2012b30-98af-5326-a3cb-e2f6cb46face', 18, 18, 'ላባ ለልጁ ለልያ የሰጣት የዘለፋ ልጆች እነዚህ ናቸው፤ እርስዋም እነዚህን ዐሥራ ስድስቱን ነፍስ ለያዕቆብ ወለደች።'),
  ('5104cfec-f92e-50c6-a555-e22ae19c6114', '95e0023a-1119-53db-a60d-0ce7309d72b6', 'c2012b30-98af-5326-a3cb-e2f6cb46face', 19, 19, 'የያዕቆብ ሚስት የራሔል ልጆች ዮሴፍና ብንያም ናቸው።'),
  ('81a67d55-1b91-5334-a44a-58c363186b2c', '95e0023a-1119-53db-a60d-0ce7309d72b6', 'c2012b30-98af-5326-a3cb-e2f6cb46face', 20, 20, 'ለዮሴፍም በግብፅ ምድር ልጆች ተወለዱለት፤ እነርሱም የሄልዮቱ ከተማ ካህን የጴጤፌራ ልጅ አስኔት የወለደችለት ምናሴና ኤፍሬም ናቸው። ሶርያዊት ዕቅብቱ የወለደችለት የምናሴም ልጅ ማኪር ነው። ማኪርም ገለዓድን ወለደ፤ የምናሴም ወንድም የኤፍሬም ልጆች ሱታላና ጠኀን ናቸው። የሱታላ ልጅም ኤዴን ነው።'),
  ('3941ed14-e06a-5fa4-ae1a-4f6df8ed9a3b', '95e0023a-1119-53db-a60d-0ce7309d72b6', 'c2012b30-98af-5326-a3cb-e2f6cb46face', 21, 21, 'የብንያምም ልጆች፤ ቤላ፥ ቦኮር፥ አስቤር፤ የቤላ ልጆችም፤ ጌራ፥ ኖሔማን፥ አሒ፥ ሮስ፥ ማንፌን፥ ሑፈም፤ ጌራም አራድን ወለደ።'),
  ('1a525b98-9f19-53c9-adc6-0b9d7be076c7', '95e0023a-1119-53db-a60d-0ce7309d72b6', 'c2012b30-98af-5326-a3cb-e2f6cb46face', 22, 22, 'ለያዕቆብ የተወለዱለት የራሔል ልጆችም እነዚህ ናቸው፤ ሁሉም ዐሥራ አራት ነፍስ ናቸው።'),
  ('3dab2e0d-041d-5ddd-a4ba-075acf7142fc', '95e0023a-1119-53db-a60d-0ce7309d72b6', 'c2012b30-98af-5326-a3cb-e2f6cb46face', 23, 23, 'የዳንም ልጅ አሳ ነው።'),
  ('51e166ca-9ebd-5a7b-af57-76b5ecf616e3', '95e0023a-1119-53db-a60d-0ce7309d72b6', 'c2012b30-98af-5326-a3cb-e2f6cb46face', 24, 24, 'የንፍታሌምም ልጆች፤ አሴሔል፥ ጎሂን፥ ዮሴር ሴሌም።'),
  ('cdb70909-3feb-5475-ae75-f9cacd305a6c', '95e0023a-1119-53db-a60d-0ce7309d72b6', 'c2012b30-98af-5326-a3cb-e2f6cb46face', 25, 25, 'ላባ ለልጁ ለራሔል የሰጣት የባላ ልጆች እነዚህ ናቸው፤ እነዚህንም ለያዕቆብ ወለደችለት፤ ባላ የወለደቻቸው ሁሉም ሰባት ነፍስ ናቸው።'),
  ('6066b6f6-3027-5e5b-aea5-d50ded128bbe', '95e0023a-1119-53db-a60d-0ce7309d72b6', 'c2012b30-98af-5326-a3cb-e2f6cb46face', 26, 26, 'ከያዕቆብ ጋር ወደ ግብፅ የገቡት ሰዎች ሁሉ ከጕልበቱ የወጡት፥ ከልጆቹ ሚስቶች ሌላ፥ ሁላቸው ስድሳ ሰባት ናቸው።'),
  ('68c9e7f7-6582-5a9a-aab0-8a3f8db2dabb', '95e0023a-1119-53db-a60d-0ce7309d72b6', 'c2012b30-98af-5326-a3cb-e2f6cb46face', 27, 27, 'በግብፅ ምድር የተወለዱለት የዮሴፍም ልጆች ሁለት ናቸው፤ ወደ ግብፅ የገቡት የያዕቆብ ቤተ ሰዎች ሁሉ ሰባ ናቸው።'),
  ('222fd0cf-b522-5c40-adfe-54934354d233', '95e0023a-1119-53db-a60d-0ce7309d72b6', '0e8c8d54-134f-55c4-a2f0-55f75f94d1d1', 1, 28, 'ይሁዳንም ኤሮስ በምትባል በራምሴ ከተማ እንዲቀበለው በፊቱ ወደ ዮሴፍ ላከው፤'),
  ('ee92d094-bc3f-5d56-adb2-2db915b39db3', '95e0023a-1119-53db-a60d-0ce7309d72b6', '0e8c8d54-134f-55c4-a2f0-55f75f94d1d1', 2, 29, 'ዮሴፍም ሰረገላውን አዘጋጀ፤ አባቱንም እስራኤልን ሊገናኘው ወደ ኤሮስ ከተማ ወጣ፤ በአየውም ጊዜ አንገቱን አቀፈው፤ ረዥም ጊዜም አለቀሰ።'),
  ('9b7f3461-04da-53da-a47e-faf96b8f2cfd', '95e0023a-1119-53db-a60d-0ce7309d72b6', '0e8c8d54-134f-55c4-a2f0-55f75f94d1d1', 3, 30, 'እስራኤልም ዮሴፍን፥ “አንተ ገና በሕይወት ሳለህ ፊትህን አይችአለሁና አሁን ልሙት” አለው።'),
  ('9662dfc7-6f4c-51b3-a5fa-b777f8976556', '95e0023a-1119-53db-a60d-0ce7309d72b6', '0e8c8d54-134f-55c4-a2f0-55f75f94d1d1', 4, 31, 'ዮሴፍም ወንድሞቹን እንዲህ አላቸው፥ “እኔ ሄጄ ለፈርዖን እንዲህ ብዬ እነግረዋለሁ፦ በከነዓን ምድር የነበሩት ወንድሞችና የአባቴ ቤተ ሰዎች ወደ እኔ መጥተዋል፤'),
  ('2c91daa9-38f5-5eff-a916-b85a21db34d6', '95e0023a-1119-53db-a60d-0ce7309d72b6', '0e8c8d54-134f-55c4-a2f0-55f75f94d1d1', 5, 32, 'እነርሱም ከብት ጠባቂዎች፥ መንጋ አርቢዎች ናቸው፤ በጎቻቸውንና ላሞቻቸውን፥ ያላቸውንም ሁሉ አመጡ።'),
  ('76e52933-b749-5b72-ab7c-10384d17586d', '95e0023a-1119-53db-a60d-0ce7309d72b6', '0e8c8d54-134f-55c4-a2f0-55f75f94d1d1', 6, 33, 'ፈርዖንም ቢጠራችሁ ተግባራችሁስ ምንድን ነው? ቢላችሁ፥'),
  ('1ad6e8e1-864d-5159-ad06-e1d92b0a17bd', '95e0023a-1119-53db-a60d-0ce7309d72b6', '0e8c8d54-134f-55c4-a2f0-55f75f94d1d1', 7, 34, 'በግ ጠባቂ ሁሉ ለግብፅ ሰዎች ርኩስ ነውና በዐረብ በኩል በጌሤም እንድትቀመጡ እኛ አገልጋዮችህ ከብላቴንነታችን ጀምረን እስከ አሁን ድረስ እኛም አባቶቻችንም እንስሳ አርቢዎች ነን” በሉት።'),
  ('338312a5-e804-5491-a416-f8072854c29a', 'aea1c7d5-ed2e-50b6-ab79-ba4140420682', '69da92be-dbd6-5eab-aca4-1d3671bbe703', 1, 1, 'ዮሴፍም ገባ፤ ለፈርዖንም እንዲህ ብሎ ነገረው፥ “አባቴና ወንድሞች በጎቻቸውም፥ ላሞቻቸውም፥ ያላቸውም ሁሉ ከከነዓን ምድር መጡ፤ እነርሱም እነሆ፥ ወደ ጌሤም ምድር ደረሱ።”'),
  ('a6ceaf60-28d3-5468-aefb-b3fb455ce42e', 'aea1c7d5-ed2e-50b6-ab79-ba4140420682', '69da92be-dbd6-5eab-aca4-1d3671bbe703', 2, 2, 'ከወንድሞቹም አምስት ሰዎችን ወስዶ በፈርዖን ፊት አቆማቸው።'),
  ('088ea9f7-1a6e-5d18-a7d3-43212456190c', 'aea1c7d5-ed2e-50b6-ab79-ba4140420682', '69da92be-dbd6-5eab-aca4-1d3671bbe703', 3, 3, 'ፈርዖንም የዮሴፍን ወንድሞች፥ “ሥራችሁ ምንድን ነው?” አላቸው። እነርሱም ፈርዖንን፥ “እኛ አገልጋዮችህ፥ አባታችንም ከብት ጠባቂዎች ነን” አሉት።'),
  ('15cdc5ce-e61e-5aaa-af67-85f0072b7732', 'aea1c7d5-ed2e-50b6-ab79-ba4140420682', '69da92be-dbd6-5eab-aca4-1d3671bbe703', 4, 4, 'ፈርዖንንም እንዲህ አሉት፥ “በምድር ልንቀመጥ በእንግድነት መጣን፤ የአገልጋዮችህ በጎች የሚሰማሩበት ስፍራ የለምና፤ ራብም በከነዓን ምድር እጅግ ጸንቶአልና፤ አሁንም አገልጋዮችህ በጌሤም ምድር እንቀመጥ።”'),
  ('8a3f89b1-de70-5289-a2b4-d40f64cbfab8', 'aea1c7d5-ed2e-50b6-ab79-ba4140420682', '69da92be-dbd6-5eab-aca4-1d3671bbe703', 5, 5, 'ፈርዖንም ዮሴፍን እንዲህ ብሎ ተናገረው፥ “አባትህና ወንድሞችህ መጥተውልሃል፤ እነሆ፥ የግብፅ ምድር በፊትህ ናት፤'),
  ('df737ee8-6033-519c-a32b-dd43db019ad1', 'aea1c7d5-ed2e-50b6-ab79-ba4140420682', '69da92be-dbd6-5eab-aca4-1d3671bbe703', 6, 6, 'በመልካሙ ምድር አባትህንና ወንድሞችህን አኑራቸው፤ ከእነርሱም ውስጥ ዕውቀት ያላቸውን ሰዎች ታውቅ እንደሆነ በእንስሶች ጠባቂዎች ላይ አለቆች አድርጋቸው።”'),
  ('c43d9560-8efb-575b-aa79-b160e2eccfb1', 'aea1c7d5-ed2e-50b6-ab79-ba4140420682', '69da92be-dbd6-5eab-aca4-1d3671bbe703', 7, 7, 'ዮሴፍም ያዕቆብን አባቱን አስገብቶ በፈርዖን ፊት አቆመው፤ ያዕቆብም ፈርዖንን ባረከው።'),
  ('c402ed48-8d47-5156-ab94-a701e165e77b', 'aea1c7d5-ed2e-50b6-ab79-ba4140420682', '69da92be-dbd6-5eab-aca4-1d3671bbe703', 8, 8, 'ፈርዖንም ያዕቆብን፥ “የኖርኸው ዘመን ስንት ነው?” አለው።'),
  ('e6569f9a-1640-599a-a2f2-6079a737ef5f', 'aea1c7d5-ed2e-50b6-ab79-ba4140420682', '69da92be-dbd6-5eab-aca4-1d3671bbe703', 9, 9, 'ያዕቆብም ለፈርዖን አለው፥ “በእንግድነት የኖርሁት የሕይወቴ ዘመንስ መቶ ሠላሳ ዓመት ነው፤ የሕይወቴም ዘመኖች ጥቂትም ክፉም ሆኑብኝ፤ አባቶች በእንግድነት የተቀመጡበትንም ዘመን አያህሉም።”'),
  ('c20ef1e6-253a-5929-a4cf-3c568ae2cbf7', 'aea1c7d5-ed2e-50b6-ab79-ba4140420682', '69da92be-dbd6-5eab-aca4-1d3671bbe703', 10, 10, 'ያዕቆብም ፈርዖንን ባረከው፤ ከፈርዖንም ፊት ወጣ።'),
  ('c70e7a76-7cec-5ab0-aaf5-4baee732a7db', 'aea1c7d5-ed2e-50b6-ab79-ba4140420682', '69da92be-dbd6-5eab-aca4-1d3671bbe703', 11, 11, 'ዮሴፍም አባቱንና ወንድሞቹን አኖረ፤ ፈርዖን እንዳዘዘላቸውም በግብፅ ምድር በተሻለችው በራምሴ ምድር ርስትን ሰጣቸው።'),
  ('18060732-5579-5238-ae34-8e3b083dba1b', 'aea1c7d5-ed2e-50b6-ab79-ba4140420682', '69da92be-dbd6-5eab-aca4-1d3671bbe703', 12, 12, 'ዮሴፍም ለአባቱና ለወንድሞቹ፥ ለአባቱም ቤተ ሰዎች ሁሉ ለእያንዳንዱ ሰው እየሰፈረ እህልን ለምግብ ይሰጣቸው ነበር።'),
  ('615f5b07-f79c-58f2-ad0f-1ab8f7ffa13b', 'aea1c7d5-ed2e-50b6-ab79-ba4140420682', '6bdce766-4e35-57de-a606-e599149be8fa', 1, 13, 'በምድርም ሁሉ እህል አልነበረም፤ ራብ እጅግ ጸንቶአልና፤ ከራብም የተነሣ የግብፅ ምድርና የከነዓን ምድር ተጐዳ።'),
  ('2289dc70-ff61-5199-a956-1075bd2efab7', 'aea1c7d5-ed2e-50b6-ab79-ba4140420682', '6bdce766-4e35-57de-a606-e599149be8fa', 2, 14, 'ዮሴፍም ከግብፅ ምድርና ከከነዓን ምድር በእህል ሸመታ የተገኘውን ብሩን ሁሉ አከማቸ፤ ዮሴፍም ብሩን ወደ ፈርዖን ቤት አስገባው።'),
  ('32a9252a-fb72-5978-aa56-1cbd44ae45e8', 'aea1c7d5-ed2e-50b6-ab79-ba4140420682', '6bdce766-4e35-57de-a606-e599149be8fa', 3, 15, 'ብሩም በግብፅ ምድርና በከነዓን ምድር አለቀ፤ የግብፅ ሰዎችም ሁሉ ወደ ዮሴፍ መጡ፤ እንዲህ ሲሉ፥ “በፊትህ እንዳንሞት እህል ስጠን፤ ብሩ አልቆብናልና።”'),
  ('fdc81b23-083d-520a-a2fa-9388983082fd', 'aea1c7d5-ed2e-50b6-ab79-ba4140420682', '6bdce766-4e35-57de-a606-e599149be8fa', 4, 16, 'ዮሴፍም፥ “ከብቶቻችሁን አምጡልኝ፤ ብር ከአለቀባችሁ በከብቶቻችሁ ፈንታ እህል እሰጣችኋለሁ” አለ።'),
  ('fd12555e-2a21-5fef-afda-2528e53f7eaf', 'aea1c7d5-ed2e-50b6-ab79-ba4140420682', '6bdce766-4e35-57de-a606-e599149be8fa', 5, 17, 'ከብቶቻቸውንም ወደ ዮሴፍ አመጡ፤ ዮሴፍም በፈረሶቻቸው፥ በበጎቻቸውም፥ በላሞቻቸውም፥ በአህዮቻቸውም ፈንታ እህልን ሰጣቸው፤ በዚያች ዓመትም ስለ ከብቶቻቸው ሁሉ ፈንታ እህልን መገባቸው።'),
  ('b9465bc9-1170-5cb3-ab97-b13e41adaef6', 'aea1c7d5-ed2e-50b6-ab79-ba4140420682', '6bdce766-4e35-57de-a606-e599149be8fa', 6, 18, 'ያችም ዓመት ተፈጸመች፤ በሁለተኛዋም ዓመት ወደ እርሱ መጥተው እንዲህ አሉት፥ “እኛ ለጌታችን ሞተን እንዳናልቅበት እህል ስጠን፤ ብሩ በፍጹም አለቀ፤ ንብረታችንና ከብታችንም በጌታችን ዘንድ ነው፤ ከሰውነታችንና ከምድራችን በቀር በጌታችን ፊት አንዳች የቀረን የለም፤'),
  ('5367b251-ff2f-5018-af05-dae1a206b73e', 'aea1c7d5-ed2e-50b6-ab79-ba4140420682', '6bdce766-4e35-57de-a606-e599149be8fa', 7, 19, 'እንግዲህ እኛ በፊትህ እንዳንሞት፥ ምድራችንም እንዳትጠፋ፥ እኛንም፥ ምድራችንንም በእህል ግዛን፤ እኛም ለፈርዖን አገልጋዮች እንሁን፤ ምድራችንም ለእርሱ ትሁን፤ እኛ እንድንድን፥ እንዳንሞትም፥ ምድራችንም እንዳትጠፋ እንዘራ ዘንድ ዘር ስጠን።”'),
  ('0f3f4711-3c52-5a02-a117-03b297d170e1', 'aea1c7d5-ed2e-50b6-ab79-ba4140420682', '6bdce766-4e35-57de-a606-e599149be8fa', 8, 20, 'ዮሴፍም የግብፅን ምድር ሁሉ ለፈርዖን ገዛ፤ የግብፅ ሰዎች ሁሉ ራብ ስለጸናባቸው ርስታቸውን ሸጠዋልና፤ ምድሪቱ ለፈርዖን ሆነች።'),
  ('96951aa6-2cb5-5d86-a83b-14d2325c3099', 'aea1c7d5-ed2e-50b6-ab79-ba4140420682', '6bdce766-4e35-57de-a606-e599149be8fa', 9, 21, 'ሕዝቡንም ሁሉ ከግብፅ ዳርቻ አንሥቶ እስከ ሌላው ዳርቻዋ ድረስ አገልጋዮች አደረጋቸው።'),
  ('48ee0a76-110d-5c49-a29a-79296bade4d4', 'aea1c7d5-ed2e-50b6-ab79-ba4140420682', '6bdce766-4e35-57de-a606-e599149be8fa', 10, 22, 'ዮሴፍ የካህናትን ምድር ብቻ አልገዛም፤ ፈርዖን ለካህናቱ ድርጎ ይሰጣቸው ነበርና፥ ፈርዖንም የሰጣቸውን ድርጎ ይበሉ ነበር፤ ስለዚህም ምድራቸውን አልሸጡም።'),
  ('3c83ab04-6f5c-54a9-a76c-40c369d48443', 'aea1c7d5-ed2e-50b6-ab79-ba4140420682', '6bdce766-4e35-57de-a606-e599149be8fa', 11, 23, 'ዮሴፍም የግብፅን ሰዎች ሁሉ እንዲህ አላቸው፥ “እነሆ ዛሬ እናንተንና ምድራችሁን ለፈርዖን ገዝቻችኋለሁ፤ ለእናንተ ዘር ውሰዱና ምድሪቱን ዝሩ፤'),
  ('41b1fb90-7d3c-5bb6-a001-755830914d3c', 'aea1c7d5-ed2e-50b6-ab79-ba4140420682', '6bdce766-4e35-57de-a606-e599149be8fa', 12, 24, 'በመከርም ጊዜ ፍሬውን ከአምስት እጅ አንዱን እጅ ለፈርዖን ስጡ፤ አራቱም እጅ ለእናንተ ለራሳችሁ፥ ለእርሻው ዘርና ለእናንተ ምግብ፥ ለቤተ ሰባችሁም ሁሉ ሲሳይ ይሁን።”'),
  ('1fd50e91-13ad-5b66-a3e6-28694b6e1c11', 'aea1c7d5-ed2e-50b6-ab79-ba4140420682', '6bdce766-4e35-57de-a606-e599149be8fa', 13, 25, 'እነርሱም፥ “አንተ አዳንኸን፤ በጌታችንም ፊት ሞገስን አገኘን፤ ለፈርዖንም አገልጋዮች እንሆናለን” አሉት።'),
  ('453d9178-b986-5693-ae59-a86a2472e64e', 'aea1c7d5-ed2e-50b6-ab79-ba4140420682', '6bdce766-4e35-57de-a606-e599149be8fa', 14, 26, 'ዮሴፍም ለፈርዖን ካልሆነችው ከካህናቱ ምድር በቀር አምስተኛው እጅ ለፈርዖን እንዲሆን በግብፅ ምድር እስከ ዛሬ ሕግ አደረጋት።'),
  ('e0a38a8a-6d24-564c-ac03-cddbb6892351', 'aea1c7d5-ed2e-50b6-ab79-ba4140420682', 'dc7e928c-265d-56bb-ab34-14b8a1313bfd', 1, 27, 'እስራኤልም በግብፅ ምድር በጌሤም ሀገር ተቀመጠ፤ እርስዋም ርስታቸው ሆነች፤ በዙ፤ እጅግም ተባዙ።'),
  ('cfc9bea6-bc86-58bb-aaa5-5fdbb4071091', 'aea1c7d5-ed2e-50b6-ab79-ba4140420682', 'dc7e928c-265d-56bb-ab34-14b8a1313bfd', 2, 28, 'ያዕቆብም በግብፅ ምድር ዐሥራ ሰባት ዓመት ተቀመጠ፤ የያዕቆብም መላው የሕይወቱ ዘመን መቶ አርባ ሰባት ዓመት ሆነ።'),
  ('5eed9f63-fa54-5979-add9-ef0f64daeaae', 'aea1c7d5-ed2e-50b6-ab79-ba4140420682', 'dc7e928c-265d-56bb-ab34-14b8a1313bfd', 3, 29, 'የእስራኤልም የሞቱ ቀን ቀረበ፤ ልጁን ዮሴፍንም ጠርቶ እንዲህ አለው፥ “በፊትህ ሞገስን አግኝቼ እንደ ሆንሁ እጅህን በጕልበቴ ላይ አድርግ፤ በግብፅ ምድርም እንዳትቀብረኝ ምሕረትንና እውነትን አድርግልኝ፤'),
  ('47cd8bc2-53fd-5f17-a29d-377bb06cf769', 'aea1c7d5-ed2e-50b6-ab79-ba4140420682', 'dc7e928c-265d-56bb-ab34-14b8a1313bfd', 4, 30, 'ከአባቶችም ጋር በአንቀላፋሁ ጊዜ ከግብፅ ምድር አውጥተህ ትወስደኛለህ፤ በአባቶችም መቃብር ትቀብረኛለህ።” እርሱም፥ “እንደ ቃልህ አደርጋለሁ” አለ። እርሱም፥ “ማልልኝ” አለው።'),
  ('efc20deb-01f1-5ac8-a809-fe282c3f9f41', 'aea1c7d5-ed2e-50b6-ab79-ba4140420682', 'dc7e928c-265d-56bb-ab34-14b8a1313bfd', 5, 31, 'ዮሴፍም ማለለት፤ እስራኤልም በአልጋው ራስ ላይ ሰገደ።'),
  ('ac0f6fc2-2a33-54e5-a871-18024cc5e73d', '4fe5a6c7-b59d-5245-ad06-3de656c1c4c7', '796d1714-9834-5bcb-afeb-edf504f9c8c2', 1, 1, 'ከዚህም ነገር በኋላ እንዲህ ሆነ፤ “እነሆ፥ አባታችን ደከመ” ብለው ለዮሴፍ ነገሩት፤ እርሱም ሁለቱን ልጆቹን ምናሴንና ኤፍሬምን ይዞ ሄደ።'),
  ('0614ff4f-b325-5d3a-a8cf-82ab8ee3c214', '4fe5a6c7-b59d-5245-ad06-3de656c1c4c7', '796d1714-9834-5bcb-afeb-edf504f9c8c2', 2, 2, 'ለያዕቆብም፥ “እነሆ፥ ልጅህ ዮሴፍ መጥቶልሃል” ብለው ነገሩት፤ እስራኤልም ተጠነካከረ፤ በአልጋውም ላይ ተቀመጠ።'),
  ('39c444c6-ee2a-5423-a7c6-0c92098d0884', '4fe5a6c7-b59d-5245-ad06-3de656c1c4c7', '796d1714-9834-5bcb-afeb-edf504f9c8c2', 3, 3, 'ያዕቆብ ዮሴፍን አለው፥ “አምላኬ በከነዓን ምድር በሎዛ ተገለጠልኝ፤ ባረከኝም።'),
  ('bc380a53-da81-580d-a81c-88755f6d8986', '4fe5a6c7-b59d-5245-ad06-3de656c1c4c7', '796d1714-9834-5bcb-afeb-edf504f9c8c2', 4, 4, 'እንዲህም አለኝ፦ እነሆ፥ አበዛሃለሁ፤ አባዛሃለሁም፤ ለብዙም ሕዝብ ጉባኤ አደርግሃለሁ፤ ይህችንም ምድር ለአንተ፥ ከአንተም በኋላ ለዘለዓለም ርስት ለዘርህ እሰጣታለሁ።'),
  ('ca66790a-fa8c-5796-a7ae-8425a8942e28', '4fe5a6c7-b59d-5245-ad06-3de656c1c4c7', '796d1714-9834-5bcb-afeb-edf504f9c8c2', 5, 5, 'አሁንም እኔ ወደ አንተ ከመምጣቴ በፊት በግብፅ ምድር የተወለዱልህ ሁለቱ ልጆችህ ለእኔ ይሁኑ፤ ኤፍሬምና ምናሴ ለእኔ እንደ ሮቤልና እንደ ስምዖን ናቸው።'),
  ('02465d7f-f78d-5ed1-acba-0351bbb321ff', '4fe5a6c7-b59d-5245-ad06-3de656c1c4c7', '796d1714-9834-5bcb-afeb-edf504f9c8c2', 6, 6, 'ከእነርሱም በኋላ የምትወልዳቸው ልጆች ለአንተ ይሁኑ፤ በርስታቸው በወንድሞቻቸው ስም ይጠሩ።'),
  ('ec94dac0-b254-5188-aaea-af51955f77af', '4fe5a6c7-b59d-5245-ad06-3de656c1c4c7', '796d1714-9834-5bcb-afeb-edf504f9c8c2', 7, 7, 'እኔም ከሶርያ መስጴጦምያ በመጣሁ ጊዜ፥ ወደ ኤፍራታ ለመግባት ጥቂት ቀርቶኝ በፈረስ መጋለቢያው መንገድ ሳለሁ፥ ራሔል በከነዓን ምድር ሞተችብኝ፤ በዚያም በኤፍራታ ወደ ፈረስ መጋለቢያ በሚወስደው መንገድ ላይ ቀበርኋት፤ እርስዋም ቤተ ልሔም ናት።”'),
  ('33d3856b-a266-5d7d-ae6b-5551081a1b17', '4fe5a6c7-b59d-5245-ad06-3de656c1c4c7', '796d1714-9834-5bcb-afeb-edf504f9c8c2', 8, 8, 'እስራኤልም የዮሴፍን ልጆች ለይቶ፥ “እነዚህ ምኖችህ ናቸው?” አለው።'),
  ('e4a40a17-ce2b-5806-a29f-76659d443525', '4fe5a6c7-b59d-5245-ad06-3de656c1c4c7', '796d1714-9834-5bcb-afeb-edf504f9c8c2', 9, 9, 'ዮሴፍም ለአባቱ ፥ “እግዚአብሔር በዚህ የሰጠኝ ልጆች ናቸው” አለው። ያዕቆብም፥ “እባርካቸው ዘንድ ወደ እኔ አቅርብልኝ” አለው።'),
  ('544f112f-0d19-54b9-adf7-2917ff18de41', '4fe5a6c7-b59d-5245-ad06-3de656c1c4c7', '796d1714-9834-5bcb-afeb-edf504f9c8c2', 10, 10, 'የእስራኤልም ዐይኖች ከሽምግልና የተነሣ ከብደው ነበር፤ ማየትም አይችልም ነበር፤ ወደ እርሱም አቀረባቸው፤ ሳማቸውም፤ አቀፋቸውም።'),
  ('41a8e889-ff30-5f5e-ac46-fc387ae7b20b', '4fe5a6c7-b59d-5245-ad06-3de656c1c4c7', '796d1714-9834-5bcb-afeb-edf504f9c8c2', 11, 11, 'እስራኤልም ዮሴፍን፥ “ከፊትህ አልተለየሁም፤ እነሆም፥ እግዚአብሔር ዘርህን ደግሞ አሳየኝ” አለው።'),
  ('61a16f72-fdee-5416-a942-0e037d097e35', '4fe5a6c7-b59d-5245-ad06-3de656c1c4c7', '796d1714-9834-5bcb-afeb-edf504f9c8c2', 12, 12, 'ዮሴፍም ከጕልበቱ ፈቀቅ አደረጋቸው፤ ወደ ምድርም በግንባሩ ሰገደ።'),
  ('f2abac31-dcbb-5fdb-aba1-ddbd73421e54', '4fe5a6c7-b59d-5245-ad06-3de656c1c4c7', '796d1714-9834-5bcb-afeb-edf504f9c8c2', 13, 13, 'ዮሴፍም ሁለቱን ልጆቹን ወሰደ፤ ኤፍሬምንም በቀኙ በእስራኤል ግራ፥ ምናሴንም በግራው በእስራኤል ቀኝ አቆማቸው፤ ወደ አባቱም አቀረባቸው።'),
  ('3174357b-aebc-5029-a134-aae3f3e332ef', '4fe5a6c7-b59d-5245-ad06-3de656c1c4c7', '796d1714-9834-5bcb-afeb-edf504f9c8c2', 14, 14, 'እስራኤልም ቀኝ እጁን ዘርግቶ በኤፍሬም ራስ ላይ አኖረው፤ እርሱም ታናሽ ነበረ፤ ግራውንም በምናሴ ራስ ላይ አኖረ፤ እጆቹንም አስተላለፈ።'),
  ('879eee33-ca7a-5dfd-a2cd-f04a8cf7f863', '4fe5a6c7-b59d-5245-ad06-3de656c1c4c7', '796d1714-9834-5bcb-afeb-edf504f9c8c2', 15, 15, 'ያዕቆብም ባረካቸው፤ እንዲህም አለ፥ “አባቶች አብርሃምና ይስሐቅ በፊቱ ደስ ያሰኙት እርሱ እግዚአብሔር፥ ከታናሽነቴ ጀምሮ እስከ ዛሬ ድረስ እኔን የመገበኝ እግዚአብሔር፥'),
  ('243b97a4-d383-52cc-a8e6-22ca811c3c57', '4fe5a6c7-b59d-5245-ad06-3de656c1c4c7', '796d1714-9834-5bcb-afeb-edf504f9c8c2', 16, 16, 'ከከፉ ነገር ሁሉ የአዳነኝ መልአክ እርሱ እነዚህን ብላቴኖች ይባርክ፤ ስሜም፥ የአባቶች የአብርሃምና የይስሐቅም ስም በእነርሱ ይጠራ፤ በምድር ላይ ይብዙ፤ የብዙ ብዙም ይሁኑ፤”'),
  ('39e78d1a-0f56-5a00-a802-3d87c809582d', '4fe5a6c7-b59d-5245-ad06-3de656c1c4c7', '796d1714-9834-5bcb-afeb-edf504f9c8c2', 17, 17, 'ዮሴፍም አባቱ ቀኝ እጁን በኤፍሬም ራስ ላይ ጭኖ በአየ ጊዜ ከባድ ነገር ሆነበት፤ ዮሴፍም የአባቱን እጅ በምናሴ ራስ ላይ ይጭነው ዘንድ ከኤፍሬም ራስ ላይ አነሣው።'),
  ('3f95ab0e-ffd5-575c-acee-d91bbfa0911b', '4fe5a6c7-b59d-5245-ad06-3de656c1c4c7', '796d1714-9834-5bcb-afeb-edf504f9c8c2', 18, 18, 'ዮሴፍም አባቱን፥ “አባቴ ሆይ፥ እንዲህ አይደለም፤ በኵሩ ይህ ነውና ቀኝህን በራሱ ላይ አድርግ” አለው።'),
  ('be771a07-02e5-5cd6-a242-71146b3c0658', '4fe5a6c7-b59d-5245-ad06-3de656c1c4c7', '796d1714-9834-5bcb-afeb-edf504f9c8c2', 19, 19, 'አባቱም እንቢ አለ፤ እንዲህ ሲል፥ “አውቃለሁ ልጄ ሆይ፥ አውቃለሁ፤ ይህም ደግሞ ሕዝብ ይሆናል፤ ታላቅም ይሆናል፤ ነገር ግን ታናሽ ወንድሙ ከእርሱ ይበልጣል፤ ዘሩም ብዙ ሕዝብ ይሆናል።”'),
  ('22c0a11a-0789-504d-ab9a-f3961d05d7ce', '4fe5a6c7-b59d-5245-ad06-3de656c1c4c7', '796d1714-9834-5bcb-afeb-edf504f9c8c2', 20, 20, 'በዚያም ቀን እንዲህ ብሎ ባረካቸው፥ “በእናንተ እስራኤል እንዲህ ተብሎ ይባረካል፦ እግዚአብሔር እንደ ኤፍሬምና እንደ ምናሴ ይባርክህ።” ኤፍሬምንም ከምናሴ ፊት አደረገው።'),
  ('7f6272e2-3cf6-5e8c-ab9a-bc0132fab869', '4fe5a6c7-b59d-5245-ad06-3de656c1c4c7', '796d1714-9834-5bcb-afeb-edf504f9c8c2', 21, 21, 'እስራኤልም ዮሴፍን፥ “እነሆ፥ እኔ እሞታለሁ፤ እግዚአብሔርም ከእናንተ ጋር ይሆናል፤ ወደ አባቶቻችሁም ምድር ይመልሳችኋል፤'),
  ('f89ee0d1-a15e-5b3f-ae6b-74fd51f78d8a', '4fe5a6c7-b59d-5245-ad06-3de656c1c4c7', '796d1714-9834-5bcb-afeb-edf504f9c8c2', 22, 22, 'እኔም ከአሞራውያን እጅ በሰይፌና በቀስቴ የወሰድሁትን ምርኮ ለአንተ ከወንድሞችህ የተሻለውን እሰጥሃለሁ” አለው።'),
  ('ed4239ec-9cc5-5dc1-a1ad-1c60e59f683b', '211aae01-c0e6-5a1e-a745-f08fbc68d92d', '82ee8394-4e3a-5afd-aa59-7daed9e63f51', 1, 1, 'ያዕቆብም ልጆቹን ጠርቶ እንዲህ አላቸው፥ “በኋለኛው ዘመን የሚያገኛችሁን እንድነግራችሁ ተሰብሰቡ።'),
  ('b2828d32-d327-56e0-a309-585acdef80e6', '211aae01-c0e6-5a1e-a745-f08fbc68d92d', '82ee8394-4e3a-5afd-aa59-7daed9e63f51', 2, 2, 'እናንት የያዕቆብ ልጆች ኑ፥ ተሰብሰቡ፤ ስሙም፤ አባታችሁ እስራኤልንም አድምጡ።'),
  ('9ad63db4-000a-5248-a387-19e5d221d2db', '211aae01-c0e6-5a1e-a745-f08fbc68d92d', '82ee8394-4e3a-5afd-aa59-7daed9e63f51', 3, 3, '“ሮቤል እርሱ የበኵር ልጄና ኀይሌ፥ የልጆችም መጀመሪያ ነው፤ ክፉ ሆነ፤ አንገቱንም አደነደነ። ጭንቅ ነገርንም አደረገ።'),
  ('2356d0c0-1b74-505c-a372-57345122f7c2', '211aae01-c0e6-5a1e-a745-f08fbc68d92d', '82ee8394-4e3a-5afd-aa59-7daed9e63f51', 4, 4, 'እንደ ውኃ የሚዋልል ነው፤ ኀይል የለውም፤ ወደ አባቱ መኝታ ወጥቶአልና፤ ያን ጊዜ የወጣበትን አልጋ አርክሶአልና።'),
  ('7e466eb2-b6ee-5e40-a6ee-420503365d98', '211aae01-c0e6-5a1e-a745-f08fbc68d92d', '82ee8394-4e3a-5afd-aa59-7daed9e63f51', 5, 5, '“ስምዖንና ሌዊ ወንድማማቾች ናቸው፤ በጭቅጭቃቸውና በጦራቸው ዐመፅን ፈጸሙአት።'),
  ('f636382b-3fd9-5330-ae97-a442aa017e1e', '211aae01-c0e6-5a1e-a745-f08fbc68d92d', '82ee8394-4e3a-5afd-aa59-7daed9e63f51', 6, 6, 'በምክራቸው ሰውነቴ አትገናኛቸው፤ ዐሳቤም በአመፃቸው አትተባበርም፤ በቍጣቸው ሰውን ገድለዋልና፤ በገዛ ፈቃዳቸውም የሀገርን ሥር ቈርጠዋልና።'),
  ('5a737e05-2ee1-5ba9-acbf-48e634678901', '211aae01-c0e6-5a1e-a745-f08fbc68d92d', '82ee8394-4e3a-5afd-aa59-7daed9e63f51', 7, 7, 'ቍጣቸው ርጉም ይሁን፤ ጽኑ ነበርና፤ ኵርፍታቸውም ብርቱ ነበርና፤ በያዕቆብ እከፋፍላቸዋለሁ፤ በእስራኤልም እበታትናቸዋለሁ።'),
  ('888652df-64b0-556f-aeca-b19454a64b86', '211aae01-c0e6-5a1e-a745-f08fbc68d92d', '82ee8394-4e3a-5afd-aa59-7daed9e63f51', 8, 8, '“ይሁዳ፥ ወንድሞችህ አንተን ያመሰግኑሃል፤ እጅህ በጠላቶችህ ደንደስ ላይ ነው፤ የአባትህ ልጆች በፊትህ ይሰግዳሉ።'),
  ('33008ca9-2ec5-5561-a593-4a5ea394bba4', '211aae01-c0e6-5a1e-a745-f08fbc68d92d', '82ee8394-4e3a-5afd-aa59-7daed9e63f51', 9, 9, 'ይሁዳ የአንበሳ ደቦል ነው፤ ልጄ ሆይ፥ ከመሰማሪያህ ወጣህ፤ እንደ አንበሳ ተኛህ፤ አንቀላፋህም፤ እንደ አንበሳም ደቦል የሚቀሰቅስህ የለም።'),
  ('62b253a4-5e8f-5592-a52b-bc0813eb9734', '211aae01-c0e6-5a1e-a745-f08fbc68d92d', '82ee8394-4e3a-5afd-aa59-7daed9e63f51', 10, 10, 'መንግሥት ከይሁዳ አይጠፋም፤ ምስፍናም ከአብራኩ፥ ለእርሱ የሚጠብቀውን እስኪያገኝ ድረስ፤ የአሕዛብ ተስፋቸው እርሱ ነውና፤'),
  ('55c13bad-28c2-5508-a6b2-4e55ca6bab5b', '211aae01-c0e6-5a1e-a745-f08fbc68d92d', '82ee8394-4e3a-5afd-aa59-7daed9e63f51', 11, 11, 'አህያይቱን በወይን ግንድ ያስራል፤ የአህያይቱንም ግልገል በወይን ሐረግ፤ ልብሱን በወይን ያጥባል፤ መጐናጸፊያውንም በዘለላው ደም።'),
  ('d0b71983-60ec-5af2-ad93-5b077f4e8015', '211aae01-c0e6-5a1e-a745-f08fbc68d92d', '82ee8394-4e3a-5afd-aa59-7daed9e63f51', 12, 12, 'ዐይኖቹ ከወይን ይልቅ ደስ ያሰኛሉ፤ ጥርሱም ከወተት ይልቅ ነጭ ነው።'),
  ('f4f5417b-77d1-5697-a90b-d5a592c9b821', '211aae01-c0e6-5a1e-a745-f08fbc68d92d', '82ee8394-4e3a-5afd-aa59-7daed9e63f51', 13, 13, '“ዛብሎን ጫማውን አዝቦ ይኖራል፤ እርሱም እንደ መርከቦች ወደብ ይሆናል፤ ዳርቻውም እስከ ሲዶና ይሰፋል።'),
  ('12ebc42d-f080-5ee3-ae46-65d37b6b2dff', '211aae01-c0e6-5a1e-a745-f08fbc68d92d', '82ee8394-4e3a-5afd-aa59-7daed9e63f51', 14, 14, '“ይሳኮር መልካም ነገርን ወደደ፤ በተወራራሾቹም መካከል ያርፋል።'),
  ('f83396a1-061c-5599-a7ad-e5aa95f95c35', '211aae01-c0e6-5a1e-a745-f08fbc68d92d', '82ee8394-4e3a-5afd-aa59-7daed9e63f51', 15, 15, 'ዕረፍትም መልካም መሆንዋን፥ ምድሪቱም የለማች መሆንዋን በአየ ጊዜ ምድርን ያርሳት ዘንድ ትከሻውን ዝቅ አደረገ፤ በሥራም ገበሬ ሆነ።'),
  ('49036d08-e8d6-52a7-a0e4-fa3f1a79b0c7', '211aae01-c0e6-5a1e-a745-f08fbc68d92d', '82ee8394-4e3a-5afd-aa59-7daed9e63f51', 16, 16, '“ዳን ከእስራኤል ነገድ እንደ አንዱ በወገኑ ይፈርዳል፤'),
  ('7740d3ff-aeaf-57d7-a628-d109c0028114', '211aae01-c0e6-5a1e-a745-f08fbc68d92d', '82ee8394-4e3a-5afd-aa59-7daed9e63f51', 17, 17, 'ዳን በጎዳና ላይ እንደሚያደባ እባብ ይሆናል፤ በመንገዱም የፈረሱን ሰኰና እንደሚናደፍ እንደ ቀንዳም እባብ ነው፤ ፈረሰኛውም ወደኋላው ይወድቃል።'),
  ('2ea28ff7-7730-57ae-af1d-64942fe97911', '211aae01-c0e6-5a1e-a745-f08fbc68d92d', '82ee8394-4e3a-5afd-aa59-7daed9e63f51', 18, 18, 'እግዚአብሔርም ያድነው ዘንድ ይጠብቃል።'),
  ('b8148a42-807a-5bb2-acef-d08072e53eac', '211aae01-c0e6-5a1e-a745-f08fbc68d92d', '82ee8394-4e3a-5afd-aa59-7daed9e63f51', 19, 19, '“ጋድን ሽፍቶች ቀሙት፤ እርሱም ፍለጋቸውን ተከታትሎ ቀማቸው።'),
  ('d5e17925-8222-55ea-a895-141c1e4d2f29', '211aae01-c0e6-5a1e-a745-f08fbc68d92d', '82ee8394-4e3a-5afd-aa59-7daed9e63f51', 20, 20, '“የአሴር እንጀራ ወፍራም ነው፤ እርሱም ለአለቆች ደስ የሚያሰኝ መብልን ይሰጣል።'),
  ('bfc51abc-c42f-5ebf-a345-85c7a59a465b', '211aae01-c0e6-5a1e-a745-f08fbc68d92d', '82ee8394-4e3a-5afd-aa59-7daed9e63f51', 21, 21, '“ንፍታሌም በፍሬው ላይ ውበትን የሚሰጥ ሰፊ ዘንባባ ነው።'),
  ('5e37fade-6598-56fa-a5d9-ab19ec17d918', '211aae01-c0e6-5a1e-a745-f08fbc68d92d', '82ee8394-4e3a-5afd-aa59-7daed9e63f51', 22, 22, '“ዮሴፍ የሚያድግ ልጅ ነው፤ ለእኔ በጣም የተወደደ የሚቀናልኝና የሚያድግልኝ ልጅ ነው፤ ወደ እኔ የሚመለስም ጐልማሳ ነው።'),
  ('dc456647-b19c-5eae-ae5e-263a4c98a97c', '211aae01-c0e6-5a1e-a745-f08fbc68d92d', '82ee8394-4e3a-5afd-aa59-7daed9e63f51', 23, 23, 'በምክራቸው የሰደቡት ጌቶች ሆኑበት፤ ቀስተኞችም ወጉት፤'),
  ('177a86dc-aab9-52ed-af45-557a47bdfaa9', '211aae01-c0e6-5a1e-a745-f08fbc68d92d', '82ee8394-4e3a-5afd-aa59-7daed9e63f51', 24, 24, 'ነገር ግን ቀስቶቻቸው በኀይል ተቀጠቀጡ፤ የእጆቻቸው ክንድ ሥርም በያዕቆብ ኀያል እጅ ዛለ፤ በዚያም በአባትህ አምላክ ዘንድ እስራኤልን አጸናው።'),
  ('dfa817cb-bbc9-5761-a4ec-cf80eb129292', '211aae01-c0e6-5a1e-a745-f08fbc68d92d', '82ee8394-4e3a-5afd-aa59-7daed9e63f51', 25, 25, '“የእኔ አምላክ ረዳህ፤ ከላይ በሰማይ በረከት፥ ሁሉ በሚገኝባት፥ በምድር በረከት፥ በጡትና በማኅፀን በረከት ባረከህ፤'),
  ('7c7a2dfc-670a-5499-a527-219e196e46ea', '211aae01-c0e6-5a1e-a745-f08fbc68d92d', '82ee8394-4e3a-5afd-aa59-7daed9e63f51', 26, 26, 'የአባትህና የእናትህ በረከቶች ጽኑዓን ከሆኑ ከተራሮች በረከቶች ይልቅ ይበልጣሉ፤ ዘለዓለማውያን ከሆኑ ከኮረብቶችም በረከቶች ይልቅ ኀያላን ናቸው፤ እነርሱም በዮሴፍ ራስ ላይ ይሆናሉ፤ በወንድሞቹ መካከል አለቃ በሆነውም ራስ አናት ላይ ይሆናሉ።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('1f983e9e-1893-5594-ae22-d204ed932fba', '211aae01-c0e6-5a1e-a745-f08fbc68d92d', '82ee8394-4e3a-5afd-aa59-7daed9e63f51', 27, 27, '“ብንያም ነጣቂ ተኵላ ነው፤ በጥዋት ይበላል፤ የማረከውንም ምግቡን በማታ ለሕዝብ ይሰጣል።”'),
  ('2edb0425-0dd0-5fb1-a0d1-820d238553a4', '211aae01-c0e6-5a1e-a745-f08fbc68d92d', '82ee8394-4e3a-5afd-aa59-7daed9e63f51', 28, 28, 'እነዚህም ሁሉ ዐሥራ ሁለቱ የያዕቆብ ልጆች ናቸው፤ አባታቸውም ይህን ነገር ነገራቸው፤ ባረካቸውም፤ እያንዳንዳቸውንም እንደ በረከታቸው ባረካቸው።'),
  ('2b519926-4b3c-52f9-ab27-154bf48b57ac', '211aae01-c0e6-5a1e-a745-f08fbc68d92d', 'cb670792-3c3d-546e-a579-d7c0edc055ff', 1, 29, 'እንዲህም ብሎ አዘዛቸው፥ “እኔ ወደ ወገኖች እሰበሰባለሁ፤ በኬጢያዊው በኤፍሮን እርሻ ላይ ባለችው ዋሻ ከአባቶች ጋር ቅበሩኝ፤ እርስዋም በከነዓን ምድር በመምሬ ፊት ያለች፥'),
  ('b106d625-e5d1-5414-a2de-50906e549d7b', '211aae01-c0e6-5a1e-a745-f08fbc68d92d', 'cb670792-3c3d-546e-a579-d7c0edc055ff', 2, 30, 'አብርሃም ለመቃብር ርስት ከኬጢያዊው ከኤፍሮን ከእርሻው ጋር የገዛት፥ ባለ ድርብ ክፍል ዋሻ ናት።'),
  ('b402f0a6-1c83-530c-a4fd-fc6f03ff61b9', '211aae01-c0e6-5a1e-a745-f08fbc68d92d', 'cb670792-3c3d-546e-a579-d7c0edc055ff', 3, 31, 'አብርሃምንና ሚስቱ ሣራንም በዚያ ቀበሩአቸው፤ ይስሐቅንና ሚስቱ ርብቃንም በዚያ ቀበሩአቸው፤ ከዚያም እኔ ልያን ቀበርኋት'),
  ('7aae0ac2-3197-5c36-a856-aa86912da01b', '211aae01-c0e6-5a1e-a745-f08fbc68d92d', 'cb670792-3c3d-546e-a579-d7c0edc055ff', 4, 32, 'እርሻውና በእርስዋ ላይ ያለችው ዋሻ ከኬጢ ልጆች የተገዙ ናቸው።”'),
  ('f4538d3c-05e7-5346-ad65-1f3db8d12b04', '211aae01-c0e6-5a1e-a745-f08fbc68d92d', 'cb670792-3c3d-546e-a579-d7c0edc055ff', 5, 33, 'ያዕቆብም ትእዛዙን ለልጆቹ ተናግሮ በፈጸመ ጊዜ እግሮቹን በአልጋው ላይ ዘርግቶ ሞተ፤ ወደ ወገኖቹም ተጨመረ።'),
  ('bf2d04cc-5346-508d-a9be-07df0e0cf671', '6a562f42-f422-53d1-a99a-b31b8abc2a3a', '85e793a9-bd6b-5cc8-ad15-969f12b470f1', 1, 1, 'ዮሴፍም በአባቱ ፊት ወደቀ፤ በእርሱም ላይ አለቀሰ፤ ሳመውም።'),
  ('d3259adf-a051-5e9b-a9d3-8ec924e0832d', '6a562f42-f422-53d1-a99a-b31b8abc2a3a', '85e793a9-bd6b-5cc8-ad15-969f12b470f1', 2, 2, 'ዮሴፍም ባለ መድኀኒቶች አገልጋዮቹ አባቱን በሽቱ ያሹት ዘንድ አዘዘ፤ ባለ መድኀኒቶችም እስራኤልን በሽቱ አሹት።'),
  ('b10e727c-59d0-56ff-a4e1-1d01c443836b', '6a562f42-f422-53d1-a99a-b31b8abc2a3a', '85e793a9-bd6b-5cc8-ad15-969f12b470f1', 3, 3, 'አርባ ቀንም ፈጸሙለት፤ ሽቱ የሚቀቡበትን ቀን እንዲሁ ይቈጥራሉና፤ የግብፅም ሰዎች ሰባ ቀን አለቀሱለት።'),
  ('878e04f4-4caa-5cbb-a29f-5eaf22417e3b', '6a562f42-f422-53d1-a99a-b31b8abc2a3a', '85e793a9-bd6b-5cc8-ad15-969f12b470f1', 4, 4, 'የልቅሶውም ወራት ከተፈጸመ በኋላ ዮሴፍ ለፈርዖን መኳንንት እንዲህ ብሎ ተናገረ፥ “እኔ በፊታችሁ ሞገስን አግኝቼ እንደ ሆንሁ ለፈርዖን እንዲህ ብላችሁ ስለ እኔ ንገሩት፦'),
  ('482b772b-7bdf-5614-ab52-a8cecb30ba52', '6a562f42-f422-53d1-a99a-b31b8abc2a3a', '85e793a9-bd6b-5cc8-ad15-969f12b470f1', 5, 5, 'አባቴ ሳይሞት አምሎኛል፤ እንዲህ ሲል፦ ‘እነሆ እኔ እሞታለሁ፤ በቈፈርሁት መቃብር በከነዓን ምድር በዚያ ቅበረኝ።’ አሁንም ወጥቼ አባቴን ልቅበርና ልመለስ።”'),
  ('188f1ccf-3983-55ee-ad78-7ba05329eca9', '6a562f42-f422-53d1-a99a-b31b8abc2a3a', '85e793a9-bd6b-5cc8-ad15-969f12b470f1', 6, 6, 'ፈርዖንም ዮሴፍን አለው፥ “ውጣ፤ አባትህንም እንዳማለህ ቅበረው።”'),
  ('0e7841c9-ed2b-5489-a4a5-98f15a936eb2', '6a562f42-f422-53d1-a99a-b31b8abc2a3a', '85e793a9-bd6b-5cc8-ad15-969f12b470f1', 7, 7, 'ዮሴፍም አባቱን ሊቀብር ወጣ፤ የፈርዖን ሎሌዎችም ሁሉ፥ የቤቱ ሽማግሌዎችም ሁሉ፥ የግብፅ ምድር ሽማግሌዎችም ሁሉ ከእርሱ ጋር ወጡ፤'),
  ('d0dfdfb1-c730-5f94-af76-3e796ab2aae2', '6a562f42-f422-53d1-a99a-b31b8abc2a3a', '85e793a9-bd6b-5cc8-ad15-969f12b470f1', 8, 8, 'የዮሴፍም ቤተ ሰቦች ሁሉ፥ ወንድሞቹም፥ የአባቱም ቤተ ሰቦች ወጡ፤ ልጆቻቸውንና በጎቻቸውን፥ ከብቶቻቸውንም ብቻ በጌሤም ተዉ።'),
  ('2df892cd-b06f-510c-a9d2-204c6bd8f81f', '6a562f42-f422-53d1-a99a-b31b8abc2a3a', '85e793a9-bd6b-5cc8-ad15-969f12b470f1', 9, 9, 'ሰረገሎችም፥ ፈረሰኞችም ከእርሱ ጋር ወጡ፤ ሠራዊቱም ብዙ ነበር።'),
  ('d5867680-1f48-5eef-a9cd-243f46c9e7b2', '6a562f42-f422-53d1-a99a-b31b8abc2a3a', '85e793a9-bd6b-5cc8-ad15-969f12b470f1', 10, 10, 'በዮርዳኖስ ማዶ ወዳለችው ወደ አጣድ አውድማ ደረሱ፤ እጅግ ታላቅ በሆነ በጽኑ ልቅሶም አለቀሱለት፤ ለአባቱም ሰባት ቀን ልቅሶ አደረገለት።'),
  ('6f6173f0-31f0-5977-adfa-db633ebbf49c', '6a562f42-f422-53d1-a99a-b31b8abc2a3a', '85e793a9-bd6b-5cc8-ad15-969f12b470f1', 11, 11, 'በዚያች ምድር የሚኖሩ የከነዓን ሰዎችም በአጣድ አውድማ የሆነውን ልቅሶ በአዩ ጊዜ፥ “የግብፅ ልቅሶ እንዲህ ታላቅ ነውን?” አሉ፤ ስለዚህም የዚያን ቦታ ስም “ላሐ ግብፅ” ብለው ጠሩት፤ እርሱም በዮርዳኖስ ማዶ ነው።'),
  ('4395eb38-5107-5193-a7a9-5b0940381609', '6a562f42-f422-53d1-a99a-b31b8abc2a3a', '85e793a9-bd6b-5cc8-ad15-969f12b470f1', 12, 12, 'ልጆቹም እንዳዘዛቸው እንደዚያው አደረጉለት፤'),
  ('01949e9a-01c6-5beb-ad0e-d1370d9202ac', '6a562f42-f422-53d1-a99a-b31b8abc2a3a', '85e793a9-bd6b-5cc8-ad15-969f12b470f1', 13, 13, 'ልጆቹም ወደ ከነዓን ምድር መለሱት፤ ባለ ሁለት ክፍል በሆነች ዋሻም ቀበሩት፤ እርስዋም በመምሬ ፊት ያለች፥ አብርሃም ለመቃብር ርስት ከኬጢያዊው ከኤፍሮን ከእርሻው ጋር የገዛት ዋሻ ናት።'),
  ('ca740ba3-168a-5970-af2d-99fe79228114', '6a562f42-f422-53d1-a99a-b31b8abc2a3a', '85e793a9-bd6b-5cc8-ad15-969f12b470f1', 14, 14, 'ዮሴፍና ወንድሞቹ፥ አባቱንም ሊቀብሩ ከእርሱ ጋር የወጡት ሰዎች ሁሉ አባቱን ከቀበረ በኋላ ወደ ግብፅ ተመለሱ።'),
  ('c82c9445-bea8-5461-a65d-aeb192000ad5', '6a562f42-f422-53d1-a99a-b31b8abc2a3a', 'f7a8170b-b39d-517a-a5b2-08c375853dd1', 1, 15, 'የዮሴፍም ወንድሞች አባታቸው እንደ ሞተ በአዩ ጊዜ እንዲህ አሉ፥ “ምናልባት ዮሴፍ ያደረግንበትን ክፋት ያስብብን ይሆናል፤ ባደረግንበትም ክፋት ሁሉ ብድራት ይመልስብን ይሆናል።”'),
  ('ba04c692-4753-515a-aaf8-11cea3b97ece', '6a562f42-f422-53d1-a99a-b31b8abc2a3a', 'f7a8170b-b39d-517a-a5b2-08c375853dd1', 2, 16, 'ወደ ዮሴፍም መጡ፤ እንዲህም አሉት፥ “አባትህ ገና ሳይሞት እንዲህ ብሎ አዝዟል፦'),
  ('3d6ea0e0-f70a-5187-a39a-0deb66f61b2f', '6a562f42-f422-53d1-a99a-b31b8abc2a3a', 'f7a8170b-b39d-517a-a5b2-08c375853dd1', 3, 17, '‘ዮሴፍን እንዲህ በሉት፦ እባክህ የወንድሞችህን በደል ኀጢአታቸውንም ይቅር በል፤ እነርሱ በአንተ ክፉ አድርገውብሃልና፤’ አሁንም እባክህ የአባትህ አምላክ ባሪያዎች የበደሉህን ይቅር በል።”'),
  ('f82d1833-cc89-5853-ac48-7d10a7629700', '6a562f42-f422-53d1-a99a-b31b8abc2a3a', 'f7a8170b-b39d-517a-a5b2-08c375853dd1', 4, 18, 'ዮሴፍም ይህን ሲሉት አለቀሰ። ወንድሞቹ ደግሞ መጡ፤ “እነሆ፥ እኛ ለአንተ አገልጋዮችህ ነን” አሉት።'),
  ('c92bab17-6d85-5446-abe6-0049bc2c709d', '6a562f42-f422-53d1-a99a-b31b8abc2a3a', 'f7a8170b-b39d-517a-a5b2-08c375853dd1', 5, 19, 'ዮሴፍም አላቸው፥ “አትፍሩ፤ ይህ ከእግዚአብሔር ዘንድ ሆኖአልና።'),
  ('7237af0e-9117-5f85-a63d-713d6d83ef17', '6a562f42-f422-53d1-a99a-b31b8abc2a3a', 'f7a8170b-b39d-517a-a5b2-08c375853dd1', 6, 20, 'እናንተ በእኔ ላይ ክፉ መከራችሁ፤ እግዚአብሔር ግን ዛሬ እንደ ሆነው ብዙ ሕዝብ እንዲመገብ ለማድረግ ለእኔ መልካም መከረ።'),
  ('8ec6d2fe-8433-526a-af52-f4215b2b46d6', '6a562f42-f422-53d1-a99a-b31b8abc2a3a', 'f7a8170b-b39d-517a-a5b2-08c375853dd1', 7, 21, 'አሁንም አትፍሩ፤ እኔ እናንተንና ቤተ ሰቦቻችሁን እመግባችኋለሁ።” አጽናናቸውም፤ በልባቸው የሚገባ ነገርም ነገራቸው።'),
  ('13495164-d5ff-50a0-a5dd-68d2cf08311a', '6a562f42-f422-53d1-a99a-b31b8abc2a3a', 'e3f520a0-5cf6-581c-a1c3-b6cdfe913385', 1, 22, 'ዮሴፍም በግብፅ ሀገር ተቀመጠ፤ እርሱና ወንድሞቹ የአባቱም ቤተ ሰብ፤ ዮሴፍም መቶ ዐሥር ዓመት ኖረ።'),
  ('11d7b2f2-171b-5cdf-a2cc-f3f85491fa42', '6a562f42-f422-53d1-a99a-b31b8abc2a3a', 'e3f520a0-5cf6-581c-a1c3-b6cdfe913385', 2, 23, 'ዮሴፍም የኤፍሬምን ልጆች እስከ ሦስት ትውልድ አየ። የምናሴ ልጅ የማኪር ልጆችም በዮሴፍ ጭን ላይ ተወለዱ።'),
  ('4f785c1e-73f3-5f5f-a9ed-213216df7139', '6a562f42-f422-53d1-a99a-b31b8abc2a3a', 'e3f520a0-5cf6-581c-a1c3-b6cdfe913385', 3, 24, 'ዮሴፍም ወንድሞቹን አላቸው፥ “እኔ እሞታለሁ፤ እግዚአብሔርም መጐብኘትን ይጐበኛችኋል፤ ከዚህችም ምድር ያወጣችኋል። ለአባቶቻችን ለአብርሃምና ለይስሐቅ ለያዕቆብም ወደ ማለላቸው ምድር ያገባችኋል።”'),
  ('df8cd1c8-ab06-5f74-a89e-f2be82b729b9', '6a562f42-f422-53d1-a99a-b31b8abc2a3a', 'e3f520a0-5cf6-581c-a1c3-b6cdfe913385', 4, 25, 'ዮሴፍም የእስራኤልን ልጆች፥ “እግዚአብሔር በጐበኛችሁ ጊዜ አጥንቴን ከዚህ አንሥታችሁ ከእናንተ ጋር አውጡ” ብሎ አማላቸው።'),
  ('31b97056-4439-536a-a92e-36581c359215', '6a562f42-f422-53d1-a99a-b31b8abc2a3a', 'e3f520a0-5cf6-581c-a1c3-b6cdfe913385', 5, 26, 'ዮሴፍም በመቶ ዐሥር ዓመት ዕድሜው ሞተ፤ በሽቱም አሹት፤ በግብፅ ምድርም በሣጥን ውስጥ አኖሩት።'),
  ('9e8e16c6-4dae-5024-ad50-8dcca0ca2a7c', '2e4dda2c-ecf1-5cf7-a75a-cc37675eb71e', 'a25e4a76-4943-5a3d-aa16-719363e45c0e', 1, 1, 'ከአባታቸው ከያዕቆብ ጋር ወደ ግብፅ የገቡት የእስራኤል ልጆች ስሞች እነዚህ ናቸው፤ ሰው ሁሉ ከቤተ ሰቡ ጋር ገባ፤'),
  ('99ec52a9-21f0-58af-adb9-82fb9dd746ef', '2e4dda2c-ecf1-5cf7-a75a-cc37675eb71e', 'a25e4a76-4943-5a3d-aa16-719363e45c0e', 2, 2, 'ሮቤል፥ ስምዖን፥ ሌዊ፥ ይሁዳ፥'),
  ('4c06c7d9-7b18-54c3-acb2-8d7f5ad017e1', '2e4dda2c-ecf1-5cf7-a75a-cc37675eb71e', 'a25e4a76-4943-5a3d-aa16-719363e45c0e', 3, 3, 'ይሳኮር፥ ዛብሎን፥ ብንያም።'),
  ('ab7b46d9-1713-507d-a420-5ab634d9d3a2', '2e4dda2c-ecf1-5cf7-a75a-cc37675eb71e', 'a25e4a76-4943-5a3d-aa16-719363e45c0e', 4, 4, 'ዳን፥ ንፍታሌም፥ ጋድ፥ አሴር።'),
  ('58c207a7-eb60-57a7-aaa8-65e2a1b29570', '2e4dda2c-ecf1-5cf7-a75a-cc37675eb71e', 'a25e4a76-4943-5a3d-aa16-719363e45c0e', 5, 5, 'ዮሴፍም አስቀድሞ በግብፅ ነበረ። ከያዕቆብ ጕልበት የወጡት ሰዎች ሁሉ ሰባ ነፍሶች ነበሩ፤'),
  ('31cb8033-7904-52e4-ab21-27aa165c5001', '2e4dda2c-ecf1-5cf7-a75a-cc37675eb71e', 'a25e4a76-4943-5a3d-aa16-719363e45c0e', 6, 6, 'ዮሴፍም ሞተ፤ ወንድሞቹም፥ ያም ትውልድ ሁሉ።'),
  ('c29967aa-bfd9-5a48-aa2f-4a592cbc0e82', '2e4dda2c-ecf1-5cf7-a75a-cc37675eb71e', 'a25e4a76-4943-5a3d-aa16-719363e45c0e', 7, 7, 'የእስራኤልም ልጆች በዙ፤ ተባዙም፤ የተጠሉም ሆኑ። እጅግም ጸኑ፤ ምድሪቱም በእነርሱ ሞላች።'),
  ('3d4be661-bbd2-594d-aad5-307259383cb1', '2e4dda2c-ecf1-5cf7-a75a-cc37675eb71e', 'a25e4a76-4943-5a3d-aa16-719363e45c0e', 8, 8, 'በግብፅ ዮሴፍን ያላወቀ ሌላ ንጉሥ ተነሣ።'),
  ('af86a466-30e6-5b17-ae7d-b07895015a09', '2e4dda2c-ecf1-5cf7-a75a-cc37675eb71e', 'a25e4a76-4943-5a3d-aa16-719363e45c0e', 9, 9, 'እርሱም ሕዝቡን፥ “እነሆ፥ የእስራኤል ልጆች ሕዝብ ታላቅና ብዙ ሆነዋል፤ ከእኛም ይልቅ በርትተዋል፤'),
  ('ea831702-da92-5bd1-aa38-f8409ea0d3ee', '2e4dda2c-ecf1-5cf7-a75a-cc37675eb71e', 'a25e4a76-4943-5a3d-aa16-719363e45c0e', 10, 10, 'ኑ፤ እንጠበብባቸው፤ የበዙ እንደሆነ ጦርነት በመጣብን ጊዜ በጠላቶቻችን ላይ ተደርበው በኋላችን ይወጉናልና፥ ከምድራችንም ያስወጡናልና።”'),
  ('636aee60-9b5a-5c9f-accc-c43352facfd1', '2e4dda2c-ecf1-5cf7-a75a-cc37675eb71e', 'a25e4a76-4943-5a3d-aa16-719363e45c0e', 11, 11, 'በብርቱ ሥራም ያስጨንቋቸው ዘንድ የሠራተኞች አለቆችን ሾመባቸው፤ ለፈርዖንም ፌቶምን፥ ራምሴንና የፀሐይ ከተማ የምትባል ዖንን ጽኑ ከተሞች አድርገው ሠሩ።'),
  ('b225391f-c628-5a5c-aff4-31b9461f13df', '2e4dda2c-ecf1-5cf7-a75a-cc37675eb71e', 'a25e4a76-4943-5a3d-aa16-719363e45c0e', 12, 12, 'ነገር ግን እንዳስጨነቁአቸው መጠን እንዲሁ በዙ፤ እጅግም ጸኑ ፤ ግብፃውያንም የእስራኤልን ልጆች ይጸየፉአቸው ነበር።'),
  ('0f39afdd-4303-58f6-ac48-202cf7490d53', '2e4dda2c-ecf1-5cf7-a75a-cc37675eb71e', 'a25e4a76-4943-5a3d-aa16-719363e45c0e', 13, 13, 'ግብፃውያንም የእስራኤልን ልጆች በግፍዕ ገዙአቸው።'),
  ('f06362c7-bfb3-5a69-a348-466a0e5e00e6', '2e4dda2c-ecf1-5cf7-a75a-cc37675eb71e', 'a25e4a76-4943-5a3d-aa16-719363e45c0e', 14, 14, 'በጽኑ ሥራ፥ በጭቃ፥ በጡብም፥ በእርሻም ሥራ ሁሉ፥ በመከራም በሚያሠሩአቸው ሥራ ሁሉ፤ ሕይወታቸውን ያስመርሩአቸው ነበር።'),
  ('f2d346b8-f252-5ecb-a0c3-080991612170', '2e4dda2c-ecf1-5cf7-a75a-cc37675eb71e', 'a25e4a76-4943-5a3d-aa16-719363e45c0e', 15, 15, 'የግብፅም ንጉሥ አንዲቱ ሲፓራ፥ ሁለተኛዪቱም ፎሓ የሚባሉትን የዕብራውያትን አዋላጆች እንዲህ ብሎ ተናገረ፦'),
  ('0e3ce389-1e63-5bc1-afb1-ec141c79243c', '2e4dda2c-ecf1-5cf7-a75a-cc37675eb71e', 'a25e4a76-4943-5a3d-aa16-719363e45c0e', 16, 16, '“እናንተ ዕብራውያትን ሴቶች ስታዋልዱ ለመውለድ እንደ ደረሱ በአያችሁ ጊዜ፥ ወንድ ቢሆን ግደሉት፤ ሴት ብትሆን ግን አትግደሏት።”'),
  ('95683aa5-a2d1-5c77-a763-7ac1e3c8da46', '2e4dda2c-ecf1-5cf7-a75a-cc37675eb71e', 'a25e4a76-4943-5a3d-aa16-719363e45c0e', 17, 17, 'አዋላጆች ግን እግዚአብሔርን ፈሩ፤ የግብፅ ንጉሥም እንደ አዘዛቸው አላደረጉም፤ ወንዶቹን ሕፃናትንም አዳኑአቸው።'),
  ('1e1481aa-f44b-5fd9-ad2a-83646136be0d', '2e4dda2c-ecf1-5cf7-a75a-cc37675eb71e', 'a25e4a76-4943-5a3d-aa16-719363e45c0e', 18, 18, 'የግብፅም ንጉሥ አዋላጆችን ጠርቶ፥ “ለምን እንዲህ አደረጋችሁ? ወንዶቹን ሕፃናትንስ ለምን አዳናችሁ?” አላቸው።'),
  ('e7928f07-2097-56df-ae9a-6a97f2daff9a', '2e4dda2c-ecf1-5cf7-a75a-cc37675eb71e', 'a25e4a76-4943-5a3d-aa16-719363e45c0e', 19, 19, 'አዋላጆችም ፈርዖንን፥ “የዕብራውያን ሴቶች እንደ ግብፅ ሴቶች ስላልሆኑ አዋላጆች ሳይገቡ ይወልዳሉ” አሉት።'),
  ('7e555131-78fb-5c74-ab04-d381b5e7e6d4', '2e4dda2c-ecf1-5cf7-a75a-cc37675eb71e', 'a25e4a76-4943-5a3d-aa16-719363e45c0e', 20, 20, 'እግዚአብሔርም ለአዋላጆች መልካም አደረገላቸው፤ ሕዝቡም በዙ፤ እጅግም ጸኑ።'),
  ('bc7ec727-d9c8-596a-a2d2-508b4dcf5d12', '2e4dda2c-ecf1-5cf7-a75a-cc37675eb71e', 'a25e4a76-4943-5a3d-aa16-719363e45c0e', 21, 21, 'እንዲህም ሆነ፤ አዋላጆች እግዚአብሔርን ስለፈሩ ቤቶችን አደረገላቸው።'),
  ('3feecf11-3fd4-59e5-a698-2866f629421e', '2e4dda2c-ecf1-5cf7-a75a-cc37675eb71e', 'a25e4a76-4943-5a3d-aa16-719363e45c0e', 22, 22, 'ፈርዖንም፥ “የሚወለደውን ወንድ ልጅ ሁሉ ወደ ወንዝ ጣሉት፤ ሴትን ልጅ ሁሉ ግን በሕይወት አድኑአት” ብሎ ሕዝቡን ሁሉ አዘዘ።'),
  ('4b481bcc-ad8a-50a6-a3db-31d31138fb9e', '6d4e5cfe-d1e1-5941-ab71-fdb5fbefdb6e', 'c0de33d9-212b-5266-a6b5-7af5aea00f6d', 1, 1, 'ከሌዊ ወገን እንበረም የሚባል አንድ ሰው ነበረ፤ እርሱም ከሌዊ ሴቶች ልጆች ሚስትን አገባ።'),
  ('39f59e2f-ae40-5a1b-a749-34d50699bb4a', '6d4e5cfe-d1e1-5941-ab71-fdb5fbefdb6e', 'c0de33d9-212b-5266-a6b5-7af5aea00f6d', 2, 2, 'ሴቲቱም ፀነሰች፤ ወንድ ልጅም ወለደች፤ መልካምም እንደሆነ በአዩ ጊዜ ሦስት ወር ሸሸጉት።'),
  ('4570f1f1-058f-52f4-a6ad-3ecc24a862f2', '6d4e5cfe-d1e1-5941-ab71-fdb5fbefdb6e', 'c0de33d9-212b-5266-a6b5-7af5aea00f6d', 3, 3, 'ደግሞም ሊሸሽጉት በአልቻሉ ጊዜ እናቱ የደንገል ሣጥን ለእርሱ ወስዳ ዝፍትና ቅጥራን ለቀለቀችው፤ ሕፃኑንም አኖረችበት፤ በወንዝም ዳር ባለ በቄጠማ ውስጥ አስቀመጠችው።'),
  ('d290a84d-bffc-55f5-abf3-e44b5be929c1', '6d4e5cfe-d1e1-5941-ab71-fdb5fbefdb6e', 'c0de33d9-212b-5266-a6b5-7af5aea00f6d', 4, 4, 'እኅቱም ምን እንደሚደርስበት ታውቅ ዘንድ በሩቅ ቆማ ትጐበኘው ነበር።'),
  ('7fdc3e1f-7eea-58b0-a3d1-9a1f615e7798', '6d4e5cfe-d1e1-5941-ab71-fdb5fbefdb6e', 'c0de33d9-212b-5266-a6b5-7af5aea00f6d', 5, 5, 'የፈርዖንም ሴት ልጅ ልትታጠብ ወደ ወንዝ ወረደች፤ ደንገጥሮችዋም በወንዝ ዳር ይሄዱ ነበር፤ ሣጥኑንም በቄጠማ ውስጥ አየች፤ ደንገጥርዋንም ልካ አስመጣችው።'),
  ('0fe1dcbd-c02f-583c-acde-1075b297a9ad', '6d4e5cfe-d1e1-5941-ab71-fdb5fbefdb6e', 'c0de33d9-212b-5266-a6b5-7af5aea00f6d', 6, 6, 'ሣጥኑን በከፈተችም ጊዜ ሕፃኑን አየች፤ እነሆም፥ ሕፃኑ በሣጥኑ ውስጥ ያለቅስ ነበር፤ የፈርዖንም ልጅ አዘነችለት፥ “ይህ ሕፃን ከዕብራውያን ልጆች አንዱ ነው” አለች።'),
  ('ede2ad6c-91f6-5ee3-a38f-99251ae0ff07', '6d4e5cfe-d1e1-5941-ab71-fdb5fbefdb6e', 'c0de33d9-212b-5266-a6b5-7af5aea00f6d', 7, 7, 'የዚያም ሕፃን እኅት ለፈርዖን ልጅ፥ “ሕፃኑን ታጠባልሽ ዘንድ ሄጄ የምታጠባ ሴት ከዕብራውያን ሴቶች ልጥራልሽን?” አለቻት።'),
  ('42bbeb55-cefb-5f42-aacf-1fbcb19c6289', '6d4e5cfe-d1e1-5941-ab71-fdb5fbefdb6e', 'c0de33d9-212b-5266-a6b5-7af5aea00f6d', 8, 8, 'የፈርዖንም ልጅ፥ “ሂጂና ጥሪልኝ” አለቻት፤ ብላቴናዪቱም ሄዳ የሕፃኑን እናት ጠራች።'),
  ('9b38d41a-bc62-559b-ac6e-0fb69d270f53', '6d4e5cfe-d1e1-5941-ab71-fdb5fbefdb6e', 'c0de33d9-212b-5266-a6b5-7af5aea00f6d', 9, 9, 'የፈርዖንም ልጅ፥ “ይህን ሕፃን ተንከባክበሽ አጥቢልኝ፤ ዋጋሽንም እሰጥሻለሁ” አለቻት። ሴቲቱም ሕፃኑን ወስዳ አጠባችው።'),
  ('e956ea67-baa0-51da-aa2a-115ea3be5630', '6d4e5cfe-d1e1-5941-ab71-fdb5fbefdb6e', 'c0de33d9-212b-5266-a6b5-7af5aea00f6d', 10, 10, 'ሕፃኑም በአደገ ጊዜ ወደ ፈርዖን ልጅ ወሰደችው፤ ለእርስዋም ልጅ ሆነላት። እኔ ከውኃ አውጥቼዋለሁና ስትልም ስሙን ሙሴ ብላ ጠራችው ።'),
  ('b0637b20-3abe-560a-ab82-bb48a41aa58f', '6d4e5cfe-d1e1-5941-ab71-fdb5fbefdb6e', '134032c2-f559-582e-abbb-cbadcec5848b', 1, 11, 'ከብዙ ቀን በኋላ እንዲህ ሆነ፤ ሙሴ አደገ፤ ወደ ወንድሞቹም ወጣ፤ መከራቸውንም ተመለከተ፤ የግብፅም ሰው ከወንድሞቹ ከእስራኤል ልጆች አንዱን ዕብራዊ ሰው ሲመታ አየ።'),
  ('e188cf92-fd36-5c14-abaf-c3f269dc6ddc', '6d4e5cfe-d1e1-5941-ab71-fdb5fbefdb6e', '134032c2-f559-582e-abbb-cbadcec5848b', 2, 12, 'ወዲህና ወዲያ ተመለከተ፤ ማንንም አላየም፤ ግብፃዊውንም ገደለው፤ በአሸዋ ውስጥም ቀበረው።'),
  ('6a8b3c33-3baa-5ba3-a1cf-8c3937c96d98', '6d4e5cfe-d1e1-5941-ab71-fdb5fbefdb6e', '134032c2-f559-582e-abbb-cbadcec5848b', 3, 13, 'በሁለተኛውም ቀን ወጣ፤ ሁለቱም የዕብራውያን ሰዎች ሲጣሉ አየ፤ ሙሴም በዳዩን፥ “ለምን ባልንጀራህን ትመታዋለህ?” አለው።'),
  ('c3f8be96-84fc-5cd9-abb9-1ccb7e034743', '6d4e5cfe-d1e1-5941-ab71-fdb5fbefdb6e', '134032c2-f559-582e-abbb-cbadcec5848b', 4, 14, 'ወንድሙን የሚበድለው ያም ሰው፥ “በእኛ ላይ አንተን አለቃ ወይስ ዳኛ ማን አደረገህ? ወይስ ግብፃዊውን ትናንት እንደ ገደልኸው ልትገድለኝ ትሻለህን?” አለው። ሙሴም፥ “በእውነት ይህ ነገር ታውቆአልን?” ብሎ ፈራ።'),
  ('1e2d08ac-77b0-5fd5-a0da-71e0f15f8971', '6d4e5cfe-d1e1-5941-ab71-fdb5fbefdb6e', '134032c2-f559-582e-abbb-cbadcec5848b', 5, 15, 'ፈርዖንም ይህን ነገር ሰማ፤ ሙሴንም ሊገድለው ፈለገ። ሙሴ ግን ከፈርዖን ፊት ኰበለለ፤ በምድያምም ምድር ተቀመጠ፤ ወደ ምድያም ምድር በደረሰ ጊዜም በውኃው ጕድጓድ አጠገብ ዐረፈ።'),
  ('c844dcdb-aa46-54bc-abf4-b24829f77458', '6d4e5cfe-d1e1-5941-ab71-fdb5fbefdb6e', '134032c2-f559-582e-abbb-cbadcec5848b', 6, 16, 'ለምድያምም ካህን ሰባት ሴቶች ልጆች ነበሩት፤ የአባታቸውንም የዮቶርን በጎች ይጠብቁ ነበር፤ እነርሱም መጥተው ውኃ ቀዱ፤ የአባታቸውንም የዮቶርን በጎች ሊያጠጡ የውኃዉን ገንዳ ሞሉ።'),
  ('3cc79aea-8f36-5bf3-a240-2b6356bde04d', '6d4e5cfe-d1e1-5941-ab71-fdb5fbefdb6e', '134032c2-f559-582e-abbb-cbadcec5848b', 7, 17, 'እረኞችም መጥተው ገፉአቸው፤ ሙሴ ግን ተነሥቶ አዳናቸው፤ እየቀዳም በጎቻቸዉን አጠጣላቸው።'),
  ('75dca90b-6450-5fa9-acc3-35797a5eea49', '6d4e5cfe-d1e1-5941-ab71-fdb5fbefdb6e', '134032c2-f559-582e-abbb-cbadcec5848b', 8, 18, 'ወደ አባታቸውም ወደ ራጉኤል መጡ እርሱም፥ “ዛሬስ እንዴት ፈጥናችሁ መጣችሁ?” አላቸው።'),
  ('8911bd39-cf76-5c7a-adcd-5e6dd9309d72', '6d4e5cfe-d1e1-5941-ab71-fdb5fbefdb6e', '134032c2-f559-582e-abbb-cbadcec5848b', 9, 19, 'እነርሱም፥ “አንድ የግብፅ ሰው ከእረኞች እጅ አዳነን፤ ደግሞም ቀዳልን፤ በጎቻችንንም አጠጣልን” አሉት።'),
  ('0d0f1b48-9214-5054-ac05-bbdca84e4600', '6d4e5cfe-d1e1-5941-ab71-fdb5fbefdb6e', '134032c2-f559-582e-abbb-cbadcec5848b', 10, 20, 'ልጆቹንም፥ “ሰውዬው ወዴት ነው? ለምንስ ያን ሰው ተዋችሁት? ጥሩት፤ እንጀራም ይብላ” አላቸው።'),
  ('37f57fc9-0ee9-5528-a20f-c0809068d9da', '6d4e5cfe-d1e1-5941-ab71-fdb5fbefdb6e', '134032c2-f559-582e-abbb-cbadcec5848b', 11, 21, 'ሙሴም ከዚያ ሰው ጋር ሊቀመጥ ወደደ፤ ልጁንም ሲፓራን ለሙሴ ሚስት ትሆነው ዘንድ ሰጠው።'),
  ('ddef88eb-20b9-56c4-a308-c67dc3141c54', '6d4e5cfe-d1e1-5941-ab71-fdb5fbefdb6e', '134032c2-f559-582e-abbb-cbadcec5848b', 12, 22, 'ያችም ሴት ፀነሰች፤ ወንድ ልጅም ወለደች፤ ሙሴም፥ “በሌላ ምድር መጻተኛ ነኝ” ሲል ስሙን ጌርሳም ብሎ ጠራው። ዳግመኛም ፀነሰች፤ ወንድ ልጅም ወለደች፤ ስሙንም ኤልኤዜር አለው፤ የአባቴ ፈጣሪ ረዳቴ ነው ሲል።'),
  ('d7e99810-5747-54bb-a873-185c41f78540', '6d4e5cfe-d1e1-5941-ab71-fdb5fbefdb6e', '134032c2-f559-582e-abbb-cbadcec5848b', 13, 23, 'ከዚያም ከብዙ ቀን በኋላ እንዲህ ሆነ፤ የግብፅ ንጉሥ ሞተ፤ የእስራኤልም ልጆች ከባርነት የተነሣ አለቀሱ፤ ጮኹም፤ ስለ ባርነታቸውም ጩኸታቸው ወደ እግዚአብሔር ወጣ።'),
  ('591b2032-d508-59ed-a8b9-998f50784603', '6d4e5cfe-d1e1-5941-ab71-fdb5fbefdb6e', '134032c2-f559-582e-abbb-cbadcec5848b', 14, 24, 'እግዚአብሔርም ጩኸታቸውን ሰማ፤ እግዚአብሔርም ከአብርሃምና ከይስሐቅ፥ ከያዕቆብም ጋር ያደረገውን ቃል ኪዳን ዐሰበ።'),
  ('f8cb2bb8-a3ef-5475-a380-16314053192f', '6d4e5cfe-d1e1-5941-ab71-fdb5fbefdb6e', '134032c2-f559-582e-abbb-cbadcec5848b', 15, 25, 'እግዚአብሔርም የእስራኤልን ልጆች ጐበኛቸው፤ ታወቀላቸውም።'),
  ('102cf93e-b13d-59db-a2ba-9ae1b48aa087', 'a622e409-6ffa-5364-ae97-f44b82479e54', '26d26a0e-5d3c-5105-a641-83b6a75ef154', 1, 1, 'ሙሴም የአማቱን የምድያምን ካህን የዮቶርን በጎች ይጠብቅ ነበር፤ በጎቹንም ወደ ምድረ በዳ ዳርቻ ነዳ፤ ወደ እግዚአብሔርም ተራራ ወደ ኮሬብ መጣ።'),
  ('194a3184-c99c-5dc5-ad3c-b4d710288ec2', 'a622e409-6ffa-5364-ae97-f44b82479e54', '26d26a0e-5d3c-5105-a641-83b6a75ef154', 2, 2, 'የእግዚአብሔርም መልአክ ለሙሴ በእሳት ነበልባል በቍጥቋጦ መካከል ታየው፤ እነሆም፥ ቍጥቋጦው በእሳት ሲነድድ፥ ቍጥቋጦውም ሳይቃጠል አየ።'),
  ('a0572f4b-0f3e-59f5-a320-7d9a65f7a2fd', 'a622e409-6ffa-5364-ae97-f44b82479e54', '26d26a0e-5d3c-5105-a641-83b6a75ef154', 3, 3, 'ሙሴም፥ “ልሂድና ቍጥቋጦው ስለምን አልተቃጠለም? ይህን ታላቅ ራእይ ልይ” አለ።'),
  ('6259f022-c1c6-5dee-ab40-5fe5ab0c9df1', 'a622e409-6ffa-5364-ae97-f44b82479e54', '26d26a0e-5d3c-5105-a641-83b6a75ef154', 4, 4, 'እግዚአብሔር እርሱ ይመለከት ዘንድ እንደ መጣ በአየ ጊዜ እግዚአብሔር ከቍጥቋጦው ውስጥ እርሱን ጠርቶ፥ “ሙሴ! ሙሴ!” አለው እርሱም፥ “ይህ ምንድን ነው?” አለ።'),
  ('0f342240-c02f-5a33-a966-26a5e903a997', 'a622e409-6ffa-5364-ae97-f44b82479e54', '26d26a0e-5d3c-5105-a641-83b6a75ef154', 5, 5, '“ወደዚህ አትቅረብ፤ አንተ የቆምህባት ስፍራ የተቀደሰች መሬት ናትና፥ ጫማህን ከእግርህ አውጣ” አለው።'),
  ('c28ada79-bd48-5031-ad04-9e5e671e9bf7', 'a622e409-6ffa-5364-ae97-f44b82479e54', '26d26a0e-5d3c-5105-a641-83b6a75ef154', 6, 6, 'ደግሞም፥ “እኔ የአባቶችህ አምላክ፥ የአብርሃም አምላክ፥ የይስሐቅም አምላክ፥ የያዕቆብም አምላክ ነኝ” አለው። ሙሴም ወደ እግዚአብሔር ያይ ዘንድ ፈርቶአልና ፊቱን መለሰ።'),
  ('5cb0d7d3-78f0-5384-a8dc-fed527c2db2d', 'a622e409-6ffa-5364-ae97-f44b82479e54', '26d26a0e-5d3c-5105-a641-83b6a75ef154', 7, 7, 'እግዚአብሔርም ሙሴን አለው፥ “በግብፅ ያለውን የሕዝቤን መከራ በእውነት አየሁ፦ ከአሠሪዎቻቸውም የተነሣ ጩኸታቸውን ሰማሁ፤ ሥቃያቸውንም ዐውቄአለሁ፤'),
  ('18bffc5e-39f3-5e0c-a5f6-e74080d3519a', 'a622e409-6ffa-5364-ae97-f44b82479e54', '26d26a0e-5d3c-5105-a641-83b6a75ef154', 8, 8, 'ከግብፃውያንም እጅ አድናቸው ዘንድ፥ ከዚያችም ሀገር ወተትና ማር ወደምታፈስሰው ሀገር፥ ወደ ሰፊዪቱና ወደ መልካሚቱ ሀገር፥ ወደ ከነዓናውያንም፥ ወደ ኬጤዎናውያንም፥ ወደ አሞሬዎናውያንም፥ ወደ ፌርዜዎናውያንም፥ ወደ ጌርጌሴዎናውያንም፥ ወደ ኤዌዎናውያንም፥ ወደ ኢያቡሴዎናውያንም ስፍራ አወጣቸው ዘንድ ወረድሁ።'),
  ('5b11e5cd-b345-5c51-a432-a6507124243b', 'a622e409-6ffa-5364-ae97-f44b82479e54', '26d26a0e-5d3c-5105-a641-83b6a75ef154', 9, 9, 'አሁንም እነሆ፥ የእስራኤል ልጆች ጩኸት ወደ እኔ ደረሰ፤ ግብፃውያንም የሚያደርጉባቸውን ግፍ ደግሞ አየሁ።'),
  ('d7fed027-5d57-5648-a5e6-8add233032b6', 'a622e409-6ffa-5364-ae97-f44b82479e54', '26d26a0e-5d3c-5105-a641-83b6a75ef154', 10, 10, 'አሁንም ና፤ ወደ ግብፅ ንጉሥ ወደ ፈርዖን እልክሃለሁ። ሕዝቤን የእስራኤልን ልጆች ከግብፅ ምድር ታወጣቸዋለህ።”'),
  ('82fd85aa-27ef-5a15-a11a-aa7d0c585bcc', 'a622e409-6ffa-5364-ae97-f44b82479e54', '26d26a0e-5d3c-5105-a641-83b6a75ef154', 11, 11, 'ሙሴም እግዚአብሔርን፥ “ወደ ግብፅ ንጉሥ ወደ ፈርዖን እሄድ ዘንድ፥ የእስራኤልንም ልጆች ከግብፅ ምድር አወጣ ዘንድ እኔ ማን ነኝ?” አለው።'),
  ('6dce281a-1822-57c9-aa8b-2b2885ed91ac', 'a622e409-6ffa-5364-ae97-f44b82479e54', '26d26a0e-5d3c-5105-a641-83b6a75ef154', 12, 12, 'እግዚአብሔርም ሙሴን ተናገረው፤ እንዲህ ሲል፥ “በእውነት እኔ ከአንተ ጋር እሆናለሁ፤ እኔም እንደ ላክሁህ ይህ ለአንተ ምልክት ይሆንሃል፤ ሕዝቡን ከግብፅ በአወጣህ ጊዜ በዚህ ተራራ ላይ እግዚአብሔርን ታመልካላችሁ” አለው።'),
  ('925dd44e-25a8-58e6-a37d-375ee9dff581', 'a622e409-6ffa-5364-ae97-f44b82479e54', '26d26a0e-5d3c-5105-a641-83b6a75ef154', 13, 13, 'ሙሴም እግዚአብሔርን፥ “እነሆ፥ እኔ ወደ እስራኤል ልጆች እሄዳለሁ፤ የአባቶቻችሁ አምላክ ወደ እናንተ ላከኝ እላቸዋለሁ፤ ‘ስሙስ ማን ነው?’ ብለው በጠየቁኝ ጊዜ ምን እላቸዋለሁ?” አለው።'),
  ('f1dd0843-7dce-54dc-a8f7-f4c850de0083', 'a622e409-6ffa-5364-ae97-f44b82479e54', '26d26a0e-5d3c-5105-a641-83b6a75ef154', 14, 14, 'እግዚአብሔርም ለሙሴ ነገረው፤ እንዲህ ሲል፥ “ያለና የሚኖር እኔ ነኝ፤ እንዲህ ለእስራኤል ‘ያለና የሚኖር’ ወደ እናንተ ላከኝ ትላቸዋለህ” አለው።'),
  ('562574dd-8bfc-523d-a4e3-c91467bb63b1', 'a622e409-6ffa-5364-ae97-f44b82479e54', '26d26a0e-5d3c-5105-a641-83b6a75ef154', 15, 15, 'ዳግመኛም እግዚአብሔር ሙሴን አለው፥ “ለእስራኤል ልጆች እንዲህ ትላለህ፦ የአባቶቻችሁ አምላክ፥ የአብርሃም አምላክ፥ የይስሐቅም አምላክ፥ የያዕቆብም አምላክ እግዚአብሔር ወደ እናንተ ላከኝ፤ ይህ ለዘለዓለም ስሜ ነው፤ እስከ ልጅ ልጅ ድረስም መታሰቢያዬ ይህ ነው።'),
  ('0fcef21d-ead0-5655-a32f-d7b7a4d16f48', 'a622e409-6ffa-5364-ae97-f44b82479e54', '26d26a0e-5d3c-5105-a641-83b6a75ef154', 16, 16, 'ሂድ የእስራኤልንም ሽማግሌዎች ሰብስብ፤ እንዲህም በላቸው፦ የአባቶቻችሁ አምላክ፥ የአብርሃም አምላክ፥ የይስሐቅም አምላክ፥ የያዕቆብም አምላክ እግዚአብሔር እንዲህ ሲል ተገለጠልኝ፦ መጐብኘትን ጐበኘኋችሁ፤ በግብፅም የሚደረግባችሁን አየሁ፤'),
  ('c036936e-32e0-5d46-ae9b-55eb9b1588d4', 'a622e409-6ffa-5364-ae97-f44b82479e54', '26d26a0e-5d3c-5105-a641-83b6a75ef154', 17, 17, 'እንዲህም አልሁ፦ ከግብፅ መከራ ወደ ከነዓናውያን፥ ወደ ኬጤዎናውያን፥ ወደ አሞሬዎናውያን፥ ወደ ፌርዜዎናውያን፥ ወደ ጌርጌሴዎናውያን፥ ወደ ኤዌዎናውያን፥ ወደ ኢያቡሴዎናውያን ሀገር፥ ወተትና ማር ወደምታፈስስ ሀገር አወጣችኋለሁ፤'),
  ('abbaef3b-d881-5921-ae22-82e06e9bd69b', 'a622e409-6ffa-5364-ae97-f44b82479e54', '26d26a0e-5d3c-5105-a641-83b6a75ef154', 18, 18, 'እነርሱም ቃልህን ይሰማሉ፤ አንተና የእስራኤል ሽማግሌዎች ወደ ግብፅ ንጉሥ ትገባላችሁ፦ የዕብራውያን አምላክ እግዚአብሔር ጠርቶናል፤ አሁንም ለአምላካችን ለእግዚአብሔር እንሠዋ ዘንድ የሦስት ቀን መንገድ ወደ ምድረ በዳ እንሄዳለን ትሉታላችሁ።'),
  ('7c7f3020-f15c-5620-aaa8-b1f5f3bc7a8a', 'a622e409-6ffa-5364-ae97-f44b82479e54', '26d26a0e-5d3c-5105-a641-83b6a75ef154', 19, 19, 'ነገር ግን በጽኑ እጅ ካልሆነ በቀር ትሄዱ ዘንድ የግብፅ ንጉሥ እንደማይፈቅድላችሁ እኔ አውቃለሁ።'),
  ('e3ed7b0b-dc13-5d0c-aef7-1f6fd7d44a40', 'a622e409-6ffa-5364-ae97-f44b82479e54', '26d26a0e-5d3c-5105-a641-83b6a75ef154', 20, 20, 'እኔም እጄን እዘረጋለሁ፤ በማደርግባቸውም ተአምራቴ ሁሉ ግብፅን እመታለሁ፤ ከዚያም በኋላ ይለቅቋችኋል።'),
  ('2910b69d-eb07-516f-a34a-16f697153f46', 'a622e409-6ffa-5364-ae97-f44b82479e54', '26d26a0e-5d3c-5105-a641-83b6a75ef154', 21, 21, 'በግብፃውያንም ፊት ለዚህ ሕዝብ ሞገስን እሰጣለሁ፤ በምትሄዱም ጊዜ ባዶ እጃችሁን አትሄዱም፤'),
  ('f4aea9d0-9af6-51ca-aee7-c26d8355d464', 'a622e409-6ffa-5364-ae97-f44b82479e54', '26d26a0e-5d3c-5105-a641-83b6a75ef154', 22, 22, 'ነገር ግን እያንዳንዲቱ ሴት ከጎረቤቷ፥ በቤቷም ካለችው ሴት የብር ዕቃ፥ የወርቅ ዕቃ፥ ልብስም ትዋሳለች፤ በወንዶችና በሴቶች ልጆቻችሁ ላይም ታደርጉታላችሁ፤ ግብፃውያንንም ትበዘብዛላችሁ።”'),
  ('887825ee-b4a8-51c0-a208-9726e055ffcb', '4be3b2f1-fdb7-53e3-ac71-0195f6adaf8d', '8c714b01-8c50-5497-ab47-d4d1c166a798', 1, 1, 'ሙሴም መለሰ፥ “እነሆ፥ ባያምኑኝ፥ ቃሌንም ባይሰሙ፦ ‘እግዚአብሔርም አልተገለጠልህም’ ቢሉኝ ምን እላቸዋለሁ?” አለ።'),
  ('ab333828-d15d-579c-a417-63804fc6b271', '4be3b2f1-fdb7-53e3-ac71-0195f6adaf8d', '8c714b01-8c50-5497-ab47-d4d1c166a798', 2, 2, 'እግዚአብሔርም፥ “ይህ በእጅህ ያለው ምንድን ነው?” አለው። እርሱም፥ “በትር ነው” አለ።'),
  ('66eaa093-3105-55a3-a09d-a4e57c480c42', '4be3b2f1-fdb7-53e3-ac71-0195f6adaf8d', '8c714b01-8c50-5497-ab47-d4d1c166a798', 3, 3, '“ወደ መሬት ጣለው” አለው፤ እርሱም በመሬት ጣለው፤ እባብም ሆነ፤ ሙሴም ከእርሱ ሸሸ።'),
  ('316a8ad3-5e6f-527d-a0fd-3b28fd871def', '4be3b2f1-fdb7-53e3-ac71-0195f6adaf8d', '8c714b01-8c50-5497-ab47-d4d1c166a798', 4, 4, 'እግዚአብሔርም ሙሴን፥ “እጅህን ዘርግተህ ጅራቱን ያዝ” አለው፤ ሙሴም እጁን ዘርግቶ፥ ጅራቱን ይዞ፥ አነሣው በእጁም በትር ሆነ።'),
  ('0dc8771f-3ca7-5903-a4ef-6c2518399de1', '4be3b2f1-fdb7-53e3-ac71-0195f6adaf8d', '8c714b01-8c50-5497-ab47-d4d1c166a798', 5, 5, 'እግዚአብሔርም፥ “የአባቶቻቸው አምላክ፥ የአብርሃም አምላክ፥ የይስሐቅም አምላክ፥ የያዕቆብም አምላክ እንደ ታየህ ያምኑሃል” አለው።'),
  ('89c8b216-342c-59e0-a4ad-110a15671aaa', '4be3b2f1-fdb7-53e3-ac71-0195f6adaf8d', '8c714b01-8c50-5497-ab47-d4d1c166a798', 6, 6, 'ዳግመኛም እግዚአብሔር፥ “እጅህን ወደ ብብትህ አግባ አለው።” እጁንም ወደ ብብቱ አገባት፤ “እጅህንም ከብብትህ አውጣ” አለው፤ እጁንም ከብብቱ አወጣ፤ እጁም ለምጽ ሆነች።'),
  ('6c282854-0765-517b-ac27-6eff767854ec', '4be3b2f1-fdb7-53e3-ac71-0195f6adaf8d', '8c714b01-8c50-5497-ab47-d4d1c166a798', 7, 7, 'ዳግመኛም፥ “እጅህን ወደ ብብትህ መልስ” አለው። እጁንም ወደ ብብቱ መለሳት፤ “እጅህን ከብብትህ አውጣ” አለው፤ እጁንም ከብብቱ አወጣ፤ ተመልሳም ገላውን መሰለች።'),
  ('91b95a9b-f07b-5e0f-abb6-b99f10a2b24f', '4be3b2f1-fdb7-53e3-ac71-0195f6adaf8d', '8c714b01-8c50-5497-ab47-d4d1c166a798', 8, 8, 'ደግሞም አለው፥ “እንዲህም ይሆናል፤ ባያምኑህ፥ በፊተኛዪቱም ምልክት ቃልህን ባይሰሙ፥ በሁለተኛዪቱ ምልክት ቃልህን ያምናሉ።'),
  ('c3ab4b1a-acd3-5579-a6ee-8fccb1d801c6', '4be3b2f1-fdb7-53e3-ac71-0195f6adaf8d', '8c714b01-8c50-5497-ab47-d4d1c166a798', 9, 9, 'እንዲህም ይሆናል፤ እነዚህን ሁለት ምልክቶች ባያምኑ፥ ቃልህንም ባይሰሙ፥ ከወንዙ ውኃን ውሰድ፤ በደረቁም መሬት ላይ አፍስሰው፤ ከወንዙም የወሰድኸው ውኃ በደረቁ መሬት ላይ ደም ይሆናል።”'),
  ('dcbbab62-4601-5121-ab51-2295787a2048', '4be3b2f1-fdb7-53e3-ac71-0195f6adaf8d', '8c714b01-8c50-5497-ab47-d4d1c166a798', 10, 10, 'ሙሴም እግዚአብሔርን አለው፥ “ጌታ ሆይ፥ እማልድሃለሁ፤ ትናንት፥ ከትናንት ወዲያ ባሪያህን ከተናገርኸኝ ጀምሮ አፈ ትብ ሰው አይደለሁም። እኔ አፌ ኰልታፋ፥ ምላሴም ተብታባ የሆነ ሰው ነኝ።”'),
  ('560be41b-127d-5cfb-a556-d3c4b0f3c42e', '4be3b2f1-fdb7-53e3-ac71-0195f6adaf8d', '8c714b01-8c50-5497-ab47-d4d1c166a798', 11, 11, 'እግዚአብሔርም ሙሴን አለው፥ “ለሰው አፍን የሰጠ ማን ነው? ዲዳስ፥ ደንቆሮስ፥ የሚያይስ፥ ዕውርስ የሚያደርግ ማን ነው? እኔ እግዚአብሔር አይደለሁምን?'),
  ('798a0753-bb20-5467-a973-1982563e0127', '4be3b2f1-fdb7-53e3-ac71-0195f6adaf8d', '8c714b01-8c50-5497-ab47-d4d1c166a798', 12, 12, 'እንግዲህ አሁን ሂድ፤ እኔም አንደበትህን አረታለሁ፤ ትናገረውም ዘንድ ያለህን አለብምሃለሁ” አለው።'),
  ('afa3a210-c95a-5db2-ac2f-43f25166e689', '4be3b2f1-fdb7-53e3-ac71-0195f6adaf8d', '8c714b01-8c50-5497-ab47-d4d1c166a798', 13, 13, 'ሙሴም፥ “ጌታ ሆይ፥ እማልድሃለሁ፤ መናገር የሚችል የምትልከው ሌላ ሰው ፈልግ” አለው።'),
  ('0ecb4b84-f585-56b0-ab75-5c0b04366a13', '4be3b2f1-fdb7-53e3-ac71-0195f6adaf8d', '8c714b01-8c50-5497-ab47-d4d1c166a798', 14, 14, 'እግዚአብሔርም በሙሴ ላይ እጅግ ተቈጣ፤ እንዲህም አለ፥ “ሌዋዊው ወንድምህ አሮን አለ አይደለምን? እርሱ እንደሚናገርልህ አውቃለሁ፤ እነሆም፥ እርሱ ሊገናኝህ ይመጣል፤ በአየህም ጊዜ በልቡ ደስ ይለዋል።'),
  ('1bc08ccf-4bd8-55f9-a352-67d2d17a82d4', '4be3b2f1-fdb7-53e3-ac71-0195f6adaf8d', '8c714b01-8c50-5497-ab47-d4d1c166a798', 15, 15, 'አንተም ትናገረዋለህ፤ ቃሌንም በአፉ ታደርገዋለህ፤ እኔ አንደበትህንና አንደበቱን አረታለሁ፤ የምታደርጉትንም አለብማችኋለሁ።'),
  ('f9d42b5a-b7bc-5415-a7cd-7692a15ec739', '4be3b2f1-fdb7-53e3-ac71-0195f6adaf8d', '8c714b01-8c50-5497-ab47-d4d1c166a798', 16, 16, 'እርሱ ስለ አንተ ከሕዝቡ ጋር ይነጋገራል፤ እርሱ አፍ ይሆንልሃል፤ አንተም በእግዚአብሔር ዘንድ ትሆንለታለህ።'),
  ('30e79c2b-7820-516f-a4fe-f137e75011a0', '4be3b2f1-fdb7-53e3-ac71-0195f6adaf8d', '8c714b01-8c50-5497-ab47-d4d1c166a798', 17, 17, 'ይህችንም ተአምራት የምታደርግባትን በትር በእጅህ ያዝ።”'),
  ('38b7e3d5-23dd-5f2c-a88b-a440890c9efb', '4be3b2f1-fdb7-53e3-ac71-0195f6adaf8d', '496658fd-19d4-5dec-af13-4459f55fb57c', 1, 18, 'ሙሴም ሄደ፤ ወደ አማቱ ወደ ዮቶርም ተመለሰ፥ “እስከ ዛሬ በሕይወት እንደ አሉ አይ ዘንድ ተመልሼ ወደ ግብፅ ወደ ወንድሞች እሄዳለሁ” አለው። ዮቶርም ሙሴን፥ “በደኅና ሂድ” አለው።'),
  ('380e8c51-7c1a-56cc-a4bc-cb464e6b9aba', '4be3b2f1-fdb7-53e3-ac71-0195f6adaf8d', '496658fd-19d4-5dec-af13-4459f55fb57c', 2, 19, 'ከብዙ ዘመንም በኋላ የግብፅ ንጉሥ ሞተ። እግዚአብሔርም ሙሴን በምድያም፥ “ነፍስህን የሚሹአት ሰዎች ሁሉ ሞተዋልና ተመልሰህ ወደ ግብፅ ሂድ” አለው።'),
  ('7bb845ee-1b1b-5809-ae05-0631d37a4643', '4be3b2f1-fdb7-53e3-ac71-0195f6adaf8d', '496658fd-19d4-5dec-af13-4459f55fb57c', 3, 20, 'ሙሴም ሚስቱንና ልጆቹን ወሰደ፤ በአህዮች ላይም አስቀመጣቸው፤ ወደ ግብፅም ሀገር ተመለሰ፤ ሙሴም ያችን የእግዚአብሔርን በትር በእጁ ይዞ ሄደ።'),
  ('a7b31279-06a2-5f32-ad21-35e0cfa7ad93', '4be3b2f1-fdb7-53e3-ac71-0195f6adaf8d', '496658fd-19d4-5dec-af13-4459f55fb57c', 4, 21, 'እግዚአብሔርም ሙሴን አለው፥ “ወደ ግብፅ ተመልሰህ ስትሄድ በእጅህ ያደረግሁትን ተአምራቴን ሁሉ በፈርዖን ፊት ታደርገው ዘንድ ተመልከት፤ እኔ ግን ልቡን አጸናዋለሁ፤ ሕዝቡንም አይለቅቅም።'),
  ('a05ce19b-4cf6-552f-a25b-6221d22c82b3', '4be3b2f1-fdb7-53e3-ac71-0195f6adaf8d', '496658fd-19d4-5dec-af13-4459f55fb57c', 5, 22, 'አንተ ግን ፈርዖንን እንዲህ ትለዋለህ፦ እግዚአብሔር እንዲህ ይላል፥ “እስራኤል የበኵር ልጄ ነው፤'),
  ('5b2771b7-51cd-52c9-a851-65dcd5f5d145', '4be3b2f1-fdb7-53e3-ac71-0195f6adaf8d', '496658fd-19d4-5dec-af13-4459f55fb57c', 6, 23, 'ያመልኩኝ ዘንድ ሕዝቤን ልቀቅ አልሁህ፤ አንተም ልትለቅቃቸው ባትፈቅድ፤ እኔ የበኵር ልጅህን እንደምገድል ዕወቅ።”'),
  ('a9401f43-2971-5637-ac9d-8b4f62a2b6e1', '4be3b2f1-fdb7-53e3-ac71-0195f6adaf8d', '496658fd-19d4-5dec-af13-4459f55fb57c', 7, 24, 'እንዲህም ሆነ፤ በመንገድ ላይ በአደረበት ስፍራ የእግዚአብሔር መልአክ ተገናኘው፤ ሊገድለውም ፈለገ።'),
  ('73890f87-61de-521d-aabb-bb0bab6da0e1', '4be3b2f1-fdb7-53e3-ac71-0195f6adaf8d', '496658fd-19d4-5dec-af13-4459f55fb57c', 8, 25, 'ሚስቱ ሲፓራም ባልጩት ወሰደች፤ የልጅዋንም ሸለፈት ገረዘች፤ “ይህ የልጄ የግርዛቱ ደም ስለ እርሱ ፈንታ ይሁን” ብላ ከእግሩ በታች ወደቀች።'),
  ('3ff2a97e-5f49-58fa-aeaf-57c8d53aea0e', '4be3b2f1-fdb7-53e3-ac71-0195f6adaf8d', '496658fd-19d4-5dec-af13-4459f55fb57c', 9, 26, 'ከእርሱም ሄደ፤ የዚያ ጊዜ፥ “ይህ የልጄ የግርዛቱ ደም ስለ እርሱ ፈንታ ይሁን” ብላለችና።'),
  ('fe2d8209-8d80-5e62-a689-474a06dde716', '4be3b2f1-fdb7-53e3-ac71-0195f6adaf8d', '496658fd-19d4-5dec-af13-4459f55fb57c', 10, 27, 'እግዚአብሔርም አሮንን አለው፥ “ሄደህ በምድረ በዳ ሙሴን ተገናኘው፤” ሄዶም በእግዚአብሔር ተራራ ተገናኘው፤ እርስ በርሳቸውም ተሳሳሙ።'),
  ('2fc79584-0495-597d-a037-457385617d11', '4be3b2f1-fdb7-53e3-ac71-0195f6adaf8d', '496658fd-19d4-5dec-af13-4459f55fb57c', 11, 28, 'ሙሴም እግዚአብሔር የላከውን ቃል ሁሉ፥ የአዘዘውንም ተአምራት ሁሉ ለአሮን ነገረው።'),
  ('ee3ae39c-8d68-5129-a3c9-e17a09ed5926', '4be3b2f1-fdb7-53e3-ac71-0195f6adaf8d', '496658fd-19d4-5dec-af13-4459f55fb57c', 12, 29, 'ሙሴና አሮንም ሄዱ፤ የእስራኤልንም ልጆች ሽማግሌዎች ሁሉ ሰበሰቡ።'),
  ('799ba328-56c5-5ec4-adfb-c4f3e8982b6e', '4be3b2f1-fdb7-53e3-ac71-0195f6adaf8d', '496658fd-19d4-5dec-af13-4459f55fb57c', 13, 30, 'አሮንም እግዚአብሔር ለሙሴ የነገረውን ቃል ሁሉ ተናገረ፤ ተአምራቱንም በሕዝቡ ፊት አደረገ።'),
  ('1b643200-b67b-54c0-abe3-1c7f1703197e', '4be3b2f1-fdb7-53e3-ac71-0195f6adaf8d', '496658fd-19d4-5dec-af13-4459f55fb57c', 14, 31, 'ሕዝቡም አመኑ፤ ደስም አላቸው፤ እግዚአብሔር የእስራኤልን ልጆች ጐብኝቶአልና፤ ጭንቀታቸውንም አይቶአልና፤ ሕዝቡም ራሳቸውን ዝቅ አድርገው ሰገዱ።'),
  ('7801a266-f883-5a69-a81f-3a3ddf41d70b', '52fb8e83-761d-53e3-a278-6bed5f5ccb01', '03a43287-f2fe-5030-a31b-990cf8ad7e6f', 1, 1, 'ከዚህም በኋላ ሙሴና አሮን ወደ ፈርዖን ገብተው እንዲህ አሉት፥ “የእስራኤል አምላክ እግዚአብሔር እንዲህ ይላል፦ ‘በምድረ በዳ በዓል ያደርግልኝ ዘንድ ሕዝቤን ልቀቅ።’ ”'),
  ('3d219f4e-453e-5a57-a527-c1fd9809eee6', '52fb8e83-761d-53e3-a278-6bed5f5ccb01', '03a43287-f2fe-5030-a31b-990cf8ad7e6f', 2, 2, 'ፈርዖንም፥ “የእስራኤልን ልጆች እለቅቅ ዘንድ ቃሉን የምሰማው እርሱ እግዚአብሔር ማን ነው? እግዚአብሔርን አላውቅም፤ እስራኤልንም ደግሞ አልለቅቅም” አለ።'),
  ('331b06af-8ca2-5be6-ab53-8ea8e13f926d', '52fb8e83-761d-53e3-a278-6bed5f5ccb01', '03a43287-f2fe-5030-a31b-990cf8ad7e6f', 3, 3, 'እነርሱም፥ “ቸነፈር ወይም ሰይፍ እንዳይጥልብን የሦስት ቀን መንገድ በምድረ በዳ እንድንሄድ፥ ለአምላካችን ለእግዚአብሔር እንድንሠዋ የዕብራውያን አምላክ ጠራን” አሉት።'),
  ('38368b73-4d0c-5aef-a2d1-f92d42665ae9', '52fb8e83-761d-53e3-a278-6bed5f5ccb01', '03a43287-f2fe-5030-a31b-990cf8ad7e6f', 4, 4, 'የግብፅ ንጉሥም፥ “እናንተ ሙሴና አሮን፥ ሕዝቡን ለምን ሥራቸዉን ታስተዋላችሁ? ወደ ተግባራችሁ ሂዱ” አላቸው።'),
  ('9d9ddb15-c77b-5c7a-a9d9-9ad08a63c264', '52fb8e83-761d-53e3-a278-6bed5f5ccb01', '03a43287-f2fe-5030-a31b-990cf8ad7e6f', 5, 5, 'ፈርዖንም ለሕዝቡ አለ፥ “እነሆ፥ ሕዝቡ በምድር በጣም በዝተዋል፤ እናንተም ከሥራቸው አሳርፋችኋቸዋል።'),
  ('94f7975f-0286-551c-aa47-f28f0feb0e91', '52fb8e83-761d-53e3-a278-6bed5f5ccb01', '03a43287-f2fe-5030-a31b-990cf8ad7e6f', 6, 6, 'ፈርዖንም በዚያ ቀን የሕዝቡን አሠሪዎችና ጸሓፊዎች እንዲህ ሲል አዘዘ፦'),
  ('b24772ff-c835-5b86-ac4f-2cf5100222bb', '52fb8e83-761d-53e3-a278-6bed5f5ccb01', '03a43287-f2fe-5030-a31b-990cf8ad7e6f', 7, 7, '“እንደ ወትሮው ለጡብ ሥራ ደግሞ ገለባ ለሕዝቡ አትስጡ፤ ነገር ግን እነርሱ ሄደው ለራሳቸው ገለባ ይሰብስቡ።'),
  ('ca4828a6-9bb7-51f4-a09b-963f8d8588bb', '52fb8e83-761d-53e3-a278-6bed5f5ccb01', '03a43287-f2fe-5030-a31b-990cf8ad7e6f', 8, 8, 'ቀድሞ ያደርጉት የነበረውን የጡብ ቍጥር እንዲሁ በየቀኑ በእነርሱ ላይ አድርጉት፤ ምንም ከእርሱ አታጕድሉ፤ ሥራ ሰልችተዋልና ስለዚህ፦ ‘ለአምላካችን እንድንሠዋ እንሂድ’ እያሉ ይጮሃሉ።'),
  ('727b243b-9bb6-5c6b-a887-dc91080a1469', '52fb8e83-761d-53e3-a278-6bed5f5ccb01', '03a43287-f2fe-5030-a31b-990cf8ad7e6f', 9, 9, 'በእነዚህ ሰዎች ላይ ሥራው ይክበድባቸው፤ ይህን ብቻ ያስባሉ፤ ከንቱ ቃልም አያስቡም።”'),
  ('f0a30a29-4bd3-50d0-a076-818332cd8995', '52fb8e83-761d-53e3-a278-6bed5f5ccb01', '03a43287-f2fe-5030-a31b-990cf8ad7e6f', 10, 10, 'የሕዝቡም አሠሪዎችና ጸሓፊዎች ወጡ፤ ሕዝቡንም፥ “ፈርዖን እንዲህ ይላል፦ እንግዲህ ገለባ አይሰጣችሁም፤'),
  ('a5039872-0877-581c-a1e4-df3d07e501f8', '52fb8e83-761d-53e3-a278-6bed5f5ccb01', '03a43287-f2fe-5030-a31b-990cf8ad7e6f', 11, 11, 'እናንተ ሂዱ፤ ከምታገኙበትም ስፍራ ገለባ ሰብስቡ፤ ከምትሠሩት ጡብ ግን ምንም አይጐድልም” አሉአቸው።'),
  ('b11f5542-b743-5644-aeb2-09cd8a1f994a', '52fb8e83-761d-53e3-a278-6bed5f5ccb01', '03a43287-f2fe-5030-a31b-990cf8ad7e6f', 12, 12, 'ሕዝቡም ሁሉ ስለ ገለባ እብቅ ሊሰበስቡ በግብፅ ምድር ሁሉ ተበተኑ።'),
  ('f1f4b7c0-2645-5d70-ad2e-bfaa78171469', '52fb8e83-761d-53e3-a278-6bed5f5ccb01', '03a43287-f2fe-5030-a31b-990cf8ad7e6f', 13, 13, 'አሠሪዎቹም፥ “ገለባ ትቀበሉበት እንደነበረ ጊዜ የቀን ሥራችሁን ጨርሱ” እያሉ ያስቸኩሉአቸው ነበር።'),
  ('b244da66-0628-52b8-a656-11a85db01146', '52fb8e83-761d-53e3-a278-6bed5f5ccb01', '03a43287-f2fe-5030-a31b-990cf8ad7e6f', 14, 14, 'የፈርዖንም ሹሞች፥ “ቀድሞ ታደርጉት እንደ ነበራችሁ እንደ ትናንትናውና እንደ ትናንትና በስቲያው የተቈጠረውን ጡብ ዛሬስ ስለምን አትጨርሱም?” እያሉ በእስራኤል ልጆች ላይ የተሾሙትን አለቆች ይገርፉ ነበር።'),
  ('5a3c2d6e-0bf2-53a1-adb9-0d0a55d5bd95', '52fb8e83-761d-53e3-a278-6bed5f5ccb01', '03a43287-f2fe-5030-a31b-990cf8ad7e6f', 15, 15, 'የእስራኤል ልጆች አለቆችም ወደ ፈርዖን ገቡ፥ “ለምን በአገልጋዮችህ እንዲህ ታደርጋለህ? ገለባ አይሰጡአቸውም፤ ጡቡንም ሥሩ ይሉአቸዋል፤'),
  ('c9cdbd16-6bc9-589f-aaa5-1d3dab0f433a', '52fb8e83-761d-53e3-a278-6bed5f5ccb01', '03a43287-f2fe-5030-a31b-990cf8ad7e6f', 16, 16, 'እነሆም፥ አገልጋዮችህ ይገረፋሉ፤ ይገፋሉም፤ ግፉም በአንተ ሕዝብ ላይ ነው” ብለው ጮኹ።'),
  ('a74f40cf-ef94-53a9-ad94-8de78d110a84', '52fb8e83-761d-53e3-a278-6bed5f5ccb01', '03a43287-f2fe-5030-a31b-990cf8ad7e6f', 17, 17, 'እርሱ ግን፥ “እናንተ አርፋችኋል፤ ቦዝናችኋል፤ ስለዚህም፦ ‘እንሂድ ለእግዚአብሔርም እንሠዋ’ ትላላችሁ።'),
  ('2895c856-de0b-5c9b-ade6-d1438e1ed2b5', '52fb8e83-761d-53e3-a278-6bed5f5ccb01', '03a43287-f2fe-5030-a31b-990cf8ad7e6f', 18, 18, 'አሁንም ሂዱ፤ ሥሩ፤ ገለባም አይሰጡአችሁም፤ የጡቡን ቍጥር ግን ታመጣላችሁ” አላቸው።'),
  ('3a4b636e-bc49-52e7-a741-fddaacece125', '52fb8e83-761d-53e3-a278-6bed5f5ccb01', '03a43287-f2fe-5030-a31b-990cf8ad7e6f', 19, 19, 'የእስራኤልም ልጆች አለቆች ዕለት ዕለት ከምትሠሩት ከጡቡ ቍጥር ምንም አታጕድሉ ባሉአቸው ጊዜ ነገሩ እንደ ከፋባቸው አዩ።'),
  ('567f52f5-c122-5135-ac96-b7295835541c', '52fb8e83-761d-53e3-a278-6bed5f5ccb01', '03a43287-f2fe-5030-a31b-990cf8ad7e6f', 20, 20, 'ከፈርዖንም ዘንድ ሲወጡ ሙሴንና አሮንን በፊታቸው ቆመው ተገናኙአቸው።'),
  ('f16980da-1c19-5f09-af2b-2711aef62df9', '52fb8e83-761d-53e3-a278-6bed5f5ccb01', '03a43287-f2fe-5030-a31b-990cf8ad7e6f', 21, 21, 'እነርሱም፥ “በፈርዖንና በሹሞቹ ፊት ሽታችንን አግምታችሁታልና፥ ይገድለንም ዘንድ ሰይፍን በእጁ ሰጥታችሁታልና እግዚአብሔር ይመልከታችሁ፤ ይፍረድባችሁም” አሉአቸው።'),
  ('911795fc-5cc5-5d9e-a655-9a4d88b34acf', '52fb8e83-761d-53e3-a278-6bed5f5ccb01', '9d416de1-9fcf-5afa-a007-20d5a7b8a7f2', 1, 22, 'ሙሴም ወደ እግዚአብሔር ተመለሰና፥ “ጌታ ሆይ፥ ስለምን ይህን ሕዝብ አስከፋህ? ስለ ምንስ ላክኸኝ?'),
  ('50c6fe66-b90d-5870-a0d5-cc7b601e422d', '52fb8e83-761d-53e3-a278-6bed5f5ccb01', '9d416de1-9fcf-5afa-a007-20d5a7b8a7f2', 2, 23, 'በስምህ እናገር ዘንድ ወደ ፈርዖን ከገባሁ ወዲህ፥ ይህን ሕዝብ አስከፍቶታልና፤ አንተም ሕዝብህን ከቶ አላዳንኸውም” አለ።'),
  ('63ca8a92-0ddd-524b-a3cf-f348c11cc618', '34e1a0d5-ffed-57c1-aead-0edb790902be', 'daf9c0ef-bab4-5c9a-a44b-45d6e7e7504a', 1, 1, 'እግዚአብሔርም ሙሴን አለው፥ “በጸናች እጅ ይለቅቃቸዋልና፥ በተዘረጋችም ክንድ ከምድሩ አስወጥቶ ይሰድዳቸዋልና አሁን በፈርዖን የማደርገውን ታያለህ።”'),
  ('94ac625a-ca0e-5519-a0a0-047cb855f0e1', '34e1a0d5-ffed-57c1-aead-0edb790902be', 'daf9c0ef-bab4-5c9a-a44b-45d6e7e7504a', 2, 2, 'እግዚአብሔርም ሙሴን ተናገረው አለውም፥ “እኔ እግዚአብሔር ነኝ።'),
  ('f075820d-4c69-5beb-a384-586801f15718', '34e1a0d5-ffed-57c1-aead-0edb790902be', 'daf9c0ef-bab4-5c9a-a44b-45d6e7e7504a', 3, 3, 'ለአብርሃምም፥ ለይስሐቅም፥ ለያዕቆብም ሁሉን እንደሚችል አምላክ ተገለጥሁ፤ ነገር ግን ስሜ እግዚአብሔር አልታወቀላቸውም ነበር።'),
  ('4aec1a62-b211-5dd5-a123-ccf5ec8cf8be', '34e1a0d5-ffed-57c1-aead-0edb790902be', 'daf9c0ef-bab4-5c9a-a44b-45d6e7e7504a', 4, 4, 'የነበሩባትንም የከነዓንን ምድር እሰጣቸው ዘንድ ከእነርሱ ጋር ቃል ኪዳኔን አቆምሁ።'),
  ('09ffe005-d906-520a-aac0-40ab9fa57f05', '34e1a0d5-ffed-57c1-aead-0edb790902be', 'daf9c0ef-bab4-5c9a-a44b-45d6e7e7504a', 5, 5, 'ደግሞ እኔ ግብፃውያን የገዙአቸውን የእስራኤልን ልጆች ልቅሶ ሰማሁ፤ ቃል ኪዳኔንም አሰብሁ።”'),
  ('5471b6ad-e032-527f-a866-a4430271b51f', '34e1a0d5-ffed-57c1-aead-0edb790902be', 'daf9c0ef-bab4-5c9a-a44b-45d6e7e7504a', 6, 6, 'ስለዚህም ፈጥነህ ለእስራኤል ልጆች እንዲህ በላቸው፥ “እኔ እግዚአብሔር ነኝ፤ ከግብፃውያንም ተገዥነት አወጣችኋለሁ፤ ከባርነታቸውም አድናችኋለሁ፤ በተዘረጋ ክንድ፤ በታላቅ ፍርድም እታደጋችኋለሁ፤'),
  ('800f81d5-0150-52b5-a5c0-e294ebd6881c', '34e1a0d5-ffed-57c1-aead-0edb790902be', 'daf9c0ef-bab4-5c9a-a44b-45d6e7e7504a', 7, 7, 'ለእኔም ሕዝብ እንድትሆኑ እቀበላችኋለሁ፤ አምላክም እሆናችኋለሁ፤ እኔም ከግብፃውያን ባርነት ያወጣኋችሁ እግዚአብሔር አምላካችሁ እንደ ሆንሁ ታውቃላችሁ።'),
  ('f6d47e5a-55b1-5fb5-a9e8-bc8307a3898c', '34e1a0d5-ffed-57c1-aead-0edb790902be', 'daf9c0ef-bab4-5c9a-a44b-45d6e7e7504a', 8, 8, 'ለአብርሃምና ለይስሐቅ፥ ለያዕቆብም እሰጣት ዘንድ እጄን ወደ ዘረጋሁባት ምድር አገባችኋለሁ፤ እርስዋንም ርስት አድርጌ እሰጣችኋለሁ፤ እኔ እግዚአብሔር ነኝ።”'),
  ('7bca42ca-494e-5df2-a1ea-d1bdfe36e8d7', '34e1a0d5-ffed-57c1-aead-0edb790902be', 'daf9c0ef-bab4-5c9a-a44b-45d6e7e7504a', 9, 9, 'ሙሴም ይህን ለእስራኤል ልጆች ተናገረ፤ እነርሱ ግን ከሰውነታቸው መጨነቅ፥ ከሥራቸውም ክብደት የተነሣ ቃሉን አልሰሙትም።'),
  ('07e8546e-0f0a-5862-a00c-a9611601b1fd', '34e1a0d5-ffed-57c1-aead-0edb790902be', 'daf9c0ef-bab4-5c9a-a44b-45d6e7e7504a', 10, 10, 'እግዚአብሔርም ሙሴን እንዲህ ብሎ ተናገረው፦'),
  ('1ed25a2a-dd28-5ed1-a738-644db41de011', '34e1a0d5-ffed-57c1-aead-0edb790902be', 'daf9c0ef-bab4-5c9a-a44b-45d6e7e7504a', 11, 11, '“ግባ፤ የእስራኤልን ልጆች ከሀገሩ ይለቅቅ ዘንድ ለግብፅ ንጉሥ ለፈርዖን ንገረው።”'),
  ('0c9544f7-5425-59f4-ae7b-a750ceaafb7a', '34e1a0d5-ffed-57c1-aead-0edb790902be', 'daf9c0ef-bab4-5c9a-a44b-45d6e7e7504a', 12, 12, 'ሙሴም በእግዚአብሔር ፊት፥ “እነሆ፥ የእስራኤል ልጆች አልሰሙኝም፤ እንዴትስ ፈርዖን ይሰማኛል? እኔም አንደበተ ርቱዕ አይደለሁም” ብሎ ተናገረ።'),
  ('3ea13119-9d29-5d4e-a418-c23d550691e1', '34e1a0d5-ffed-57c1-aead-0edb790902be', 'daf9c0ef-bab4-5c9a-a44b-45d6e7e7504a', 13, 13, 'እግዚአብሔርም ሙሴንና አሮንን ተናገራቸው፤ የግብፅ ንጉሥ ፈርዖንም የእስራኤልን ልጆች ከግብፅ እንዲያወጣቸው ይነግሩት ዘንድ አዘዛቸው።'),
  ('95ea1f69-0538-5e7e-a6b0-8ea380d60df8', '34e1a0d5-ffed-57c1-aead-0edb790902be', '4a0c0839-4ca5-5329-afa4-01de8409a450', 1, 14, 'የአባቶቻቸውም ቤት አለቆች እነዚህ ናቸው። የእስራኤል የበኵር ልጅ የሮቤል ልጆች ሄኖኅ፥ ፍሉስ፥ አስሮን፥ ከርሚ፤ እነዚህ የሮቤል ትውልድ ናቸው።'),
  ('2dcb1f54-2ce5-5117-a0b7-546b04525689', '34e1a0d5-ffed-57c1-aead-0edb790902be', '4a0c0839-4ca5-5329-afa4-01de8409a450', 2, 15, 'የስምዖንም ልጆች፤ ይሙኤል፥ ያሚን፥ አኡድ፥ ያኪን፥ ሱሐር፥ የፊኒቃዊቱም ልጅ ሳኡል፤ እነዚህ የስምዖን ትውልድ ናቸው።'),
  ('f28e5f3b-6cd3-5ad6-a9d0-ff6fe54575f0', '34e1a0d5-ffed-57c1-aead-0edb790902be', '4a0c0839-4ca5-5329-afa4-01de8409a450', 3, 16, 'እነዚህም እንደ ወገኖቻቸው የሌዊ ልጆች ስሞች ናቸው፤ ጌድሶን፥ ቀዓት፥ ሜራሪ ናቸው። የሌዊም የሕይወት ዘመን መቶ ሠላሳ ሰባት ዓመት ነው።'),
  ('8160c570-9a3c-5694-a610-ea92e9d4af0c', '34e1a0d5-ffed-57c1-aead-0edb790902be', '4a0c0839-4ca5-5329-afa4-01de8409a450', 4, 17, 'የጌድሶንም ልጆች በየአባታቸው ወገን ሎቤኒ፥ ሰሜኢ ናቸው።'),
  ('23adbe65-eab0-58c6-af20-ab2827d0dc84', '34e1a0d5-ffed-57c1-aead-0edb790902be', '4a0c0839-4ca5-5329-afa4-01de8409a450', 5, 18, 'የቀዓትም ልጆች እንበረም፥ ይስዓር፥ ኬብሮን፥ ዑዝኤል ናቸው፤ የቀዓትም የሕይወቱ ዘመን መቶ ሠላሳ ሦስት ዓመት ነው።'),
  ('a97259e3-fb87-512d-a38d-10a15f330a76', '34e1a0d5-ffed-57c1-aead-0edb790902be', '4a0c0839-4ca5-5329-afa4-01de8409a450', 6, 19, 'የሜራሪ ልጆች ሞሖሊ፥ ሐሙሲ ናቸው። እነዚህም እንደ ትውልዳቸው የሌዊ ትውልድ ናቸው።'),
  ('c0c8592d-29f2-58fd-a335-c03ffbe334ec', '34e1a0d5-ffed-57c1-aead-0edb790902be', '4a0c0839-4ca5-5329-afa4-01de8409a450', 7, 20, 'እንበረምም የአባቱን ወንድም ልጅ ዮካብድን አገባ፤ አሮንንና ሙሴን፥ እኅታቸውንም ማርያምን ወለደችለት፤ የእንበረምም የሕይወቱ ዘመን መቶ ሠላሳ ሰባት ዓመት ነው።'),
  ('ec5273ec-7bc5-5fe2-a322-c8fe82a3c16a', '34e1a0d5-ffed-57c1-aead-0edb790902be', '4a0c0839-4ca5-5329-afa4-01de8409a450', 8, 21, 'የይስዓርም ልጆች ቆሬ፥ ናፌግ፥ ዝክሪ ናቸው።'),
  ('65fdd362-2b4c-5637-a1ae-d49f1cfe2307', '34e1a0d5-ffed-57c1-aead-0edb790902be', '4a0c0839-4ca5-5329-afa4-01de8409a450', 9, 22, 'የዑዝኤልም ልጆች ሚሳኤል፥ ኤልሳፋን፥ ሴትሪ ናቸው።'),
  ('0ab40f57-8055-5e29-aa17-934707c07876', '34e1a0d5-ffed-57c1-aead-0edb790902be', '4a0c0839-4ca5-5329-afa4-01de8409a450', 10, 23, 'አሮንም የአሚናዳብን ልጅ የነአሶንን እኅት ኤልሳቤጥን አገባ። እርስዋም ናዳብንና አብዩድን፥ አልዓዛርንና ኢታምርን ወለደችለት።'),
  ('6d54080d-e80e-5807-a664-bc4a443dabf7', '34e1a0d5-ffed-57c1-aead-0edb790902be', '4a0c0839-4ca5-5329-afa4-01de8409a450', 11, 24, 'የቆሬ ልጆች አሴር፥ ሕልቃና፥ አብያሳፍ ናቸው፤ እነዚህ የቆሬ ልጆች ትውልድ ናቸው።'),
  ('22a27363-2322-5a6a-a66c-6705aa2a7998', '34e1a0d5-ffed-57c1-aead-0edb790902be', '4a0c0839-4ca5-5329-afa4-01de8409a450', 12, 25, 'የአሮንም ልጅ አልዓዛር ከፋትኤል ልጆች ሚስትን አገባ፤ እርስዋም ፊንሐስን ወለደችለት። እነዚህም በየወገኖቻቸው የሌዋውያን አባቶች አለቆች ናቸው።'),
  ('f65e8695-7f55-5df2-afd3-599a6d835e7c', '34e1a0d5-ffed-57c1-aead-0edb790902be', '4a0c0839-4ca5-5329-afa4-01de8409a450', 13, 26, 'እነዚህ አሮንና ሙሴ እግዚአብሔር፥ “ከግብፅ ምድር ከሠራዊቶቻቸው ጋር የእስራኤልን ልጆች አውጡ” ያላቸው ናቸው።'),
  ('413fedd8-fdd7-5e7e-a109-6719668e040a', '34e1a0d5-ffed-57c1-aead-0edb790902be', '4a0c0839-4ca5-5329-afa4-01de8409a450', 14, 27, 'እነዚህ የእስራኤልን ልጆች ከግብፅ ያወጡ ዘንድ ከግብፅ ንጉሥ ከፈርዖን ጋር የተነጋገሩ ናቸው፤ እነዚህም ሙሴና አሮን ናቸው።'),
  ('fe32db3b-a1f9-5f61-a108-3f2d6ef9cc12', '34e1a0d5-ffed-57c1-aead-0edb790902be', 'e147dd0c-7acc-504c-ae7c-dd37e15c88ae', 1, 28, 'እግዚአብሔርም በግብፅ ሀገር ሙሴን በተናገረው ቀን እንዲህ ሆነ፤'),
  ('8be1412f-55a7-5e25-a92e-47dd36d2c124', '34e1a0d5-ffed-57c1-aead-0edb790902be', 'e147dd0c-7acc-504c-ae7c-dd37e15c88ae', 2, 29, 'እግዚአብሔር ሙሴን፥ “እኔ እግዚአብሔር ነኝ፤ እኔ የምነግርህን ሁሉ ለግብፅ ንጉሥ ለፈርዖን ንገር” ብሎ ተናገረው።'),
  ('d133eb8e-a736-5f37-a782-46579fe365d6', '34e1a0d5-ffed-57c1-aead-0edb790902be', 'e147dd0c-7acc-504c-ae7c-dd37e15c88ae', 3, 30, 'ሙሴም በእግዚአብሔር ፊት፥ “እነሆ፥ እኔ አንደበተ ርቱዕ አይደለሁም፤ እንዴትስ ፈርዖን ይሰማኛል?” አለ።'),
  ('cd7ff576-2951-5f18-aa78-69295e3bea0a', 'ca84ce93-46cd-591c-a7ee-ce55e5d43762', '5b78a624-5867-56af-a701-9bec45d506e2', 1, 1, 'እግዚአብሔርም ሙሴን አለው፥ “እነሆ፥ እኔ ለፈርዖን አምላክ አድርጌሃለሁ፤ ወንድምህም አሮን ነቢይ ይሆንልሃል።'),
  ('6ea1c484-5d1f-529d-af0e-0d1cc3d07722', 'ca84ce93-46cd-591c-a7ee-ce55e5d43762', '5b78a624-5867-56af-a701-9bec45d506e2', 2, 2, 'ያዘዝሁህን ነገር ሁሉ አንተ ትነግረዋለህ፤ ወንድምህም አሮን የእስራኤልን ልጆች ከሀገሩ ይለቅቅ ዘንድ ለፈርዖን ይንገረው።'),
  ('214bc7c4-02db-55b8-a5b7-21899a1f7863', 'ca84ce93-46cd-591c-a7ee-ce55e5d43762', '5b78a624-5867-56af-a701-9bec45d506e2', 3, 3, 'እኔም የፈርዖንን ልብ አጸናለሁ፤ በግብፅ ምድርም ድንቄንና ተአምራቴን አበዛለሁ።'),
  ('b54cdd20-26e3-5bc2-a770-c9571b14ee74', 'ca84ce93-46cd-591c-a7ee-ce55e5d43762', '5b78a624-5867-56af-a701-9bec45d506e2', 4, 4, 'ፈርዖንም አይሰማችሁም፤ እጄንም በግብፅ ላይ አደርጋለሁ፤ የእስራኤልንም ልጆች ሕዝቤን በኀይሌ በታላቅ ፍርድ ከግብፅ ሀገር አወጣለሁ።'),
  ('6440d67a-c912-5b1b-a8bc-686fbdc10a96', 'ca84ce93-46cd-591c-a7ee-ce55e5d43762', '5b78a624-5867-56af-a701-9bec45d506e2', 5, 5, 'ግብፃውያንም እጄን በግብፅ ላይ በዘረጋሁ ጊዜ፥ የእስራኤልንም ልጆች ከመካከላቸው በአወጣሁ ጊዜ፥ እኔ እግዚአብሔር እንደ ሆንሁ ያውቃሉ።”'),
  ('00190aed-81c5-5953-a595-9a0f7edfea5d', 'ca84ce93-46cd-591c-a7ee-ce55e5d43762', '5b78a624-5867-56af-a701-9bec45d506e2', 6, 6, 'ሙሴና አሮንም እንዲህ አደረጉ፤ እግዚአብሔር እንዳዘዛቸው አደረጉ።'),
  ('c6be3d2b-bab5-5a4b-ae17-50c41f255450', 'ca84ce93-46cd-591c-a7ee-ce55e5d43762', '5b78a624-5867-56af-a701-9bec45d506e2', 7, 7, 'ፈርዖንንም በተናገሩት ጊዜ ሙሴ ሰማንያ ዓመት ሆኖት ነበር፤ አሮንም ሰማንያ ሦስት ዓመት ሆኖት ነበረ።'),
  ('4c3e6e7b-a64f-57df-a097-9291ec96da88', 'ca84ce93-46cd-591c-a7ee-ce55e5d43762', '15d828b0-6bc2-584a-a2c3-6b63511679e5', 1, 8, 'እግዚአብሔርም ሙሴንና አሮንን እንዲህ ሲል ተናገራቸው፦'),
  ('c9161964-de48-5e1f-aa57-441e0ec526be', 'ca84ce93-46cd-591c-a7ee-ce55e5d43762', '15d828b0-6bc2-584a-a2c3-6b63511679e5', 2, 9, '“ፈርዖን፦ ተአምራትንና ድንቅን አሳዩኝ ሲላችሁ፥ ወንድምህ አሮንን፦ ‘በትርህን ወስደህ በፈርዖንና በሹሞቹ ፊት ጣላት’ በለው፤ እባብም ትሆናለች።”'),
  ('39faa3bd-b9d0-51b3-ac7c-41e29454d97a', 'ca84ce93-46cd-591c-a7ee-ce55e5d43762', '15d828b0-6bc2-584a-a2c3-6b63511679e5', 3, 10, 'ሙሴና አሮንም ወደ ፈርዖን ገቡ፤ እግዚአብሔርም እንዳዘዛቸው እንዲሁ አደረጉ፤ አሮንም በትሩን በፈርዖንና በሹሞቹ ፊት ጣለ፤ እባብም ሆነች።'),
  ('96c1fb8c-ca1c-5892-a22a-b0a966f3c1ac', 'ca84ce93-46cd-591c-a7ee-ce55e5d43762', '15d828b0-6bc2-584a-a2c3-6b63511679e5', 4, 11, 'ፈርዖንም ጠቢባንንና መተተኞችን ጠራ፤ የግብፅም ጠንቋዮች በአስማታቸው እንዲሁ ደግሞ አደረጉ።'),
  ('43de9d6d-29d8-5860-af5f-3985a076cca4', 'ca84ce93-46cd-591c-a7ee-ce55e5d43762', '15d828b0-6bc2-584a-a2c3-6b63511679e5', 5, 12, 'እያንዳንዳቸውም በትራቸውን ጣሉ፤ እባቦችም ሆኑ፤ የአሮን በትር ግን በትራቸውን ዋጠች።'),
  ('84517813-f028-58e2-a204-017655e78025', 'ca84ce93-46cd-591c-a7ee-ce55e5d43762', '15d828b0-6bc2-584a-a2c3-6b63511679e5', 6, 13, 'እግዚአብሔርም እንደ ተናገረ፥ የፈርዖን ልብ ጸና፤ መስማትንም እንቢ አለ።'),
  ('101a8f13-8870-512b-a48f-ee5e14d8f299', 'ca84ce93-46cd-591c-a7ee-ce55e5d43762', '1a647757-1633-5c50-a29c-b876af0f88b9', 1, 14, 'እግዚአብሔርም ሙሴን አለው፥ “ሕዝቡን እንዳይለቅቅ የፈርዖን ልብ ደነደነ።'),
  ('831adaf1-79bd-52c2-a931-3469f276fc73', 'ca84ce93-46cd-591c-a7ee-ce55e5d43762', '1a647757-1633-5c50-a29c-b876af0f88b9', 2, 15, 'ማልደህ ወደ ፈርዖን ሂድ፤ እነሆ፥ ወደ ውኃ ይወጣል፤ ትገናኘውም ዘንድ አንተ በወንዝ ዳር ትቆማለህ፤ እባብም ሆና የተለወጠችዉን በትር በእጅህ ትወስዳለህ።'),
  ('ac08a7c8-d222-5db9-a326-6f0c27c22fb1', 'ca84ce93-46cd-591c-a7ee-ce55e5d43762', '1a647757-1633-5c50-a29c-b876af0f88b9', 3, 16, 'እንዲህም ትለዋለህ፦ ‘የዕብራውያን አምላክ እግዚአብሔር፦ በምድረ በዳ እንዲያመልኩኝ ሕዝቤን ልቀቅ’ ብሎ ወደ አንተ ላከኝ፤ እነሆም፥ እስከ ዛሬ አልሰማህም።'),
  ('1beece96-85f6-57bc-a1f5-fc4f649afb40', 'ca84ce93-46cd-591c-a7ee-ce55e5d43762', '1a647757-1633-5c50-a29c-b876af0f88b9', 4, 17, 'እግዚአብሔር እንዲህ ይላል፦ እኔ እግዚአብሔር እንደ ሆንሁ በዚህ ታውቃለህ፤ እነሆ፥ እኔ የወንዙን ውኃ በእጄ ባለችው በትር እመታለሁ፤ ውኃውም ወደ ደም ይለወጣል።'),
  ('30ca9a05-b6ff-5db7-a9fe-ad956661b01b', 'ca84ce93-46cd-591c-a7ee-ce55e5d43762', '1a647757-1633-5c50-a29c-b876af0f88b9', 5, 18, 'በወንዙም ያሉት ዓሦች ይሞታሉ፤ ወንዙም ይገማል፤ ግብፃውያንም የወንዙን ውኃ ለመጠጣት አይችሉም።”'),
  ('be9f9364-2c74-541c-aa13-b4d3876e4b94', 'ca84ce93-46cd-591c-a7ee-ce55e5d43762', '1a647757-1633-5c50-a29c-b876af0f88b9', 6, 19, 'እግዚአብሔርም ሙሴን አለው፥ “ወንድምህ አሮንን፦ ‘በትርህን ውሰድ፤ በግብፅ ውኆች፥ በወንዞቻቸው፥ በመስኖዎቻቸውም፥ በኩሬዎቻቸውም፥ በውኃ ማከማቻቸውም ሁሉ ላይ እጅህን ዘርጋ’ በለው፤ ደምም ይሆናል፤” በግብፅም ሀገር ሁሉ በዕንጨት ዕቃና በድንጋይ ዕቃ ሁሉ ደም ሆነ።'),
  ('a6a7e090-ee60-5518-a91f-668457be73b4', 'ca84ce93-46cd-591c-a7ee-ce55e5d43762', '1a647757-1633-5c50-a29c-b876af0f88b9', 7, 20, 'ሙሴና አሮንም እግዚአብሔር እንዳዘዛቸው እንዲሁ አደረጉ፤ አሮንም በትሩን አነሣ፤ በፈርዖንና በሹሞቹ ፊት የወንዙን ውኃ መታ፤ የወንዙም ውኃ ሁሉ ተለውጦ ደም ሆነ።'),
  ('dfa60884-029b-5f83-a1cd-a3b507e9b0c0', 'ca84ce93-46cd-591c-a7ee-ce55e5d43762', '1a647757-1633-5c50-a29c-b876af0f88b9', 8, 21, 'በወንዙም የነበሩ ዓሦች ሞቱ፤ ወንዙም ገማ፤ ግብፃውያንም ከወንዙ ውኃ ይጠጡ ዘንድ አልቻሉም፤ ደሙም በግብፅ ሀገር ሁሉ ሆነ።'),
  ('c178c467-d304-54d4-a480-b15b32118b48', 'ca84ce93-46cd-591c-a7ee-ce55e5d43762', '1a647757-1633-5c50-a29c-b876af0f88b9', 9, 22, 'የግብፅም ጠንቋዮች በአስማታቸው እንዲሁ አደረጉ፤ እግዚአብሔርም እንደ ተናገረ የፈርዖን ልብ ጸና፤ አልሰማቸውምም።'),
  ('936dc67f-fc9e-525d-a32d-fa441f609f84', 'ca84ce93-46cd-591c-a7ee-ce55e5d43762', '1a647757-1633-5c50-a29c-b876af0f88b9', 10, 23, 'ፈርዖንም ተመልሶ ወደ ቤቱ ገባ፤ በዚህም ሁሉ ልቡ አልተመለሰም።'),
  ('aafa4667-af76-530e-abee-79adf1758247', 'ca84ce93-46cd-591c-a7ee-ce55e5d43762', '1a647757-1633-5c50-a29c-b876af0f88b9', 11, 24, 'ግብፃውያንም ሁሉ ከወንዙ ውኃ ይጠጡ ዘንድ አልቻሉምና በወንዙ ዳር ውኃ ሊጠጡ ቈፈሩ።'),
  ('d0bd1161-f1e0-5a3c-aa03-303a01d1490b', 'ca84ce93-46cd-591c-a7ee-ce55e5d43762', '1a647757-1633-5c50-a29c-b876af0f88b9', 12, 25, 'እግዚአብሔርም ወንዙን ከመታ በኋላ ሰባት ቀን ተፈጸመ።'),
  ('f68ecda3-d475-53e5-ab30-3d9e48d86205', '14409c91-88ad-5251-ae5e-a16d058c8b93', '36973644-10da-5d13-a8f1-c75ef818c6c7', 1, 1, 'እግዚአብሔርም ሙሴን አለው፥ “ወደ ፈርዖን ግባ፤ እንዲህም በለው፦ እግዚአብሔር እንዲህ ይላል፦ ያመልኩኝ ዘንድ ሕዝቤን ልቀቅ።'),
  ('2c5f3b3c-46df-5e9d-a8f6-97f119085891', '14409c91-88ad-5251-ae5e-a16d058c8b93', '36973644-10da-5d13-a8f1-c75ef818c6c7', 2, 2, 'ለመልቀቅ እንቢ ብትል ግን እነሆ፥ ሀገርህን ሁሉ በጓጕንቸሮች እመታለሁ፤'),
  ('3d246018-9a65-5497-adb5-2969879832e4', '14409c91-88ad-5251-ae5e-a16d058c8b93', '36973644-10da-5d13-a8f1-c75ef818c6c7', 3, 3, 'ወንዙም ጓጕንቸሮችን ያፈላል፤ ወጥተውም ወደ ቤትህ፥ ወደ መኝታ ቤትህ፥ ወደ አልጋህም፥ ወደ ሹሞችህም ቤት፥ በሕዝብህም ላይ፥ ወደ ቡሃቃዎችህም፥ ወደ ምድጃዎችህም ይገባሉ፤'),
  ('54be7024-6d16-52e5-a84f-8cfca95078a3', '14409c91-88ad-5251-ae5e-a16d058c8b93', '36973644-10da-5d13-a8f1-c75ef818c6c7', 4, 4, 'ጓጕንቸሮችም በአንተ፥ በሕዝብህም፥ በሹሞችህም ሁሉ ላይ ይወጣሉ።”'),
  ('9728e8b0-291f-58c2-a87f-ef4f23252541', '14409c91-88ad-5251-ae5e-a16d058c8b93', '36973644-10da-5d13-a8f1-c75ef818c6c7', 5, 5, 'እግዚአብሔርም ሙሴን አለው፥ “ወንድምህን አሮንን፦ ‘በትርህን ይዘህ በወንዞቹና በመስኖዎቹ፥ በውኃ ማከማቻዎቹም ላይ እጅህን ዘርጋ፤ ጓጕንቸሮችንም አውጣ’ ” በለው።'),
  ('a5db19f0-e17e-5ad9-a682-b27aacf35855', '14409c91-88ad-5251-ae5e-a16d058c8b93', '36973644-10da-5d13-a8f1-c75ef818c6c7', 6, 6, 'አሮንም በግብፅ ውኆች ላይ እጁን ዘረጋ፤ ጓጕንቸሮቹም ወጡ፤ የግብፅንም ሀገር ሸፈኑ።'),
  ('16bed06b-1909-59f9-acec-d3eb81d4ebcf', '14409c91-88ad-5251-ae5e-a16d058c8b93', '36973644-10da-5d13-a8f1-c75ef818c6c7', 7, 7, 'የግብፅ ጠንቋዮችም በአስማታቸው እንዲህ አደረጉ፤ በግብፅም ሀገር ላይ ጓጕንቸሮችን አወጡ።'),
  ('237281bd-b0cd-554d-a095-9f79f4f7b314', '14409c91-88ad-5251-ae5e-a16d058c8b93', '36973644-10da-5d13-a8f1-c75ef818c6c7', 8, 8, 'ፈርዖንም ሙሴንና አሮንን ጠርቶ፥ “ጓጕንቸሮቹን ከእኔ፥ ከሕዝቤም እንዲያርቅ ወደ እግዚአብሔር ጸልዩልኝ፤ ለእግዚአብሔርም ይሠዋ ዘንድ ሕዝቡን እለቅቃለሁ” አላቸው።'),
  ('92551a1a-479e-5a51-a0ca-64a436755dd3', '14409c91-88ad-5251-ae5e-a16d058c8b93', '36973644-10da-5d13-a8f1-c75ef818c6c7', 9, 9, 'ሙሴም ፈርዖንን፥ “ጓጕንቸሮቹ ከአንተ፥ ከሕዝብህም፥ ከቤቶችህም እንዲጠፉ፥ በወንዙም ብቻ እንዲቀሩ፥ ለአንተ፥ ለሹሞችህም፥ ለሕዝብህም መቼ እንድጸልይ ቅጠረኝ” አለው። ፈርዖንም፥ “ነገ” አለው።'),
  ('5e9886cf-a301-5ec1-a4c0-a8e91279e675', '14409c91-88ad-5251-ae5e-a16d058c8b93', '36973644-10da-5d13-a8f1-c75ef818c6c7', 10, 10, 'ሙሴም፥ “ከእግዚአብሔር በቀር ሌላ አምላክ እንደሌለ ታውቅ ዘንድ እሺ እንደ አልህ ይሁን።'),
  ('4c5747c1-1361-5e55-a9e9-00a47dae3eff', '14409c91-88ad-5251-ae5e-a16d058c8b93', '36973644-10da-5d13-a8f1-c75ef818c6c7', 11, 11, 'ጓጕንቸሮቹም ከአንተ፥ ከቤቶችህም፥ ከመንደሮችህም፥ ከሹሞችህም፥ ከሕዝብህም ይሄዳሉ፤ በወንዙም ብቻ ይቀራሉ” አለው።'),
  ('1a2e76d1-c612-54f4-a400-160d224401c8', '14409c91-88ad-5251-ae5e-a16d058c8b93', '36973644-10da-5d13-a8f1-c75ef818c6c7', 12, 12, 'ሙሴና አሮንም ከፈርዖን ዘንድ ወጡ፤ ሙሴም ፈርዖን እንደ ቀጠረው ሰለ ጓጕንቸሮቹ መራቅ ወደ እግዚአብሔር ጮኸ።'),
  ('6ac823a9-a70e-5a5e-a1fe-508a7686501a', '14409c91-88ad-5251-ae5e-a16d058c8b93', '36973644-10da-5d13-a8f1-c75ef818c6c7', 13, 13, 'እግዚአብሔርም ሙሴ እንደ አለ አደረገ፤ ጓጕንቸሮቹም ከቤት፥ ከመንደርም፥ ከሜዳም ሞቱ።'),
  ('a249f4d9-f387-5350-a56a-befeb6492bbb', '14409c91-88ad-5251-ae5e-a16d058c8b93', '36973644-10da-5d13-a8f1-c75ef818c6c7', 14, 14, 'እንደ ክምርም አድርገው ሰበሰቡአቸው፤ ምድርም ገማች።'),
  ('2a499037-02e8-50c9-abda-32a3e4527b95', '14409c91-88ad-5251-ae5e-a16d058c8b93', '36973644-10da-5d13-a8f1-c75ef818c6c7', 15, 15, 'ፈርዖንም ጸጥታ እንደ ሆነ በአየ ጊዜ ልቡ ደነደነ፤ እግዚአብሔርም እንደ ተናገረው አልሰማቸውም።'),
  ('72c3120a-dee4-529f-ab6a-6b3141b804ad', '14409c91-88ad-5251-ae5e-a16d058c8b93', '7be9f02b-36c0-5a19-a18e-5bf64ccb9f34', 1, 16, 'እግዚአብሔርም ሙሴን አለው፥ “አሮንን፦ ‘በትርህን በእጅህ ዘርጋ፤ የምድሩንም ትቢያ ምታ’ በለው፤ ቅማልም በግብፅ ሀገር ሁሉ በሰውና በእንስሳ ላይ ይወጣል።”'),
  ('d1f01c97-7b10-5b14-a116-223b72acc49e', '14409c91-88ad-5251-ae5e-a16d058c8b93', '7be9f02b-36c0-5a19-a18e-5bf64ccb9f34', 2, 17, 'አሮንም እጁን ዘረጋ፤ በበትሩም የምድሩን ትቢያ መታው፤ በሰውና በእንስሳም ላይ ቅማል ሆነ፤ በግብፅ ሀገር ሁሉ የምድር ትቢያ ሁሉ ቅማል ሆነ።'),
  ('5bd8adff-ec44-5380-a2a2-c1e1b6de2d2a', '14409c91-88ad-5251-ae5e-a16d058c8b93', '7be9f02b-36c0-5a19-a18e-5bf64ccb9f34', 3, 18, 'የግብፅ ጠንቋዮችም በአስማታቸው ቅማል ያወጡ ዘንድ እንዲሁ አደረጉ፤ ነገር ግን አልቻሉም፤ ቅማሉም በሰውና በእንስሳ ላይ ነበረ።'),
  ('5dc66be4-7113-5281-af36-e864fc2eba51', '14409c91-88ad-5251-ae5e-a16d058c8b93', '7be9f02b-36c0-5a19-a18e-5bf64ccb9f34', 4, 19, 'ጠንቋዮችም ፈርዖንን፥ “ይህስ የእግዚአብሔር ጣት ነው” አሉት፤ የፈርዖን ልብ ግን ጸና፤ እግዚአብሔርም እንደ ተናገረ አልሰማቸውም።'),
  ('1d6ba636-05c2-5f24-a223-57671c071f62', '14409c91-88ad-5251-ae5e-a16d058c8b93', '94a2562f-33cd-5806-a6cf-5cca43d99b0b', 1, 20, 'እግዚአብሔርም ሙሴን አለው፥ “ማልደህ ተነሣ፤ በፈርዖንም ፊት ቁም፤ እነሆ፥ እርሱ ወደ ውኃ ይወርዳል፤ እንዲህም በለው፦ እግዚአብሔር እንዲህ ይላል፦ በምድረ በዳ እንዲያመልኩኝ ሕዝቤን ልቀቅ።'),
  ('38051202-e59a-5b40-a18d-5fec5f08c6d6', '14409c91-88ad-5251-ae5e-a16d058c8b93', '94a2562f-33cd-5806-a6cf-5cca43d99b0b', 2, 21, 'ሕዝቤን ለመልቀቅ እንቢ ብትል ግን እነሆ፥ በአንተ፥ በሹሞችህም፥ በሕዝብህም፥ በቤቶችህም ላይ የውሻ ዝንብ እሰድዳለሁ፤ የግብፃውያን ቤቶች፥ የሚኖሩባትም ምድር ሁሉ በውሻ ዝንብ ይመላሉ።'),
  ('fdf1d1c7-c827-5c0b-a0a2-431c87b0a5a4', '14409c91-88ad-5251-ae5e-a16d058c8b93', '94a2562f-33cd-5806-a6cf-5cca43d99b0b', 3, 22, 'በዚያም ቀን የምድር ሁሉ አምላክ እኔ እግዚአብሔር እንደ ሆንሁ ታውቅ ዘንድ፥ በዚያ የውሻ ዝንብ እንዳይሆን ሕዝቤ የሚቀመጥባትን የጌሤምን ምድር እለያለሁ።'),
  ('ddfcd06d-672b-5be4-aecd-a12b165318d9', '14409c91-88ad-5251-ae5e-a16d058c8b93', '94a2562f-33cd-5806-a6cf-5cca43d99b0b', 4, 23, 'በሕዝቤና በሕዝብህ መካከል እለያለሁ፤ ይህም ነገር ነገ በምድሪቱ ላይ ይሆናል።”'),
  ('256c4773-def3-5519-ab4c-e3beae61b583', '14409c91-88ad-5251-ae5e-a16d058c8b93', '94a2562f-33cd-5806-a6cf-5cca43d99b0b', 5, 24, 'እግዚአብሔርም እንዲህ አደረገ፤ የውሻው ዝንብም በፈርዖን ቤት፥ በሹሞቹም ቤቶች ውሰጥ፥ በግብፅም ሀገር ሁሉ መጣ፤ ምድሪቱም ከውሻው ዝንብ የተነሣ ጠፋች።'),
  ('d2f28801-fe03-523e-a4ce-c64f438c56a2', '14409c91-88ad-5251-ae5e-a16d058c8b93', '94a2562f-33cd-5806-a6cf-5cca43d99b0b', 6, 25, 'ፈርዖንም ሙሴንና አሮንን ጠርቶ፥ “ሂዱ፤ በዚያች ምድር ለአምላካችሁ ሠዉ” አላቸው።'),
  ('cf10e71a-71f8-5621-a1a0-f1e7cf83ab51', '14409c91-88ad-5251-ae5e-a16d058c8b93', '94a2562f-33cd-5806-a6cf-5cca43d99b0b', 7, 26, 'ሙሴም፥ “ለእግዚአብሔር ለአምላካችን ግብፃውያን እርም የሚሉትን እንሠዋለንና እንዲሁ ይሆን ዘንድ አይቻልም፤ እነሆ፥ ግብፃውያን እርም የሚሉትን እኛ በፊታቸው ብንሠዋ በድንጋይ ይወግሩናል።'),
  ('9e26b405-38dc-54be-ade9-5bafdf38b884', '14409c91-88ad-5251-ae5e-a16d058c8b93', '94a2562f-33cd-5806-a6cf-5cca43d99b0b', 8, 27, 'እኛስ ለእግዚአብሔር ለአምላካችን እንሠዋ ዘንድ እግዚአብሔር እንዳዘዘን የሦስት ቀን መንገድ ወደ ምድረ በዳ እንሄዳለን” አለ።'),
  ('4a0c57cf-59a4-5744-a4c3-bb1a73c1632a', '14409c91-88ad-5251-ae5e-a16d058c8b93', '94a2562f-33cd-5806-a6cf-5cca43d99b0b', 9, 28, 'ፈርዖንም፥ “ለእግዚአብሔር ለአምላካችሁ በምድረ በዳ ትሠዉ ዘንድ እለቅቃችኋለሁ፤ ነገር ግን በጣም ርቃችሁ አትሂዱ፤ ወደ እግዚአብሔርም ጸልዩልኝ” አለ።'),
  ('bc66378e-f5d2-530d-a2a6-351688541ce8', '14409c91-88ad-5251-ae5e-a16d058c8b93', '94a2562f-33cd-5806-a6cf-5cca43d99b0b', 10, 29, 'ሙሴም፥ “እነሆ፥ ከአንተ ዘንድ እወጣለሁ፤ ወደ እግዚአብሔርም እጸልያለሁ፤ የውሻ ዝንቡም ከአንተ፥ ከሹሞችህና ከሕዝብህ ነገ ይርቃል፤ ነገር ግን ለእግዚአብሔር ይሠዉ ዘንድ ሕዝቡን እንደማትለቅቅ እንደገና ማታለልን አትድገም።”'),
  ('b785cd7c-160c-58f8-ae62-aacd013e88fc', '14409c91-88ad-5251-ae5e-a16d058c8b93', '94a2562f-33cd-5806-a6cf-5cca43d99b0b', 11, 30, 'ሙሴም ከፈርዖን ዘንድ ወጣ፤ ወደ እግዚአብሔርም ጸለየ።'),
  ('9186b843-0138-5ed5-a7fb-d2c6802d8c57', '14409c91-88ad-5251-ae5e-a16d058c8b93', '94a2562f-33cd-5806-a6cf-5cca43d99b0b', 12, 31, 'እግዚአብሔርም ሙሴ እንደ አለ አደረገ፤ የውሻውንም ዝንብ ከፈርዖን፥ ከሹሞቹም፥ ከሕዝቡም አራቀ፤ አንድ ስንኳ አልቀረም።'),
  ('c2e3a675-aede-5200-aa30-d689ed5e2c8e', '14409c91-88ad-5251-ae5e-a16d058c8b93', '94a2562f-33cd-5806-a6cf-5cca43d99b0b', 13, 32, 'ፈርዖንም በዚህ ጊዜ ደግሞ ልቡን አደነደነ፤ ሕዝቡንም አልለቀቀም።'),
  ('b3cb3b74-fb31-591c-afed-9321892831cd', '30452a47-ba26-551e-a7fd-d294959be329', 'cb7b1a76-446b-5004-a6a7-60227f970b9f', 1, 1, 'እግዚአብሔርም ሙሴን አለው፥ “ወደ ፈርዖን ገብተህ እንዲህ በለው፦ የዕብራውያን አምላክ እግዚአብሔር እንዲህ ይላል፦ ያመልኩኝ ዘንድ ሕዝቤን ልቀቅ።'),
  ('3358fe12-45f2-56a1-a3c3-55f24827678c', '30452a47-ba26-551e-a7fd-d294959be329', 'cb7b1a76-446b-5004-a6a7-60227f970b9f', 2, 2, 'ሕዝቤን ልትለቃቸው እንቢ ብትል፥ ብትይዛቸውም፥'),
  ('cd084090-9d36-5a8b-a04d-29352d786089', '30452a47-ba26-551e-a7fd-d294959be329', 'cb7b1a76-446b-5004-a6a7-60227f970b9f', 3, 3, 'እነሆ፥ የእግዚአብሔር እጅ በሜዳ ውስጥ በአሉት በከብቶችህ፥ በፈረሶችም፥ በአህዮችም፥ በግመሎችም፥ በበሬዎችም፥ በበጎችም ላይ ትሆናለች፤ ይኸውም እጅግ ጽኑዕ ሞት ነው፤'),
  ('af1246ae-9956-5e45-acee-5614afa60a64', '30452a47-ba26-551e-a7fd-d294959be329', 'cb7b1a76-446b-5004-a6a7-60227f970b9f', 4, 4, 'በዚያ ጊዜም በግብፃውያን ከብቶችና በእስራኤል ልጆች ከብቶች መካከል ልዩነት አደርጋለሁ። ከእስራኤልም ልጆች ከብቶች አንዳች አይሞትም።”'),
  ('ca9bcdbc-b56f-580f-a1fc-5b8b85989d24', '30452a47-ba26-551e-a7fd-d294959be329', 'cb7b1a76-446b-5004-a6a7-60227f970b9f', 5, 5, 'እግዚአብሔርም፥ “ነገ እግዚአብሔር ይህን ነገር በምድር ላይ ያደርጋል ብሎ ጊዜን ወሰነ።” እግዚአብሔርም ያን ነገር በነጋው አደረገ፤'),
  ('8b6e8080-6f6e-5e34-ab12-ae1996a9352d', '30452a47-ba26-551e-a7fd-d294959be329', 'cb7b1a76-446b-5004-a6a7-60227f970b9f', 6, 6, 'የግብፅም ከብት ሁሉ ሞተ፤ ከእስራኤል ልጆች ከብት ግን አንድ ስንኳ አልሞተም።'),
  ('3a4d6270-f6ad-5e41-a35d-de15d8efeef8', '30452a47-ba26-551e-a7fd-d294959be329', 'cb7b1a76-446b-5004-a6a7-60227f970b9f', 7, 7, 'ፈርዖንም ከእስራኤል ልጆች ከብት አንድ ስንኳ እንዳልሞተ በአየ ጊዜ ልቡ ደነደነ፤ ሕዝቡንም አልለቀቀም።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('7f971de7-2af1-5519-a995-c171d0957a09', '30452a47-ba26-551e-a7fd-d294959be329', '0b8951d3-47be-57d4-a89f-087d321a3bbb', 1, 8, 'እግዚአብሔርም ሙሴንና አሮንን፥ “እጃችሁን ሞልታችሁ ከምድጃ አመድ ውሰዱ፤ ሙሴም በፈርዖንና በሹሞቹ ፊት ወደ ሰማይ ይበትነው።'),
  ('f398df80-6362-5070-a822-3f1a57b89493', '30452a47-ba26-551e-a7fd-d294959be329', '0b8951d3-47be-57d4-a89f-087d321a3bbb', 2, 9, 'እርሱም በግብፅ ሀገር ሁሉ ትቢያ ይሆናል፤ በግብፅም ሀገር ሁሉ በሰውና በእንስሳ ላይ ሻህኝ የሚያመጣ ቍስል ይሆናል” አላቸው።'),
  ('736c0585-0016-59fa-af3e-6c5c9f163d1c', '30452a47-ba26-551e-a7fd-d294959be329', '0b8951d3-47be-57d4-a89f-087d321a3bbb', 3, 10, 'ሙሴም አመዱን በፈርዖን ፊት ወስዶ ወደ ሰማይ በተነው፤ በሰውና በእንስሳም ላይ ሻህኝ የሚያወጣ ቍስል ሆነ።'),
  ('9357894d-5050-5e56-a752-eaa8d2aab659', '30452a47-ba26-551e-a7fd-d294959be329', '0b8951d3-47be-57d4-a89f-087d321a3bbb', 4, 11, 'ጠንቋዮችም ቍስል ስለ ነበረባቸው በሙሴ ፊት መቆም አልቻሉም፤ ቍስል ጠንቋዮችንና ግብፃውያንን ሁሉ ይዞአቸው ነበርና።'),
  ('3115aed0-9496-533e-ac81-1be1d20123c6', '30452a47-ba26-551e-a7fd-d294959be329', '0b8951d3-47be-57d4-a89f-087d321a3bbb', 5, 12, 'እግዚአብሔርም የፈርዖንን ልብ አጸና፤ እግዚአብሔርም ለሙሴና ለአሮን እንደ ተናገረው አልሰማቸውም።'),
  ('4307b946-a815-5b27-af30-3261c4533ef3', '30452a47-ba26-551e-a7fd-d294959be329', '7c1db5af-6df7-5f31-ad0c-f5c036e8ca67', 1, 13, 'እግዚአብሔርም ሙሴን አለው፥ “ማልደህ ተነሣ፤ በፈርዖንም ፊት ቆመህ እንዲህ በለው፦ የዕብራውያን አምላክ እግዚአብሔር እንዲህ ይላል፦ እንዲያመልኩኝ ሕዝቤን ልቀቅ።'),
  ('a053e3b4-1cf2-56df-aeb8-daedffe10192', '30452a47-ba26-551e-a7fd-d294959be329', '7c1db5af-6df7-5f31-ad0c-f5c036e8ca67', 2, 14, 'በምድር ሁሉ እንደ እኔ ያለ እንደሌለ ታውቅ ዘንድ በሰውነትህ፥ በአገልጋዮችህም፥ በሕዝብህም ላይ መቅሠፍቴን ሁሉ በዚህ ጊዜ እልካለሁ።'),
  ('2fd531f2-058d-560c-aa2a-da18b7114610', '30452a47-ba26-551e-a7fd-d294959be329', '7c1db5af-6df7-5f31-ad0c-f5c036e8ca67', 3, 15, 'አሁን እጄን ዘርግቼ አንተን እመታሃለሁ፤ ሕዝብህንም እገድላቸዋለሁ፤ ምድራችሁም ትመታለች።'),
  ('a7f0cb6a-bf97-5bb7-a9ff-e893b1128d28', '30452a47-ba26-551e-a7fd-d294959be329', '7c1db5af-6df7-5f31-ad0c-f5c036e8ca67', 4, 16, 'ነገር ግን ኀይሌን እገልጥብህ ዘንድ፥ ስሜም በምድር ሁሉ ላይ ይነገር ዘንድ ስለዚህ ጠበቅሁህ።'),
  ('e81e873c-ae59-5a8b-a290-4e35a49c3135', '30452a47-ba26-551e-a7fd-d294959be329', '7c1db5af-6df7-5f31-ad0c-f5c036e8ca67', 5, 17, 'አንተ ግን እንዳትለቃቸው ገና በሕዝቤ ላይ ትታበያለህ፤'),
  ('c9b15907-b699-51aa-a164-eaaac9b0cc68', '30452a47-ba26-551e-a7fd-d294959be329', '7c1db5af-6df7-5f31-ad0c-f5c036e8ca67', 6, 18, 'እነሆ፥ ከተመሠረተች ጀምሮ እስከ ዛሬ ድረስ እንደ እርሱ ያለ በግብፅ ሆኖ የማያውቅ እጅግ ታላቅ በረዶ ነገ በዚህ ጊዜ አዘንባለሁ።'),
  ('11c445a9-305c-5f9b-a70e-149aeafa25e8', '30452a47-ba26-551e-a7fd-d294959be329', '7c1db5af-6df7-5f31-ad0c-f5c036e8ca67', 7, 19, 'አሁን እንግዲህ ፥ ከብቶችህንም በሜዳም ያለህን ሁሉ ፈጥነህ ሰብስብ። በሜዳ የተገኘ ወደ ቤት ያልገባ ሰውና እንስሳ ሁሉ በረዶ ወርዶበት ይሞታልና።”'),
  ('8599f409-a40e-5128-aee6-a36bc0388029', '30452a47-ba26-551e-a7fd-d294959be329', '7c1db5af-6df7-5f31-ad0c-f5c036e8ca67', 8, 20, 'ከፈርዖን ሹሞች የእግዚአብሔርን ቃል የፈራ ከብቶቹን ወደ ቤቶቹ ሰበሰበ።'),
  ('de97b01a-4a70-533f-a4ff-714b27438d20', '30452a47-ba26-551e-a7fd-d294959be329', '7c1db5af-6df7-5f31-ad0c-f5c036e8ca67', 9, 21, 'የእግዚአብሔርን ቃል በልቡ ያላሰበ ግን ከብቶቹን በሜዳ ተወ።'),
  ('9f2460f0-79ee-5a6c-ad1e-986fb1ae41a5', '30452a47-ba26-551e-a7fd-d294959be329', '7c1db5af-6df7-5f31-ad0c-f5c036e8ca67', 10, 22, 'እግዚአብሔርም ሙሴን አለው፥ “እጅህን ወደ ሰማይ ዘርጋ፤ በግብፅም ሀገር ሁሉ በሰውና በእንስሳም በምድርም ቡቃያ ሁሉ ላይ በረዶ ይሆናል።”'),
  ('a02dcfdf-70ba-54c1-a165-07aac404dd1f', '30452a47-ba26-551e-a7fd-d294959be329', '7c1db5af-6df7-5f31-ad0c-f5c036e8ca67', 11, 23, 'ሙሴም እጁን ወደ ሰማይ ዘረጋ፤ እግዚአብሔርም ነጐድጓድና በረዶ ላከ፤ እሳትም ወደ ምድር ወረደ፤ እግዚአብሔርም በግብፅ ሀገር ሁሉ ላይ በረዶ አዘነበ።'),
  ('95318195-bfc6-5bc1-aa20-1b8499f6c75b', '30452a47-ba26-551e-a7fd-d294959be329', '7c1db5af-6df7-5f31-ad0c-f5c036e8ca67', 12, 24, 'በረዶም ነበረ፤ በበረዶውም መካከል እሳት ይቃጠል ነበር፤ በረዶውም በግብፅ ሀገር ሁሉ ሕዝብ ከኖረበት ጊዜ ጀምሮ እስከዚች ቀን እንደ እርሱ ያልሆነ እጅግ ብዙና ጠንካራ ነበረ።'),
  ('3209b33c-51a7-5270-ae31-92ebaa54452f', '30452a47-ba26-551e-a7fd-d294959be329', '7c1db5af-6df7-5f31-ad0c-f5c036e8ca67', 13, 25, 'በረዶውም በግብፅ ሀገር ሁሉ በሜዳ ያለውን ሁሉ ሰውንና እንስሳን መታ፤ በረዶውም የእርሻን ቡቃያ ሁሉ መታ። የጫካውንም ዛፍ ሁሉ ሰበረ።'),
  ('7c8c697a-add9-5ac5-ab80-eb31ce379ef5', '30452a47-ba26-551e-a7fd-d294959be329', '7c1db5af-6df7-5f31-ad0c-f5c036e8ca67', 14, 26, 'የእስራኤል ልጆች ተቀምጠው በነበሩባት በጌሤም ሀገር ብቻ በረዶ አልወረደም።'),
  ('fe0a0434-357c-533b-a311-ee6744d25359', '30452a47-ba26-551e-a7fd-d294959be329', '7c1db5af-6df7-5f31-ad0c-f5c036e8ca67', 15, 27, 'ፈርዖንም ልኮ ሙሴንና አሮንን ጠራ፤ “አሁንም በደልሁ፤ እግዚአብሔር ጻድቅ ነው፤ እኔና ሕዝቤ ግን ኀጢአተኞች ነን።'),
  ('add07a18-25c6-5df6-af74-1ba8a3b697e3', '30452a47-ba26-551e-a7fd-d294959be329', '7c1db5af-6df7-5f31-ad0c-f5c036e8ca67', 16, 28, 'እንግዲህ ወደ እግዚአብሔር ጸልዩልኝ፤ የአምላክ ነጐድጓድ፥ በረዶውም፥ እሳቱም ጸጥ ይላል፤ እኔም እለቅቃችኋለሁ፤ ከዚያም በኋላ ከዚህ አትቀመጡም” አላቸው።'),
  ('dfce0b7a-6be8-552c-a2d7-f7619a58359e', '30452a47-ba26-551e-a7fd-d294959be329', '7c1db5af-6df7-5f31-ad0c-f5c036e8ca67', 17, 29, 'ሙሴም፥ “ለፈርዖን ከከተማ በወጣሁ ጊዜ እጄን ወደ እግዚአብሔር እዘረጋለሁ፤ ምድሪቱም ለእግዚአብሔር እንደ ሆነች ታውቅ ዘንድ ነጐድጓዱ ጸጥ ይላል፤ በረዶውም፥ ዝናቡም ደግሞ አይወርድም።'),
  ('1444b694-0b6d-559a-a5db-35dbd8ea860f', '30452a47-ba26-551e-a7fd-d294959be329', '7c1db5af-6df7-5f31-ad0c-f5c036e8ca67', 18, 30, 'ነገር ግን አንተና ሹሞችህ እግዚአብሔር አምላክን ምንጊዜም እንደማትፈሩ አውቃለሁ” አለው።'),
  ('04018de7-9572-5ec1-ae4f-271c69a9ee57', '30452a47-ba26-551e-a7fd-d294959be329', '7c1db5af-6df7-5f31-ad0c-f5c036e8ca67', 19, 31, 'ተልባውና ገብሱ ተመታ፤ ገብሱ አሽቶ፥ ተልባውም አፍርቶ ነበርና።'),
  ('d73ee8da-af0b-5e1f-a45b-9ec2244ebd61', '30452a47-ba26-551e-a7fd-d294959be329', '7c1db5af-6df7-5f31-ad0c-f5c036e8ca67', 20, 32, 'ስንዴውና አጃው ግን አልተመቱም፤ ገና ቡቃያ ነበሩና።'),
  ('a128f99d-21df-52e0-a5f0-7c949929da22', '30452a47-ba26-551e-a7fd-d294959be329', '7c1db5af-6df7-5f31-ad0c-f5c036e8ca67', 21, 33, 'ሙሴም ከፈርዖን ዘንድ ከከተማ ወጣ፤ እጁንም ወደ እግዚአብሔር ዘረጋ፤ ነጐድጓዱም፥ በረዶውም ጸጥ አለ፤ ዝናቡም በምድር ላይ አላካፋም።'),
  ('23eb4732-b704-5e97-aeaa-3bf1229380d3', '30452a47-ba26-551e-a7fd-d294959be329', '7c1db5af-6df7-5f31-ad0c-f5c036e8ca67', 22, 34, 'ፈርዖንም ዝናቡ፥ በረዶውም፥ ነጐድጓዱም ጸጥ እንደ አለ በአየ ጊዜ በደልን ጨመረ፤ እርሱና ሹሞቹም ልባቸውን አደነደኑ።'),
  ('0f0fbdeb-efaf-5b9d-af91-9d940be80d91', '30452a47-ba26-551e-a7fd-d294959be329', '7c1db5af-6df7-5f31-ad0c-f5c036e8ca67', 23, 35, 'የፈርዖንም ልብ ጸና፤ እግዚአብሔርም በሙሴ አፍ እንደ ተናገረ የእስራኤልን ልጆች አልለቀቀም።'),
  ('e39858b8-1eea-52e3-a267-2a8ff53fed8d', '169d1cf6-20f6-58c7-ab61-9f7bfb05b50b', '8e900095-9cd7-5f30-a244-b0f381dc097d', 1, 1, 'እግዚአብሔርም ሙሴን እንዲህ ብሎ ተናገረው፥ “ወደ ፈርዖን ግባ፤ እኔ የፈርዖንንና የሹሞቹን ልብ አጽንቼአለሁና፥ ተአምራቴ በእነርሱ ላይ በትክክል ይመጣ ዘንድ፤'),
  ('ab0c4bc9-24c7-52cc-aa46-f6e4913ef6a3', '169d1cf6-20f6-58c7-ab61-9f7bfb05b50b', '8e900095-9cd7-5f30-a244-b0f381dc097d', 2, 2, 'በግብፃውያንም ላይ የተዘባበትሁትን ሁሉ፥ ያደረግሁባቸውንም ተአምራቴን በልጆቻችሁና በልጅ ልጆቻችሁ ጆሮች ትነግሩ ዘንድ፤ እኔም እግዚአብሔር እንደ ሆንሁ ታውቃላችሁ።”'),
  ('60a42300-5ca6-5207-a681-a3f777c8eada', '169d1cf6-20f6-58c7-ab61-9f7bfb05b50b', '8e900095-9cd7-5f30-a244-b0f381dc097d', 3, 3, 'ሙሴና አሮንም ወደ ፈርዖን ገቡ፤ አሉትም፥ “የዕብራውያን አምላክ እግዚአብሔር እንዲህ ይላል፦ እኔን ማፈርን እስከ መቼ እንቢ ትላለህ? ያመልኩኝ ዘንድ ሕዝቤን ልቀቅ።'),
  ('68725d3c-62bf-53e1-a33a-38b6804aa330', '169d1cf6-20f6-58c7-ab61-9f7bfb05b50b', '8e900095-9cd7-5f30-a244-b0f381dc097d', 4, 4, 'ሕዝቤን ለመልቀቅ እንቢ ብትል ግን፥ እነሆ፥ ነገ በዚህ ጊዜ በተራራዎችህ ሁሉ ላይ አንበጣን አመጣለሁ፤'),
  ('4d47eb77-f2d1-50bf-a24b-022f8baf8bd7', '169d1cf6-20f6-58c7-ab61-9f7bfb05b50b', '8e900095-9cd7-5f30-a244-b0f381dc097d', 5, 5, 'የምድሩንም ፊት ይሸፍናል፤ ምድሩን ለማየት አይቻልም፤ ከበረዶውም ተርፎ በምድር ላይ የቀረላችሁን ትርፍ ሁሉ ይበላል፤ ያደገላችሁንም የእርሻውን ዛፍ ሁሉ ይበላል፤'),
  ('9d596340-582f-5e51-a9f4-ee533f365c88', '169d1cf6-20f6-58c7-ab61-9f7bfb05b50b', '8e900095-9cd7-5f30-a244-b0f381dc097d', 6, 6, 'ቤቶችህም የሹሞችህም ሁሉ ቤቶች፥ የግብፃውያን ሁሉ ቤቶች በእርሱ ይሞላሉ፤ አባቶችህ፥ የአባቶችህም አባቶች በምድር ላይ ከተቀመጡበት ቀን ጀምሮ እስከዚህ ቀን ድረስ እንደ እርሱ ያለ ያላዩት ነው።” ሙሴም ተመልሶ ከፈርዖን ዘንድ ወጣ።'),
  ('dc4d7b97-3704-5575-ad57-5b68d9a268f2', '169d1cf6-20f6-58c7-ab61-9f7bfb05b50b', '8e900095-9cd7-5f30-a244-b0f381dc097d', 7, 7, 'የፈርዖንም ሹሞች፥ “ይህ ሰው እስከ መቼ እንቅፋት ይሆንብናል? አምላካቸውን እግዚአብሔርን ያመልኩት ዘንድ ሰዎችን ልቀቅ፤ ግብፅስ እንደ ጠፋች ገና አታውቅምን?” አሉት።'),
  ('309b76c9-fce4-593a-a08a-d4118f3a182d', '169d1cf6-20f6-58c7-ab61-9f7bfb05b50b', '8e900095-9cd7-5f30-a244-b0f381dc097d', 8, 8, 'ሙሴንና አሮንንም ወደ ፈርዖን ጠሩአቸው፤ ፈርዖንም እንዲህ አላቸው፥ “ሂዱ፤ አምላካችሁን እግዚአብሔርን አምልኩ፤ ነገር ግን ከእናንተ ጋር የሚሄዱት እነማን ናቸው?”'),
  ('af9170ed-8a1c-5791-a81e-5bba2443d832', '169d1cf6-20f6-58c7-ab61-9f7bfb05b50b', '8e900095-9cd7-5f30-a244-b0f381dc097d', 9, 9, 'ሙሴም አለው፥ “እኛ ከታናናሾቻችንና ከሽማግሌዎቻችን፥ ከወንዶችና ሴቶች ልጆቻችን ጋር እንሄዳለን፤ በጎቻችንንና ላሞቻችንንም እንወስዳለን። የአምላካችን የእግዚአብሔር በዓል ነውና።”'),
  ('5599b90c-ba7a-59d5-ade3-f9a776c0a600', '169d1cf6-20f6-58c7-ab61-9f7bfb05b50b', '8e900095-9cd7-5f30-a244-b0f381dc097d', 10, 10, 'ፈርዖንም አላቸው፥ “እግዚአብሔር ከእናንተ ጋር ይሁን፤ እነሆ፥ እናንተን ስለቅ ልጆቻችሁንም መልቀቅ አለብኝን? ክፉ ነገር እንደሚገጥማችሁ ዕወቁ።'),
  ('5d2d7fea-a33f-5c83-a593-80f00bbd83ad', '169d1cf6-20f6-58c7-ab61-9f7bfb05b50b', '8e900095-9cd7-5f30-a244-b0f381dc097d', 11, 11, 'እንዲህም አይደለም፤ እናንተ ወንዶቹ ሂዱ፤ ይህን ፈልጋችኋልና እግዚአብሔርን አምልኩ” አላቸው። ሙሴንና አሮንንም ከፈርዖን ፊት አስወጡአቸው።'),
  ('95f5e3ff-1596-5f7c-afba-1a0ebf7b7985', '169d1cf6-20f6-58c7-ab61-9f7bfb05b50b', '8e900095-9cd7-5f30-a244-b0f381dc097d', 12, 12, 'እግዚአብሔርም ሙሴን አለው፥ “በግብፅ ሀገር ላይ እጅህን ዘርጋ፤ አንበጣም በምድር ላይ ይወጣል፤ ከበረዶውም የተረፈውን የምድር ቡቃያ ሁሉና የዛፉን ፍሬ ሁሉ ይበላል።”'),
  ('ba0cb63e-0f8e-53fa-a383-c31b910691f6', '169d1cf6-20f6-58c7-ab61-9f7bfb05b50b', '8e900095-9cd7-5f30-a244-b0f381dc097d', 13, 13, 'ሙሴም በትሩን ወደ ሰማይ ዘረጋ፤ እግዚአብሔርም የደቡብን ነፋስ ያን ቀን ሁሉ ሌሊቱንም ሁሉ አመጣ፤ ማለዳም በሆነ ጊዜ የደቡብ ነፋስ አንበጣን አመጣ።'),
  ('f6fa3238-2e68-5f97-a192-b3f8c8dee736', '169d1cf6-20f6-58c7-ab61-9f7bfb05b50b', '8e900095-9cd7-5f30-a244-b0f381dc097d', 14, 14, 'አንበጣም በግብፅ ሀገር ሁሉ ላይ ወጣ፤ በግብፅም ዳርቻ ሁሉ ላይ ተቀመጠ፤ እጅግም ብዙና ጠንካራ ነበር፤ ይህንም የሚያህል አንበጣ በፊት አልነበረም፤ ወደፊትም ደግሞ እንደ እርሱ አይሆንም።'),
  ('e6bafda4-76df-535b-a8c3-062d5b050088', '169d1cf6-20f6-58c7-ab61-9f7bfb05b50b', '8e900095-9cd7-5f30-a244-b0f381dc097d', 15, 15, 'የምድሩንም ፊት ፈጽሞ ሸፈነው፤ ሀገሪቱም ጠፋች፤ የሀገሪቱን ቡቃያ ሁሉ ከበረዶውም የተረፈውን፥ በዛፉ የነበረውን ፍሬ ሁሉ በላ፤ ለምለም ነገር በዛፎች ላይ፥ በእርሻውም ቡቃያ ሁሉ ላይ በግብፅ ሀገር ሁሉ አልቀረም።'),
  ('abd81116-257d-5176-ac8a-5a444a85b8a6', '169d1cf6-20f6-58c7-ab61-9f7bfb05b50b', '8e900095-9cd7-5f30-a244-b0f381dc097d', 16, 16, 'ፈርዖንም ሙሴንና አሮንን በፍጥነት ጠራ፥ “በአምላካችሁ በእግዚአብሔር ፊት፥ በእናንተም ላይ በደልሁ፤'),
  ('3fcdc8a5-cc04-5dc6-ad92-0a3dfc8146fe', '169d1cf6-20f6-58c7-ab61-9f7bfb05b50b', '8e900095-9cd7-5f30-a244-b0f381dc097d', 17, 17, 'አሁን እንግዲህ እንደገና በዚህ ጊዜ ብቻ ኀጢአቴን ይቅር በሉኝ፤ ይህንም ሞት ብቻ ከእኔ ያነሣልኝ ዘንድ ወደ አምላካችሁ ወደ እግዚአብሔር ጸልዩልኝ” አላቸው።'),
  ('7b6c22f9-b2eb-5984-a183-6a6ee2c1be00', '169d1cf6-20f6-58c7-ab61-9f7bfb05b50b', '8e900095-9cd7-5f30-a244-b0f381dc097d', 18, 18, 'ሙሴም ከፈርዖን ፊት ወጣ፤ ወደ እግዚአብሔርም ጸለየ።'),
  ('3cc4ba9f-1184-5d51-af24-e3b9c6c8fe82', '169d1cf6-20f6-58c7-ab61-9f7bfb05b50b', '8e900095-9cd7-5f30-a244-b0f381dc097d', 19, 19, 'እግዚአብሔርም ከባሕር ዐውሎ ነፋሱን አስወገደ፤ አንበጣዎችንም ወስዶ በኤርትራ ባሕር ውስጥ ጣላቸው፤ አንድ አንበጣም እንኳን በግብፅ ዳርቻ ሁሉ አልቀረም።'),
  ('60505a18-1ba4-5571-ad65-ce0715073c87', '169d1cf6-20f6-58c7-ab61-9f7bfb05b50b', '8e900095-9cd7-5f30-a244-b0f381dc097d', 20, 20, 'እግዚአብሔር የፈርዖንን ልብ አጸና የእስራኤልንም ልጆች አልልቀቀም።'),
  ('67d55d44-a041-5e40-a875-9f2f1e5e2090', '169d1cf6-20f6-58c7-ab61-9f7bfb05b50b', '7c408b74-b5fa-59a6-a87a-19fa4194238b', 1, 21, 'እግዚአብሔርም ሙሴን፥ “እጅህን ወደ ሰማይ ዘርጋ፤ በግብፅም ሀገር ላይ ጨለማ ይሁን፤ ጨለማውም የሚዳሰስ ነው” አለው።'),
  ('a11a4641-f88d-5a41-adcc-ef32ae4bce9a', '169d1cf6-20f6-58c7-ab61-9f7bfb05b50b', '7c408b74-b5fa-59a6-a87a-19fa4194238b', 2, 22, 'ሙሴም እጁን ወደ ሰማይ ዘረጋ፤ በግብፅም ሀገር ሁሉ ላይ ጽኑ ጨለማና ጭጋግ ሦስት ቀን ሆነ፤'),
  ('b6f6fc1e-5160-541b-a1fb-4f05324b3672', '169d1cf6-20f6-58c7-ab61-9f7bfb05b50b', '7c408b74-b5fa-59a6-a87a-19fa4194238b', 3, 23, 'ማንም ወንድሙን አላየም፤ ሦስት ቀን ሙሉም ከመኝታው ማንም አልተነሣም፤ ለእስራኤል ልጆች ሁሉ ግን በተቀመጡበት ስፍራ ሁሉ ብርሃን ነበራቸው።'),
  ('59a9de10-7636-51d0-a09f-969982cae6c3', '169d1cf6-20f6-58c7-ab61-9f7bfb05b50b', '7c408b74-b5fa-59a6-a87a-19fa4194238b', 4, 24, 'ፈርዖንም ሙሴንና አሮንን ጠርቶ፥ “ሂዱ፤ አምላካችሁ እግዚአብሔርን አምልኩ፤ ነገር ግን በጎቻችሁንና ከብቶቻችሁን ብቻ ተዉ፤ ልጆቻችሁና ሴቶቻችሁ ግን ከእናንተ ጋር ይሂዱ” አላቸው።'),
  ('e901f810-b5c4-5c25-a744-21d69bbff44a', '169d1cf6-20f6-58c7-ab61-9f7bfb05b50b', '7c408b74-b5fa-59a6-a87a-19fa4194238b', 5, 25, 'ሙሴም አለው፥ “አይሆንም! አንተ ደግሞ ለአምላካችን ለእግዚአብሔር የምንሠዋው መሥዋዕትንና የሚቃጠል መሥዋዕትን ትሰጠናለህ።'),
  ('f1febd5c-e223-50e3-ad3d-f665acbd4748', '169d1cf6-20f6-58c7-ab61-9f7bfb05b50b', '7c408b74-b5fa-59a6-a87a-19fa4194238b', 6, 26, 'ከብቶቻችን ከእኛ ጋር ይሄዳሉ፤ አንድ ሰኰናም አይቀርም፤ አምላካችንን እግዚአብሔርን ለማምለክ ከእነርሱ እንወስዳለንና፤ አምላካችንን እግዚአብሔርን እንደምናመልከው ከዚያ እስክንደርስ አናውቅም።”'),
  ('d6060c58-e521-5814-a4a1-545e6ed0206a', '169d1cf6-20f6-58c7-ab61-9f7bfb05b50b', '7c408b74-b5fa-59a6-a87a-19fa4194238b', 7, 27, 'እግዚአብሔርም የፈርዖንን ልብ አጸና፤ ሊለቅቃቸውም አልወደደም።'),
  ('8df2733b-805d-5c58-a528-0f38b5ff770c', '169d1cf6-20f6-58c7-ab61-9f7bfb05b50b', '7c408b74-b5fa-59a6-a87a-19fa4194238b', 8, 28, 'ፈርዖንም ሙሴን፥ “ከእኔ ዘንድ ሂድ፤ በፊቴ በምትታይበት ቀን ትሞታለህና ዳግመኛ ፊቴን እንዳታይ ተጠንቀቅ” አለው።'),
  ('81d09c67-5678-5ae7-a855-fc889991d37e', '169d1cf6-20f6-58c7-ab61-9f7bfb05b50b', '7c408b74-b5fa-59a6-a87a-19fa4194238b', 9, 29, 'ሙሴም፥ “እንደ ተናገርህ ይሁን፤ ፊትህን እንደገና አላይም” አለ።'),
  ('026e9fe7-157a-5c17-aed5-0558941234c4', '23377c7d-bd2c-508c-afc7-be1b4212d674', '68cc6822-e45b-5738-a812-5ef512da0535', 1, 1, 'እግዚአብሔርም ሙሴን አለው፥ “በፈርዖንና በግብፅ ላይ ገና አንዲት መቅሠፍት አመጣለሁ፤ ከዚያም በኋላ ከዚያ ይለቅቃችኋል፤ ሲለቅቃችሁም ከመነሻ ገንዘብ ጋር ይሰድዳችኋል።'),
  ('ca5e0471-2aba-53ff-af2a-38e851069354', '23377c7d-bd2c-508c-afc7-be1b4212d674', '68cc6822-e45b-5738-a812-5ef512da0535', 2, 2, 'ወንዱ ከወዳጁ፥ ሴቲቱም ከወዳጅዋ የብርና የወርቅ ዕቃ፥ ልብስም ይዋሱ ዘንድ በሕዝቡ ጆሮ በስውር ተናገር።”'),
  ('93859027-cdb7-56f7-ad7b-7561ecea0da8', '23377c7d-bd2c-508c-afc7-be1b4212d674', '68cc6822-e45b-5738-a812-5ef512da0535', 3, 3, 'እግዚአብሔርም በግብፃውያን ፊት ለሕዝቡ ሞገስን ሰጠ፤ አዋሱአቸውም፤ ይህ ሙሴም በግብፃውያንና በፈርዖን፥ በሹሞቹም ፊት እጅግ የከበረ ሰው ነበረ።'),
  ('8baf91b5-a688-5a0c-abdd-378e15536c33', '23377c7d-bd2c-508c-afc7-be1b4212d674', '68cc6822-e45b-5738-a812-5ef512da0535', 4, 4, 'ሙሴም አለ፥ “እግዚአብሔር እንዲህ ይላል፦ በእኩለ ሌሊት እኔ በግብፅ መካከል እገባለሁ፤'),
  ('d2f4357b-e13a-5f96-a82b-07e06a2f6f2c', '23377c7d-bd2c-508c-afc7-be1b4212d674', '68cc6822-e45b-5738-a812-5ef512da0535', 5, 5, 'በግብፅም ሀገር ያለ በኵር ሁሉ፥ በዙፋኑ ከሚቀመጠው ከፈርዖን በኵር ጀምሮ በወፍጮ እግር እስካለችው እስከ አገልጋዪቱ በኵር ድረስ፥ የከብቱም በኵር ሁሉ ይሞታል።'),
  ('e92296cc-b08a-538c-aead-f6b1d26830e7', '23377c7d-bd2c-508c-afc7-be1b4212d674', '68cc6822-e45b-5738-a812-5ef512da0535', 6, 6, 'በግብፅም ሀገር ሁሉ አስቀድሞ እንደ እርሱ ያልሆነ፥ ኋላም ደግሞ እንደ እርሱ የማይሆን ታላቅ ጩኸት ይሆናል።'),
  ('b4849c20-b4f9-54b7-aa5a-98a217f251fd', '23377c7d-bd2c-508c-afc7-be1b4212d674', '68cc6822-e45b-5738-a812-5ef512da0535', 7, 7, 'እግዚአብሔር ግን በግብፃውያንና በእስራኤል መካከል ታላቅ ልዩነትን እንደሚያደርግ እንድታውቁ በእስራኤል ልጆች መካከል ከሰው ጀምሮ እስከ እንስሳ ድረስ ውሻ ምላሱን አያንቀሳቅስባቸውም።'),
  ('8575a8fd-17d0-52b4-a68d-6462efdfcc39', '23377c7d-bd2c-508c-afc7-be1b4212d674', '68cc6822-e45b-5738-a812-5ef512da0535', 8, 8, 'እነዚህ አገልጋዮችህ ሁሉ፦ አንተ ውጣ፤ የሚከተሉህም ሕዝብ ሁሉ ከዚያች ምድር ይውጡ እያሉ ወደ እኔ ይወርዳሉ፤ ለእኔም ይሰግዳሉ፤ ከዚያም በኋላ እወጣለሁ።” ሙሴም በጽኑ ቍጣ ከፈርዖን ዘንድ ወጣ።'),
  ('84150055-eea4-5d7c-a6b3-c7978282a54b', '23377c7d-bd2c-508c-afc7-be1b4212d674', '68cc6822-e45b-5738-a812-5ef512da0535', 9, 9, 'እግዚአብሔርም ሙሴን አለው፥ “ተአምራቴና ድንቄ በግብፅ ሀገር ብዙ እንዲሆን ፈርዖን አይሰማችሁም።”'),
  ('16675aeb-dea9-51a7-a320-30c8d7d766cf', '23377c7d-bd2c-508c-afc7-be1b4212d674', '68cc6822-e45b-5738-a812-5ef512da0535', 10, 10, 'ሙሴና አሮንም እነዚህን ተአምራቶችና ድንቆች ሁሉ በፈርዖን ፊት አደረጉ፤ እግዚአብሔርም የፈርዖንን ልብ አጸና፤ የእስራኤልንም ልጆች ከግብፅ ምድር ለመልቀቅ እንቢ አለ።'),
  ('6d672406-0282-5249-a50a-b990ac054f86', '90b6f48f-1500-525a-a128-d4bf40de63d0', 'ca38d6a3-0b2e-5368-a8ca-5f7b0e69307f', 1, 1, 'እግዚአብሔርም በግብፅ ሀገር ሙሴንና አሮንን እንዲህ ብሎ ተናገራቸው፦'),
  ('db733ca1-b290-51f7-a7fa-894919c88d5e', '90b6f48f-1500-525a-a128-d4bf40de63d0', 'ca38d6a3-0b2e-5368-a8ca-5f7b0e69307f', 2, 2, '“ይህ ወር የወሮች መጀመሪያ ይሁናችሁ፤ የዓመቱም መጀመሪያ ወር ይሁናችሁ።'),
  ('fa9b1253-9bdb-522b-a8c9-7726b453f730', '90b6f48f-1500-525a-a128-d4bf40de63d0', 'ca38d6a3-0b2e-5368-a8ca-5f7b0e69307f', 3, 3, 'ለእስራኤል ልጆች ማኅበር ሁሉ ተናገሩ፤ በሉአቸውም፦ በዚህ ወር በዐሥረኛው ቀን ሰው ሁሉ ለአባቱ ቤተ ሰቦች ቤቶች አንድ አንድ ጠቦት፥ እያንዳንዱ ሰውም ለራሱ ቤተ ሰብእ አንድ ጠቦት ይውሰድ።'),
  ('bb8c4b23-bf9e-54c7-afe3-46e309d81807', '90b6f48f-1500-525a-a128-d4bf40de63d0', 'ca38d6a3-0b2e-5368-a8ca-5f7b0e69307f', 4, 4, 'በቤት ያሉት ሰዎች ጥቂት ቢሆኑ፥ አንድ በግም የማይጨርሱ ቢሆኑ በጉን ሊጨርሱ በሚበቁ በሰዎች ቍጥር እያንዳንዱ በአጠገቡ የሚኖረውን ጎረቤቱን ይውሰድ።'),
  ('93c2274a-d629-5450-a8bf-749db58b38a4', '90b6f48f-1500-525a-a128-d4bf40de63d0', 'ca38d6a3-0b2e-5368-a8ca-5f7b0e69307f', 5, 5, 'ነውር የሌለበት የአንድ ዓመት ተባት ጠቦት ለእናንተ ይሁን፤ ከበጎች ወይም ከፍየሎች ውሰዱ።'),
  ('1d4f951e-1975-51ae-abb6-142a8a125463', '90b6f48f-1500-525a-a128-d4bf40de63d0', 'ca38d6a3-0b2e-5368-a8ca-5f7b0e69307f', 6, 6, 'በዚህም ወር እስከ ዐሥራ አራተኛ ቀን ድረስ ጠብቁት፤ የእስራኤልም ልጆች ማኅበር ሁሉ ሲመሽ ይረዱት።'),
  ('7d38ad83-1969-5165-aeb2-8ab9fd9ebd17', '90b6f48f-1500-525a-a128-d4bf40de63d0', 'ca38d6a3-0b2e-5368-a8ca-5f7b0e69307f', 7, 7, 'ከደሙም ወስደው በሚበሉበት ቤት ሁለቱን መቃንና ጉበኑን ይቅቡት።'),
  ('8bbbd1c8-3ace-5186-ab62-3f323272c762', '90b6f48f-1500-525a-a128-d4bf40de63d0', 'ca38d6a3-0b2e-5368-a8ca-5f7b0e69307f', 8, 8, 'በእሳትም የተጠበሰውን ሥጋውን በዚያች ሌሊት ይብሉ፤ ቂጣውን እንጀራም ከመራራ ቅጠል ጋር ይብሉት።'),
  ('1531ae1a-0aee-5d97-a0b9-a395057e655d', '90b6f48f-1500-525a-a128-d4bf40de63d0', 'ca38d6a3-0b2e-5368-a8ca-5f7b0e69307f', 9, 9, 'ጥሬውንም፥ በውኃም የበሰለውን አትብሉ፤ ነገር ግን በእሳት የተጠበሰውን ራሱን፥ እግሩንና ሆድ ዕቃውን ብሉት።'),
  ('75f6209c-a33d-5c26-aa72-6a82c37ab515', '90b6f48f-1500-525a-a128-d4bf40de63d0', 'ca38d6a3-0b2e-5368-a8ca-5f7b0e69307f', 10, 10, 'ከእርሱም እስከ ጥዋት አንዳች አታስቀሩ፤ አጥንቱንም ከእርሱ አትስበሩ፤ ከእርሱም እስከ ጥዋት የተረፈ ቢኖር በእሳት አቃጥሉት።'),
  ('c75571b6-0135-54d5-aa0e-d9a18df3f006', '90b6f48f-1500-525a-a128-d4bf40de63d0', 'ca38d6a3-0b2e-5368-a8ca-5f7b0e69307f', 11, 11, 'ወገቦቻችሁን ታጥቃችሁ፥ ጫማችሁን በእግራችሁ ተጫምታችሁ፥ በትራችሁንም በእጃችሁ ይዛችሁ እንዲህ ብሉት፦ እየቸኰላችሁም ትበሉታላችሁ፤ እርሱ የእግዚአብሔር ፋሲካ ነውና።'),
  ('65e8727b-c561-53bf-a97f-692f8623c8e0', '90b6f48f-1500-525a-a128-d4bf40de63d0', 'ca38d6a3-0b2e-5368-a8ca-5f7b0e69307f', 12, 12, 'እኔም በዚያች ሌሊት በግብፅ ሀገር አልፋለሁ፤ በግብፅም ሀገር ከሰው እስከ እንስሳ ድረስ በኵርን ሁሉ እገድላለሁ፤ በግብፅም አማልክት ሁሉ ላይ በቀልን አደርግባቸዋለሁ፤ እኔ እግዚአብሔር ነኝ።'),
  ('f562657a-4c21-5c10-a799-cd89a787ac03', '90b6f48f-1500-525a-a128-d4bf40de63d0', 'ca38d6a3-0b2e-5368-a8ca-5f7b0e69307f', 13, 13, 'ደሙም ባላችሁባቸው ቤቶች ምልክት ይሆንላችኋል፤ ደሙንም አያለሁ፤ እናንተንም እሰውራችኋለሁ፤ እኔም የግብፅን ሀገር በመታሁ ጊዜ የጥፋት መቅሠፍት አይመጣባችሁም።'),
  ('9e13cd77-23f1-5060-a04d-3c44aa581bd3', '90b6f48f-1500-525a-a128-d4bf40de63d0', 'ca38d6a3-0b2e-5368-a8ca-5f7b0e69307f', 14, 14, 'ይህም ቀን መታሰቢያ ይሁናችሁ፤ ለእግዚአብሔርም በዓል ታደርጉታላችሁ፤ ለልጅ ልጃችሁም ሥርዐት ሆኖ ለዘለዓለም ታደርጉታላችሁ።'),
  ('19cf2f26-b48c-5a97-ad52-e48708b1e6b1', '90b6f48f-1500-525a-a128-d4bf40de63d0', '4e0409b7-e243-5aad-a7e9-d90a093ed186', 1, 15, '“ሰባት ቀን ቂጣ ትበላላችሁ፤ በመጀመሪያም ቀን እርሾውን ከቤታችሁ ታወጣላችሁ፤ ከመጀመሪያውም ቀን አንሥቶ እስከ ሰባተኛው ቀን እርሾ ያለበትን እንጀራ የሚበላ ነፍስ ከእስራኤል ተለይቶ ይጥፋ።'),
  ('770c97b8-103a-5bfb-ad76-83ee18079cfe', '90b6f48f-1500-525a-a128-d4bf40de63d0', '4e0409b7-e243-5aad-a7e9-d90a093ed186', 2, 16, 'የመጀመሪያዪቱ ቀን ቅድስት ትባላላች፤ እንዲሁም ሰባተኛዋ ቀን ቅድስት ትሁንላችሁ፤ ለነፍስ ከሚሠራው ሥራ ሁሉ በቀር ማናቸውንም ሥራ ሁሉ አትሥሩ'),
  ('67c4a0b5-e20b-5f15-a03b-d1c32c01b258', '90b6f48f-1500-525a-a128-d4bf40de63d0', '4e0409b7-e243-5aad-a7e9-d90a093ed186', 3, 17, 'በዚህም ቀን ሠራዊታችሁን ከግብፅ ሀገር አወጣዋለሁና ይህን ትእዛዝ ጠብቁት፤ እንግዲህ ይህን ቀን ለልጅ ልጃችሁ ለዘለዓለም ሥርዐት አድርጋችሁ ትጠብቃላችሁ።'),
  ('484e59fb-79b5-5baa-a019-3fd19c8365d1', '90b6f48f-1500-525a-a128-d4bf40de63d0', '4e0409b7-e243-5aad-a7e9-d90a093ed186', 4, 18, 'ከመጀመሪያውም ወር በዐሥራ አራተኛው ቀን ሠርክ ጀምራችሁ እስከዚሁ ወር ሃያ አንደኛ ቀን ሠርክ ድረስ ቂጣ ትበላላችሁ።'),
  ('2c78fc65-e2ac-54c4-ac39-01214b11da36', '90b6f48f-1500-525a-a128-d4bf40de63d0', '4e0409b7-e243-5aad-a7e9-d90a093ed186', 5, 19, 'ሰባት ቀን በቤታችሁ እርሾ አይገኝ፤ እርሾ ያለበትንም እንጀራ የሚበላ ሁሉ ያ ሰው ከመጻተኛው ጀምሮ እስከ ሀገር ልጁ ድረስ፥ ከእስራኤል ማኅበር ተለይቶ ይጥፋ።'),
  ('2abb9518-966f-5d4a-ac50-016b48c32565', '90b6f48f-1500-525a-a128-d4bf40de63d0', '4e0409b7-e243-5aad-a7e9-d90a093ed186', 6, 20, 'እርሾ ያለበትን ምንም አትብሉ፤ በቤቶቻችሁም ሁሉ ውስጥ ቂጣ ብሉ።”'),
  ('68dc2241-ebb5-5a82-a068-09da487e8d90', '90b6f48f-1500-525a-a128-d4bf40de63d0', '9311c24e-e709-5a7a-a1d5-adc53fda5a79', 1, 21, 'ሙሴም የእስራኤልን ልጆች ሽማግሌዎች ጠርቶ አላቸው፥ “ሂዱና በየወገናችሁ ጠቦት ውሰዱ፤ ለፋሲካም እረዱት።'),
  ('1acd3d8a-528f-5101-ac0e-fca8b85236c2', '90b6f48f-1500-525a-a128-d4bf40de63d0', '9311c24e-e709-5a7a-a1d5-adc53fda5a79', 2, 22, 'ከሂሶጵ ቅጠልም ጭብጥ ውሰዱ፤ በዕቃ ውስጥ ባለውም ደም ንከሩት፤ በዕቃውም ውስጥ ከአለው ደም ሁለቱን መቃኖችና ጉበኑን እርጩ፤ ከእናንተም አንድ ሰው እስኪነጋ ድረስ ከቤቱ ደጅ አይውጣ።'),
  ('a7160cc7-e9a4-56be-ac77-335131b6ebe9', '90b6f48f-1500-525a-a128-d4bf40de63d0', '9311c24e-e709-5a7a-a1d5-adc53fda5a79', 3, 23, 'እግዚአብሔር ግብፃውያንን ይመታ ዘንድ ያልፋልና፤ ደሙንም በጉበኑና በሁለቱ መቃኖች ላይ በአየ ጊዜ እግዚአብሔር በሩን ያልፋል፤ አጥፊውም ይመታችሁ ዘንድ ወደ ቤታችሁ እንዲገባ አይተወውም።'),
  ('19c6f57d-4dce-59f0-a482-8347c5afbda2', '90b6f48f-1500-525a-a128-d4bf40de63d0', '9311c24e-e709-5a7a-a1d5-adc53fda5a79', 4, 24, 'ለእናንተ ለልጆቻችሁም ለዘለዓለም ይሆናችሁ ዘንድ ይህን ሕግ ጠብቁ።'),
  ('c4b8a3a8-ed8b-5630-a764-9a03a714236a', '90b6f48f-1500-525a-a128-d4bf40de63d0', '9311c24e-e709-5a7a-a1d5-adc53fda5a79', 5, 25, 'እግዚአብሔር እንደ ተናገረ ወደሚሰጣችሁ ሀገር በገባችሁ ጊዜ ይህን አምልኮ ጠብቁት።'),
  ('73f81b26-e8a7-5226-a1a7-3e6964bdefbe', '90b6f48f-1500-525a-a128-d4bf40de63d0', '9311c24e-e709-5a7a-a1d5-adc53fda5a79', 6, 26, 'ልጆቻችሁ፦ ‘ይህ ሥርዐት ለእናንተ ምንድር ነው?’ ባሉአችሁ ጊዜ እናንተ፦'),
  ('10684287-e2a9-5fe0-aec6-24e4386646ef', '90b6f48f-1500-525a-a128-d4bf40de63d0', '9311c24e-e709-5a7a-a1d5-adc53fda5a79', 7, 27, '‘ይህ በግብፅ ሀገር የእስራኤልን ልጆች ቤቶች ሰውሮ ግብፃውያንን በመታ ጊዜ፥ ቤቶቻችንን የአዳነ የእግዚአብሔር የፋሲካው መሥዋዕት ነው’ ትሉአቸዋላችሁ።” ሕዝቡም ተጐነበሱ፤ ሰገዱም።'),
  ('a03bef99-8095-5889-a45e-5c10409b0e1b', '90b6f48f-1500-525a-a128-d4bf40de63d0', '9311c24e-e709-5a7a-a1d5-adc53fda5a79', 8, 28, 'የእስራኤልም ልጆች ሄዱ፤ እንዲህም አደረጉ፤ እግዚአብሔር ሙሴንና አሮንን እንደ አዘዛቸው እንዲሁ አደረጉ።'),
  ('da71c906-b62f-532c-a458-1b6ac0050f73', '90b6f48f-1500-525a-a128-d4bf40de63d0', '85e5d1d6-ee30-56d5-ad0f-6d4bb368a9a6', 1, 29, 'እንዲህም ሆነ፤ እኩለ ሌሊት በሆነ ጊዜ እግዚአብሔር በዙፋን ከተቀመጠው ከፈርዖን በኵር ጀምሮ እስከ ውኃ ቀጅዋ ምርኮኛ በኵር ድረስ፥ በግብፅ ምድር በኵሩን ሁሉ፥ የእንስሳውንም በኵር ሁሉ መታ።'),
  ('1dac1777-2087-59d2-a576-c25279993dae', '90b6f48f-1500-525a-a128-d4bf40de63d0', '85e5d1d6-ee30-56d5-ad0f-6d4bb368a9a6', 2, 30, 'ፈርዖንም፥ ሹሞቹም ሁሉ፥ ግብፃውያንም ሁሉ በሌሊት ተነሡ፤ የሞተ የሌለበት ቤት አልነበረምና በግብፅ ምድር ሁሉ ታላቅ ልቅሶ ሆነ።'),
  ('c1a973a9-c901-51d7-ab27-fa2c4a4f8033', '90b6f48f-1500-525a-a128-d4bf40de63d0', '85e5d1d6-ee30-56d5-ad0f-6d4bb368a9a6', 3, 31, 'ፈርዖንም ሙሴንና አሮንን በሌሊት ጠርቶ አላቸው፥ “እናንተ የእስራኤልም ልጆች ተነሡ፤ ከሕዝቤ መካከል ውጡ፤ ሂዱም፤ እንዳላችሁም እግዚአብሔርን አምልኩት፤'),
  ('aaace780-37ef-5af3-af6e-775b2be8d82d', '90b6f48f-1500-525a-a128-d4bf40de63d0', '85e5d1d6-ee30-56d5-ad0f-6d4bb368a9a6', 4, 32, 'በጎቻችሁንም፥ ላሞቻችሁንም ውሰዱ፤ ሂዱም፤ እኔንም ደግሞ ባርኩኝ።”'),
  ('0e7b1ead-cd13-5df3-a873-c92425b4d8d8', '90b6f48f-1500-525a-a128-d4bf40de63d0', '85e5d1d6-ee30-56d5-ad0f-6d4bb368a9a6', 5, 33, 'ግብፃውያንም ፈጥነው ከምድሩ ይወጡ ዘንድ ሕዝቡን ያስቸኩሉአቸው ነበር፥ “ሁላችንም እንሞታለን” ብለዋልና።'),
  ('71b252df-8751-556e-a5e4-b43629dd0f9e', '90b6f48f-1500-525a-a128-d4bf40de63d0', '85e5d1d6-ee30-56d5-ad0f-6d4bb368a9a6', 6, 34, 'ሕዝቡም ሊጡን ሳይቦካ ተሸከሙ፤ ቡሃቃውንም በልብሳቸው ጠቅልለው በትከሻቸው ተሸከሙት።'),
  ('2c129436-c9a8-5b9f-a12b-5bd8cbb72a07', '90b6f48f-1500-525a-a128-d4bf40de63d0', '85e5d1d6-ee30-56d5-ad0f-6d4bb368a9a6', 7, 35, 'የእስራኤልም ልጆች ሙሴ እንዳዘዘ አደረጉ። ከግብፃውያንም የብርንና የወርቅን ዕቃ፥ ልብስንም ተዋሱ።'),
  ('dbd81319-b8af-522c-abeb-291b198cadcf', '90b6f48f-1500-525a-a128-d4bf40de63d0', '85e5d1d6-ee30-56d5-ad0f-6d4bb368a9a6', 8, 36, 'እግዚአብሔርም ለሕዝቡ በግብፃውያን ፊት ሞገስን ሰጠ፤ እነርሱም አዋሱአቸው። እነርሱም ግብፃውያንን በዘበዙአቸው።'),
  ('5c158705-9ed2-52d2-ab44-4c513cf6df75', '90b6f48f-1500-525a-a128-d4bf40de63d0', 'c97774fc-a9bd-51be-af0d-8137ac1ac8f0', 1, 37, 'የእስራኤልም ልጆች ከራምሴ ተነሥተው ወደ ሱኮት ሄዱ፤ ከጓዝ ጋር ካሉት ሌላ ስድስት መቶ ሺህ ሰው የሚያህል እግረኛ ነበረ።'),
  ('10ce2ef6-6fa0-51d7-a0a9-c954abed5c61', '90b6f48f-1500-525a-a128-d4bf40de63d0', 'c97774fc-a9bd-51be-af0d-8137ac1ac8f0', 2, 38, 'ደግሞም ሌላ ብዙ ድብልቅ ሕዝብ፥ መንጎችና ላሞችም እጅግ ብዙም ከብቶች ከእነርሱ ጋር ወጡ።'),
  ('f4c6e277-f7dc-539f-a30b-d0f27b51f93c', '90b6f48f-1500-525a-a128-d4bf40de63d0', 'c97774fc-a9bd-51be-af0d-8137ac1ac8f0', 3, 39, 'ከግብፅም ከእነርሱ ጋር ያወጡትን ሊጥ ቂጣ እንጎቻ አድርገው ጋገሩት። አልቦካም ነበርና፤ ግብፃውያንም ስለ አስወጡአቸው ይቈዩ ዘንድ አልተቻላቸውምና፤ ለመንገድም ስንቅ አላሰናዱም ነበርና።'),
  ('f042657b-fc49-59aa-a680-3cda1aeac4fb', '90b6f48f-1500-525a-a128-d4bf40de63d0', 'c97774fc-a9bd-51be-af0d-8137ac1ac8f0', 4, 40, 'የእስራኤልም ልጆች በግብፅ ምድርና በከነዓን ምድር እነርሱና አባቶቻቸው የተቀመጡት ዘመን አራት መቶ ሠላሳ ዓመት ነው።'),
  ('1e748993-5fe8-5d12-af5e-3f3b7bc740ea', '90b6f48f-1500-525a-a128-d4bf40de63d0', 'c97774fc-a9bd-51be-af0d-8137ac1ac8f0', 5, 41, 'እንዲህም ሆነ፤ አራት መቶ ሠላሳ ዓመት ከተፈጸመ በኋላ የእግዚአብሔር ሠራዊት ሁሉ በሌሊት ከግብፅ ምድር ወጣ።'),
  ('f5a16002-58a2-51e8-a7e7-feaa8bc88c05', '90b6f48f-1500-525a-a128-d4bf40de63d0', 'c97774fc-a9bd-51be-af0d-8137ac1ac8f0', 6, 42, 'ይህች ሌሊት ከግብፅ ምድር ስላወጣቸው ለእግዚአብሔር የተጠበቀች ናት፤ ይህች ሌሊት በእስራኤል ልጆች ሁሉ ዘንድ እስከ ልጅ ልጃቸው ድረስ ለእግዚአብሔር የተጠበቀች ናት።'),
  ('7cdbd1a6-ee8c-543f-af42-ae35b1d6546b', '90b6f48f-1500-525a-a128-d4bf40de63d0', '45bbba22-9da0-503b-a15f-c4f24e67a615', 1, 43, 'እግዚአብሔርም ሙሴንና አሮንን አላቸው፥ “ይህ የፋሲካ ሕግ ነው፤ ከእርሱ ባዕድ ሰው አይብላ።'),
  ('9294bd6f-62ab-53a3-ae87-617761d291ed', '90b6f48f-1500-525a-a128-d4bf40de63d0', '45bbba22-9da0-503b-a15f-c4f24e67a615', 2, 44, 'አገልጋይ ወይም በብር የተገዛ ቢኖር ከተገረዘ በኋላ ያን ጊዜ ከእርሱ ይብላ።'),
  ('741d5f1b-0dac-52b4-a56a-4e9b0ffc9f82', '90b6f48f-1500-525a-a128-d4bf40de63d0', '45bbba22-9da0-503b-a15f-c4f24e67a615', 3, 45, 'ጥገኛና ሞያተኛ ግን ከእርሱ አይብሉ።'),
  ('8ed71e07-e26d-5161-a2ba-1503a99f66b9', '90b6f48f-1500-525a-a128-d4bf40de63d0', '45bbba22-9da0-503b-a15f-c4f24e67a615', 4, 46, 'በአንድ ቤትም ይበላ፤ ከሥጋውም አንዳች ከቤት ወደ ሜዳ አታውጡ፤ አጥንቱንም አትስበሩ።'),
  ('1a8893fb-6c83-54cc-a76f-3115ba5d1154', '90b6f48f-1500-525a-a128-d4bf40de63d0', '45bbba22-9da0-503b-a15f-c4f24e67a615', 5, 47, 'የእስራኤልም ማኅበር ሁሉ ያድርጉት።'),
  ('3a0454df-0a5b-5714-a359-b74f6e85f3c9', '90b6f48f-1500-525a-a128-d4bf40de63d0', '45bbba22-9da0-503b-a15f-c4f24e67a615', 6, 48, 'የእግዚአብሔርን ፋሲካ ያደርግ ዘንድ ወደ እናንተ የመጣ መጻተኛ ቢኖር ወንዱን ሁሉ ትገርዛለህ፤ ያን ጊዜም ፋሲካ ያደርግ ዘንድ ይገባል፤ እንደ ሀገር ልጅም ይሆንላችኋል፤ ያልተገረዘ ሁሉ ግን ከእርሱ አይብላ።'),
  ('28bd4832-62a1-5e03-a0ca-9db342d02dde', '90b6f48f-1500-525a-a128-d4bf40de63d0', '45bbba22-9da0-503b-a15f-c4f24e67a615', 7, 49, 'ለሀገር ልጅ፥ በእናንተ መካከልም ለሚቀመጡ መጻተኞች አንድ ሥርዐት ይሆናል።”'),
  ('043a4390-4cb3-5c46-a327-f1d13ccc09cc', '90b6f48f-1500-525a-a128-d4bf40de63d0', '45bbba22-9da0-503b-a15f-c4f24e67a615', 8, 50, 'የእስራኤልም ልጆች ሁሉ እንዲህ አደረጉ፤ እግዚአብሔር ሙሴንና አሮንን እንደ አዘዘ እንዲሁ አደረጉ።'),
  ('2ac02be3-8091-5a0b-abc8-fdd914811c41', '90b6f48f-1500-525a-a128-d4bf40de63d0', '45bbba22-9da0-503b-a15f-c4f24e67a615', 9, 51, 'በዚያም ቀን እግዚአብሔር የእስራኤልን ልጆች ከሠራዊታቸው ጋር ከግብፅ ምድር አወጣቸው።'),
  ('925f7be0-7091-5062-aca6-77d41c32124f', 'e80c05d0-747d-5ee5-a2f6-1e1dcdd2e291', '7e0573f5-fa89-5243-a145-a78a3ae2aea1', 1, 1, 'እግዚአብሔርም ሙሴን እንዲህ ብሎ ተናገረው፦'),
  ('82f81bf4-8ee6-5f4d-a574-34780c444f52', 'e80c05d0-747d-5ee5-a2f6-1e1dcdd2e291', '7e0573f5-fa89-5243-a145-a78a3ae2aea1', 2, 2, '“በእስራኤል ልጆች ዘንድ ከሰውም፥ ከእንስሳም መጀመሪያ የተወለደውን ማሕፀንን የሚከፍት በኵር ሁሉ ለእኔ ለይልኝ፤ የእኔ ነው።”'),
  ('34ba2ab0-1002-54d7-a547-5985efbb0688', 'e80c05d0-747d-5ee5-a2f6-1e1dcdd2e291', 'a601021d-e82c-5441-a4af-28ba39a0ac86', 1, 3, 'ሙሴም ሕዝቡን አለ፥ “ከባርነት ቤት ከግብፅ የወጣችሁባትን ይህችን ቀን ዐስቡ፤ እግዚአብሔር ከዚህ ቦታ በበረታች እጅ አውጥቶአችኋልና። ስለዚህ የቦካ እንጀራ አትብሉ።'),
  ('a1b34a13-6b2c-58ae-afc1-df626266c238', 'e80c05d0-747d-5ee5-a2f6-1e1dcdd2e291', 'a601021d-e82c-5441-a4af-28ba39a0ac86', 2, 4, 'እናንተ በዚች ቀን በሚያዝያ ወር ወጥታችኋልና።'),
  ('d8ffd4b0-ddcf-5537-af0e-458a56fb822f', 'e80c05d0-747d-5ee5-a2f6-1e1dcdd2e291', 'a601021d-e82c-5441-a4af-28ba39a0ac86', 3, 5, 'እግዚአብሔርም ለእናንተ ይሰጣት ዘንድ ለአባቶቻችሁ ወደማለላቸው፥ ወተትና ማር ወደምታፈስስ ምድር፥ ወደ ከናኔዎናውያን፥ ወደ ኬጢዎናውያንም፥ ወደ አሞሬዎናውያንም፥ ወደ ኤዌዎናውያን፥ ወደ ኢያቡሴዎናውያንም፥ ወደ ጌርጌሴዎናውያንም፥ ወደ ፌርዜዎናውያንም ምድር በአገባችሁ ጊዜ ይህችን ሥርዐት በዚህ ወር አድርጉ።'),
  ('48295372-5cb3-5c13-a62b-419e7e8a6cd3', 'e80c05d0-747d-5ee5-a2f6-1e1dcdd2e291', 'a601021d-e82c-5441-a4af-28ba39a0ac86', 4, 6, 'ስድስት ቀን ቂጣ ትበላላችሁ፤ ሰባተኛውም ቀን የእግዚአብሔር በዓል ይሆናል።'),
  ('5b7fa632-7fae-50fd-a44e-c54c1976daab', 'e80c05d0-747d-5ee5-a2f6-1e1dcdd2e291', 'a601021d-e82c-5441-a4af-28ba39a0ac86', 5, 7, 'ሰባት ቀንም ሙሉ ቂጣ ትበላላችሁ፤ በእናንተም ዘንድ እርሾ ያለበት እንጀራ አይታይ፤ በአውራጃዎቻችሁ ሁሉ እርሾ አይኑር።'),
  ('9a16636d-a2d3-5856-a62f-c6ca2c786432', 'e80c05d0-747d-5ee5-a2f6-1e1dcdd2e291', 'a601021d-e82c-5441-a4af-28ba39a0ac86', 6, 8, 'በዚያም ቀን፦ ‘ከግብፅ በወጣሁ ጊዜ እግዚአብሔር አምላክ ስለአደረገልኝ ነው’ ስትል ለልጅህ ትነግረዋለህ።'),
  ('89d52455-f71e-5d08-a6b2-99d7471be0cc', 'e80c05d0-747d-5ee5-a2f6-1e1dcdd2e291', 'a601021d-e82c-5441-a4af-28ba39a0ac86', 7, 9, 'እግዚአብሔርም በበረታች እጅ ከግብፅ አውጥቶሃልና የእግዚአብሔር ሕግ በአፍህ ይሆን ዘንድ በእጅህ እንደ ምልክት፥ በዐይኖችህም መካከል እንደ መታሰቢያ ይሁንልህ።'),
  ('9cad219d-f774-586e-a6d9-f6f11bac17ee', 'e80c05d0-747d-5ee5-a2f6-1e1dcdd2e291', 'a601021d-e82c-5441-a4af-28ba39a0ac86', 8, 10, 'ከቀን ወደ ቀን በየጊዜው ይህን ሕግ ጠብቁት።'),
  ('9976f2f6-6dcf-5ede-a436-9eabc944700b', 'e80c05d0-747d-5ee5-a2f6-1e1dcdd2e291', 'a601021d-e82c-5441-a4af-28ba39a0ac86', 9, 11, '“እግዚአብሔርም ለአባቶችህ እንደማለ ወደ ከነዓናውያን ምድር በአገባህ ጊዜ፥ እርስዋንም ለአንተ በሰጠህ ጊዜ፥'),
  ('9f3ce538-034b-5ef0-ad23-cae2b591d61a', 'e80c05d0-747d-5ee5-a2f6-1e1dcdd2e291', 'a601021d-e82c-5441-a4af-28ba39a0ac86', 10, 12, 'ማሕፀንን የሚከፍተውን ሁሉ ለይ፤ ከመንጋህና ከከብትህም መጀመሪያ የሚወለደው ተባት ለእግዚአብሔር ይሆናል።'),
  ('c86f7991-0af5-5415-a081-53265ccc88e7', 'e80c05d0-747d-5ee5-a2f6-1e1dcdd2e291', 'a601021d-e82c-5441-a4af-28ba39a0ac86', 11, 13, 'የአህያውን በኵር በበግ ትለውጠዋለህ፤ ባትለውጠው ግን ትዋጀዋለህ። የሰውንም በኵር ሁሉ ከልጆችህ መካከል ትዋጀዋለህ።'),
  ('2b03efae-ec9c-5647-a87a-95e97c3726b0', 'e80c05d0-747d-5ee5-a2f6-1e1dcdd2e291', 'a601021d-e82c-5441-a4af-28ba39a0ac86', 12, 14, 'እንዲህም ይሆናል፤ ከዚህ በኋላ ልጅህ፦ ‘ይህ ምንድን ነው?’ ብሎ በጠየቀህ ጊዜ እንዲህ ትለዋለህ፦ እግዚአብሔር በብርቱ እጅ ከባርነት ቤት ከግብፅ ምድር አወጣን፤'),
  ('5416ce14-739d-5125-a183-185b978f0459', 'e80c05d0-747d-5ee5-a2f6-1e1dcdd2e291', 'a601021d-e82c-5441-a4af-28ba39a0ac86', 13, 15, 'ፈርዖንም እኛን ለመልቀቅ እንቢ ባለ ጊዜ እግዚአብሔር ከሰው በኵር ጀምሮ እስከ እንስሳ በኵር ድረስ በግብፅ ምድር ያለውን በኵር ሁሉ ገደለ፤ ስለዚህ ወንድ ሆኖ ማሕፀንን የከፈተውን ሁሉ ለእግዚአብሔር እሠዋለሁ፤ ነገር ግን የልጆችን በኵር ሁሉ እዋጃለሁ።’'),
  ('0ae3e32a-73f7-5201-a5bc-4d5a60421cf0', 'e80c05d0-747d-5ee5-a2f6-1e1dcdd2e291', 'a601021d-e82c-5441-a4af-28ba39a0ac86', 14, 16, 'እግዚአብሔርም በብርቱ እጅ ከግብፅ አውጥቶሃልና በእጅህ እንደ ምልክት ፥ ከዐይኖችህም እንደማይርቅ ነገር ይሁንልህ።”'),
  ('61b08ff3-9ed2-52b0-af3c-7256dd10783c', 'e80c05d0-747d-5ee5-a2f6-1e1dcdd2e291', '2a976b6e-f216-5cb5-a36c-bd6aae707765', 1, 17, 'እንዲህም ሆነ፤ ፈርዖን ሕዝቡን በለቀቀ ጊዜ፥ ምንም ቅርብ ቢሆን እግዚአብሔር በፍልስጥኤማውያን ምድር መንገድ አልመራቸውም፤ እግዚአብሔር፥ “ሕዝቡ ሰልፉን በአየ ጊዜ እንዳይጸጽተው፥ ወደ ግብፅም እንዳይመለስ” ብሎአልና።'),
  ('b39ffce8-f7bf-5290-a190-00833783403d', 'e80c05d0-747d-5ee5-a2f6-1e1dcdd2e291', '2a976b6e-f216-5cb5-a36c-bd6aae707765', 2, 18, 'ነገር ግን እግዚአብሔር ሕዝቡን በዙሪያ መንገድ በኤርትራ ባሕር ባለችው ምድረ በዳ መራቸው። የእስራኤልም ልጆች በአምስተኛው ትውልድ ከግብፅ ምድር ወጡ።'),
  ('4566e3b7-7f23-58d0-a393-f5955efd810d', 'e80c05d0-747d-5ee5-a2f6-1e1dcdd2e291', '2a976b6e-f216-5cb5-a36c-bd6aae707765', 3, 19, 'ሙሴም የዮሴፍን ዐጽም ከእርሱ ጋር ወሰደ፥ “እግዚአብሔር መጐብኘትን በጐበኛችሁ ጊዜ ዐጽሜን ውሰዱ፤ ከእናንተም ጋር ከዚህ አውጡ” ብሎ የእስራኤልን ልጆች አምሎአቸው ነበርና።'),
  ('2ea2055e-6eaf-5784-a03c-b5bc4a63f4ac', 'e80c05d0-747d-5ee5-a2f6-1e1dcdd2e291', '2a976b6e-f216-5cb5-a36c-bd6aae707765', 4, 20, 'የእስራኤል ልጆችም ከሱኮት ተጓዙ፤ በምድረ በዳውም ዳር በኦቶም ሰፈሩ።'),
  ('c0b90ff9-bc16-5f87-add6-6a1448a1017f', 'e80c05d0-747d-5ee5-a2f6-1e1dcdd2e291', '2a976b6e-f216-5cb5-a36c-bd6aae707765', 5, 21, 'እግዚአብሔርም መንገድ ሊያሳያቸው ቀን በዐምደ ደመና፥ ሌሊትም በዐምደ እሳት ይመራቸው ነበር።'),
  ('ecc89966-882b-58b7-a771-26064933ab60', 'e80c05d0-747d-5ee5-a2f6-1e1dcdd2e291', '2a976b6e-f216-5cb5-a36c-bd6aae707765', 6, 22, 'ዐምደ ደመናው በቀን፥ ዐምደ እሳቱም በሌሊት ከሕዝቡ ፊት ከቶ ፈቀቅ አላለም።'),
  ('4818ad04-4303-564a-a0d6-5c59c8389f84', 'f1a278db-ae68-5e1a-ad38-a324666e882f', '8dc3ee24-5266-58f4-a023-637f3bd6dd7f', 1, 1, 'እግዚአብሔርም ሙሴን እንዲህ ብሎ ተናገረው፦'),
  ('ca0b2996-333f-5eb5-aeb5-f4b6f5b1e2e0', 'f1a278db-ae68-5e1a-ad38-a324666e882f', '8dc3ee24-5266-58f4-a023-637f3bd6dd7f', 2, 2, '“ተመልሰው በመግደሎና በባሕር መካከል፥ በብኤልሴፎን ፊት ለፊት ባለው ገላጣ መንደር አንጻር እንዲሰፍሩ ለእስራኤል ልጆች ተናገር፤ ከእርሱም አጠገብ በባሕር ዳር ትሰፍራላችሁ።'),
  ('d8de5707-712b-50a1-a72c-76690a09e216', 'f1a278db-ae68-5e1a-ad38-a324666e882f', '8dc3ee24-5266-58f4-a023-637f3bd6dd7f', 3, 3, 'ፈርዖንም ለሕዝቡ ስለ እስራኤል ልጆች፦ ‘በምድር ይቅበዘበዛሉ፤ ምድረ በዳም ዘጋቻቸው’ ይላል።'),
  ('521a4de4-90a4-5295-a0e7-8e4b0755d6f0', 'f1a278db-ae68-5e1a-ad38-a324666e882f', '8dc3ee24-5266-58f4-a023-637f3bd6dd7f', 4, 4, 'እኔም የፈርዖንን ልብ አጸናለሁ፤ እርሱም ከኋላቸው ይከተላቸዋል፤ እኔም በፈርዖንና በሠራዊቱ ሁሉ ላይ እከብራለሁ፤ ግብፃውያንም ሁሉ እኔ እግዚአብሔር እንደ ሆንሁ ያውቃሉ።” እነርሱም እንዲሁ አደረጉ።'),
  ('bf2b0165-1bdd-550e-a6de-dcb65bc507d4', 'f1a278db-ae68-5e1a-ad38-a324666e882f', '8dc3ee24-5266-58f4-a023-637f3bd6dd7f', 5, 5, 'ሕዝቡም እንደ ኰበለሉ ለግብፅ ንጉሥ ነገሩት፤ የፈርዖንና የሹሞቹም ልብ በሕዝቡ ላይ ተለወጠና፥ “እንዳይገዙልን የእስራኤልን ልጆች የለቀቅነው ምን ማድረጋችን ነው?” አሉ።'),
  ('4a7b33df-9439-576b-a9bd-43cbb21bbe85', 'f1a278db-ae68-5e1a-ad38-a324666e882f', '8dc3ee24-5266-58f4-a023-637f3bd6dd7f', 6, 6, 'ፈርዖንም ሰረገላውን አሰናዳ፤ ሕዝቡንም ከእርሱ ጋር ሰበሰበ።'),
  ('539b8905-266c-594a-ab9e-24efae292677', 'f1a278db-ae68-5e1a-ad38-a324666e882f', '8dc3ee24-5266-58f4-a023-637f3bd6dd7f', 7, 7, 'ስድስት መቶ የተመረጡ ሰረገሎችንም፥ የግብፅንም ፈረሶች ሁሉ ወስዶ ሁሉንም ከሦስት ከፈላቸው።'),
  ('e88d9a79-1a7a-576a-a76e-d79be34d619f', 'f1a278db-ae68-5e1a-ad38-a324666e882f', '8dc3ee24-5266-58f4-a023-637f3bd6dd7f', 8, 8, 'እግዚአብሔርም የግብፅን ንጉሥ የፈርዖንንና የሹሞቹን ልብ አጸና፤ እርሱም የእስራኤልን ልጆች አሳደደ፤ የእስራኤልም ልጆች ከፍ ባለች እጅ ወጡ።'),
  ('d5939f15-4994-5347-a1bc-1122f2071dfe', 'f1a278db-ae68-5e1a-ad38-a324666e882f', '8dc3ee24-5266-58f4-a023-637f3bd6dd7f', 9, 9, 'ግብፃውያንም፥ የፈርዖን ፈረሶች፥ ሰረገሎቹም፥ ፈረሰኞቹም፥ ሠራዊቱም ሁሉ አሳደዱአቸው፤ በባሕሩ ዳር በብኤልሴፎን ፊት ለፊት ባለው ገላጣ መንደር አንጻርም ሰፍረው አገኙአቸው።'),
  ('97f30772-4687-5ee4-a27f-bfe0275378f5', 'f1a278db-ae68-5e1a-ad38-a324666e882f', '8dc3ee24-5266-58f4-a023-637f3bd6dd7f', 10, 10, 'ፈርዖንም በቀረበ ጊዜ የእስራኤል ልጆች ዐይናቸውን አነሡ፤ እነሆም፥ ግብፃውያን ሲከተሉአቸው አዩ፤ የእስራኤልም ልጆች እጅግ ፈሩ፤ የእስራኤልም ልጆች ወደ እግዚአብሔር ጮኹ።'),
  ('3839f8a3-c9b9-5f9b-a766-ceb771d0913a', 'f1a278db-ae68-5e1a-ad38-a324666e882f', '8dc3ee24-5266-58f4-a023-637f3bd6dd7f', 11, 11, 'ሙሴንም አሉት፥ “በግብፅ መቃብር ስላልኖረ በምድረ በዳ እንሞት ዘንድ አወጣኸን? ከግብፅ ታወጣን ዘንድ ይህ ያደረግህብን ምንድን ነው?'),
  ('d670799f-b73b-52d0-ac47-aa61f3c50750', 'f1a278db-ae68-5e1a-ad38-a324666e882f', '8dc3ee24-5266-58f4-a023-637f3bd6dd7f', 12, 12, 'በምድረ በዳ ከምንሞት ብንገዛላቸው ይሻለናልና፦ ‘ተወን፤ ለግብፃውያን እንገዛ’ ብለን በግብፅ ሳለን ያልንህ ቃል ይህ አይደለምን?”'),
  ('05aa21b9-6da8-5842-abfd-dde0adb48321', 'f1a278db-ae68-5e1a-ad38-a324666e882f', '8dc3ee24-5266-58f4-a023-637f3bd6dd7f', 13, 13, 'ሙሴም ለሕዝቡ፥ “አትፍሩ፤ ዛሬ የምታዩአቸውን ግብፃውያንን ለዘለዓለም አታዩአቸውምና ቁሙ፤ ዛሬ ለእናንተ የሚያደርጋትን የእግዚአብሔርን ማዳን እዩ።'),
  ('34967c11-5342-54d7-adb3-a1ab04498245', 'f1a278db-ae68-5e1a-ad38-a324666e882f', '8dc3ee24-5266-58f4-a023-637f3bd6dd7f', 14, 14, 'እግዚአብሔር ስለ እናንተ ይዋጋል፤ እናንተም ዝም ትላላችሁ” አላቸው።'),
  ('1b998045-9960-5708-ab99-07fd4f3c1546', 'f1a278db-ae68-5e1a-ad38-a324666e882f', '8dc3ee24-5266-58f4-a023-637f3bd6dd7f', 15, 15, 'እግዚአብሔርም ሙሴን አለው፥ “ለምን ትጮኽብኛለህ? ከብቶቻቸውን እንዲነዱ ለእስራኤል ልጆች ንገር።'),
  ('9307fd62-633c-5c8f-acff-dad807b74650', 'f1a278db-ae68-5e1a-ad38-a324666e882f', '8dc3ee24-5266-58f4-a023-637f3bd6dd7f', 16, 16, 'አንተም በትርህን አንሣ፤ እጅህንም በባሕሩ ላይ ዘርጋ፤ ክፈለውም፤ የእስራኤልም ልጆች በባሕሩ ውስጥ በየብስ ያልፋሉ።'),
  ('e2518bac-2273-58e8-aed7-ca1c48be43e4', 'f1a278db-ae68-5e1a-ad38-a324666e882f', '8dc3ee24-5266-58f4-a023-637f3bd6dd7f', 17, 17, 'እነሆም፥ እኔ የፈርዖንንና የግብፃውያንን ልብ አጸናለሁ፤ በኋላቸውም ይገባሉ፤ በፈርዖንና በሠራዊቱም ሁሉ፥ በሰረገሎቹም፥ በፈረሰኞቹም ላይ እከብራለሁ።'),
  ('e8cd85f3-9bf7-52dd-a981-9be4dc292f1a', 'f1a278db-ae68-5e1a-ad38-a324666e882f', '8dc3ee24-5266-58f4-a023-637f3bd6dd7f', 18, 18, 'ግብፃውያንም በፈርዖንና በሰረገሎቹ፥ በፈረሰኞቹም ላይ ክብር በአገኘሁ ጊዜ እኔ እግዚአብሔር እንደ ሆንሁ ያውቃሉ።”'),
  ('641e2454-b0d9-5eed-a7e6-6c0d9572b6e4', 'f1a278db-ae68-5e1a-ad38-a324666e882f', '8dc3ee24-5266-58f4-a023-637f3bd6dd7f', 19, 19, 'በእስራኤልም ሠራዊት ፊት ይሄድ የነበረው የእግዚአብሔር መልአክ ፈቀቅ ብሎ በኋላቸው ሄደ፤ የደመናውም ዐምድ ከፊታቸው ፈቀቅ ብሎ በኋላቸው ቆመ፤'),
  ('570ea347-023c-519c-a418-9e89902418b0', 'f1a278db-ae68-5e1a-ad38-a324666e882f', '8dc3ee24-5266-58f4-a023-637f3bd6dd7f', 20, 20, 'በግብፃውያን ሰፈርና በእስራኤል ሰፈር መካከልም ገባ፤ በዚያም ጭጋግና ጨለማ ነበረ፤ ሌሊቱም አለፈ፤ ሌሊቱንም ሁሉ እርስ በእርሳቸው አልተቃረቡም።'),
  ('47406b2b-eac6-564e-a273-96e965cabfe2', 'f1a278db-ae68-5e1a-ad38-a324666e882f', '8dc3ee24-5266-58f4-a023-637f3bd6dd7f', 21, 21, 'ሙሴም በባሕሩ ላይ እጁን ዘረጋ፤ እግዚአብሔርም ሌሊቱን ሁሉ ጽኑ የአዜብ ነፋስ አምጥቶ ባሕሩን አስወገደው፤ ባሕሩንም አደረቀው፤ ውኃውም ተከፈለ።'),
  ('6c4ce0f6-31f7-5c08-ab1e-45fdb8e5101e', 'f1a278db-ae68-5e1a-ad38-a324666e882f', '8dc3ee24-5266-58f4-a023-637f3bd6dd7f', 22, 22, 'የእስራኤልም ልጆች በባሕሩ መካከል በየብስ ገቡ፤ ውኃውም በቀኛቸውና በግራቸው እንደ ግድግዳ ሆነላቸው።'),
  ('fc20c298-c8d4-5bbc-ad9d-429d5edc8023', 'f1a278db-ae68-5e1a-ad38-a324666e882f', '8dc3ee24-5266-58f4-a023-637f3bd6dd7f', 23, 23, 'ግብፃውያንም፥ የፈርዖን ፈረሶችና ሰረገሎች፥ ፈረሰኞቹም ሁሉ እያሳደዱ በኋላቸው ወደ ባሕር መካከል ገቡ።'),
  ('6870b607-852f-5e2f-af22-52992b8763a7', 'f1a278db-ae68-5e1a-ad38-a324666e882f', '8dc3ee24-5266-58f4-a023-637f3bd6dd7f', 24, 24, 'ንጋትም በሆነ ጊዜ እግዚአብሔር በእሳትና በደመና ዐምድ ሆኖ የግብፃውያንን ሠራዊት ተመለከተ፤ የግብፃውያንንም ሠራዊት አወከ።'),
  ('0319f7cb-94cb-513e-acc5-c4faa967297f', 'f1a278db-ae68-5e1a-ad38-a324666e882f', '8dc3ee24-5266-58f4-a023-637f3bd6dd7f', 25, 25, 'የሰረገሎቹንም መንኰራኵር አሰረ፤ ወደ ጭንቅም አገባቸው፤ ግብፃውያንም፥ “እግዚአብሔር ስለ እነርሱ ይዋጋላቸዋልና ከእስራኤል ፊት እንሽሽ” አሉ።'),
  ('fba322c2-258e-58e0-a357-93277a036ae4', 'f1a278db-ae68-5e1a-ad38-a324666e882f', '3fa9ffb9-5d07-5d87-ab35-f662958d79c2', 1, 26, 'እግዚአብሔርም ሙሴን አለው፥ “እጅህን በባሕሩ ላይ ዘርጋ፤ ውኃውም በግብፃውያን፥ በሰረገሎቻቸውም፥ በፈረሰኞቻቸውም ላይ ይመለስ፤ ይሸፍናቸውም።”'),
  ('2a2d7368-ab2e-5980-a6bb-a8debc94cb71', 'f1a278db-ae68-5e1a-ad38-a324666e882f', '3fa9ffb9-5d07-5d87-ab35-f662958d79c2', 2, 27, 'ሙሴም እጁን በባሕሩ ላይ ዘረጋ፤ ባሕሩም ማለዳ ወደ መፍሰሱ ተመለሰ፤ ግብፃውያንም ከእርሱ ሸሹ፤ እግዚአብሔርም ግብፃውያንን በባሕሩ መካከል ጣላቸው።'),
  ('f01523af-1326-506c-a54b-a79601be5857', 'f1a278db-ae68-5e1a-ad38-a324666e882f', '3fa9ffb9-5d07-5d87-ab35-f662958d79c2', 3, 28, 'ውኃውም ተመልሶ በኋላቸው ወደ ባሕር የገቡትን ሰረገሎችን፥ ፈረሰኞችንም፥ የፈርዖንንም ሠራዊት ሁሉ ከደነ፤ ከመጡትም ሁሉ አንድ ስንኳ የቀረ የለም።'),
  ('59a88bbc-859e-5e52-ad41-459a5ee97fff', 'f1a278db-ae68-5e1a-ad38-a324666e882f', '3fa9ffb9-5d07-5d87-ab35-f662958d79c2', 4, 29, 'የእስራኤል ልጆች ግን በባሕሩ ውስጥ በየብስ ሄዱ፤ ውኃውም በቀኛቸውና በግራቸው እንደ ግድግዳ ሆነላቸው።'),
  ('1979ce2f-5b6e-5ee0-a02d-e8cb25e8809d', 'f1a278db-ae68-5e1a-ad38-a324666e882f', '3fa9ffb9-5d07-5d87-ab35-f662958d79c2', 5, 30, 'እግዚአብሔርም በዚያ ቀን እስራኤልን ከግብፃውያን እጅ አዳናቸው፤ እስራኤልም ግብፃውያን እንደ ሞቱ በባሕር ዳር አዩ።'),
  ('72fcaa93-9a4c-500d-ae35-6d4716f324ee', 'f1a278db-ae68-5e1a-ad38-a324666e882f', '3fa9ffb9-5d07-5d87-ab35-f662958d79c2', 6, 31, 'እስራኤልም እግዚአብሔር በግብፃውያን ላይ ያደረጋትን ታላቂቱን እጅ አዩ፤ ሕዝቡም እግዚአብሔርን ፈሩ፤ በእግዚአብሔርም አመኑ፤ ባሪያውንም ሙሴን አከበሩ።'),
  ('9c147db5-8217-5fd2-a679-b8caf45b3944', 'efd3491f-0a49-58d2-a217-815b0527b4c4', '829ad789-0551-56df-a99a-1d694480f465', 1, 1, 'በዚያ ጊዜም ሙሴና የእስራኤል ልጆች ይህን መዝሙር ለእግዚአብሔር ዘመሩ፤ እንዲህም ብለው ተናገሩ፦'),
  ('c1cf1fd5-901e-5eae-aa12-f5f06ecba57b', 'efd3491f-0a49-58d2-a217-815b0527b4c4', '829ad789-0551-56df-a99a-1d694480f465', 2, 2, 'እኔን ለማዳን ረዳትና ሰዋሪ ሆነኝ፤'),
  ('ce826ccf-aa95-50ae-afd2-af2a36925866', 'efd3491f-0a49-58d2-a217-815b0527b4c4', '829ad789-0551-56df-a99a-1d694480f465', 3, 3, 'እግዚአብሔር ጦርነትን ያጠፋል፤ ስሙም እግዚአብሔር ነው፤'),
  ('6fc4bbf5-d59e-5c05-a214-087696b30a4e', 'efd3491f-0a49-58d2-a217-815b0527b4c4', '829ad789-0551-56df-a99a-1d694480f465', 4, 4, 'የፈርዖንን ሰረገሎች፥ ሠራዊቱንም በባሕር ጣላቸው።'),
  ('f420055f-606d-5628-a18c-a1e6c5e92ea9', 'efd3491f-0a49-58d2-a217-815b0527b4c4', '829ad789-0551-56df-a99a-1d694480f465', 5, 5, 'ማዕበልም ከደናቸው፤'),
  ('a085429b-8e78-52ff-a327-86236a1b40ab', 'efd3491f-0a49-58d2-a217-815b0527b4c4', '829ad789-0551-56df-a99a-1d694480f465', 6, 6, 'አቤቱ፥ ቀኝህ በኀይል ከበረ፤'),
  ('e63ad5d7-c210-554f-a13e-e962d65b1a2f', 'efd3491f-0a49-58d2-a217-815b0527b4c4', '829ad789-0551-56df-a99a-1d694480f465', 7, 7, 'በክብርህም ብዛት ጠላቶችህን አጠፋህ፤'),
  ('7b416c88-a464-58ca-a064-d17021729952', 'efd3491f-0a49-58d2-a217-815b0527b4c4', '829ad789-0551-56df-a99a-1d694480f465', 8, 8, 'በቍጣህ እስትንፋስ ውኃው ቆመ፤'),
  ('59f9cc20-7477-5dd2-a5f5-b2b6b8012acf', 'efd3491f-0a49-58d2-a217-815b0527b4c4', '829ad789-0551-56df-a99a-1d694480f465', 9, 9, 'ጠላትም፦ ‘አሳድጄ እይዛቸዋለሁ፤'),
  ('73426e16-9720-5440-a8d9-0fa0c5d8b1e1', 'efd3491f-0a49-58d2-a217-815b0527b4c4', '829ad789-0551-56df-a99a-1d694480f465', 10, 10, 'ነፋስህን ላክህ፤ ባሕርም ከደናቸው፤'),
  ('fd5e4515-a6d9-5bba-ae0b-e1507b24afca', 'efd3491f-0a49-58d2-a217-815b0527b4c4', '829ad789-0551-56df-a99a-1d694480f465', 11, 11, 'አቤቱ፦ በአማልክት መካከል አንተን የሚመስል ማን ነው?'),
  ('e8ea59bd-e40b-5f81-aaa2-9f5adf3a4b90', 'efd3491f-0a49-58d2-a217-815b0527b4c4', '829ad789-0551-56df-a99a-1d694480f465', 12, 12, 'ቀኝህን ዘረጋህ፤ ምድርም ዋጠቻቸው።'),
  ('b225e2f7-a280-58ca-a747-0fadce95d83e', 'efd3491f-0a49-58d2-a217-815b0527b4c4', '829ad789-0551-56df-a99a-1d694480f465', 13, 13, 'በቸርነትህ የተቤዠሃቸውን ሕዝብህን መራህ፤'),
  ('8e0e49ce-d795-54f3-a195-48fe6ef0bbf7', 'efd3491f-0a49-58d2-a217-815b0527b4c4', '829ad789-0551-56df-a99a-1d694480f465', 14, 14, 'አሕዛብ ሰሙ፤ ተቈጡም፤'),
  ('6b7de5b2-c177-5b2e-aec3-50b774f2320f', 'efd3491f-0a49-58d2-a217-815b0527b4c4', '829ad789-0551-56df-a99a-1d694480f465', 15, 15, 'ያን ጊዜ የኤዶም አለቆች ሸሹ፤'),
  ('27d9170f-d308-5dc9-a299-9aaa6a041c9f', 'efd3491f-0a49-58d2-a217-815b0527b4c4', '829ad789-0551-56df-a99a-1d694480f465', 16, 16, 'ፍርሀትና ድንጋጤ ወደቀባቸው፤'),
  ('97500eb1-947e-50c5-a0b8-e415c0c50c7d', 'efd3491f-0a49-58d2-a217-815b0527b4c4', '829ad789-0551-56df-a99a-1d694480f465', 17, 17, 'አቤቱ፥ አንተ ታስገባቸዋለህ፤'),
  ('e52ae716-3331-509b-ac57-051a7108ba05', 'efd3491f-0a49-58d2-a217-815b0527b4c4', '829ad789-0551-56df-a99a-1d694480f465', 18, 18, 'እግዚአብሔር ለዘለዓለም እስከ ዘለዓለምም ይነግሣል።'),
  ('082505bb-00da-5a07-a13e-630b9f90185a', 'efd3491f-0a49-58d2-a217-815b0527b4c4', '4984da74-6a10-54fc-aa79-5e5f17bb511c', 1, 19, '“የፈርዖን ፈረሶች ከሰረገሎቹና ከፈረሰኞቹ ጋር ወደ ባሕር ገቡ፤ እግዚአብሔርም የባሕሩን ውኆች መለሰባቸው፤ የእስራኤል ልጆች ግን በባሕሩ መካከል በየብስ አለፉ፤ ውኃውም ለእነርሱ በቀኝ እንደ ግድግዳ፥ በግራም እንደ ግድግዳ ሆነላቸው።”'),
  ('a5405e74-173b-5d34-a54d-1f022da471fd', 'efd3491f-0a49-58d2-a217-815b0527b4c4', '4984da74-6a10-54fc-aa79-5e5f17bb511c', 2, 20, 'የአሮን እኅት ነቢይቱ ማርያምም ከበሮ በእጅዋ ወሰደች፤ ሴቶችም ሁሉ በከበሮና በዝማሬ በኋላዋ ወጡ።'),
  ('87db44d9-58f9-511f-a045-740fca921b55', 'efd3491f-0a49-58d2-a217-815b0527b4c4', '4984da74-6a10-54fc-aa79-5e5f17bb511c', 3, 21, 'ማርያምም አስቀድማ ለእግዚአብሔር እንዘምር አለች፥ “ለእግዚአብሔር እንዘምር በክብር እጅግ ከፍ ከፍ ብሎአልና፤ ፈረሱንና ፈረሰኛውን በባሕር ጥሎአልና።”'),
  ('bb75f4c2-249f-589f-a632-244a142a2f00', 'efd3491f-0a49-58d2-a217-815b0527b4c4', '1c40f8c1-7846-5dc7-ae93-e3ae0193aa89', 1, 22, 'ሙሴም የእስራኤልን ልጆች ከኤርትራ ባሕር አውጥቶ ወደ ሱር ምድረ በዳ ወሰዳቸው። በምድረ በዳም ሦስት ቀን ተጓዙ፤ ይጠጡም ዘንድ ውኃ አላገኙም።'),
  ('8678f7df-43f6-5488-acbe-96c379a941fd', 'efd3491f-0a49-58d2-a217-815b0527b4c4', '1c40f8c1-7846-5dc7-ae93-e3ae0193aa89', 2, 23, 'ወደ ማራም በመጡ ጊዜ ከማራ ውኃ ሊጠጡ አልቻሉም፤ ውኃው መራራ ነበርና፤ ስለዚህ የዚያ ስፍራ ስም “መሪር” ተብሎ ተጠራ።'),
  ('811a7ebe-2c3b-5cf7-aa8f-81f3f5b769e7', 'efd3491f-0a49-58d2-a217-815b0527b4c4', '1c40f8c1-7846-5dc7-ae93-e3ae0193aa89', 3, 24, 'ሕዝቡም፥ “ምን እንጠጣለን?” ብለው በሙሴ ላይ አንጐራጐሩ።'),
  ('83416f87-6471-5d4e-aaad-331fb66fc12a', 'efd3491f-0a49-58d2-a217-815b0527b4c4', '1c40f8c1-7846-5dc7-ae93-e3ae0193aa89', 4, 25, 'ሙሴም ወደ እግዚአብሔር ጮኸ፤ እግዚአብሔርም ዕንጨትን አሳየው፤ በውኃውም ላይ ጣለው፤ ውኃውም ጣፈጠ። በዚያም ሥርዐትንና ፍርድን አደረገላቸው፤ በዚያም ፈተናቸው።'),
  ('153650d6-a90e-5d4e-a8a1-3c439bc510d3', 'efd3491f-0a49-58d2-a217-815b0527b4c4', '1c40f8c1-7846-5dc7-ae93-e3ae0193aa89', 5, 26, 'እርሱም፥ “አንተ የአምላክህን የእግዚአብሔርን ቃል አጥብቀህ ብትሰማ፥ በፊቱም መልካምን ብታደርግ፥ ትእዛዙንም ብታደምጥ፥ ሥርዐቱንም ሁሉ ብትጠብቅ፥ በግብፃውያን ላይ ያመጣሁትን በሽታ አላደርስብህም፤ እኔ ፈዋሽህ እግዚአብሔር ነኝና” አለ።'),
  ('330aa33d-98d4-55d9-afe4-41e97668c600', 'efd3491f-0a49-58d2-a217-815b0527b4c4', '1c40f8c1-7846-5dc7-ae93-e3ae0193aa89', 6, 27, 'እነርሱም ወደ ኤሎም መጡ፤ በዚያም ዐሥራ ሁለት የውኃ ምንጮችና ሰባ የዘንባባ ዛፎች ነበሩባት፤ በዚያም በውኃው አጠገብ ሰፈሩ።'),
  ('92c7c34c-e3a8-5b77-a928-261ea230108b', 'b72ca4e8-28f1-566d-a44a-685af15b860e', '825c261a-3c3f-5e1b-a962-7d0a38a8594b', 1, 1, 'የእስራኤልም ልጆች ማኅበር ሁሉ ከኤሎም ተጓዙ፤ ከግብፅ ሀገር ከወጡ በኋላ በሁለተኛው ወር ከወሩም በዐሥራ አምስተኛው ቀን በኤሎምና በሲና መካከል ወዳለችው ወደ ሲን ምድረ በዳ መጡ።'),
  ('63bee473-5327-5542-ac4d-547d4fc401ce', 'b72ca4e8-28f1-566d-a44a-685af15b860e', '825c261a-3c3f-5e1b-a962-7d0a38a8594b', 2, 2, 'የእስራኤልም ልጆች ማኅበር ሁሉ በሙሴና በአሮን ላይ አንጐራጐሩ።'),
  ('0dbf86ae-41f3-5597-abdb-a45f4033d1ad', 'b72ca4e8-28f1-566d-a44a-685af15b860e', '825c261a-3c3f-5e1b-a962-7d0a38a8594b', 3, 3, 'የእስራኤልም ልጆች አሉአቸው፥ “በሥጋው ምንቸት አጠገብ ተቀምጠን እስክንጠግብ ድረስ እንጀራና ሥጋ በምንበላበት ጊዜ በግብፅ ምድር በእግዚአብሔር እጅ ምነው በሞትን! ይህን ጉባኤ ሁሉ በራብ ልትገድሉ እኛን ወደዚች ምድረ በዳ አምጥታችኋልና።”'),
  ('56c4fac9-d0a2-5e00-a163-826fd4874d3e', 'b72ca4e8-28f1-566d-a44a-685af15b860e', '825c261a-3c3f-5e1b-a962-7d0a38a8594b', 4, 4, 'እግዚአብሔርም ሙሴን፥ “በሕጌ ይሄዱ ወይም አይሄዱ እንደ ሆነ እኔ እንድፈትናቸው፥ እነሆ፥ ከሰማይ እንጀራን አዘንብላችኋለሁ፤ ሕዝቡም ወጥተው ለዕለት ለዕለት የሚበቃቸውን ይሰብስቡ።'),
  ('5fa559fb-2f64-58d7-a389-54437859ee52', 'b72ca4e8-28f1-566d-a44a-685af15b860e', '825c261a-3c3f-5e1b-a962-7d0a38a8594b', 5, 5, 'እንዲህም ይሆናል፤ በስድስተኛው ቀን ያመጡትን ያዘጋጁ፤ ዕለት ዕለትም ከሚለቅሙት ይልቅ ሁለት እጥፍ ይሁን” አለው።'),
  ('d0ec46f9-07eb-5422-aba1-2130079fd3f3', 'b72ca4e8-28f1-566d-a44a-685af15b860e', '825c261a-3c3f-5e1b-a962-7d0a38a8594b', 6, 6, 'ሙሴና አሮንም ለእስራኤል ልጆች ሁሉ፥ “እግዚአብሔር ከግብፅ ምድር እንደ አወጣችሁ ማታ ታውቃላችሁ፤'),
  ('aefb0253-8fca-5d01-a533-6c4dc7e26c20', 'b72ca4e8-28f1-566d-a44a-685af15b860e', '825c261a-3c3f-5e1b-a962-7d0a38a8594b', 7, 7, 'የእግዚአብሔርንም ክብር ጥዋት ታያላችሁ፤ በእግዚአብሔር ላይ ያንጐራጐራችሁትን ሰምቶአልና፤ በእኛም ላይ የምታንጐራጕሩ እኛ ምንድን ነን?” አሉ።'),
  ('62a018b2-b599-5d51-a2fd-b268b79d0e99', 'b72ca4e8-28f1-566d-a44a-685af15b860e', '825c261a-3c3f-5e1b-a962-7d0a38a8594b', 8, 8, 'ሙሴም፥ “እግዚአብሔር ያንጐራጐራችሁበትን ማንጐራጐራችሁን ሰምቶአልና በመሸ ጊዜ ትበሉ ዘንድ ሥጋን፥ በማለዳም ትጠግቡ ዘንድ እንጀራን እግዚአብሔር ይሰጣችኋል፤ እኛም ምንድን ነን? ማንጐራጐራችሁ በእግዚአብሔር ላይ ነው እንጂ በእኛ ላይ አይደለም” አለ።'),
  ('b5c7ac92-60d3-528b-a29a-dc037f74a8e5', 'b72ca4e8-28f1-566d-a44a-685af15b860e', '825c261a-3c3f-5e1b-a962-7d0a38a8594b', 9, 9, 'ሙሴም አሮንን፥ “ለእስራኤል ልጆች ማኅበር ሁሉ፦ ‘ማንጐራጐራችሁን ሰምቶአልና ወደ እግዚአብሔር ፊት ቅረቡ’ በል” አለው።'),
  ('f48e479b-e2fc-575e-aefa-b97e877e9409', 'b72ca4e8-28f1-566d-a44a-685af15b860e', '825c261a-3c3f-5e1b-a962-7d0a38a8594b', 10, 10, 'አሮንም ለእስራኤል ልጆች ማኅበር ሁሉ በተናገረ ጊዜ ወደ ምድረ በዳ ፊታቸውን አቀኑ፤ እነሆም፥ የእግዚአብሔር ክብር በደመናው ታየ።'),
  ('79d6e1a0-f90e-5a3e-a94c-845063ba1b8a', 'b72ca4e8-28f1-566d-a44a-685af15b860e', '825c261a-3c3f-5e1b-a962-7d0a38a8594b', 11, 11, 'እግዚአብሔርም ሙሴን አለው፦'),
  ('5fc5aee3-aecc-5495-a4a2-c55044534d28', 'b72ca4e8-28f1-566d-a44a-685af15b860e', '825c261a-3c3f-5e1b-a962-7d0a38a8594b', 12, 12, '“የእስራኤልን ልጆች ማንጐራጐር ሰማሁ፦ ማታ ሥጋን ትበላላችሁ፤ ማለዳም እንጀራን ትጠግባላችሁ፤ እኔም እግዚአብሔር አምላካችሁ እንደ ሆንሁ ታውቃላችሁ በላቸው።”'),
  ('a665b952-8581-52ef-a8e4-25be28af02bd', 'b72ca4e8-28f1-566d-a44a-685af15b860e', '825c261a-3c3f-5e1b-a962-7d0a38a8594b', 13, 13, 'እንዲህም ሆነ፤ በመሸ ጊዜ ድርጭቶች መጡ፤ ሰፈሩንም ሸፈኑት፤ በማለዳም በሰፈሩ ዙሪያ ጠል ወድቆ ነበር።'),
  ('e23cacc8-6bcf-58bf-a854-a853dd1cb652', 'b72ca4e8-28f1-566d-a44a-685af15b860e', '825c261a-3c3f-5e1b-a962-7d0a38a8594b', 14, 14, 'የወደቀው ጠል በአለፈ ጊዜ፥ እነሆ፥ በመሬት ላይ እንደ ውርጭ ነጭ ሆኖ ድንብላል የሚመስል ደቃቅ ነገር በምድረ በዳ ታየ።'),
  ('55db2955-c991-5512-a0a2-ce70d294d809', 'b72ca4e8-28f1-566d-a44a-685af15b860e', '825c261a-3c3f-5e1b-a962-7d0a38a8594b', 15, 15, 'የእስራኤልም ልጆች በአዩት ጊዜ እርስ በርሳቸው፥ “ይህ ምንድን ነው?” ተባባሉ። ያ ምን እንደሆነ አላወቁምና። ሙሴም አላቸው፥ “ትበሉ ዘንድ እግዚአብሔር የሰጣችሁ እንጀራ ይህ ነው።'),
  ('0240bef1-261b-5993-a46b-3aaf73cb9cc6', 'b72ca4e8-28f1-566d-a44a-685af15b860e', '825c261a-3c3f-5e1b-a962-7d0a38a8594b', 16, 16, 'ታደርጉት ዘንድ እግዚአብሔር ያዘዘው ነገር ይህ ነው፦ እያንዳንዱ ሰው ለቤተ ሰቡ ለእያንዳንዱ አንድ ጎሞር ይሰብስብ፤ እንደ ቤተ ሰቡ ቍጥር ለእያንዳንዱ በድንኳኑ አብረውት ከሚኖሩት ጋር ይሰብስብ።”'),
  ('a677247e-ac8b-5ae7-a519-950429884109', 'b72ca4e8-28f1-566d-a44a-685af15b860e', '825c261a-3c3f-5e1b-a962-7d0a38a8594b', 17, 17, 'የእስራኤልም ልጆች እንዲሁ አደረጉ፤ አንዱ አብዝቶ፥ አንዱም አሳንሶ ሰበሰበ።'),
  ('c3d64187-8405-5527-a5dc-6e5fe5ac399c', 'b72ca4e8-28f1-566d-a44a-685af15b860e', '825c261a-3c3f-5e1b-a962-7d0a38a8594b', 18, 18, 'በጎሞርም በሰፈሩት ጊዜ እጅግ ለሰበሰበ አልተረፈውም፤ ጥቂትም ለሰበሰበ አልጐደለበትም፤ ሁሉም እያንዳንዱ ሰው ለየቤቱ ሰበሰበ።'),
  ('7d8a3952-365a-5c3b-ae05-da6febb8a718', 'b72ca4e8-28f1-566d-a44a-685af15b860e', '825c261a-3c3f-5e1b-a962-7d0a38a8594b', 19, 19, 'ሙሴም፥ “የእስራኤልን ልጆች ማንም ከእርሱ አንዳች ለነገ አያስቀር” አላቸው።'),
  ('2e41cff3-f41d-53ad-ae91-a297fce34531', 'b72ca4e8-28f1-566d-a44a-685af15b860e', '825c261a-3c3f-5e1b-a962-7d0a38a8594b', 20, 20, 'ነገር ግን ሙሴን አልሰሙትም፤ አንዳንድ ሰዎችም ከእርሱ ለነገ አስቀሩ፤ እርሱም ተላ፤ ሸተተም፤ ሙሴም ተቈጣቸው።'),
  ('2b9ea08d-a387-5618-a29b-c7052092d37f', 'b72ca4e8-28f1-566d-a44a-685af15b860e', '825c261a-3c3f-5e1b-a962-7d0a38a8594b', 21, 21, 'ሰውም ሁሉ ለየራሱ ጥዋት ጥዋት ሰበሰበ፤ ፀሐይም በተኰሰ ጊዜ ቀለጠ።'),
  ('d7c0f284-53e6-59aa-afce-3727963b24aa', 'b72ca4e8-28f1-566d-a44a-685af15b860e', '825c261a-3c3f-5e1b-a962-7d0a38a8594b', 22, 22, 'እንዲህም ሆነ፤ በስድስተኛው ቀን ሁለት እጥፍ አድርገው እያንዳንዳቸው ሁለት ጎሞር እንጀራ ሰበሰቡ፤ የማኅበሩም አለቆች ሁሉ መጥተው ለሙሴ ነገሩት።'),
  ('6d21ebe2-3b63-541f-ae66-b2cb2e45a481', 'b72ca4e8-28f1-566d-a44a-685af15b860e', '825c261a-3c3f-5e1b-a962-7d0a38a8594b', 23, 23, 'ሙሴም፥ “እግዚአብሔር የተናገረው ይህ ነው፦ ነገ ዕረፍት፥ ለእግዚአብሔርም የተቀደሰ ሰንበት ነው፤ ነገ የምትጋግሩትን ዛሬ ጋግሩ፤ የምትቀቅሉትንም ቀቅሉ፤ የተረፈውንም ሁሉ ለነገ እንዲጠበቅ አኑሩ” አላቸው።'),
  ('2e1c9b5e-be7e-5ce6-aa32-39871e95fc84', 'b72ca4e8-28f1-566d-a44a-685af15b860e', '825c261a-3c3f-5e1b-a962-7d0a38a8594b', 24, 24, 'ሙሴም እንደ አዘዘ ለነገ አኖሩት፤ አልሸተተም፤ ትልም አልሆነበትም።'),
  ('95fbabb2-01c8-507d-a256-ac17addfe62b', 'b72ca4e8-28f1-566d-a44a-685af15b860e', '825c261a-3c3f-5e1b-a962-7d0a38a8594b', 25, 25, 'ሙሴም፥ “የእግዚአብሔር ሰንበት ዛሬ ነውና ብሉት፤ ዛሬ በሜዳ አታገኙትም።'),
  ('86eb4e54-0346-56d4-a287-64be82457d87', 'b72ca4e8-28f1-566d-a44a-685af15b860e', '825c261a-3c3f-5e1b-a962-7d0a38a8594b', 26, 26, 'ስድስት ቀን ልቀሙት፤ ሰባተኛው ቀን ግን ሰንበት ነው፤ በእርሱ አይገኝም” አለ።'),
  ('49f81d0d-ad98-58de-a4af-76bb2fcd1aec', 'b72ca4e8-28f1-566d-a44a-685af15b860e', '825c261a-3c3f-5e1b-a962-7d0a38a8594b', 27, 27, 'በሰባተኛውም ቀን እንዲህ ሆነ፤ ከሕዝቡ አንዳንድ ሰዎች ሊለቅሙ ወጡ፤ ግን ምንም አላገኙም።'),
  ('e77b18db-7db9-5e3f-a296-9d2a7669c6f2', 'b72ca4e8-28f1-566d-a44a-685af15b860e', '825c261a-3c3f-5e1b-a962-7d0a38a8594b', 28, 28, 'እግዚአብሔርም ሙሴን፥ “ትእዛዞችንና ሕጎችን ለመስማት እስከ መቼ እንቢ ትላላችሁ?'),
  ('b8234c4f-8649-54c4-ad46-8e91066e929f', 'b72ca4e8-28f1-566d-a44a-685af15b860e', '825c261a-3c3f-5e1b-a962-7d0a38a8594b', 29, 29, 'እግዚአብሔር ሰንበትን እንደ ሰጣችሁ እዩ፤ ስለዚህ በስድስተኛው ቀን የሁለት ቀን እንጀራ ሰጣችሁ፤ ሰው ሁሉ በቤቱ ይቀመጥ፤ በሰባተኛውም ቀን ማንም ከቤቱ አይሂድ” አለው።'),
  ('c8404ce9-18f3-531e-ad29-5fc08e3c0f0d', 'b72ca4e8-28f1-566d-a44a-685af15b860e', '825c261a-3c3f-5e1b-a962-7d0a38a8594b', 30, 30, 'ሕዝቡም በሰባተኛው ቀን ዐረፈ።'),
  ('b67c5d41-658f-5b9d-af66-c4eb8fc6a509', 'b72ca4e8-28f1-566d-a44a-685af15b860e', '825c261a-3c3f-5e1b-a962-7d0a38a8594b', 31, 31, 'የእስራኤልም ልጆች ስሙን መና ብለው ጠሩት፤ እርሱም እንደ ድንብላል ዘር ነጭ ነው፤ ጣዕሙም እንደ ማር እንጀራ ነው።'),
  ('407ec42e-1b7b-5f4e-aa7f-777e168d113e', 'b72ca4e8-28f1-566d-a44a-685af15b860e', '825c261a-3c3f-5e1b-a962-7d0a38a8594b', 32, 32, 'ሙሴም፥ “እግዚአብሔር ያዘዘው ነገር ይህ ነው፦ ከግብፅ ምድር በአወጣኋችሁ ጊዜ በምድረ በዳ ያበላኋችሁን እንጀራ ያዩ ዘንድ ከእርሱ አንድ ጎሞር ሙሉ ለልጅ ልጆቻችሁ ይጠበቅ” አለ።'),
  ('d3565c87-26ad-5b5d-a0e8-bd6b7bd2ec60', 'b72ca4e8-28f1-566d-a44a-685af15b860e', '825c261a-3c3f-5e1b-a962-7d0a38a8594b', 33, 33, 'ሙሴም አሮንን፥ “አንድ የወርቅ መሶብ ወስደህ ጎሞር ሙሉ መና አግባበት፤ ለልጅ ልጃችሁም ይጠበቅ ዘንድ በእግዚአብሔር ፊት አኑረው” አለው።'),
  ('cda47134-4e51-5244-a084-13de97320c2d', 'b72ca4e8-28f1-566d-a44a-685af15b860e', '825c261a-3c3f-5e1b-a962-7d0a38a8594b', 34, 34, 'እግዚአብሔርም ሙሴን እንዳዘዘው እንዲሁ ይጠበቅ ዘንድ አሮን በምስክሩ ፊት አኖረው።'),
  ('f90cf268-380c-54c6-a630-c9197b387ac4', 'b72ca4e8-28f1-566d-a44a-685af15b860e', '825c261a-3c3f-5e1b-a962-7d0a38a8594b', 35, 35, 'የእስራኤልም ልጆች ወደሚኖሩባት ምድር እስከሚመጡ ድረስ አርባ ዓመት መና በሉ።'),
  ('7d5f065f-4c5f-5b74-ad2e-b2bed2b25035', 'b72ca4e8-28f1-566d-a44a-685af15b860e', '825c261a-3c3f-5e1b-a962-7d0a38a8594b', 36, 36, 'ወደ ፊኒቆንም ምድር እስኪመጡ ድረስ መና በሉ። ጎሞርም የሦስት ላዳን መስፈሪያ ዐሥረኛ ክፍል ነው።'),
  ('13c3dedd-b3ad-50cd-aa83-41c447a0db3e', '6ba9e687-f8f0-5675-ae64-fcfd5f520f18', '4a970be7-0b33-5177-a95c-bf2191a193f3', 1, 1, 'የእስራኤል ልጆች ማኅበር ሁሉ እግዚአብሔር እንዳዘዘ ከሲን ምድረ በዳ ሊጓዙ ተነሡ፤ በራፊድም ሰፈሩ፤ በዚያም ሕዝቡ የሚጠጡት ውኃ አልነበረም።'),
  ('3cae1e60-623d-5418-a293-e4cd9c368542', '6ba9e687-f8f0-5675-ae64-fcfd5f520f18', '4a970be7-0b33-5177-a95c-bf2191a193f3', 2, 2, 'ሕዝቡም ሙሴን ተጣሉት፥ “የምንጠጣውን ውኃ ስጠን” አሉ። ሙሴም፥ “ለምን ትጣሉኛላችሁ? እግዚአብሔርንስ ለምን ትፈታተናላችሁ?” አላቸው።'),
  ('783482c8-47de-52dc-a5ca-798f23b36889', '6ba9e687-f8f0-5675-ae64-fcfd5f520f18', '4a970be7-0b33-5177-a95c-bf2191a193f3', 3, 3, 'ሕዝቡም በዚያ ስፍራ ውኃ ተጠሙ፥ “እኛንና ልጆቻችንን፥ ከብቶቻችንንም በጥማት ልትገድል ለምን ከግብፅ አወጣኸን?” ሲሉ በሙሴ ላይ አንጐራጐሩ።'),
  ('1140903b-1838-5577-a457-f4abecf57763', '6ba9e687-f8f0-5675-ae64-fcfd5f520f18', '4a970be7-0b33-5177-a95c-bf2191a193f3', 4, 4, 'ሙሴም፦ ወደ እግዚአብሔር ጮኸ፤ እንዲህም አለ፥ “ለዚህ ሕዝብ ምን ላድርግ? በድንጋይ ሊወግሩኝ ጥቂት ቀርቶአቸዋልና።”'),
  ('63de1ce2-3610-51d8-a857-704f76e4075e', '6ba9e687-f8f0-5675-ae64-fcfd5f520f18', '4a970be7-0b33-5177-a95c-bf2191a193f3', 5, 5, 'እግዚአብሔርም ሙሴን፥ “በሕዝቡ ፊት እለፍ፤ ከእስራኤልም ሽማግሌዎችን ከአንተ ጋር ውሰድ፤ ወንዙንም የመታህባትን በትር በእጅህ ይዘሃት ሂድ።'),
  ('d0fa2d23-de4b-5390-a593-5be72888d368', '6ba9e687-f8f0-5675-ae64-fcfd5f520f18', '4a970be7-0b33-5177-a95c-bf2191a193f3', 6, 6, 'እነሆ፥ እኔ በዚያ በኮሬብ በዓለት ላይ በፊትህ እቆማለሁ፤ ዓለቱንም ትመታለህ፤ ሕዝቡም ይጠጣ ዘንድ ከእርሱ ውኃ ይወጣል” አለው። ሙሴም በእስራኤል ልጆች ፊት እንዲሁ አደረገ።'),
  ('376b8dde-1a08-5cc7-ab70-d7d8898b97cd', '6ba9e687-f8f0-5675-ae64-fcfd5f520f18', '4a970be7-0b33-5177-a95c-bf2191a193f3', 7, 7, 'ስለ እስራኤልም ልጆች ክርክር፥ “እግዚአብሔር በመካከላችን ነውን? ወይስ አይደለም?” ሲሉ እግዚአብሔርን ስለ ተፈታተኑት የዚያን ስፍራ ስም “መንሱት” ደግሞም “ጋእዝ” ብሎ ጠራው።'),
  ('244bf210-1ba4-5023-ac10-7107ce8119a9', '6ba9e687-f8f0-5675-ae64-fcfd5f520f18', '8c84115c-3be2-5ed4-a29e-83c46acc01e9', 1, 8, 'ዐማሌቅም መጥቶ ከእስራኤል ጋራ በራፊድ ተዋጋ።'),
  ('0a4599a6-086d-5b8f-a400-10df49026254', '6ba9e687-f8f0-5675-ae64-fcfd5f520f18', '8c84115c-3be2-5ed4-a29e-83c46acc01e9', 2, 9, 'ሙሴም ኢያሱን፥ “ጐልማሶችን ለአንተ ምረጥ፤ ሲነጋም ወጥተህ ከዐማሌቅ ጋር ተዋጋ፤ እኔም በተራራው ራስ ላይ እቆማለሁ፤ የእግዚአብሔርም በትር በእጄ ናት” አለው።'),
  ('7f933a71-425f-5589-aead-9b1ae24aa7b8', '6ba9e687-f8f0-5675-ae64-fcfd5f520f18', '8c84115c-3be2-5ed4-a29e-83c46acc01e9', 3, 10, 'ኢያሱም ሙሴ እንደ አለው አደረገ፤ ወጥቶም ከዐማሌቅ ጋር ተዋጋ፤ ሙሴና አሮን፥ ሖርም ወደ ኮረብታው ራስ ወጡ።'),
  ('199d481c-66ce-5b48-a062-3b2c661d7597', '6ba9e687-f8f0-5675-ae64-fcfd5f520f18', '8c84115c-3be2-5ed4-a29e-83c46acc01e9', 4, 11, 'እንዲህም ሆነ፤ ሙሴ እጁን በአነሣ ጊዜ እስራኤል ድል ያደርግ ነበር ፤ እጁንም በአወረደ ጊዜ ዐማሌቅ ድል ያደርግ ነበር።'),
  ('397dfea9-bf5d-5883-a544-3db09b78025e', '6ba9e687-f8f0-5675-ae64-fcfd5f520f18', '8c84115c-3be2-5ed4-a29e-83c46acc01e9', 5, 12, 'የሙሴ እጆች ግን ከብደው ነበር፤ ድንጋይም ወሰዱ፤ በበታቹም አኖሩ፤ እርሱም ተቀመጠበት፤ አሮንና ሖርም አንዱ በዚህ አንዱ በዚያ ሆነው እጆቹን ይደግፉ ነበር፤ ፀሐይም እስክትገባ ድረስ እጆቹ ተዘርግተው ነበር።'),
  ('04e7c290-a1fb-54e5-a67a-ff5818b7773a', '6ba9e687-f8f0-5675-ae64-fcfd5f520f18', '8c84115c-3be2-5ed4-a29e-83c46acc01e9', 6, 13, 'ኢያሱም ዐማሌቅንና ሕዝቡን በሰይፍ ስለት አሸነፈ።'),
  ('44bce4ec-a942-548a-aaf2-e6219be57a17', '6ba9e687-f8f0-5675-ae64-fcfd5f520f18', '8c84115c-3be2-5ed4-a29e-83c46acc01e9', 7, 14, 'እግዚአብሔርም ሙሴን፥ “የዐማሌቅን ዝክር ከሰማይ በታች ጨርሼ እደመስሳለሁና ይህን ለመታሰቢያ በመጽሐፍ ጻፈው፤ በኢያሱም ጆሮ ተናገር” አለው።'),
  ('d65725d0-4f6d-57d0-a04b-6aa631187197', '6ba9e687-f8f0-5675-ae64-fcfd5f520f18', '8c84115c-3be2-5ed4-a29e-83c46acc01e9', 8, 15, 'ሙሴም መሠዊያ ሠራ፤ ስሙንም “ምምሕፃን” ብሎ ጠራው፤'),
  ('d99f57c2-b51d-5f35-a481-204c898eccef', '6ba9e687-f8f0-5675-ae64-fcfd5f520f18', '8c84115c-3be2-5ed4-a29e-83c46acc01e9', 9, 16, 'እግዚአብሔር በተሰወረች እጅ ዐማሌቅን እስከ ልጅ ልጅ ይዋጋልና።')
